INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (1, 'Miss Jerry', 'The adventures of a female reporter in the 1890s.', 'Alexander Black', 45, '1894-10-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eDRXkbGYQf4TIrha6Akg24mZuXN.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (2, 'The Corbett-Fitzsimmons Fight', 'This legendary fight was filmed on March 17, 1897, using 63mm film that produced an aspect ratio of about 1.75:1. Using three adjacent cameras, Enoch Rector recorded the entire fight, simultaneously creating the world''s first known feature film, as the resulting footage lasted over 90 minutes in length. About a quarter of the film survives today.', 'Enoch J. Rector', 100, '1897-05-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nL7aYlGYJZU7Gx8kFu9bTp3QYRu.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (3, 'The Story of the Kelly Gang', 'Just as Galeen and Wegener''s Der Golem (1915) can be seen as a testament to early German film artistry, The Story of the Kelly Gang (1906) symbolizes both the birth of the Australian film industry and the emergence of an Australian cinema identity. Even more significantly, it heralds the emergence of the feature film format. However, only fragments of the original production of more than one hour are known to exist, preserved at the National Film and Sound Archive, Canberra; Efforts at reconstruction have made the film available to modern audiences.', 'Charles Tait', 70, '1906-12-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yjpsmvhel7zOY1Ov7Ebl7RlbjEy.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (4, 'The Fairylogue and Radio-Plays', 'L. Frank Baum would appear in a white suit and present his live actors, slide shows and films as a live travelogue presentation of his popular fantasies. Highlights include Dorothy being swept to Oz in various ways, such as with back-projection tornadoes and storms in a chicken coop. Lack of financial backing forced the show to fold after appearing in only two cities, despite being a critical and commercial success. This film is lost.', 'Francis Boggs, Otis Turner', 120, '1908-09-23', 'T13', 'xx', 'https://image.tmdb.org/t/p/w500/jecGhyYtPGrlVh32OFbDZF9KaTZ.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (5, 'Amleto', 'A selection of Hamlet’s most famous scenes are reproduced in this Italian production from 1910.', 'Mario Caserini', 8, '1910-09-26', 'P', 'it', NULL, 'https://www.youtube.com/watch?v=4HfkqpRcjQY', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (6, 'Camille', 'Marguerite is a courtesan in Paris. She falls deeply in love with a young man of promise, Armand Duval. When Armand''s father begs her not to ruin his hope of a career and position by marrying Armand, she acquiesces and leaves her lover. However, when poverty and terminal illness overwhelm her, Marguerite discovers that Armand has not lost his love for her.', 'André Calmettes, Henri Pouctal, Louis Mercanton', 16, '1912-01-02', 'K', 'fr', 'https://image.tmdb.org/t/p/w500/c3e3kXpipHXETF9STAZp4W1AzNW.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (7, 'The Life of Moses', 'Released in five parts (The Persecution of the Children of Israel by the Egyptians, Forty Years in the Land of Midian, The Plagues of Egypt and the Deliverance of the Hebrews, The Victory of Israel, The Promised Land), 4 December 1909 to 19 February 1910. A Vitagraph advertisement in the Moving Picture World (31 Dec. 1909) refers to The Life of Moses as a "Biblical Film-de-Luxe". It is preserved in the Library of Congress collection.', 'J. Stuart Blackton', 54, '1909-12-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/buFV9r0KJzKbBvs9C4qr5n8to5E.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (8, 'The Girl Behind the Counter', 'Edgar the rich man’s son meets Ebba the waitress, and sparks fly. Ebba quickly becomes pregnant, but when the young lovers want to marry, Edgar’s father will stop at nothing to quash the mismatch. (stumfilm.dk)', 'August Blom', 52, '1911-08-12', 'T13', 'da', 'https://image.tmdb.org/t/p/w500/dH8rwF0y6NHimA3U0VsddaPruU0.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (9, 'The Strange Bird', 'The English landowner Wolton has gone on a fishing trip in the Spreewald with his daughter May. They meet fellow Englishman Bruce, who falls head over heels in love with the beautiful May and plans to make her his wife before their holiday is over. However, there is just one problem: May has only eyes for the young boatman Max. Bruce finds an ally in Max’s girlfriend, Grete, and together they do everything in their power to stop the budding love affair. A war of love with a fatal outcome.', 'Urban Gad', 45, '1911-11-03', 'P', 'de', 'https://image.tmdb.org/t/p/w500/sF0Ld4XkcQE8t07O0nhkPpweG5h.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (10, 'Les Misérables - Part 1: Jean Valjean', 'The story begins with Jean Valjean as a humble worker endeavoring to provide for his invalid mother. They live in a squalid home, made more wretched by his inability to provide sufficient food. He goes out in search of work, but is unsuccessful. Finally, in desperation, he steals a loaf of bread regardless of consequences. He hastens home with it, pursued by a crowd, and gives it to his mother. Valjean is arrested for the theft and sentenced to five years at hard labor.', 'Albert Capellani', 60, '1913-01-01', 'P', 'en', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (11, 'The Black Dream', 'Stella, a circus princess, has two suitors: young, handsome Count Waldberg and the greying, hidebound jeweller Hirsch. Stella’s love for Waldberg drives Hirsch mad with jealousy. He will stop at nothing to be near the woman of his dreams. When the count loses a staggering sum to the jeweller in a gambling duel, Stella embarks on a fateful mission to save her beloved’s honour. (Stumfilm.dk)', 'Urban Gad', 53, '1911-09-04', 'P', 'da', 'https://image.tmdb.org/t/p/w500/pqDNASbQdqDcUH32PZUh1td7AwN.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (12, 'The Traitress', 'A woman betrays the regiment location in which the officer she is interested in is assigned because he despises her, only to regret it when he is caught and try to free him.', 'Urban Gad', 48, '1911-12-09', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/zNUoIs100tHZ7BkgKhHaNqDSg8w.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (13, 'The Adventures of Lieutenant Petrosino', 'The story of Lt. Joseph Petrosino, an Italian-American New York City police detective, who was assigned to investigate the Sicilian Mafia, which was beginning to become a major problem in New York. He did such a good job that the city sent him to Sicily to gather information on the Sicily/New York Mafia connections. He was murdered in Palermo by Mafia gunmen.', 'Sidney M. Goldin', 47, '1912-11-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8IYQTgLHYFYo5kpHcWbzBFh9lvR.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (14, 'Queen Elizabeth', 'Episodes from the life of Elizabeth I, Queen of England (1533-1603), focusing on her ill-fated love affair with Robert Devereux, Earl of Essex.', 'Henri Desfontaines, Louis Mercanton', 50, '1912-08-16', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/oMwEJfh8toj9bY0K1stPrnyAYCB.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (15, 'Cleopatra', 'The fabled queen of Egypt''s affair with Roman general Marc Antony is ultimately disastrous for both of them.', 'Charles L. Gaskill', 88, '1912-11-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9Mi6Fiy68c3JIF3wnnD99JS38zR.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (16, 'Dante''s Inferno', 'The classic tale of Dante''s journey through hell, loosely adapted from the Divine Comedy and inspired by the illustrations of Gustav Doré. This historically important film stands as the first feature from Italy and the oldest fully-surviving feature in the world, and boasts beautiful sets and special effects that stand above other cinema of the era.', 'Adolfo Padovan, Francesco Bertolini, Giuseppe de Liguoro', 72, '1911-03-01', 'T16', 'it', 'https://image.tmdb.org/t/p/w500/ky0z9hDlajlwL3fBqwsCSbjJGjR.jpg', 'https://www.youtube.com/watch?v=HkVzLMo5yts', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (17, 'The Great Circus Catastrophe', 'Of the films that Psilander made at Nordisk during the first two years it is the film Dødsspring til Hest fra Cirkuskuplen (The Great Circus Catastrophe), that is worth noting. Maybe not so much for Psilander''s acting, but for the sensational, action-packed storylines that he was in. This film shows the other side of Psilander''s fame: his daring. He was an excellent rider and looked fantastic in long riding boots and elegant riding jackets and this skill was exploited in his films.', 'Eduard Schnedler-Sørensen', 45, '1912-08-26', 'P', 'da', 'https://image.tmdb.org/t/p/w500/hYjlByldIM4f05e2bJxjOeH8U6I.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (18, 'The Pride of the Circus', 'A tightrope walker from a traveling circus falls deeply in love with the mayor''s daughter in a small seaside town. When he saves her from a deadly fire, his feelings are reciprocated by the young woman, who immediately accepts his marriage proposal. To spite the mayor''s disapproval of the liaison between his daughter and the poor artist, the tightrope walker prepares a sensational but dangerous act, that will make him worthy of his bride. (stumfilm.dk)', 'Alfred Lind', 46, '1912-03-20', 'K', 'da', 'https://image.tmdb.org/t/p/w500/rwAUgu9N0spgKlIEOybjSquWtLp.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (19, 'From the Manger to the Cross', 'The life of Jesus is played out in tableaux shot in the Holy Land.', 'Sidney Olcott', 71, '1912-10-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wsRp6nRPam7F7ShyhRtswBRE283.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (20, 'Madame DuBarry', 'The story of Madame DuBarry, the mistress of Louis XV of France, and her loves in the time of the French revolution.', 'Ernst Lubitsch', 114, '1919-09-18', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/cRyZz3Rz3WfyGaSRnaxnrGBBafT.jpg', 'https://www.youtube.com/watch?v=q0oQaT61tC8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (21, 'Quo Vadis?', 'During the latter years of the reign of the tyrannical Roman emperor Nero, Marcus Vinicius, one of Nero''s officers, falls in love with a young Christian named Lygia, attempting to enslave her. Lygia''s protector, the noble and burly Ursus, works to save her from Vinicius'' clutches. Pursuing Lygia, Vinicius finds himself at a catacomb prayer meeting led by the apostle Peter and finds his conscience stirring-- just as Nero orders Rome burned. A landmark in epic film, Enrico Guazzoni’s grand-scale masterpiece laid the foundations for what colossal Italian spectacles would become. The film had tremendous influence on Giovanni Pastrone’s Cabiria (1914) and D.W. Griffith’s Intolerance (1916).', 'Enrico Guazzoni', 94, '1913-03-01', 'P', 'it', 'https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (22, 'The Independence of Romania', 'Having as “covers” the leaving for battle and the coming back of Penes Curcanul, the hero of a popular poem by Vasile Alecsandri, the film represents the well-known episodes of the Romanian-Russian-Turkish war (the “Independence War”) of 1877, such as: the mobilization, the Romanian army’s crossing of the Danube, the battles of Plevna and Grivita, aspects from the hospitals full of wounded soldiers and the surrender of Osman Pasha. The film ends with newsreel sequences from the Royal Parade in Bucharest on the 10th of May, 1912. This is the first feature-length Romanian film.', 'Aristide Demetriade', 82, '1912-09-01', 'T13', 'xx', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (23, 'The Life and Death of King Richard III', 'Shakespeare''s tragedy of the wicked and hump-backed Duke of Gloucester, who rises to the throne of England by chicanery, treachery, and brilliance.', 'André Calmettes, James Keane', 55, '1912-10-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xVxV4tDdMnmu0V6EgKTpjacjgF4.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (24, 'The Last Bohemian', 'The Last Bohemian (Hungarian: Az Utolsó bohém) is a 1912 Hungarian film directed by Michael Curtiz. It was Curtiz''s debut film as a director.', 'Michael Curtiz', 60, '1913-08-31', 'T13', 'hu', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (25, 'Zigomar vs. Nick Carter', 'Nick Carter, the famous detective, is ordered to prosecute the gang of Zigomar. Carter gets into various thorny situations but manages to escape every time, helped by Olga, a former girlfriend of Zigomar. Carter finally manages to trap Zigomar and Zigomar is arrested. However, Zigomar avoids going to court by apparently poisoning himself.', 'Lucien N. Andriot, Victorin-Hippolyte Jasset', 48, '1912-03-24', 'T16', 'xx', 'https://image.tmdb.org/t/p/w500/yQDrB6FqVkaRjeJhHzPfwHSXW9R.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (26, 'The Adventures of Kathlyn', 'The serial detailed the experiences of Kathlyn Hare, the pretty daughter of an explorer. Kathlyn resided in a mythical India, fighting off unwanted advances from a handsome native, Umballah, when not battling an endless array of ferocious jungle fauna.', 'Francis J. Grandon', 300, '1913-12-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v8SvfWwPjrpEUXErFneMtVwoEb6.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (27, 'Der Andere', 'A man has an accident while out riding his horse and soon discovers that he now has a split personality, and that his alternate is helping a criminal to rob his house.', 'Max Mack', 48, '1913-01-21', 'P', 'de', 'https://image.tmdb.org/t/p/w500/Aosrb7oQ34SjnoRyUnZ5b85djay.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (28, 'Atlantis', 'Overwhelmed by personal and professional problems, biologist Friedrich von Kammacher decides to travel abroad in order to regain the joy of living. During his adventurous journey he will meet two very different women, one of whom will be the key to his fate.', 'August Blom', 117, '1913-12-20', 'T13', 'da', 'https://image.tmdb.org/t/p/w500/d089CbV3K1YOyFPBoVaHHlUp3Gc.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (29, 'The Count of Monte Cristo', 'A French sailor, imprisoned for years on false charges of conpiring against the king, escapes and exacts revenge on his accusers.', 'Edwin S. Porter, Joseph A. Golden', 69, '1913-11-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4kjbSEs4FS1zs8dND7jjko8D5zg.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (30, 'What 80 Million Women Want', 'The women''s suffrage movement inspired this silent film classic that includes appearances by equal rights crusaders Emmeline Pankhurst and Harriet Stanton Blatch. As politicos work to deny women the right to vote, a young lawyer tells his activist girlfriend of the corruption within the government that actively seeks to ensure that her voice is never heard.', 'Will Louis', 56, '1913-11-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1qHpfpWOhKjVhmR7SaG0736QbnK.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (31, 'From Dusk To Dawn', 'An employee of an iron works is fired as a dangerous agitator, and after his friend dies in an explosion at the iron works, he runs for governor on a labor ticket.', 'Frank E. Wolfe', 90, '1913-09-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sOaUyJW6MVPJviOaK0QwuPvbXLe.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (32, 'Germinal', 'Based on Emile Zola''s novel, an uncompromisingly harsh and realistic story of a coalminers'' strike in northern France in the 1860s.', 'Albert Capellani', 150, '1913-10-03', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/lJzJh2SWL7rOGEI3FHpTWrOTd5N.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (33, 'Brother Against Brother', 'Two brothers compete for the love of a woman while the impending war threatens to separate them from both sides of the border. Based on the novel "La Débâcle" by Émile Zola.', 'Mauritz Stiller', 51, '1913-11-21', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/3I108XGCchW9sGURpFbX1riGPsj.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (34, 'Hamlet', 'Hamlet is a 1913 British silent drama film directed by Hay Plumb and starring Johnston Forbes-Robertson, Gertrude Elliot and Walter Ringham.', 'Hay Plumb', 64, '1913-09-22', 'P', 'en', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (35, 'Ingeborg Holm', 'After Ingeborg Holm''s husband becomes sick and dies, the family''s small grocery store fails, Ingeborg becomes bankrupt, and she is forced to move to the workhouse. Her three children go to foster homes. Ingeborg simply must see them again.', 'Victor Sjöström', 108, '1913-10-27', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/1xvNugzStYyB5ZxycMiUebKb9up.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (36, 'The Island of the Blessed', 'Max Reinhardt’s second and last silent film. It tells the story of two young girls (Cheerful & Shy) who, in order to escape their father’s authority, reaches an island of wonder filled with gods, nymphs, fauns and other creatures.', 'Max Reinhardt', 60, '1913-10-03', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/eR8jy2dwmAHro7x350Ig0KjXaP.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (37, 'Ivanhoe', 'Wilfred of Ivanhoe (King Baggot), son of Sir Cedric (Wallace Bosco), returns to England from the Crusades in the Holy Land. As Ivanhoe, disguised, discovers that his beloved Lady Rowena (Evelyn Hope) has remained faithful, two weary travelers, Isaac of York (Herbert Brenon) and his pretty daughter Rebecca (Leah Baird), are admitted to Sir Cedric''s castle, but after the knights learn that Isaac has money they abduct the visitors to the Norman stronghold of Torquilstone Castle.', 'Herbert Brenon', 53, '1913-09-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pIUGTomfRCMOrTI19YpDB1yRwNU.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (38, 'Love Everlasting', 'Grand Duchy of Wallenstein. Elsa Holbein is the young beautiful daughter of General Julius, the Chief of the General Staff. After a spy named Moise Sthar steals military documents, Julius is accused of betrayal. He kills himself while Elsa is forced to leave. Homeless, she begins wandering the streets until, on the Riviera, she starts her performing career under the pseudonym of Diana Cadouleur and becomes a successful actress and singer. One day, in a small church, she meets an elegant young man and she falls in love with him. But during a tour on the Lucarno Lake she runs into Sthar who, rejected by Elena, spreads rumors about Prince Massimiliano’s behavior.', 'Mario Caserini', 90, '1913-10-03', 'P', 'it', 'https://image.tmdb.org/t/p/w500/485HCMbvSaQvwhzYGf0MhuiKZJg.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (39, 'Damn the War', 'An army pilot is visiting the home of another army pilot in a neighboring country, and falling in love with his sister, when war breaks out.', 'Alfred Machin', 50, '1914-04-30', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/yC89sqsGpe6Yo8stfa3xyxrqocJ.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (40, 'Les Misérables - Part 2: Fantine', 'Jean Valjean, guilty of a minor theft of food, is pursued and hounded for years by a relentless lawman, Javert.', 'Albert Capellani', 35, '1913-01-01', 'T13', 'en', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (41, 'Home, Sweet Home', 'John Howard Payne leaves home and begins a career in the theater. Despite encouragement from his mother and his sweetheart, Payne begins leading a life of dissolute habits, which soon leads to ruin and misery. In deep despair, he recalls better days, and writes a song that later provides inspiration to several others in their own times of need.', 'D.W. Griffith', 55, '1914-05-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dAyHCONOhYJiMzb6PMD9TR1Qz6L.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (42, 'The Prisoner of Zenda', 'A kingdom''s ascending heir, marked for assassination, switches identities with a lookalike, who takes his place at the coronation. When the real king is kidnapped, his followers try to find him, while the stand-in falls in love with the king''s intended bride, the beautiful Princess Flavia.', 'Edwin S. Porter, Hugh Ford', 55, '1913-02-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1TOcHSkarwXWSlkiEPEjVyFJPZj.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (43, 'The Life and Works of Richard Wagner', 'This biographical portrait of composer Richard Wagner (1813-1883), feature-length and lavishly produced, was released in conjunction with the centennial of his birth. It''s an outstanding achievement in many respects. Naturally it looks primitive by modern standards, but contemporary viewers should bear in mind that it was made at a time when the motion picture industry was still in its infancy, and feature films were still a novelty. The very notion of a silent movie about a composer may seem odd, but Wagner is an ideal choice, simply because his life was so tempestuous and dramatic. Wagner''s personality was operatic, while his tumultuous love life unfolded like a soap opera. He knew great success and abysmal failure, luxury one day and poverty the next. He participated in the wave of revolutions that swept Europe in the late 1840s, and had to flee Germany under threat of arrest.', 'Carl Froelich, William Wauer', 102, '1913-05-31', 'P', 'de', 'https://image.tmdb.org/t/p/w500/sfKuCdRLHu74JzxB6c5lyDk4Gsi.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (44, 'Robin Hood', 'Robin Hood and his followers aid the poor and oppressed from their hideout in Sherwood Forest, pursued by the Sheriff of Nottingham.', 'Theodore Marston', 31, '1913-09-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8sJuZD0YMigdLEXBU8YyQ6uBlZu.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (45, 'The Student of Prague', 'Prague, Bohemia, 1820. Balduin, a penniless student, falls in love with Countess Margit, a wealthy noblewoman whom he has saved from drowning.', 'Stellan Rye', 85, '1913-08-11', 'P', 'de', 'https://image.tmdb.org/t/p/w500/tO2zgNEY0MqtvEyPioTTfHgmN2Q.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (46, 'Traffic in Souls', 'A woman, with the aid of her police officer sweetheart, endeavors to uncover the prostitution ring that has kidnapped her sister, and the philanthropist who secretly runs it.', 'George Loane Tucker', 88, '1913-11-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/m1n4TslM0zpOZ3AEDdUifz964RC.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (47, 'The Last Days of Pompeii', 'Well-respected Pompeiian Glaucus performs an act of kindness by purchasing Nydia, a blind slave being mistreated by her owner. Nydia falls in love with her new master, but he only has eyes for Ione. Ione in turn is lusted after by Arbace, an Egyptian high priest of Isis. When Nydia beseeches Isis for help in capturing Glaucus'' heart, Arbace gives her a "love" potion-- an elixir made to drive Glaucus mad, securing Ione for himself. Ultimately, Mount Vesuvius will end their lives and seal their fates in a terrible, glorious eruption.', 'Eleuterio Rodolfi, Mario Caserini', 106, '1913-08-13', 'T13', 'it', 'https://image.tmdb.org/t/p/w500/8aKwvUqzvMaIDkHQCWnbRSqQCf4.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (48, 'Where Is Coletti?', 'Jean Coletti, a popular police detective, criticized for not using the press to help catch criminals, wages 100.000 marks that he can lose himself in Berlin for forty-eight hours without being caught.', 'Max Mack', 86, '1913-04-02', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/oCiARXBz3yekD0oI8ut69yAkphy.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (49, 'The Active Life of Dolly of the Dailies #5: The Chinese Fan', 'An early Thomas Edison short. A young woman is kidnapped while attending a play in Chinatown. A reporter attends another play in Chinatown, is likewise kidnapped and rescues the young woman. Preserved by the Academy Film Archive in 2011 in partnership with the National Film Preservation Foundation New Zealand Project.', 'Walter Edwin', 14, '1914-01-31', 'P', 'en', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (50, 'Assunta Spina', 'Assunta and Michele are in love, but others come between them and jealousy arises. Assunta Spina stands out as an early landmark of naturalistic acting and a blueprint for the Italian Neorealist films to come.', 'Francesca Bertini, Gustavo Serena', 73, '1915-10-27', 'P', 'it', 'https://image.tmdb.org/t/p/w500/x5Rq27ZzhnWN8wWHkre8ZlAgyvh.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (51, 'The Avenging Conscience', 'Thwarted by his despotic uncle from continuing his love affair, a young man''s thoughts turn dark as he dwells on ways to deal with his uncle. Increasingly convinced that murder is merely a natural part of life, he kills his uncle and hides the body. However, the man''s conscience awakens; paranoia sets in and nightmarish visions begin to haunt him.', 'D.W. Griffith', 83, '1914-08-02', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/3NwXxPM7f3mHdlF6YylD3cao8CS.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (52, 'The Bargain', 'After the bandit known as the Two-Gun Man Jim Stokes robs the stage, he is wounded in his flight from the scene. Recuperating at a ranch, he falls in love with a local settler''s daughter. Now wishing to go straight, Stokes encounters trouble when the Sheriff-- not entirely incorruptible-- Catches wind of his location.', 'Reginald Barker', 80, '1914-12-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gVfq3RPdFaSbZvKxjClSub8ZWll.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (53, 'The Battle of the Sexes', 'Frank Andrews is a successful businessman. He has always found pride and joy in the company of his wife, son and daughter. He suddenly finds himself enthralled by the advances of a gay young woman siren, who lives in the same apartment house as he does. So marked an influence does she have over him as time progresses that at last he quite forgets his home ties, neglects his family, and goes the way of many other men who have forgotten the meaning of paternity and blood ties. The story is advanced through many scenes enacted with the accompanying notes of New York''s night life, and the denouement comes when the faithful wife discovers her husband''s infidelity. At this time the mother''s mind nearly loses balance, while Jane, the beautiful daughter, crazed by the grief of her mother, determines to take part in the tragedy. With revolver in hand she steals up to the apartment of the woman, but her frail nature is overcome by the temperamental anger of the woman and her mission fails.', 'D.W. Griffith', 50, '1914-04-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kArZ9z1cPKwrfF3Vtz4rcCkZWxZ.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (54, 'Brewster''s Millions', 'The first movie adaptation of the famous novel where a young man has to spend a fortune on 60 days to inherit an even larger sum of money. Considered to be a lost film.', 'Cecil B. DeMille, Oscar Apfel', 50, '1914-04-14', 'K', 'en', 'https://image.tmdb.org/t/p/w500/pz41bQ98fDSuSmkatzegOG36zbg.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (55, 'Cabiria', 'Young Cabiria is kidnapped by pirates and sold as a slave in Carthage. Just as she''s to be sacrificed to Moloch, Cabiria is rescued by Fulvius Axilla, a good-hearted Roman spy, and his powerful slave, Maciste. The trio are broken up as Cabiria is entrusted to a woman of noble birth. With Cabiria''s fate unknown, Maciste punished for his heroism, and Fulvius sent away to fight for Rome, is there any hope of our heroes reuniting?', 'Giovanni Pastrone', 148, '1914-06-01', 'P', 'it', 'https://image.tmdb.org/t/p/w500/xBghuwewK37knryQ03lyRGzvoAO.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (56, 'The Call of the North', 'Graehme, Ned Stewart''s father, was accused of adultery and killed being innocent. Ned decided to avenge his father, but got captured and sent to the long journey to death "la longue traverse".', 'Cecil B. DeMille, Oscar Apfel', 49, '1914-08-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4riQn2Dj0xPEFYg9K6zlNzxGGCR.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (57, 'Cinderella', 'Good-hearted Cinderella is mistreated by her stepmother and stepsisters, but she is able to go to the Royal Ball with the help of the Fairy Godmother. Based on Charles Perrault''s fairy tale, and featuring unforgettable chemistry between Pickford and then-husband Owen Moore as Prince Charming.', 'James Kirkwood', 52, '1914-12-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2cLfN2sVYo3niOmmEdqQMuQXk78.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (58, 'The Child of Paris', 'The young daughter of an army captain missing in action runs away from school and is kidnapped by Parisian lowlifes. When the kidnapper flees to Nice with the child, the kind-hearted employee of one of his accomplices sets off in pursuit.', 'Léonce Perret', 124, '1913-09-17', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/me87mIv1uKyn19pnS7kBSSPg3Rh.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (59, 'Little Angel', 'Engelein is a comedy of deliberately mistaken identity. If Jesta, a 17-year-old, can play the part of a 12-year-old, her family will gain a large inheritance from a rich uncle from Chicago. Her unruly “play-acting” for the uncle is preceded by an earlier incident in the film that results in Jesta being evicted from her girl’s school. Wearing a long, woman’s skirt, she climbs up a ladder and onto a thatched roof. She reaches over the top of the wall to kiss her boyfriend, who appears from the other side. However, Jesta is caught by the headmistress, and her forced descent is precipitous. Pulled downward, she reveals a great deal of a black-stockinged leg. She looks distinctly sexual as she falls into the matrimonly arms of the law, whose duty is to enforce the rules of female decorum.', 'Urban Gad', 49, '1914-01-03', 'P', 'de', 'https://image.tmdb.org/t/p/w500/a2TCLoySkFri15Sx5fCk3Kj7yMy.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (60, 'The Escape', 'A dramatic comparison between the mating habits of animals and the way humans choose their own partners. The film is now considered to be a lost film.', 'D.W. Griffith', 77, '1914-06-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7UCl4Gt86d9gmA8OfYY3ocMZhs3.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (61, 'The Exploits of Elaine', 'Elaine Dodge is the beautiful young daughter of Taylor Dodge, president of the Consolidated Insurance Company. When Mr Dodge is murdered by a mysterious cloaked figure known only as the Clutching Hand, Elaine enlists the aid of Craig Kennedy to unmask the killer', 'George B. Seitz, Leopold Wharton, Louis J. Gasnier', 280, '1914-12-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ulTOnP8Gn5fXS8lOyErTFvAC0xp.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (62, 'A Florida Enchantment', 'Lillian Travers, a New York heiress, pops down to Florida to surprise her fiancé, Fred Cassadene, the house doctor at a prominent Saint Augustine hotel. The surprise, however, is Lillian''s when she finds Fred in a series of compromising situations with a certain wealthy widow staying there. When she can take no more, Lillian discovers a box forgotten at an old curiosity shop in which lies a hundred-year-old secret: a vial of four rare and exotic African seeds that promises to transform whoever swallows one from a woman to a man or vice versa.', 'Sidney Drew', 63, '1914-08-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vgqKwZrz8TXXSuNGYMaZnPKH03F.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (63, 'The Ghost Breaker', 'Carmen, a maid, steals a locket belonging to the Aragon princess Maria Theresa and sells it to Gaines, a New York art collector, not knowing that the locket contains the clue to the Aragon family fortune''s whereabouts. Based on the 1909 Broadway play of the same name by Paul Dickey and Charles W. Goddard.', 'Cecil B. DeMille, Oscar Apfel', 60, '1914-12-07', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/guDzZ9tAnt44RanhAQqXJeCvenR.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (64, 'Cajus Julius Caesar', 'A colossal epic film like this that tries to depict the life and glory of Julius Caesar, must have a variety of scenery appropriate to the film''s hero. This includes the Senate and its conspirators..or .. strange places beyond Rome full of barbarians that must fall under the Rome yoke. Let''s not forget the sequences depicting the masses mentioned before.. or.. the human side of Caesar and his troublesome relationship with his son Brutus.', 'Enrico Guazzoni', 112, '1914-11-13', 'T13', 'it', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (65, 'The Golem', 'This mostly lost film is often confused with director Paul Wegener third and readily available interpretation of the legend; Der Golem, wie er in die Welt kam (1920). In this version of the golem legend, the golem, a clay statue brought to life by Rabbi Loew in 16th century Prague to save the Jews from the ongoing brutal persecution by the city''s rulers, is found in the rubble of an old synagogue in the 20th century. Brought to life by an antique dealer, the golem is used as a menial servant. Eventually falling in love with the dealer''s wife, it goes on a murderous rampage when its love for her goes unanswered.', 'Henrik Galeen, Paul Wegener', 60, '1915-01-14', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/vu5KgTbTqeCNu0uqOrESBfnw3EV.jpg', 'https://www.youtube.com/watch?v=ydKJaiZ2a4s', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (66, 'The Hazards of Helen', 'The Hazards of Helen is an American melodramatic adventure film serial of 119 twelve-minute episodes released between November 7, 1914 and February 24, 1917. Most episodes of this serial are presumed lost.', 'J. Gunnis Davis, J.P. McGowan', 999, '1917-02-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qOLy0ZS2bNW7wepemvUGeU4E3eq.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (67, 'The Mysterious X', 'Not long before marine officer van Hauen goes off to war and heavy-heartedly leaves his family, he coincidentally discovers that his wife has a secret liaison with the dubious Count Spinelli. What the van Hauens do not yet know, is that the sleazy Spinelli has a hidden agenda. (stumfilm.dk)', 'Benjamin Christensen', 90, '1914-03-23', 'T13', 'da', 'https://image.tmdb.org/t/p/w500/dzP62g32ZWBrz50UqOZpMjuAJtb.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (68, 'His Majesty, the Scarecrow of Oz', 'A wicked king has taken over the Emerald City, and wants his daughter, Princess Gloria to marry the horrid courtier Googly-Goo, though she loves Pon, the Gardener''s Boy. The camera follows two farmers placing a Scarecrow upon a pole in a cornfield. Pon rescues a Kansas girl named Dorothy from the evil witch Mombi, whom Princess Gloria has been taken to by King Krewl to freeze her heart so she will no longer love Pon. An Indian princess has a ceremony to bring the Scarecrow to life. Pon rescues the cold-hearted princess and they flee for help, discovering the Scarecrow, who promptly falls in love with the princess, and Button-Bright, a lost boy from America. They come to the castle of the Tin Emperor, Nick Chopper, and after oiling him, he falls in love with Gloria. After a bit of a chase aided by the Sawhorse and the Wizard, Mombi turns Pon into a Kangaroo, and a slough of Fred Woodward''s animals battle it out.', 'J. Farrell MacDonald, L. Frank Baum', 59, '1914-10-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mqT8lcBHbtmdHBeXJGOEsfnpVro.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (69, 'The Hound of the Baskervilles', 'In this early version the classic "Hound of the Baskervilles" mystery is not faithfully adapted, Watson''s character is absent and there are two Holmes. Holmes'' foe is called Stapleton and he menaces Holmes'' client Lord Henry and his fiancée, Laura Lyons, masquerading himself as Holmes. Hidden passages, hand bombs and mechanical devices abound, reminding more of a serial than of a Conan Doyle story.', 'Rudolf Meinert', 65, '1914-06-12', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/ch9iCPBOWAfSv22s5IcrcjTx6KI.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (70, 'Hypocrites', 'The story of St. Gabriel, who was killed by an ignorant mob for making a nude statue representing Purity, who is also represented by a ghostly naked girl that flits through the film.', 'Lois Weber', 52, '1915-01-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qB6ZyamUibmzvKKD0t6zZTOQw1h.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (71, 'In the Land of the Head Hunters', 'In the Land of the Head Hunters is a 1914 silent film fictionalizing the world of the Kwakwaka''wakw (Kwakiutl) peoples of the Queen Charlotte Strait region of the Central Coast of British Columbia, Canada, written and directed by Edward S. Curtis and acted entirely by Kwakwaka''wakw natives. It was the first feature-length film whose cast was composed entirely of Native North Americans; the second, eight years later, was Robert Flaherty''s Nanook of the North.', 'Edward S. Curtis', 65, '1914-12-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uj9F9uG2xuT1qUCz7bw5bwvGqYk.jpg', 'https://www.youtube.com/watch?v=QB93E0Ct3W8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (72, 'Ireland, a Nation', 'The story of Ireland and her fight for Home Rule, as seen through the experiences of Father Tom Murphy, a patriot with a price on his head, and the famous Irish leader Robert Emmet.', 'Walter MacNamara', 50, '1914-09-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iFU9FCgu1OXmnuHBhsby0IBzuow.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (73, 'Joseph in the Land of Egypt', 'Film realization of the Biblical story of Joseph, played here by future director James Cruze.', 'Eugene Moore', 52, '1914-02-01', 'P', 'en', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (74, 'Judith of Bethulia', 'In the 7th-century B.C., the Assyrians storm the walls of the Jewish city of Bethulia, leaving its people frightened and ready to hand their homes over to the invaders. As the Assyrians close in, the citizens are cut off from the outside world, and they began to starve. Seeing her people''s desperation, Jewish widow Judith poses as a harem worker, winning her entry into the Assyrian camp, where she plans to kill their general, Holofernes.', 'D.W. Griffith', 72, '1914-03-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/paLiTzDwYlgVTnbXLaEZSppdD17.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (75, 'The Jungle', 'Lithuanian immigrant, Jurgis Rudkus, gains a job in the Chicago stockyards. Once working at the stockyards he meets and marries Ona. But due to cut backs at the stockyards, loses his job, and they fall into financial hardship. Ona, in order to get money to feed their child, engages in sexual activity with her husband''s foreman, Connor. Connor, rapes her. When Rudkus finds out about the affair, he throws Connor into a cattle pen where he is killed. While in prison Ona dies. When Rudkus gets out of prison he becomes an advocate for women via the Socialist Party. Considered a lost film.', 'Augustus E. Thomas, George Irving, Jack Pratt', 55, '1914-05-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3tKUF3f4R88OJ2gGHO8KFmub4Z1.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (76, 'The Life of General Villa', 'Silent biographical action–drama film starring Pancho Villa as himself. The movie incorporates both staged scenes and authentic live footage from real battles during the Mexican Revolution.', 'Christy Cabanne, Raoul Walsh', 105, '1914-05-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gbm49GQD4lMGGUZkrWwrQ2ZnGzn.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (77, 'McVeagh of the South Seas', 'Harvard grad Bruce McVeagh has fled San Francisco for the South Seas, where he rules as a king on a remote island. With his half-crazed first-mate ''Pearly'' Gates, he keeps the natives subjugated with gin. Any who dare disobey him find brutal punishment on his dreaded torture rack. But his kingdom threatens to crash down around him when his lost love, Nancy Darrell, is shipwrecked on the island, just as the aroused natives rise up against their tormentor in an armed rebellion.', 'Cyril Bruce, Harry Carey', 59, '1914-11-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3WUSiYdVrfByribNoHjnITZsDk8.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (78, 'Lay Down Your Arms!', 'Martha, a war widow, finds a new zest for life when she meets the noble Captain von Tilling. They marry, but before long he, too, is called to war. In his absence, Martha falls into a depression and is hospitalised. Sick with longing and learning that her banking firm has gone belly-up, she leaves the hospital and takes a train to the battlefield to find her husband. (stumfilm.dk)', 'Holger-Madsen', 68, '1914-08-14', 'T16', 'da', 'https://image.tmdb.org/t/p/w500/cyG01ebdVRfE5rHqUgqd7NUUMzj.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (79, 'Silent Witnesses', 'In order to allow another servant to go home to be with her children, Nastya agrees to serve in her place, as a maid in the household in which Nastya''s grandfather is a porter. Soon afterwards, the woman who owns the house goes on a trip, leaving her son Pavel at home. Pavel is engaged to Ellen, but Ellen flirts openly with other men. Nastya and the servants quickly realize that Ellen is having an ongoing romantic affair with Baron von Rehren. This puts the servants, and especially the sensitive Nastya, in a painfully uncomfortable position.', 'Yevgeni Bauer', 65, '1914-04-29', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/oxxOa0dbzpogrYVUmAgl7scUH9j.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (80, 'Neptune''s Daughter', 'The daughter of King Neptune takes on human form to avenge the death of her young sister, who was caught in a fishing net. However, she falls in love with the king, the man she holds responsible.', 'Herbert Brenon', 95, '1914-04-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fdbrbj9VfYrOMGQQ0vbF4An08Sx.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (81, 'The Patchwork Girl of Oz', 'Ojo and Unc Nunkie are out of food, so they decide to journey to the Emerald City where they will never starve. Along the way, they meet Mewel, a waif and stray (mule) who leads them to Dr. Pipt, who has been stirring the powder of life for nine years. Ojo adds plenty of brains to Margolotte''s Patchwork servant before she is brought to life with the powder. When Scraps does come to life, she accidentally knocks the liquid of petrifaction upon Unc Nunkie, Margolotte, and Danx (daughter Jesseva''s boyfriend). So all go on separate journeys to find the ingredients to the antidote.', 'J. Farrell MacDonald', 66, '1914-09-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ySOqjT7KY2hZfi4MGWBLI9I230B.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (82, 'The Perils of Pauline', 'The Perils of Pauline is a motion picture serial shown in weekly installments featuring the actress Pearl White playing the title character. Pauline has often been cited as a famous example of a damsel-in-distress, although viewers will find her character more resourceful and less helpless than the classic ''damsel'' stereotype. Nine episodes (from a condensed 1916 re-release) survive to this day.', 'Donald MacKenzie, Louis J. Gasnier', 410, '1914-03-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jR5QxRKlTrrYUkID76aPW9I0rjt.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (83, 'The Reign of Terror', 'The scene takes place in Paris in March 1793 during the Reign of Terror. The Knight of Maison-Rouge, posing as Citizen Morand, is organizing the escape of Queen Marie-Antoinette. He is assisted in his undertaking by Dixmer, a master tanner who passes himself off as an ardent revolutionary and his wife Geneviève, who also happens to be the Knight''s sister. While on mission with her brother, she is saved from arrest thanks to the intervention of Lieutenant Maurice Lindey. Geneviève, who is married without love to Dixmer, falls for the young man, who requites her love. A tunnel is dug between a house rented by Dixmer and the Tower of the Temple but the various attempts to rescue the queen attempts fail. Marie-Antoinette risks the guillotine/ Moreover, Lindey finds himself involved in the plot...', 'Albert Capellani', 108, '1914-02-27', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/xL3Q94svonzWgwXsQCE1QOfVRyE.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (84, 'The Rose of the Rancho', 'Esra Kincaid takes land by force and, having taken the Espinoza land, his sights are set on the Castro rancho. Government agent Kearney holds him off till the cavalry shows up and he can declare his love for Juanita, called “the Rose of the Rancho.”', 'Cecil B. DeMille', 50, '1914-11-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eQbfgtvQsCXRCIhFSOXNkxhoSys.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (85, 'Salomy Jane', 'When beautiful Salomy Jane resists the romantic advances of a young ruffian, she is rescued by Jack Dart, who has his own additional reasons for tangling with the man. Jack fights the ruffian and kills him. He escapes with the law on his trail, for it is (wrongly) presumed that he is also the man who held up the stagecoach. Salomy Jane comes to his rescue when he is captured and about to be lynched.', 'Lucius Henderson, William Nigh', 87, '1914-11-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vVGsK6oeKnTe6ZGDBLdVFRpfM7f.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (86, 'The Sign of the Cross', 'In 64 A.D., Marcus Superbus is Prefect of Rome. When the Emperor Nero decides to renew persecution of the Christians, Marcus opposes him, fearing for the safety of Mercia, the Christian woman whom he loves. Through the machinations of the Empress Poppaea and other women at court, Tigellinus, Nero''s agent in the war against the Christians, convinces Nero to have Mercia arrested. Marcus appeals to the emperor for mercy, but is told that she can be saved only by renouncing Christianity. Waiting to enter the arena to be killed, Mercia steadfastly refuses to reject her religion, despite Marcus'' pleas. Finally, Marcus is converted by her and they enter the arena to face death together.', 'Frederick A. Thomson', 67, '1914-12-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hL4ZW604u9FmiAaviETu8nbH9Ju.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (87, 'The Spoilers', 'The Spoilers is a 1914 film directed by Colin Campbell. It is set in Nome, Alaska during the 1898 Gold Rush, with William Farnum as Roy Glennister, Kathlyn Williams as Cherry Malotte, and Tom Santschi as Alex McNamara. The film culminates in a spectacular saloon fistfight between Glennister and McNamara. It was adapted to screen by Lanier Bartlett from the Rex Beach novel of the same name.', 'Colin Campbell', 110, '1914-04-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wAoIGs19u53yLAbLKLZwHjSkrJl.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (88, 'The Squaw Man', 'Blamed for the theft of an orphans fund, Captain James Wynnegate flees to the West where he makes a new life with the Indian woman Nat-U-Rich.', 'Cecil B. DeMille, Oscar Apfel', 74, '1914-02-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9uLXtNGpxw1gCFjSczjsJKpsG3r.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (89, 'Tess of the Storm Country', 'A young girl, squatting on a wealthy man''s land fights for her fellow squatters'' right to stay.', 'Edwin S. Porter', 80, '1914-03-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iEHS5DM6zdL2mPXqzkXMj9UOgTv.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (90, 'Tillie''s Punctured Romance', 'A womanizing city man meets Tillie in the country. When he sees that her father has a very large bankroll for his workers, he persuades her to elope with him.', 'Mack Sennett', 82, '1914-12-21', 'K', 'en', 'https://image.tmdb.org/t/p/w500/cSHJ3i426ZdedU5tEAc7bVEf798.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (91, 'The Undesirable', 'A young woman living in the country is told by her dying father that he is really her uncle and raised her as his own when her mother was sent to prison for killing her husband. Alone and not knowing her mother’s fate, Betty travels to the city in search of work. There she finds employment as a maid in the house of a wealthy couple and their dashing son, Nick, with whom she falls in love...', 'Michael Curtiz', 63, '1915-03-20', 'P', 'hu', 'https://image.tmdb.org/t/p/w500/8fl5LvoCxJSljizIwOzsfaERhY4.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (92, 'Uncle Tom''s Cabin', 'The first screen adaptation of Harriet Beecher Stowe''s novel to star a black man in the title role.', 'William Robert Daly', 54, '1914-08-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/cU50uH15n7rB2T1IcmvhGfM5pzG.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (93, 'The Virginian', 'A good-natured but chivalrous cowboy romances the local schoolmarm and leads the posse that brings a gang of rustlers, which includes his best friend, to justice.', 'Cecil B. DeMille', 55, '1914-09-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6174WKsZ8CRtX4Aw4i48Cbz4Nbq.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (94, 'The Wishing Ring: An Idyll of Old England', 'Giles Bateson gets expelled from college for misconduct. His angry father, the Earl, sends him a message: "Never let me see you again until you have earned a half crown and proven yourself worthy of confidence."', 'Maurice Tourneur', 60, '1914-11-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/c8GZ615S46zVulnAclt5H7poBiZ.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (95, 'The Woman in Black', 'Young gypsy girl Mary, is seduced by the immoral Robert Crane and abandoned. She is exiled from the gypsies and, along with her mother Zenda, known as "The Woman in Black," she vows revenge. Meanwhile, Crane blackmails Stella Everett''s father into forcing her to marry him, even though she loves Frank Mansfield, Crane''s rival for a congressional seat. Frank wins, but Stella still faces the prospect of marriage to Crane until Zenda comes to her with a plan. On their wedding day, after the vows are recited, when Crane lifts the veil from his wife''s face, he is shocked to discover, that his new bride is Mary. Now Stella and Frank are free to marry, and Zenda has gained her revenge.', 'Lawrence Marston', 55, '1914-11-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/n2l23UkgzUVRmYkrnlmCYAYfLi3.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (96, 'The Wrath of the Gods', 'An American sailor falls in love with a fisherman''s daughter and convinces her that Jesus is more powerful than the gods who have cursed her.', 'Reginald Barker', 56, '1914-06-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bt4rSuVhRrKmWtpZyn2Ydegp2Yh.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (97, 'Alias Jimmy Valentine', 'After robbing a bank, a criminal is wrongfully pardoned from prison.', 'Maurice Tourneur', 65, '1915-02-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sJqFv3GofZ2piY1jZ4FvSXdP8yv.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (98, 'Alice in Wonderland', 'Alice goes with her sister to a picnic and then she falls asleep and starts dreaming about a wonderland full of talking animals and walking playing cards.', 'W.W. Young', 59, '1915-01-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6R12mA8mHhjcpo7V9OkMBU4Mnqd.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (99, 'The Arab', 'An old sheik punishes his son Jamil for robbing a caravan by giving his horse to the wronged merchant. The horse is sold to a Turkish general then given to a Christian missionary Mary Hilbert. Jamil takes it from her but then, after falling in loves, save her and her father. When his father dies, Jamil must relinquish Mary to become the new sheik.', 'Cecil B. DeMille', 50, '1915-06-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/r6S0qvUB4a1EFpsQa6pWj8iBqtw.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (100, 'The Birth of a Nation', 'Two families, abolitionist Northerners the Stonemans and Southern landowners the Camerons, intertwine. When Confederate colonel Ben Cameron is captured in battle, nurse Elsie Stoneman petitions for his pardon. In Reconstruction-era South Carolina, Cameron founds the Ku Klux Klan, battling Elsie''s congressman father and his African-American protégé, Silas Lynch.', 'D.W. Griffith', 195, '1915-03-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pNpOXpQI5GSUfiWypubYtMh9928.jpg', 'https://www.youtube.com/watch?v=a9UPOkIpR0A', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (101, 'The Captive', 'During the Balkan Wars, Sonia is a young woman living in Montenegro and left to care for her younger brother Milos and the family farm while elder brother Marko goes off to battle. Unable to handle the daily tasks following her brother’s tragic death, help comes in the form of Mahmud Hassan, a captured Turk nobleman, now a prisoner of war. Tasked with helping Sonia, their initial frosty relationship soon melts into romance. As the war rages on Sonia, Mahmud and Milos will face near-insurmountable obstacles in their quest for a better life amidst the hell of war.', 'Cecil B. DeMille', 50, '1915-04-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hMD50brIA1o9LGkVFAoASHLuoOd.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (102, 'Carmen', 'Hot-blooded gypsy Carmen attempts to seduce Don Jose, a lawman sent to thwart a gang of illegal smugglers in Spain. Carmen''s plan backfires when Don Jose''s passion for the gypsy girl escalates into a jealous rage as she spurns him for her bullfighter beau, Escamillo, with tragic results.', 'Cecil B. DeMille', 59, '1915-10-31', 'K', 'en', 'https://image.tmdb.org/t/p/w500/kQteMuTH7agRQ6S0ZSwJOVF6hBG.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (103, 'Carmen', 'A Spanish soldier falls under the spell of a fiery gypsy girl named Carmen. His obsession with her leads to his ruin.', 'Raoul Walsh', 50, '1915-11-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qdySshER4tJFeEETe0VjkBxZj7H.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (104, 'Charley''s Aunt', 'Charley Wyckham and Jack Chesney pressure fellow student Fancourt Babberly to pose as Charley''s Brazilian Aunt Donna Lucia. Their purpose is to have a chaperone for their amorous visits with Amy and Kitty, niece and ward of crusty Stephen Spettigue. Complications begin when Fancourt, in drag, becomes the love object of old Spettigue and Sir Francis Chesney.', 'Scott Sidney', 80, '1925-02-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ifdNB5YQgpmebbh9vXOT1YhftHk.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (105, 'The Cheat', 'A venal, spoiled stockbroker''s wife impulsively embezzles $10,000 from the charity she chairs and desperately turns to a Burmese ivory trader to replace the stolen money.', 'Cecil B. DeMille', 59, '1915-12-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1cnktg7gG1HutqKQ47jgcAWsP9R.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (106, 'Children of Eve', 'An illegitimate child of the slums comes to faith. Later, she chooses to labor in a canning factory in order to investigate its poor conditions, not realizing she has a significant connection to the cold-hearted factory owner.', 'John H. Collins', 73, '1915-11-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dmaiRmb2X8jdoQXMYS6vjvA5iSj.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (107, 'The Coward', 'Set during the American Civil War, Keenan stars as a Virginia colonel and Charles Ray as his weak-willed son. The son is forced, at gunpoint, by his father to enlist in the Confederate army. He is terrified by the war and deserts during a battle. The film focuses on the son''s struggle to overcome his cowardice.', 'Reginald Barker', 69, '1915-11-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/Hh2MTqCEL6Hq91wfUIExXO8n7u.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (108, 'David Harum', 'The story of David Harum, a small-town banker, and how what he does and who he is affects the lives of everyone in his town, whether they--or he--realize it.', 'Allan Dwan', 68, '1915-02-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ktf4omdiE05blf6lJEkBiyx10F.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (109, 'The Disciple', 'Jim Houston, the "Shootin'' Iron" Parson, comes to Barren Gulch to reform the morals of the frontier community.', 'William S. Hart', 50, '1915-10-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/imTXx3MqKSS6Ez7gWiDpxc7VBb3.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (110, 'Double Trouble', 'Double Trouble is a 1915 American silent romantic comedy film written and directed by Christy Cabanne and stars Douglas Fairbanks in his third motion picture. The film is based on the novel of the same name by Herbert Quick. A print of the film is held by the Cohen Media Group.', 'Christy Cabanne', 55, '1915-12-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/mImPeTkMblrN8xbgzjfWohJ9AVq.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (111, 'Fanchon, the Cricket', 'A young wild girl, Fanchon, lives in a forest with her eccentric grandmother who is suspected by the villagers of being a witch. The unkempt Fanchon suffers from her grandmother''s sorceress reputation. One day the girl rescues a boy from drowning and they fall in love, but Fanchon won''t agree to marry him unless his father asks her. A year later the boy has fallen very ill and it is only the presence of the enchanting Fanchon that helps to restore his health.', 'James Kirkwood', 75, '1915-05-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kgVM2mzpQdq53x7TxdBVH4uBMGT.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (112, 'A Fool There Was', 'John Schuyler, a happily married lawyer, is appointed diplomat and sent to England. Due to an unfortunate accident, his wife and child can not come along with him. On the ship to England, Schuyler meets the notorious Vampire - a relentless gold digger who causes the moral degradation of those she seduces, first fascinating and then draining the very life from her victims.', 'Frank Powell', 67, '1915-01-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iM909o6J43zwWfWqjbAQXIXpaFO.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (113, 'Ghosts', 'Helen Alving leads an outwardly contented life. On the eve of the 10th anniversary of her husband''s death, she is about to open an orphanage as a memorial to him. To mark this occasion, her bohemian painter son Oswald has returned from Paris. Helen plans to take the opportunity to tell Oswald the truth about his father. But ghosts of the past erupt during an eventful evening, bringing the facade of civilised family life crashing down.', 'George Nichols, John Emerson', 58, '1915-05-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lewOc7lwBuGt20GxuU0Zr34Pgmo.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (114, 'The Girl of the Golden West', 'A saloon hostess loves Ramerrez, a notorious highwayman. Sheriff Jack Rance, who loves the girl too, instigates a card game that will determine the fate of all three of them. If she wins, the girl''s lover will go free; but if she loses…', 'Cecil B. DeMille', 45, '1915-01-04', 'K', 'xx', 'https://image.tmdb.org/t/p/w500/nXhoKALkoyZ1CGpK9cHhKQHVqN8.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (115, 'The Golden Chance', 'Despite her well-bred upbringing, Mary had disobeyed her family’s wishes and married Steve Denby, a petty thief whose penchant for booze has left them destitute. Mary answers an ad to be a society woman’s seamstress and is hired by Mrs. Hillary. Mr. Hillary is trying to close a deal with Roger Manning and entices him by inviting him, as a dinner guest, to meet the “prettiest girl in the world.” Upon learning that the “prettiest girl” is indisposed, Mrs. Hillary, realizing that Mary had good upbringing, enlists Mary as a substitute. Naturally Mary and Manning fall in love, and, since the deal still isn’t signed, the Hillary’s hire Mary’s services for the weekend.', 'Cecil B. DeMille', 74, '1915-12-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4zrTTB5AjHNPo6bL7pRax1JZskG.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (116, 'Hearts in Exile', 'In Czarist Russia, attractive Anna Ivanovna has consecrated her life to work among Russia''s persecuted poor. She dispenses food, medicine, and funds to the needy, from a busy charity headquarters. Two men, separate in station, are in love with Ivanovna: Poor doctor Paul helps as much as he can, and wealthy merchant Serge donates money. The relentless and lascivious Chief of Police, also attracted by Ivanova''s beauty and virtue, determines to possess her, and sentences all three to fifteen years in Siberia and East Russia on false charges.', 'James Young', 59, '1915-04-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/66Op6fn52LSOfLXLIKyWkkQr7pi.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (117, 'How Molly Malone Made Good', 'Molly, an Irish girl just hired by a New York newspaper, is assigned as a test a chain interview of celebrities that must be accomplished within a set amount of time. She goes through innumerable paths and obstacles to achieve the goal.', 'Lawrence B. McGill', 70, '1915-10-25', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/xYrfVGxHAil4EqoiwWlor2ccgbD.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (118, 'Blind Justice', 'On New Year''s Eve, the convicted murderer, Strong Henry, escapes from prison and collects his son from the orphanage. When he breaks into a local manor to get some milk for his child, he is surprised by a young woman, Eva. Out of pity, she decides to help the stranger, but unfortunately some of the manor''s other occupants wake up and call the police. Fourteen years later, Henry is released from prison. Convinced that Eva betrayed him, he sets out to take revenge and find his son.', 'Benjamin Christensen', 106, '1916-09-25', 'T16', 'da', 'https://image.tmdb.org/t/p/w500/57QHTW4kxZL3MD8wyMDSKwyXev9.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (119, 'The Italian', 'An immigrant leaves his sweetheart in Italy to find a better life across the sea in the grimy slums of New York.', 'Reginald Barker', 78, '1915-06-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/spFWzzHsIXa90LFPBj7tyjJ9H3S.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (120, 'The Lamb', 'Gerald, the somewhat frail son of a wealthy New York family, is bested at the beach by Bill, a strapping young cowboy from Arizona. His fiancée Mary, ashamed of Gerald''s "yellow streak", leaves him and goes by train to visit some friends in Arizona, with Bill in tow. Gerald follows them, and before long he and Mary winds up captured by Yaqui Indians and Gerald must prove to Mary that he is not the "weakling" she thinks he is by coming up with a plan for them to escape their captors.', 'Christy Cabanne', 56, '1915-11-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9yqyLnR756USqmDENpeVDYMA2WF.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (121, 'Life Without Soul', 'A young man gives life to a statue with disastrous results. Early adaptation of Frankenstein with the names changed.', 'Joseph W. Smiley', 70, '1915-11-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1oHldp7peZWcEE42TW9Zf3eB5ob.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (122, 'The Lily and the Rose', 'To the dismay of Allison Edwards, her bookworm, adoring neighbor, Mary Randolph, falls in love with and marries Jack Van Norman, a rich and handsome former football star. After a few months of marital contentment, Jack becomes infatuated with Rose, an exotic dancer.', 'Paul Powell', 50, '1915-11-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jQ8HGtgAdObDR5ZHXHtQPUMbNEW.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (123, 'Maciste', 'A young girl, pursued by a band of conspirators, hides in a movie theatre where she watches the film Cabiria. She determines to seek the aid of that film''s strongman, Maciste. When she locates him, he helps her overcome her enemies, but not without many thrilling and dangerous adventures.', 'Luigi Romano Borgnetto, Vincenzo Denizot', 67, '1915-05-02', 'T16', 'it', 'https://image.tmdb.org/t/p/w500/dY1oip8WZ5HHZ5L6DAJ5AwbAtnU.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (124, 'Madame Butterfly', 'The story of a Japanese woman and the tragedy that ensues when she loves an American naval officer.', 'Sidney Olcott', 61, '1915-11-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sEokDeuvSV9thLWO5MjMi8NoOe2.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (125, 'Madame de Thèbes', 'The story is wacky – a gypsy is cursed by her father, so that she has to deny her illegitimate son in order for him to have a successful life. She gives him to a well-to-do lady who has lost her own child. Later, he has grown up to be a politician who wants to become the foreign minister. He doesn’t know that his real mother is the famous Madame de Thebes, the fortuneteller who all politicians make sure to visit! This information falls into the hands of a rival, who tries to use it to ruin his career. Meanwhile, the rival’s attractive daughter is attacked by a ruffian and needs to be rescued… There are a lot of striking images in this film. You can see the beauty of them even if the state of the print is far from perfect. The Norwegian actress Ragna Wettergreen gives a haunting performance as Madame de Thebes, with wisdom and regret – and quite a few melodramatic gestures. Understatement was not the norm in those days.', 'Mauritz Stiller', 68, '1915-08-06', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/oxsTwZoduXJ6ZTR4Zd2qxK5pL6v.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (126, 'Martyrs of the Alamo', 'The story of the defense of the mission-turned-fortress by 185 Texans against an overwhelming Mexican army in 1836.', 'Christy Cabanne', 71, '1915-11-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vdIzRIByluBrg06dLGSWsxkGQ42.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (127, 'Old Heidelberg', 'Karl Heinrich is the heir to the throne of the small European principality of Rutania, but he''s a lonely child, not allowed to play with other children and knowing little about life outside the castle. When he reaches maturity, he is sent to attend the University of Heidelberg, and finds fellowshi with classmates and a blossoming love with Katie Ruder, his only friend during childhood and the niece of an innkeeper. However, political turmoil in Rutania forces him to return. War is declared. Heinrich returns to Heidelberg one last time to bid a somber farewell to his beloved Katie.', 'John Emerson', 63, '1915-11-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/f5RoQLHAZVZ77Y5Mwtiup141SOT.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (128, 'On the Night Stage', 'A stagecoach robber falls in love with a saloon girl. However, she falls for a pastor, who converts her and she marries him. The robber is so impressed by this that he decides to turn over a new leaf. However, a shady gambler sets his sights on the former saloon girl, and the robber has to protect her from his advances.', 'Reginald Barker', 62, '1915-04-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vv0sVikosFdNxpk8BstUl6XoooS.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (129, 'After Death', 'Young scholar Andrei, fascinated by haunting actress Zoia Kadmina, is surprised when she sends him a note. The two have a brief scheduled meeting, then three months later Andrei is shocked to learn she has died. He becomes obsessed with Zoia''s memory and decides he must find out all that he can about her.', 'Yevgeni Bauer', 46, '1915-12-29', 'T18', 'ru', 'https://image.tmdb.org/t/p/w500/ky6KhOfeL6B5tYJpjxf8BTdOMlu.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (130, 'Rags', 'Mary Pickford plays "Rags," a pretty but wild girl who defends her alcoholic father a disgraced bank cashier, no matter how he mistreats her. Enter a handsome engineer whose family had once fired Rag''s father for theft. Rags falls in love but realizes that marriage is a hopeless proposition considering her lowly place in society. But when she learns that her father plans to rob the newcomer, Rags betrays him to the sheriff, and he is shot in the ensuing battle.', 'James Kirkwood', 66, '1915-08-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zzFrNFFHCRXlrdzDnDYbuNIa4kI.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (131, 'Satan''s Rhapsody', 'A Faustian tale about an old woman who makes a pact with Mephisto to regain her youth, but in return she must stay away from love. After making the deal, she meets two brothers who fall in love with her.', 'Nino Oxilia', 44, '1917-07-31', 'T16', 'it', 'https://image.tmdb.org/t/p/w500/pkE7y47jbxkuXFumXsQQG2s0Yiz.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (132, 'The Raven', 'After a brief view of Edgar Allan Poe''s family background, his grandfather, David Poe, Sr., an Irish immigrant to America, and his father, David Poe, Jr., the poet''s life is depicted from the death of his mother and his subsequent adoption by John Allan, to his own tortured death in 1849. Expelled from the University of Virginia for incurring too many debts, Poe nonetheless courts and marries Virginia Clemm but is disowned by his foster father. While residing in Fordham, New York, Poe tries to earn a living as a writer but meets with little financial success. Overwhelmed by their impoverished state, Virginia dies and Poe sinks into a profound depression. Always a victim of alcohol and subject to hallucinations, Poe first imagines that his neighbor, Helen Whitman, is Virginia, then plunges himself into an elaborate delusion in which his wife''s spirit, various other spectres and a raven finally drive him to his own death.', 'Charles Brabin', 80, '1915-11-08', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/xbYzoE5kRF4juOdJjr3SUnP2Fd8.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (133, 'The Regeneration', 'At 10 years old, Owen becomes a ragged orphan when his mother dies. Abusive next-door neighbors the Conways take him in, and by 17, Owen has learned that might is right. At 25, he''s a career gangster: loitering, gambling and drinking in dens of iniquity. Marie Deering arrives in Owen''s area, eager to empower the impoverished, gang-affiliated youth through education. Owen slowly but surely leaves his old life behind, choosing the narrow path- all the while falling in love with Marie. Skinny, who''s taken over Owen''s role in the gang, reappears to him, spelling trouble.', 'Raoul Walsh', 72, '1915-09-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wNgKRJ8l5KKTmoOC7bqtRSRB43O.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (134, 'The Pride of the Firm', 'Der Stolz der Firma, meaning The Pride of the Business, is a classic German silent film from 1914. The film tells the story of a shrewd apprentice and is filmed in the comical style of director Lubitsch. This is one of the few Lubitsch films from World War I that wasn’t lost.', 'Carl Wilhelm', 40, '1914-04-30', 'P', 'de', 'https://image.tmdb.org/t/p/w500/pK9la4Y3WfcU3VJwcxt6sh1wH0T.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (135, 'Tillie''s Tomato Surprise', 'Tillie Todd gifts her wealthy Aunt Sally a dime-store tomato pincushion, falsely claiming it’s handmade. Cousin Percy exposes the lie, vying for Sally’s favor. At Sally’s birthday, Tillie’s suitor “The Bat” crash-lands his flying invention, inspiring Sally to take flight herself. Declared dead after vanishing for days, she wills Tillie the pincushion but leaves most of her estate to her pet monkey Jim, with Percy as eventual heir. Percy kidnaps Jim to hasten his fortune, framing Tillie for the crime. Pursued by police, Tillie is saved when Sally returns alive. In frustration, Tillie tears apart the despised pincushion—only to discover it stuffed with $10,000.', 'Howell Hansel', 66, '1915-09-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3QakvKHj8WK7yhDCxlf45KgcnxF.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (136, 'Trilby', 'The hypnotic Svengali controls the singing voice of a young starlet, but he cannot control her heart.', 'Maurice Tourneur', 59, '1915-09-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5wxVcMHfhXVKp2CMCSBSLqqfHhb.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (137, 'The Vampires or, The Arch Criminals of Paris', 'Paris is prey to an invisible terror against which the police can do nothing: a sinister organization that sows chaos and death. The intrepid journalist Philippe Guérande and his partner embark on a long crusade to put an end to the crimes of the Great Vampire and Irma Vep, his dangerous accomplice. (A ten episode movie serial.)', 'Louis Feuillade', 422, '1915-11-13', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/8jO0Zmd468zS9WRLHpwsKUowZAX.jpg', 'https://www.youtube.com/watch?v=Qf-s-jPsm4E', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (138, 'Young Romance', 'Two young clerks in a department store meet and fall in love during a seaside vacation in Maine, but part as strangers because, unknown to each other, both had been masquerading as upper-class ''swells'', just to see how the better half lives.', 'George Melford', 59, '1915-01-20', 'K', 'en', 'https://image.tmdb.org/t/p/w500/yPW9j5GJsgCuuKTgG1GJZb40FOA.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (139, '20,000 Leagues Under the Sea', 'Captain Nemo has built a fantastic submarine for his mission of revenge. He has traveled over 20,000 leagues in search of Charles Denver - a man who caused the death of Princess Daaker. Seeing what he had done, Denver took the daughter to his yacht and sailed away.', 'Stuart Paton', 99, '1916-12-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/edY5eDCC08OUKjS0k7zWUxYM9BB.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (140, 'American Aristocracy', 'A young man fights to overcome a piratical arms smuggler and to win the heart of a rich man''s daughter.', 'Lloyd Ingraham', 52, '1916-11-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mpvp6C5YBfoon0jeasWRPvJWS0Q.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (141, 'The Americano', 'Doug is an American mining engineer. Pres. Valdez of Paragonia wants him to reopen the country''s mines. Doug is not interested ... until he sees the President''s beautiful daughter, Juana. Valdez returns to Paragonia, but is deposed by Generals Sanchez and Garcia and locked in San Mateo Prison. The Americano arrives...', 'John Emerson', 54, '1916-12-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/foD4uCRRUzzecn32fKD5aaOhwse.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (142, 'The Aryan', 'Steve Denton, rich from years of prospecting, is fleeced by the citizens of Yellow Ridge. In his rage, he kidnaps the woman most responsible and makes her his slave in a desert hideaway.', 'William S. Hart', 50, '1916-04-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ikRr7T4hVXesX4n9rICRdbVNnM5.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (143, 'The Avenger', 'Hämnaren (The Avenger) was made in 1915, and was rediscovered in Berlin in 2001. It begins with a woman named Ester, who is reading a letter and crying. The letter says that a man named George won''t marry her, because he knows his father would never allow him to marry a Jewish woman. Ester dies of childbirth, and possibly a broken heart. Her suitor Jakob takes care of her son, who is named Josef, and sends George a note, accusing him of causing her death', 'Mauritz Stiller', 49, '1915-09-05', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/9svroAk57kb6kKRqoR6pvp7yI04.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (144, 'The Ballet’s Prima-donna', 'Lovers are torn apart by a noble''s desire for the female half of the couple.', 'Mauritz Stiller', 54, '1916-11-20', 'T13', 'sv', 'https://image.tmdb.org/t/p/w500/vb5If8jrb9t12beOg8laM9OqbNR.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (145, 'The Battle of the Somme', 'A documentary and propaganda film which shows the British Army''s preparations for, and the early stages of, the battle of the Somme.', 'Geoffrey Malins', 74, '1916-08-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xdeYhT7XiKZcabu4yaoPGBqsW6l.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (146, 'Beatrice Fairfax', 'Beatrice Fairfax, the original advice-to-the-lovelorn reporter and her friend and not-so-secret admirer Jimmy Barton investigate calls for help and escape exotic perils and dangers. Episodes include exciting and fun stories of baby-napping, blackmail, jewel thievery, disguise, counterfeiting, and the long-unseen episode featuring entrancing cult starlet Olive Thomas and the real New York Yankees and Giants playing a game in the Polo Grounds.', 'Leopold Wharton, Theodore Wharton', 300, '1916-08-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1TshMLvwfVuOQc2NwvYOEhuHZS1.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (147, 'The Queen of the Stock Exchange', 'Mine owner Helene has a crush on the manager. He is however, enamored with Helene''s cousin Lina.', 'Edmund Edel', 63, '1918-05-23', 'P', 'de', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (148, 'The Call of the Cumberlands', 'An aspiring New York painter returns home to the Kentucky mountains to settle a feud between two rival families.', 'Frank Lloyd, Julia Crawford Ivers', 63, '1916-01-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AgU9tYkTuMBMi7yycLadPQUT3lk.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (149, 'The Children in the House', 'A woman is stuck with an unfaithful husband until he is killed robbing a bank.', 'Chester M. Franklin, Sidney Franklin', 50, '1916-04-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yNKDiOdGk2U6ktOq939FsewF1c6.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (150, 'Christus', 'Antamoro''s CHRISTUS, epic in scale and ambition, and featuring decidedly otherworldly special effects, was released in 1916. Telling the story of the Life of Christ, the film is divided into three segments-- three Mysteries. The first of these includes the Birth of Jesus, the arrival of the Magi, Herod and the slaughter of the innocents, the flight into Egypt. The second Mystery features the expulsion of the merchants from the Temple, Mary Magdalene''s conversion and Christ''s entry into Jerusalem. The third Mystery is itself divided into three separate parts, which are The Passion, The Death and The Resurrection.', 'Giulio Antamoro', 97, '1916-04-08', 'K', 'it', 'https://image.tmdb.org/t/p/w500/uLTwa9ATsVRPCsCmSBudFXAhVkJ.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (151, 'Civilization', 'Count Ferdinand, a submarine commander and secret pacifist refuses to torpedo a defenseless passenger ship during wartime. His submarine is sunk in the following fracas. In the spirit world, Christ commends the captain, and returns to earth in the commander''s body to promote His message of peace.', 'Raymond B. West, Reginald Barker, Thomas H. Ince', 86, '1916-06-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7IeGb9MLyZP7599FdA5M36nIot7.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (152, 'The Cossack Whip', 'Feodor Turov, chief of the Russian Czar''s secret police, orders his Cossacks to attack a village he believes to be infested with rebels. The Cossacks attack the village and massacre almost everyone, and the young Katerina is whipped to death. Before escaping to England, her sister Darya swears to avenge her sister''s death. Years later--now one of the world''s most famous prima ballerinas--she returns to Russia. Turov falls in love with her and manages to secure a meeting. She coyly asks him to take her to see a prison first. As it turns out, what he has planned for her is nothing compared to what she has planned for him.', 'John H. Collins', 93, '1916-11-13', 'T13', 'xx', 'https://image.tmdb.org/t/p/w500/qE0py60DhGdsrCk0QJUtQBIctrT.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (153, 'Daphne and the Pirate', 'Philip de Mornay, a courtier in the French royal court of the 18th century, falls in love with Daphne La Tour, the daughter of a nobleman. Knowing that her family would never approve of their marriage, he takes her and hides her in a brothel, but is soon captured by pirates. Soldiers looking for women to bring with them to a settlement across the ocean in Louisiana raid the brothel and take the girls, including Daphne. Later on the trip to the new world their ship is attacked by pirates--and she discovers that her lover Philip is on board the pirate ship.', 'Christy Cabanne', 50, '1916-03-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9CjRmzrEkQmFNMfNrREggO0PEkR.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (154, 'A Daughter of the Gods', 'A sultan agrees to help an evil witch destroy a mysterious beauty if the witch will bring his young son back to life. A lost film.', 'Herbert Brenon', 180, '1916-10-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8xoKYA7UgGDBUlderoMxuJw65H0.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (155, 'The Devil''s Needle', 'Renee is a French artist''s model who uses morphine as an escape from the dull reality of her life. She recommends it to a neurotic artist because "it kindles the fires of genius." The artist quickly becomes addicted to the drug and the quality of his work begins to disintegrate. He takes on a new model, marries her, and starts her on the same path of moral degradation, until a guilt-ridden Renee decides to intervene in order to save them both. According to silent film historian Kevin Brownlow, THE DEVIL''S NEEDLE was banned by the state of Ohio, but the censor board reversed its decision after recognizing the positive message beneath the film''s scandalous surface. This special edition was mastered from a 35mm preservation print of the 1923 re-release version. The only known surviving copy, the element suffers significant nitrate decomposition during some scenes.', 'Chester Withey', 66, '1916-08-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7B7yCPlePUQXnAFkeps0U3DpIex.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (156, 'Diane of the Follies', 'Phillips Christy an amateur sociologist from a wealthy family, subscribes to the theory that people are shaped by their environment. When he falls in love with Diane, a showgirl from the follies, he sees a chance to prove his theory, but fate intervenes .......', 'Christy Cabanne', 50, '1916-09-24', 'T13', 'en', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (157, 'The Dumb Girl of Portici', 'Fenella, a poor Italian girl, falls in love with a Spanish nobleman, but their affair triggers a revolution and national catastrophe.', 'Lois Weber, Phillips Smalley', 115, '1916-01-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1SL8tAnWy97ce6lJpDEhzqelicS.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (158, 'Kiss of Death', 'After the respectable Dr. Monro was found dead, the housekeeper and two engineers testify in court. A case of commercial delinquency and bribery is reconstructed on that occasion. Sadly only about half the film exists today.', 'Victor Sjöström', 65, '1916-08-25', 'T16', 'sv', 'https://image.tmdb.org/t/p/w500/xKLYYHNLobIiIdFgDhyqhwtFrKm.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (159, 'East Lynne', 'An adaptation of the 1861 novel by English author Ellen Wood: The story of long-suffering Lady Isabel Carlisle cast in a modern setting.', 'Bertram Bracken', 74, '1916-06-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vV0TmpX6NE59CRRgpPmWEFTXRez.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (160, 'The Fall of a Nation', 'A sequel to DW Griffith''s The Birth of a Nation, by the same author, and now lost. It is considered the first film sequel ever made and recounts a fictional invasion of America by a united army from Europe.', 'Thomas F. Dixon Jr.', 75, '1916-06-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/dG9cEbXUg96IrHrjFjFLxHOqkre.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (161, 'Flirting with Fate', 'In the midst of an emotional depression, a man hires a murderer to kill him. But the despair soon passes, and the man must now escape the killer he''s hired to end his life.', 'Christy Cabanne', 57, '1916-01-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5dnIsCDWmB6otlGMRgR88HTLx8x.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (162, 'Friday the 13th', 'When a judge is financially ruined by Peter Brownley, a Wall Street millionaire, his daughter seeks revenge by getting a job in the tycoon''s office. She manages to discover information that she believes her father can use to recover his swindled money and do to Peter what he did to her father. However, she meets and falls in love with Robert, the son of the man who ruined her father.', 'Émile Chautard', 50, '1916-09-18', 'K', 'en', 'https://image.tmdb.org/t/p/w500/9rOjEQKp4G7PGDP9hEqpYU0vN9Z.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (163, 'The Prisoner of Karlsten''s Fortress', 'Count de Faber is working on a new type of explosive, but finds out that Professor Plussman has beat him to it. After an unsuccessful attempt to acquire the formula from Plussman, he breaks into the professor''s house, steals the formula, and kidnaps his daughter, Mary. He takes her to Carlsten Fortress.', 'Georg af Klercker', 61, '1916-11-14', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/p7czXAp8JlouMgAtn7C3s61kFKU.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (164, 'Deadly Gas', 'Hopson, a prestigious scientist, studies the effect of snake venom to cure many diseases of mankind. His son enlists in the army when the Great War breaks out. A series of circumstances will lead the scientist to change his way of thinking about values ​​and principles that until then he had as immovable.', 'Abel Gance', 71, '1916-09-01', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/wgO8saob0oVBtzUzi1WYcuJmKGO.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (165, 'Going Straight', 'A man and his wife both have criminal pasts, but have quit crime and are now respectable citizens. One day a member of their old gang shows up and threatens to expose them if they don''t help him pull a heist.', 'Chester M. Franklin, Sidney Franklin', 60, '1916-06-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5uFEReQ0fKFOsaQ35QyakuXsHo6.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (166, 'The Good Bad-Man', 'An outlaw calling himself Passin'' Through halts his "evil" ways long enough to help out some children in difficulty.', 'Allan Dwan', 50, '1916-04-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/17mj3WppuNYgYRaadHn9a3edgRm.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (167, 'Gretchen the Greenhorn', 'Gretchen Van Houck is just arriving in the USA, on a ship from Holland. She joins her father, who has already spent several years in America, where he owns an engraving business. In the tenement community where the Van Houcks live, there are residents of many nationalities. Gretchen soon becomes close friends with Pietro, a popular resident, and she also takes an interest in the widow Garrity and her children. Another resident, Rogers, is more mysterious. One day Rogers tells Mr. Van Houck that he could help him get a job printing money for the government. Van Houck eagerly agrees to try, but when he finds out what Rogers is really doing, he is placed in a painful dilemma.', 'Chester M. Franklin, Sidney Franklin', 58, '1916-09-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fCtPKifTYj0MDjh9L6CD2coBrYJ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (168, 'The Habit of Happiness', 'Douglas Fairbanks stars as "Sunny" Wiggins, who believes in eternal optimism and good spirits. This places Wiggins at odds with his staid, wealthy family, who decide to get even when he blithely invites a group of derelicts to his sister''s coming-out party.', 'Allan Dwan', 44, '1916-03-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/i6l4WpWcknoXkaqLVdxi42cAmfG.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (169, 'The Half-Breed', 'In an attempt to brand himself as a serious actor, the smiling swashbuckler Douglas Fairbanks starred in THE HALF-BREED (1916), a Western melodrama written by Anita Loos and directed with flair by Allan Dwan. Fairbanks stars as Lo Dorman, who has been ostracized from society because of this mixed ethnicity - his Native American mother was abandoned by his white father. When Lo catches the eye of the rich white debutante Nellie (Jewel Carmen), he becomes a target for the racist Sheriff Dunn (Sam De Grasse), who wants to break them up and take Nelli for his own. This love triangle becomes a quadrangle with the arrival of Teresa (Alma Rubens), who is on the run from the law. Through fire and fury Lo must decide who and what he truly loves.', 'Allan Dwan', 72, '1916-07-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/d66a73MZGiEfmD1KmTf7WdYeam5.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (170, 'The Sea Vultures', 'Two smugglers meet two customs officers at sea, and happen to kill them. The story continues fifteen years later when a son of one of the officers and a smuggler''s daughter fall in love with each other.', 'Victor Sjöström', 44, '1916-01-31', 'T16', 'sv', 'https://image.tmdb.org/t/p/w500/o6IhllufNXl8TTYaTsWiZJ4Q0m6.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (171, 'Hell''s Hinges', 'When Reverend Robert Henley and his sister Faith arrive in the town of Hell''s Hinges, saloon owner Silk Miller and his cohorts sense danger to their evil ways. They hire gunman Blaze Tracy to run the minister out of town. But Blaze finds something in Faith Henley that turns him around, and soon Silk Miller and his compadres have Blaze to deal with.', 'Charles Swickard', 64, '1916-03-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nBM2Y1JB8NK8mV8U89ZEozZxvpG.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (172, 'His Picture in the Papers', 'Produced at the Reliance studio in Yonkers, New York, HIS PICTURE IN THE PAPERS solidly established Fairbanks as the American ideal of pop, vim, and vigor. Furthermore, the film brought him together with the two collaborators who were to play a profound role in the evolution of his screen persona: writer Anita Loos and her future husband, director John Emerson. The theme was, according to Emerson and Loos, "the great American love of publicity."', 'John Emerson', 62, '1916-02-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v6bqB7waxQx3MYci76tiie6d2kV.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (173, 'Tales of Hoffmann', 'This movie, directed by Richard Oswald, is based on the operetta "Les contes de Hoffmann" by Jacques Offenbach (1819-1880), which is a genial musical potpourri from various short stories and novels by the Prussian writer, composer, painter, lawyer and judge E.T.A. Hoffmann (1776-1822). While Hoffmann''s literary work was longtime considered to be merely fantastical, it was finally researched, in the last years, according to its metaphysical background. Characteristic for Hoffmann''s work is his life-long fight against rationalism and for the revelation of nature morte, culminating mostly in carnival-like scenes anticipating literary techniques only described in the works of Bachtin and Bachelard.', 'Richard Oswald', 71, '1916-02-26', 'P', 'de', 'https://image.tmdb.org/t/p/w500/2qfeFBHwDHIj5qdNimGdSd7PCC4.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (174, 'The Artificial Man', 'Part of the artificial-creature series encompassing Der Golem (1914 and 1920), Alraune (1918, 1928, 1930) and Metropolis (1926), ''Homunculus'' was the most popular serial in Germany during World War I even influencing the dress of fashionable Berlin. Foenss, a Danish star, is the perfect creature manufactured in a laboratory by Kuehne. Having discovered his origins, that he has no ''soul'' and is incapable of love, he revenges himself on mankind, instigating revolutions and becoming a monstrous but beautiful tyrant, relentlessly pursued by his creator-father who seeks to rectify his mistake.', 'Otto Rippert', 69, '1916-08-18', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/hYdwfZrgV3QeUr0eAeiS9B06wJE.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (175, 'Hoodoo Ann', 'A teenage orphan (who believes herself to be "hoodooed") is taken in by a childless couple and quickly falls for the boy next door; Her luck seems to have changed. But the idyll is broken up after a trip to the movies-- It seems the ''hoodoo'' has returned after she tries to replicate what she''d seen on the screen.', 'Lloyd Ingraham', 65, '1916-03-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/e4TFrBvo7ol3cRTEGkmK8DYSuf7.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (176, 'Idle Wives', 'Characters in the film attend a movie titled ''Life’s Mirror'', where they see parallel, cautionary versions of their own lives. Only the first two of the original seven reels survive.', 'Lois Weber, Phillips Smalley', 30, '1916-09-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hTKhAmPFY2gDz8NWPyqPV9FUCJK.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (177, 'The Innocence of Ruth', 'The young Ruth Travers, left an orphan after the death of her father financially ruined by Mortimer Reynolds, is welcomed at home by Jimmy Carter, a young millionaire who becomes her guardian. Ruth''s winsome qualities gradually win Jimmy''s heart. Meanwhile at a Charity Ball, Ruth meets Mr. Reynolds, who is contriving to ruin her virtue.', 'John H. Collins', 59, '1916-01-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cHZX6L5nxAUJG1eWNdZjo1DpDgV.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (178, 'An Innocent Magdalene', 'When Dorothy''s Southern, aristocratic father Colonel Raleigh refuses to let her marry Forbes Stewart, a Northern gambler, the couple elopes. When Dorothy soon thereafter becomes pregnant, Forbes vows to reform, but authorities arrest him on a gambling charge, and he serves a year in prison. During that time, and just before the birth of the baby, a woman comes to Dorothy and claims to be Forbes'' wife. Stunned, Dorothy returns to her father, but the colonel throws her out, and so, on her own, she has her baby, whom the community believes to be illegitimate. Convinced that she has sinned, Dorothy is about to kill herself when Forbes, just out of jail, finds her and explains that the other woman simply had been an ex-sweetheart trying to win him back.', 'Allan Dwan', 50, '1916-06-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ezST2vhpuQrJJcqPLeGQpckwLxj.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (179, 'Intolerance: Love''s Struggle Throughout the Ages', 'The story of a poor young woman, separated by prejudice from her husband and baby, is interwoven with tales of intolerance from throughout history.', 'D.W. Griffith', 197, '1916-09-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lJCabs4TMOsKfnl0BmA5Hf16Ezb.jpg', 'https://www.youtube.com/watch?v=f0yEkRCpCmw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (180, 'The Intrigue', 'A sci-fi/espionage film in which world powers vie for control of a death ray during World War I as an undercover countess infiltrates enemy ranks to prevent them from getting their hands on the weapon.', 'Frank Lloyd', 64, '1916-10-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pZ58GApJWapaIxSaRSrfznP3Pow.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (181, 'Judex', 'When an unscrupulous banker ruins his family, a young man swears to bring him to justice, so he adopts a new identity, the mysterious Judex, and ominously disguised and sunk into the muddy path of vengeance, punishes the crooks and protects the innocents. (Originally a twelve-part epic serial.)', 'Louis Feuillade', 317, '1916-12-16', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/t01u9TqcExE6bEqiyMGsImyjRoZ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (182, 'King Lear', 'An aging King invites disaster, when he abdicates to his corrupt, toadying daughters, and rejects his loving and honest one.', 'Ernest C. Warde', 63, '1916-12-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/v0TCMsgx0fBgUcDlOcNyZrC6yMv.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (183, 'Less Than the Dust', 'Young Hindu woman Radha, becomes best friends with Captain Raymond Townsend during his service in India, but he soon goes back to England to tend to the estate of an uncle who has just died. Then, Ramlan, the sword maker who raised Radha, is arrested for taking part in an anti-British uprising, and before he goes to jail, he decides to tell Radha the story of her birth, her real father, Captain Brooke, died of a drug overdose, and her destitute mother then entrusted her to Ramlan. After learning about her background, Radha goes to England to claim her rightful inheritance from the estate of her late grandfather, who is also Raymond''s uncle. Raymond is delighted to discover that his Hindu friend is really a white woman, and after dividing the estate with Radha, he brings the fortune back together by marrying her.', 'John Emerson', 93, '1916-11-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vnCIUbHEdXv3ib0mzW8hOo5wgDO.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (184, 'Little Mary Sunshine', 'Just after Bob''s fiancée breaks off their engagement, he meets young Mary, whose mother has just died, and the two of them comfort each other.', 'Henry King', 46, '1916-03-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5WEHwMLkgKbm6NqE3ikFkY2BNC5.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (185, 'The Lottery Man', 'A young man proposes a lottery with himself as the prize in marriage. However he finds himself very much in love with a woman other than the winner.', 'Leopold Wharton, Theodore Wharton', 50, '1916-06-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hAejJ6K5gk2bxkGUVlmx0y1h3sb.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (186, 'The Warrior', 'A soldier of near-superhuman strength fights battles in the First World War and wages a private war to rescue a young woman from the castle where she is imprisoned.', 'Giovanni Pastrone', 94, '1916-12-06', 'T16', 'it', 'https://image.tmdb.org/t/p/w500/d6cetT2faBiGhid66HphhTAix7i.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (187, 'Manhattan Madness', 'Steve O''Dare, a young New Yorker who has gone off to Wyoming to be a cowboy, returns to New York to sell some cattle. He bores his friends with tales of the exciting Western life, so they plot to trick him with a mock abduction. But although Steve falls for the gag, he ends up turning the tables on his friends.', 'Allan Dwan', 50, '1916-10-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bsfbGt7ji4W2dbEngb1DTh8FuEU.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (188, 'The Matrimaniac', 'A young couple attempts to elope, with the bride''s irate father in hot pursuit. The train stops briefly and the young man dashes off to find a minister, but before he can get himself and the minister onto the train, it leaves, carrying his bride-to- be away. Now the young man, minister in tow, pursues his bride while her father and a horde of lawmen pursue them both.', 'Paul Powell', 46, '1916-12-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4UGbI5ee4TdLFNTUNgVdH7C5rdJ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (189, 'Poor Little Peppina', 'Holding a grudge against Robert Torrens and his wife, who live in Italy, a member of the Mafia kidnaps their infant daughter Lois. Fifteen years later, after having been raised by Italian peasants, Lois, now called Peppina, dresses as a boy and stows away on a ship to America in order to avoid a marriage to a particularly loathsome count. While aboard ship she befriends Hugh Carroll, an assistant district attorney, who arranges first-class transportation for the "boy." In New York, she once again meets her kidnapper, who fled to America after the crime. He forces Peppina to maintain the masculine disguise and to pass counterfeit bills for him, for which she is arrested. Peppina gladly exposes the kidnapper''s operation to the authorities, one of whom, Hugh, recognizes her as the "boy" he met on the ship. Then, once the kidnapper has been apprehended, Peppina is reunited with her parents, after which she and Hugh, who has finally discovered that she is female, get married.', 'Sidney Olcott', 48, '1916-03-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eyVrPxEjrOAzbxOQzUc3w9fbasX.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (190, 'The Revenge of the Homunculus', 'Richard Ortmann the artificial man (Homunculus) has become the head of the corporation that represents the capital and power of the country, but he has stopped believing in human love. All the more clear is his goal now: the annihilation of mankind.', 'Otto Rippert', 68, '1917-03-05', 'T16', 'de', NULL, NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (191, 'Reggie Mixes In', 'Reggie, a wealthy young man about town, is eager for excitement, so he takes to visiting the rougher sections of the city in search of thrills. He meets and falls for a cabaret singer, but she turns out to be the inamorata of the local gang boss. The gangster sends his men after Reggie, but eventually it comes down to a duel between the two men themselves.', 'Christy Cabanne', 50, '1916-06-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7Wyie7vmOzSU7yyLPR20WBoMe6f.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (192, 'The Return of Draw Egan', 'A small town marshal’s secret past as an outlaw comes back to haunt him when an old associate shows up and threatens to expose his former dark deeds.', 'William S. Hart', 52, '1916-10-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7MrBXHdYfMnnLj2TR13kW4pGDO3.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (193, 'Rübezahl''s Wedding', 'In this film, the people of a Tyrolean town climb up into the nearby mountains, searching for a place where they can hold a picnic and a spring festival: ideally, a place where they can eventually erect dwellings and cultivate crops. Led by the local nobleman (Arthur Ehrens), they find an appropriate spot, and the festivities begin. Some children briefly perform a charming folk dance. Suddenly the Rübezahl arrives and threatens to kill all the townsfolk if they don''t leave immediately.', 'Paul Wegener, Rochus Gliese', 83, '1916-01-01', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/4wkHi8nwKJzEjReK7oTZdfiapN6.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (194, 'Pinkus''s Shoe Palace', 'Sally Pinkus is an German-Jewish boy who takes a job as a shoe store clerk after being expelled from school for goofing around. Soon fired for trying to court the owner''s daughter, Pinkus lands another job in a more ''upmarket'' shoe salon, only to be fired again, before charming a rich benefactress to fund his ultimate dream: Pinkus'' Shoe Palace.', 'Ernst Lubitsch', 45, '1916-06-09', 'P', 'de', 'https://image.tmdb.org/t/p/w500/2QEwezlaorNhJ3zE4qnLSWNGy2Y.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (195, 'Sherlock Holmes', 'When a couple of scammers hold young Alice Faulkner against her will to discover the whereabouts of letters whose dissemination could cause a scandal affecting the royal family, Sherlock Holmes decides to take over the case. (Considered lost, a copy was found in 2014, in the vaults of the Cinémathèque Française.)', 'Arthur Berthelet', 117, '1916-06-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qxbSnrfaPbfM2jYuS7OGOfExtOK.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (196, 'Shoes', 'A young working girl, struggling to support her family on her meager salary, desperately wishes for a new pair of shoes.', 'Lois Weber', 50, '1916-06-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vICb3QVdn8uyUl5FG87v8TBhFli.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (197, 'Snow White', 'Snow White, a beautiful girl, is despised by a wicked queen who tries to destroy her. With the aid of dwarfs in the woods, Snow White overcomes the queen.', 'J. Searle Dawley', 63, '1916-12-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lejbiFj0Vg5bGWZSLWvvj8zSdK4.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (198, 'The Social Secretary', 'An attractive young girl struggles to hold a job as she deals with unwanted romantic advances from her boss.', 'John Emerson', 52, '1916-09-16', 'K', 'en', 'https://image.tmdb.org/t/p/w500/tu67XQyaYk3KGTpQvawu5slGisC.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (199, 'Sold for Marriage', 'A poor Russian girl''s beauty leads her unscrupulous uncle to bring her to the United States. There he is going to sell her into a marriage with a rich old man she has never met. But her lover, an returning immigrant visiting Russia from the U.S., sails on the same ship. When they arrive he learns, to his surprise, that the American police, unlike those of his native country, are not oppressors of the poor, but friends that will aid in securing the release of his beloved Marfa.', 'Christy Cabanne', 55, '1916-04-15', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/bB08CePSYNew9BAfRewTG2LkWra.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (200, 'Thaïs', 'The beautiful Thaïs Galitzy plays Vera, a Slavic countess, a seductress who drags married men to the brink of ruin. When she seduces the husband of her best friend, all involved meet a nasty fate.', 'Anton Giulio Bragaglia', 35, '1917-10-04', 'T13', 'it', 'https://image.tmdb.org/t/p/w500/kYx4L0cm0SlCXLmJcjnvQgLIAl2.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (201, 'The Three Godfathers', 'Three outlaws fleeing a posse through the desert come upon a dying woman and her baby in a wagon. Before she passes away, she makes the men promise to take care of her baby and get it safely through the desert.', 'Edward LeSaint', 60, '1916-06-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ufNC6Gt2OiSvQdvLjaclUk4npuB.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (202, 'The Royal Tigress', '"Tigre Reale" (1916) was the film that consolidated Frau Menichelli''s stardom, a film more than suitable for her performing skills and silent idiosyncrasy that any silent diva would kill to star in… In "Tigre Reale", Frau Menichelli performs the part of Frau Natka, a Russian countess with a troublesome past and an uncertain future. She was married to a revolutionary and the matrimony ended in tragedy. She likes to flirt with men but due to her traumatic sentimental past, she doesn''t allow herself attachments. That is until she meets a young diplomat who will help her to make up her mind and exorcize her old sentimental traumas.', 'Giovanni Pastrone', 80, '1916-11-09', 'P', 'it', 'https://image.tmdb.org/t/p/w500/30JdKhinReDareP5o8ncFuOOlGw.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (203, 'The Wings', 'The story is that of a conniving countess coming between a gay sculptor, Claude Zoret, and his bisexual model and lover, Mikaël, ultimately leading to Zoret''s death in a raging storm at the base of a statue of Mikaël as the mythological Icarus. The film is missing 19 minutes of run time.', 'Mauritz Stiller', 50, '1916-09-04', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/q0MJCPnphW0NRLhynK7aZeIX73R.jpg', 'https://www.youtube.com/watch?v=_dRk7z8Eiyo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (204, 'Where Are My Children?', 'Walton, the District Attorney, yearns to have children. Soon after defending an author on trial for publishing indecent literature, Walton discovers a secret his wife and her socialite friends have been hiding from him.', 'Lois Weber, Phillips Smalley', 64, '1916-04-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uSVlcp0kIEhATg5BGhDnLRSAIL6.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (205, 'The World and the Woman', 'In "The World and the Woman", Jeanne Eagels plays Mary, a prostitute (which is implied by her walking the streets and being hassled by policemen) who reluctantly takes a better position at a country lodge as a maid. In this woodland community, she attends church and the path to Salvation becomes clear to her. Through Mary''s faith, the injured folk of the countryside are healed. However, her old employer, whose lustful advances she''d previously spurned, still has designs on her.', 'Eugene Moore, Frank Lloyd', 66, '1916-11-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/i6VbC4Efw7Zy6e7wPfhJrpil8hf.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (206, '''49 – ''17', 'A judge who had taken part in the gold rush of 1849 hires an acting troupe to recreate the experience in this rather fanciful silent Western. The make-believe turns serious when a real gold mine is discovered nearby and a local girl is kidnapped by a nasty gambler.', 'Ruth Ann Baldwin', 69, '1917-10-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/h1vNqbkxhQlBPlp10tQxo9hCBLx.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (207, 'Aladdin and the Wonderful Lamp', 'In Bagdad, Princess Badr al-Budur, the daughter of the Sultan, falls in love with Aladdin, the son of a poor tailor, and rejects the suit of evil alchemist al-Talib, her father''s choice. Al-Talib consults his Evil Spirit, who advises him to find the magic lamp hidden in an underground cave. Unable to get it himself, al-Talib hires Aladdin, who secures the lamp but keeps it when he realizes al-Talib''s wickedness. With wealth obtained through wishes, Aladdin courts the princess. After the lamp changes hands between al-Talib and Aladdin, al-Talib steals it and abducts the princess to the desert. Aladdin follows with only a gourd of water. Suffering from thirst and exhaustion, Aladdin nearly succumbs, but the horsemen of the Sultan, who learned of his daughter''s abduction, ride up and rescue Aladdin.', 'Chester M. Franklin, Sidney Franklin', 80, '1917-10-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sR2axaZxCERetwSt8p0z2pXyLDj.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (208, 'Alexander the Great', 'In a small provincial town there is a hotel run by one of those eccentric cooks of long ago who made generous meals that have nothing in common with the extravagant restaurateurs of nowadays and their meagre menus. The manager is named after Alexander the Great and in his restaurant the town bourgeoisie meet and discuss various issues, especially matters of the heart. Morals are part of the conversations and prove to be complicated issues even for strict and serious Nordics. 28 minutes of runtime are missing and presumed lost.', 'Mauritz Stiller', 110, '1917-11-12', 'T13', 'sv', NULL, NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (209, 'Betsy Ross', 'Revolutionary War heroine Betsy Ross finds herself in competition with her sister for the affections of a British soldier.', 'George Cowl, Travers Vale', 59, '1917-09-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zX0GeDHQR9fzzFo0wGSbecFmAN0.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (210, 'Blue Jeans', 'June, a young orphan, is befriended by Perry Bascom when he shares his lunch with her on the road to Rising Sun. They soon fall in love and marry, only to find out that a woman in Perry''s past has come to town to make trouble. Teaming up with the local political bully, the schemers set out to make Perry''s life miserable, but June sticks by her husband to the end.', 'John H. Collins', 84, '1917-12-10', 'K', 'en', 'https://image.tmdb.org/t/p/w500/ArQIzQeOA73lbxTUYhufLqCajSe.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (211, 'Bucking Broadway', 'On a ranch in Wyoming, one of the cowboys, Cheyenne Harry (Harry Carey), falls in love with his boss''s daughter. But she decides to elope to the city with Captain Thornton, a wealthy visitor to the ranch. She quickly discovers that life in the city is not what she expected. Cheyenne, devastated by the loss of his fiancée, decides to go to the city to find her, and in the end rescues her from the grips of Captain Thornton and from the extravagant and decadent way of life in the city.', 'John Ford', 54, '1917-12-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eOm0hmostHIjWo5Xu8l7NOuuIL3.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (212, 'The Cinderella Man', 'When Marjorie Caner returns from abroad, she is quite lonely in her millionaire father''s big house. Learning that a young poet, Anthony Quintard, is living in poverty next door while working on the libretto of a great opera, she skips across the roofs and brings him a Christmas banquet. The poet sees Marjorie, and knowing that he detests wealth, she pretends to be the secretary of the Caner family.....', 'George Loane Tucker', 60, '1917-12-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/l9OydgjvMpPnmAunqbhlrYhFnXe.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (213, 'Cleopatra', 'The story of Cleopatra, the fabulous queen of Egypt, and the epic romances between her and the greatest men of Rome, Julius Caesar and Antony. Only a small fragment of this film survives.', 'J. Gordon Edwards', 125, '1917-10-14', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/30nI26oGkZiJ3YAOEYLI45XwbTB.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (214, 'Down to Earth', 'A healthy outdoors-type follows the girl he loves to a resort for wealthy hypochondriacs. In order to prove to her and the other patients that their "illnesses" are all in their minds, he hatches a scheme to take them on a boat ride, then get them stranded in the wilderness, where he can show them that they can live without their pills, doctors and "cures".', 'John Emerson', 70, '1917-08-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/r0A0n5wCn2KNsqaQVgLeO0ADcoz.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (215, 'The Man from Painted Post', 'In order to find out who''s behind a cattle rustling operation that''s hurting ranchers, a detective for the Cattleman''s Protective Association pretends to be a tenderfoot from back east who''s just arrived in the area and doesn''t know how to ride, rope or shoot.', 'Joseph Henabery', 58, '1917-09-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/c8bUBdIQk13H2Vve6LdrolkIq5Y.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (216, 'Fear', 'A millionaire steals an ancient idol causing some natives call upon him a terrible curse.', 'Robert Wiene', 73, '1917-09-21', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/wCToHeo3KnXkEKhpdsGMhkPnp7e.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (217, 'The Secret of Delft', 'The secret from the title is the lost recipe for shiny Delft pottery, that Jan Vogel is desperately trying to rediscover. For his attempts he needs platinum, but the funds run out because the factory owner Van Haaften has lost his money in stock-speculations. Luckily for Jan, he finds a farewell letter in the park, including a large sum of money. Meanwhile, the owner''s son Leo confesses his love for Jan''s daughter Annie, but Van Haaften forbids their marriage.', 'Maurits Binger', 70, '1917-03-09', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/iBTiFAlLS4LGS07fsluVUMnWmD9.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (218, 'A Girl''s Folly', 'A restless young girl yearns to leave her rural environment and "get away from it all". One day she stumbles upon a film crew shooting a western near her home. She makes friends with the film''s leading man, who encourages her to try her luck as an actress. So she leaves her small town and goes to the big city to break into the picture business. However, things don''t turn out quite the way she planned.', 'Maurice Tourneur', 65, '1917-02-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/knzmVdSpFxSnlNB2vkONfeVbX0w.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (219, 'The Heart of Texas Ryan', 'To get in the good graces of his rancher boss’s daughter, cowboy Single Shot captures a cattle raider but then gets kidnapped by his gang of thieves.', 'E.A. Martin', 50, '1917-02-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lCMEHO1HGwFP8BsUXburk0AUHFQ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (220, 'Hilde Warren and Death', 'Hilde Warren, a famous actress, is impregnated by a convicted murderer and becomes plagued by visions of Death. Upon discovering her child is the image of its criminal father, Hilde must decide whether to allow it to live, or to kill it and risk the embrace of Death himself.', 'Joe May', 61, '1917-08-31', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/vvXjf9gLxLScm6j5xFvTPpAdsKn.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (221, 'A Trip to Mars', 'The navy captain Avanti Planetaros is inspired by his astronomer-father to travel through outer space to reach other worlds. He becomes an aviator and, along with the young scientist Dr. Krafft, the driving force behind the construction of a space-ship. Despite oppostion from the mocking Professor Dubius, Planetaros gathers a crew of fearless men and takes off. During the long voyage, the crew becomes restless; a mutiny is narrowly avoided. Finally, they reach Mars and discover that the planet is inhabited by people who have reached a higher stage of development, free of diseases, sorrow, violence, sexual urges, and the fear of death. Avanti falls in love with Marya, daughter of the Prince of Wisdom, the head of the Martians. Marya shares his feelings and decides to return with him in order to bring the wisdom of the Martians to the backward Earthlings. (stumfilm.dk)', 'Holger-Madsen', 81, '1918-02-22', 'P', 'da', 'https://image.tmdb.org/t/p/w500/41OY4EAtbxzTAWe13lzJSUlfi2U.jpg', 'https://www.youtube.com/watch?v=DjKyBofRLqM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (222, 'Joan the Woman', 'A WWI English officer is inspired the night before a dangerous mission by a vision of Joan of Arc, whose story he relives.', 'Cecil B. DeMille', 138, '1916-12-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/blIDLFaCsdGPGUXaOEptJ45nJ6F.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (223, 'Kidnapped', 'In Scotland in 1751, young David Balfour is shanghaied aboard a ship where he meets Jacobite rebel Alan Breck Stewart with whom he escapes to the Scottish Highlands, dodging the redcoats.', 'Alan Crosland', 64, '1917-05-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/muMxFsOTnkFjgXpZrFyFG2zzGWk.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (224, 'The King of Paris', 'The lives of two young men-- A virtuous artist who''s renounced a background of riches and a debonair swindler proclaimed by many the King of Paris-- intersect when the artist''s mother becomes the target of the kingly charlatan.', 'Olga Rakhmanova, Yevgeni Bauer', 64, '1917-12-06', 'T13', 'ru', 'https://image.tmdb.org/t/p/w500/zrY7SqYyjDKbUtuexkIFRPE0VOl.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (225, 'The Little American', 'A young American has her ship torpedoed by a German U-boat but makes it back to her ancestral home in France, where she witnesses German brutality firsthand.', 'Cecil B. DeMille, Joseph Levering', 63, '1917-07-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sB610f0BTWWtyWsST5VNxMsb0DU.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (226, 'A Little Princess', 'Little Sara Crewe is placed in a boarding school by her father when he goes off to war, but he does not understand that the headmistress is a cruel, spiteful woman who makes life miserable for Sara.', 'Marshall Neilan', 62, '1917-11-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5qpqn59J5eCKLyp4Oi6tNH21Sr3.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (227, 'Malombra', 'Marina di Malombra (Borelli) lives in a castle prior to her wedding. She begins to read letters written by an ancestor called Cecilia. She finds out that Cecilia was driven to her death by her uncle. Marina identifies with Cecilia and take revenge on her behalf by murdering her uncle.', 'Carmine Gallone', 75, '1917-01-01', 'T16', 'it', 'https://image.tmdb.org/t/p/w500/muAqfyDES0z36ysXEQ9Mi6hFva4.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (228, 'The Man Without a Country', 'Convicted in a revolutionary conspiracy, a man rashly states that he wishes never again to hear the name of the United States of America. The judge grants him his wish, sentencing him to life aboard a ship always at sea, aboard with sailors under orders never to let him hear of his homeland in any way. The punishment nearly destroys him, while changing him thoroughly.', 'Ernest C. Warde', 60, '1917-09-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vB0JD3jadKPLzcy2N4e6XNnJVTV.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (229, 'A Marked Man', 'Bandit Cheyenne Harry reforms because of the faith placed in him by Molly Young and her father. Soon, however, Harry is lured from the straight and narrow when he meets his old friend Ben Kent and consents to participate in Kent''s plan of robbing a stagecoach.', 'John Ford', 50, '1917-10-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gt5oRQFxTNLUzeSghCNbrTlau6J.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (230, 'The Torture of Silence', 'A doctor, specialist in pediatrics, has no time for his wife Marthe. She seeks solace in the arms of his brother. Unable to keep up the charade, Marthe attempts to shoot herself, but it is her lover who is mortally wounded.', 'Abel Gance', 70, '1917-03-06', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/vOECTljQaZpXKgvNSZiuwUnfxEU.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (231, 'A Modern Musketeer', 'A young man grows restless living in a small Kansas town, dreaming of the adventures of the Three Musketeers. So in hopes of becoming a modern D''Artagnan, he mounts his steed (a Model T Ford) and sets out across the West in search of excitement and adventure.', 'Allan Dwan', 68, '1917-12-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tbzIGfBckHtL5pCFZCdvGk0pMhB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (232, 'A Mormon Maid', 'This silent melodrama is set against the 1840s westward migration of the Mormons. Dora, a young woman, and her family are saved from an Indian attack by a Mormon community traveling to Utah. They join the wagon train. Dora is pursued by two men, one a recent convert, the other a scheming elder with a stable of wives. The Mormon elder wants her in his harem. When the mother kills herself from revulsion toward polygamy, the daughter must consider her own future and the man she loves. One of Mae Murray''s few surviving films, this was intended by Robert Leonard to be a thoughtful drama about the goods and evils of Mormonism, but today it is generally considered pure anti-Mormon propaganda.', 'Robert Z. Leonard', 68, '1917-04-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8eX6mWH3Br1pe2jT2UExT2wF2Is.jpg', 'https://www.youtube.com/watch?v=BiyIc3yqK-c', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (233, 'Mothers of Men', 'Dorothy Davenport as Clara Madison, a prominent lawyer, wins a judgeship over fellow Attorney Grant Williams, played by Willis L. Robards. Upon winning the prominent position as judge, Ms. Madison finds herself walking a political tight rope with enemies all around doing what they can to cause her down fall. Judge Madison convicts a murderer to death paving the way for her to be easily elected as the first female Governor. As Governor she is faced with a difficult dilemma. She has the power to pardon her husband who has been convicted of a serious crime, but to do so she’d be using her office for her own personal gain. “I must find some way to realize my ideals without sacrificing my husband. I must struggle on somehow for the sake of womanhood!”', 'Willis Robards', 60, '1917-01-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6cc3hVAmpjwHT3U1MCr0362G44f.jpg', 'https://www.youtube.com/watch?v=Ikw5XWXKCvw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (234, 'Mothers of France', 'A mother loses first her son and then her husband in the trenches of France during the First World War. She devotes herself to the French cause and to helping those wounded in the war.', 'Louis Mercanton, René Hervil', 74, '1916-01-02', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/aAZJ5LS5xDQ27FNiYTMUTAoq5Wz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (235, 'The Narrow Trail', 'Ice Harding, outlaw, tames a wild horse and names it King. Ice and his gang hold up a stagecoach and encounter San Francisco vice king Bates and his innocent niece Betty Werdin. Ice is taken with the young woman, but at first she sees nothing in him. But she begins to come around when her uncle tries to swindle Ice, and the outlaw himself undergoes a change of course under the influence of the girl.', 'Lambert Hillyer, William S. Hart', 68, '1917-12-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/XuHKjc4xPOhUgjSKcOKGOCNBls.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (236, 'On Dangerous Ground', 'Carlyle Blackwell stars as an American in Germany at the outbreak of World War I. A mysterious stranger bursts into his room and proclaims him her husband. What''s a gentleman to do? He poses as her husband to deliver "papers" to French headquarters. Adventure follows.', 'Robert Thornby', 72, '1917-01-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/i2bjnG0aMucuNCOhTa1mRwT5Rmi.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (237, 'Father Sergius', 'The story of Prince Stepán Kasátsky discovering his fiancée was the mistress of the Czar, so he then becomes a monk.', 'Yakov Protazanov', 112, '1918-05-14', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/ucuJAd4wNCozykHYq7WSJBNURzv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (238, 'Polly of the Circus', 'When circus aerialist Polly Fisher is injured, she is taken to the nearby home of minister John Hartley. The two fall in love and marry secretly. But when the news leaks out, the minister loses his pastorate over disdain by the parishioners for Polly''s background as a performer. Polly must decide whether to stay with the man she loves or leave him for the good of his calling.', 'Charles Horan, Edwin L. Hollywood', 80, '1917-09-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gdXpNyNN1i02NeI2ZBlY02YKcnD.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (239, 'The Poor Little Rich Girl', 'Gwen''s family is rich, but her parents ignore her and most of the servants push her around, so she is lonely and unhappy. Her father is concerned only with making money, and her mother cares only about her social position. But one day a servant''s irresponsibility creates a crisis that causes everyone to rethink what is important to them.', 'Maurice Tourneur', 75, '1917-03-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xTcoZ5DuCRCy2AAM7VGIG77pDjT.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (240, 'The Pride of the Clan', 'Donald MacTavish, the last chieftain of his clan on an island off the coast of Scotland, dies at sea. This leaves his only daughter, Marget, to assume the responsibilities of leadership. Marget''s burden is partially eased by her blossoming romance with Jamie Campbell. But there is a secret from Jamie''s past that neither of them know about.', 'Maurice Tourneur', 84, '1917-01-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/r8gnr3qOIifDgK3Jn4UvOLJkHnp.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (241, 'Raffles, the Amateur Cracksman', 'A.J. Raffles, an educated and handsome cricket champ with entry to the best social circles steals precious trinkets and jewels, purely for the love of the game and the thrill of the chase, outwitting police and detectives.', 'George Irving', 65, '1917-12-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yQNxymVVZEw16XI2zDZOqkbipQw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (242, 'Reaching for the Moon', 'A button factory worker has always dreamed that he was meant for better things, to be rich and famous and in "the company of kings". One day he discovers that he is indeed the only heir to the throne of a small European kingdom. However, there are forces at work who don''t want him to survive to take the throne.', 'John Emerson', 69, '1917-11-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/tE2QvxzpmiUSM75nxJGtNUgIKDF.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (243, 'Rebecca of Sunnybrook Farm', 'Behind in the mortgage on Sunnybrook Farm and barely managing to feed seven hungry mouths, mother sends young Rebecca off to Riverboro to be raised by her wealthy Aunt Miranda. The little girl is treated like a prisoner by her strict Aunt, yet she gamely does her best to get an education. When spoiled girls at school mock the spirited Rebecca as "missy poor-house," she soon makes them come to eat their words. Despite many difficulties, Rebecca manages to help the less fortunate and spread joy in Riverboro, dreaming that her reward will come when she is "all growed up." This version is notable for having been adapted by famed female screenwriter Frances Marion.', 'Marshall Neilan', 78, '1917-09-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/FE0KSHtjsHz5kYdGvQxViqLA5X.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (244, 'A Romance of the Redwoods', 'A young girl travels west to live with her uncle during the California Gold Rush only to find that he has been killed by Indians and his identity assumed by an outlaw.', 'Cecil B. DeMille', 91, '1917-05-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zVVlbHMn8tSEk7gMiL6Gdhv0kTF.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (245, 'Runaway Romany', 'Press agent "Inky" Ames, in a quandary to publicize showgirl Anitra St. Clair, convinces her to paint a birthmark on her shoulder and pose as millionaire mine owner Theodore True''s long-lost daughter.', 'George W. Lederer', 50, '1917-12-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/f4Ggbb0HOYXh64uiVdDXWPEMHbb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (246, 'Satan Triumphant', 'Pastor Talnoх furiously urges the flock to fight temptations, but he himself becomes a victim of temptation. In his house appears Satan, pushing the hero to theft and spiritual fall.', 'Yakov Protazanov', 87, '1917-10-21', 'K', 'ru', 'https://image.tmdb.org/t/p/w500/8MRlsWMyeFJUyCoy4MsEcl5HIPW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (247, 'The Scarlet Car', 'Paul Revere Forbes, an descendant of Paul Revere, is a teller at Cyrus Peabody''s bank. He learns that Cyrus and his son, Ernest, have speculated with $35,000 of the bank''s money, and the entire sum has been lost.', 'Joseph De Grasse', 50, '1917-12-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tzIxZY8R7WKdACGuHbL3oQZwtli.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (248, 'The Secret Game', 'In the office of Major Northfield, the quartermaster of the Pacific Coast, a leak has been discovered which may endanger the safety of American transports that are secretly carrying troops across the Pacific. Nara-Nara, a Japanese detective, is assigned to the case because his country has guaranteed safety to these transport ships. Nara-Nara believes that Northfield is guilty, although in reality it is Northfield''s secretary Kitty Little, a girl of German ancestry, who is passing information to Dr. Ebell Smith, a German agent. Nara-Nara falls in love with Kitty, but soon after discovers that she is the leak in the quartermaster''s office.', 'William C. deMille', 67, '1917-12-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eLfjWeLmNKEtfiMqe5OwGq2MWJ0.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (249, 'The Secret Man', 'Convict Cheyenne Harry escapes from prison in a garbage truck and boards a train, where he eludes capture with the help of passenger Henry Beaufort. Beaufort is returning to his wealthy uncle''s ranch, where earlier he had married Molly in secret because his uncle did not like her. Beaufort tells Pedro, who takes care of his child Elizabeth, to take her away because his uncle is coming, and Pedro, driving drunk, wrecks the wagon. Harry finds her and must protect her while still evading the sheriff.', 'John Ford', 50, '1917-09-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7kEirDtJwfAb3DqNdYedxVxrxOw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (250, 'Seven Keys to Baldpate', 'A writer bets a publisher friend that he can write a 10,000-word novel in 24 hours. The publisher takes the bet, and gives him the "only key" to his Baldpate Inn, which has been closed for the winter, so he can write in complete seclusion. Things start heating up, though, when a succession of people who also have keys to the inn begin showing up.', 'Hugh Ford', 65, '1917-10-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5zdJxv5IUxt4GhdngCwOGAMTRlL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (251, 'The Silent Man', 'A hard-working prospector enters the town of Bakeoven to stake his claim, only to have his rights stolen and his face on "Wanted" posters. He plans reprisal.', 'William S. Hart', 61, '1917-11-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ucZ8ubhXiSiyLaVkGT6UAQ5w8jN.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (252, 'Straight Shooting', 'Cattleman Flint cuts off farmer Sims'' water supply. When Sims'' son Ted goes for water, one of Flint''s men kills him. Cheyenne is sent to finish off Sims, but finding the family at the newly dug grave, he changes sides.', 'John Ford', 62, '1917-08-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/woebX5PK6A7npcs781fIlaD6grZ.jpg', 'https://www.youtube.com/watch?v=darotFrBNFM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (253, 'A Tale of Two Cities', 'At the outbreak of the French Revolution, Charles Darnay goes to Paris to rescue an imprisoned former family servant. He is himself imprisoned and condemned by the revolutionary forces there. His wife, the former Lucie Manette, is secretly loved by a gentlemanly wastrel, Sydney Carton. Carton embarks on a daring plan to save the husband of the woman he loves.', 'Frank Lloyd', 70, '1917-03-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vFuJ7kpoPpeYMdLRotVyWmeJHXJ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (254, 'Tepeyac', 'A man (Arroyo Carrillo) is sent to Europe on a diplomatic mission. The ship in which he travels is sunk by a German submarine. In Mexico, his girlfriend Lupita (Cota) receives a telegram with the news and looks for relief in La Virgen de Guadalupe, saint patron of catholic mexicans. After reading a book about the Virgin legend, Lupita falls asleep. Next morning, she receives good news, her boyfriend is alive. Together they go to La Villa del Tepeyac (a church devoted to La Virgen de Guadalupe) and thank for the miracle.', 'Carlos E. González, Fernando Sáyago, José Manuel Ramos', 63, '1917-08-17', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/eccHRe1Tt1sv1pMcnPNFOZNsZS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (255, 'A Man There Was', 'Terje Vigen, a sailor, suffers the loss of his family through the inflexibility of another man. Years later, when his enemy''s family finds itself dependent on his benevolence, Terje must decide whether to avenge himself.', 'Victor Sjöström', 56, '1917-01-29', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/ejxTovLF2vbcII1kz5vClkFt8np.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (256, 'Thomas Graal''s Best Film', 'Thomas Graal''s a screenwriter, is very fond of his secretary Bessie. Overtaken by a kiss by Thomas she runs away. In his misfortune Thomas writes a screenplay inspired by Bessie. But she has not been really honest with him. 31 minutes of runtime are missing and presumed lost.', 'Mauritz Stiller', 90, '1917-08-13', 'T13', 'sv', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (257, 'Tillie Wakes Up', 'Tillie and her neighbor Mr. Pipkins are both distraught over their respective marriages. One day, they sneak off to have a lively time at Coney Island. They flee the park together just as their spouses come to find them. After a chase, each is rescued from the ocean and reconcile with their respective spouses.', 'Harry Davenport', 48, '1917-01-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/AtVUmUyGqBQ12yw3EhlShlNBieN.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (258, 'Tom Sawyer', 'Silent version of the Twain tale, filmed in Pleasanton, California. A Missouri boy (Jack Pickford) encounters his first love (Clara Horton) and bucks responsibilities to find adventure with his friend, Huck Finn (Robert Gordon).', 'William Desmond Taylor', 62, '1917-12-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vxDbrbvnCRZuOXq1mt52z3okUaQ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (259, 'The Girl from the Marsh Croft', 'Helga is a young single lady who has a baby by a much older married man. After the older man tells Helga''s father that he refuses to pay child support because he isn''t the child''s father, her father insists that Helga take him to court. On court day, just as the older married man is about to swear on the Bible that he is not the father of Helga''s child, Helga suddenly tells the court that she''s dropping the case because although the man did father her child, she doesn''t want him to commit perjury, which is not only a serious crime but a mortal sin as well.', 'Victor Sjöström', 87, '1917-09-09', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/uuvlA1c5L8f1E6aEI4z1xiqXYQe.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (260, 'Until They Get Me', 'In an effort to reach his wife''s deathbed, Kirby is forced to kill a man in self-defense. He is arrested by Selwyn, a member of the North West Mounted Police, who allows him to say a last farewell to his wife. After visiting his wife''s deathbed, Kirby eludes Selwyn and becomes a fugitive from the police. Each year he returns to visit his son and, during one of his sojourns, meets Margy, a little farmhouse servant who has run away from her life of drudgery.', 'Frank Borzage', 58, '1917-12-02', 'T13', 'xx', 'https://image.tmdb.org/t/p/w500/hyEFZ8mr0zjUj71AbgrGQhBvCVp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (261, 'The Last Dawn', 'Kernett is a destitute gentleman who tries to kill himself. He is saved by lord Harding who hires him as his personal secretary.', 'Michael Curtiz', 78, '1917-09-30', 'P', 'hu', 'https://image.tmdb.org/t/p/w500/sSldl50pXhVTlJE6xqf4v1uMdke.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (262, 'The Vicar of Wakefield', 'The production vindicated the new feature-length movie format by restoring several characters, plot complications, and atmosphere that had been truncated in Thanhouser’s 1910 version of less than one-sixth the length.', 'Ernest C. Warde', 90, '1917-02-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iSOeft05lTSERfgU1DnZAgtX0ej.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (263, 'The Whip', 'The story of the training of a racehorse, the Whip, of the amnesiac nobleman who loves the horse, and of the villains who attempt to keep it from racing.', 'Maurice Tourneur', 80, '1917-03-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/58xphLHacUisXvbkySukT8KjnOe.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (264, 'Wild and Woolly', 'A rich Easterner who has always wanted to live in "the Wild West" plans to move to a Western town. Unknown to him, the town''s "wild" days are long gone and it is an orderly and civilized place now. The townsmen, not wanting to lose a rich potential resident, contrive to make over the town to suit the young man''s fantasy.', 'John Emerson', 72, '1917-06-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gWBQfwFxwwjnTR8T0Imna5lQ14y.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (265, 'Wolf Lowry', 'Tom "Wolf" Lowry confronts new settlers in his valley but has a change of heart when he sees Mary Davis.', 'William S. Hart', 52, '1917-05-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lSMEckZIuAypE21HAkOvnaqPyZ6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (266, 'The Woman God Forgot', 'Cortez sends Alvarado to Montezuma who throws him into a dungeon from which he is rescued by Tecza who loves him. He is recaptured when her lover Guatemoco finds Alvarado hiding in her chambers. Tecza next leads Cortez into the city, thus causing the destruction of her nation and securing the love of Alvarado.', 'Cecil B. DeMille', 77, '1917-10-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iIT9TSuJK8PMCgEPmPvnDc5bFyG.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (267, 'The Last Indian Attack', 'The movie dramatizes the last Indian uprising in Argentina, which happened in the north of the country, in the Chaco region, in the early 1900s.', 'Alcides Greca', 72, '1918-04-04', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/nkz2QoeQkn8EwvnQmscokUm9PE6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (268, 'All Night', 'A married society couple (Dorian and Warren) persuade an unmarried pair (Valentino and Myers) to take their places at a party while they pretend to be the servants.', 'Paul Powell', 58, '1918-11-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/r3Bp2Oe9dFqe1Zjm6lavMNhBXqQ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (269, 'Alraune', 'It is a variation on the original legend of Alraune in which a Mad Scientist creates a beautiful but demonic child from the forced union between a woman and a Mandrake root. Not to be confused with the 1918 German version of Alraune.', 'Edmund Fritz, Michael Curtiz', 80, '1918-01-01', 'T16', 'hu', 'https://image.tmdb.org/t/p/w500/sxbM6fUqHBKbcWCId6ypFAfZmtG.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (270, 'Amarilly of Clothes-Line Alley', 'Amarilly comes from a large family in a working-class neighborhood. She is happy with her family and her boyfriend Terry, a bartender in a cafe. But one day she meets Gordon, a sculptor who comes from a rich family, and she begins to be drawn into the world of the upper class.', 'Marshall Neilan', 67, '1918-03-10', 'K', 'en', 'https://image.tmdb.org/t/p/w500/gN3Mm5N2r2YcGKoTZcuZc30iNGX.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (271, 'The Man of Gold', 'Faithful to his word, Michael Tímar, captain of the St. Barbara, becomes the guardian of Kondya, daughter of a Turkish aristocrat on the run. Later, he weds the grateful young Turkish girl whom he saved from the waters of the Danube. While skillfully managing his wife''s fortune, entrepreneur Tímar becomes an important wholesaler of wheat and exports his products to Brazil. But his marriage of convenience proves a failure. He is torn between the demands of bourgeois civilization, governed by money, and the ideal of freedom, consisting of living simply within nature. He then takes refuge by the side of the sweet Noemi on an island on the Danube.', 'Alexander Korda', 83, '1919-01-19', 'P', 'hu', 'https://image.tmdb.org/t/p/w500/7Z8CakydMh60uaREYpzXRkckib7.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (272, 'The Eyes of the Mummy', 'Egyptians Radu and Ma milk British tourists out of their money by offering phony tours of a mummy''s tomb-- Radu has the girl lend her eyes to the "mummy" from inside an empty sarcophagus. When adventurer Wendland comes to visit the tomb, Ma is rescued and falls in love with him, leaving Radu in the dust. Needless to say, her former employer / captor follows them abroad in order to exact his revenge.', 'Ernst Lubitsch', 58, '1918-10-03', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/2timSoyq2mACa43Ge2XUqVP18nX.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (273, 'The Beloved Blackmailer', 'The girlfriend of the son of a rich railroad tycoon, attempts to help him escape the clutches of his well-meaning, but over-bearing mother whilst encouraging her own father not to give up on his business, by instigating a staged kidnapping and black-mailing scheme.', 'Dell Henderson', 50, '1918-08-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5IuKvILyoUkAH6ChNBDhdBaUrpC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (274, 'The Outlaw and His Wife', 'A stranger comes to work at widow Halla''s farm. Halla and the stranger fall in love, but when he is revealed as Eyvind, an escaped thief forced into crime by his family''s starvation, they flee and become two of the many outlaws of Iceland''s mountains.', 'Victor Sjöström', 111, '1918-01-01', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/21W049VzjH6KH4258mwZ6UOGTzO.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (275, 'The Blue Bird', 'Peasant children Mytyl and Tyltyl are led on a magical quest for the fabulous Blue Bird of Happiness by the fairy Berylune. On their journey, they''re accompanied by the anthropomorphized presences of a Dog, a Cat, Light, Fire, and Bread, among other entities.', 'Maurice Tourneur', 75, '1918-03-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eI9l0EIB2YGB24JAAczlYQBPQYw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (276, '''Blue Blazes'' Rawden', 'Rawden, a lumberjack in the North woods, fights with crooked dance hall owner ''Ladyfingers'' Hilgard over the affections of Babette DuFresne. Hilgard is killed. When Hilgard''s mother and younger brother arrive in the remote logging town, Rawden attempts to ease their suffering by creating the fiction that Hilgard had been a well-loved man who died naturally. But when young Eric Hilgard learns the truth of his brother''s death, he comes gunning for Rawden.', 'William S. Hart', 51, '1918-02-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sfoJJOYstzzn1BFC1viO3LKMSAv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (277, 'Bread', 'Bread is a socially engaged drama which follows the fate of a woman struggling to pull herself out of poverty as she’s ruthlessly exploited by a string of men.', 'Ida May Park', 60, '1918-08-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lFjHLR32gOhgylBdTEJEWiijDBw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (278, 'Broadway Love', 'A small-town girl who goes to New York hoping to become a Broadway star falls in with a fast crowd.', 'Ida May Park', 60, '1918-01-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6QYRMeg15cB9V88qzdZMSWH2iLR.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (279, 'Carmen', 'The tragic story of Don Jose, a Spanish cavalryman, who falls under the spell of a gypsy girl, Carmen, who treats him with both love and contempt and leads him into temptation and thus damnation.', 'Ernst Lubitsch', 94, '1918-12-20', 'P', 'de', 'https://image.tmdb.org/t/p/w500/b6rtwpcB1kPmYZVrTBOLiJ4h4lq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (280, 'Cecilia of the Pink Roses', 'Cecilia is a spunky Irish girl from a struggling family, faced with the imminent death of her mother.', 'Julius Steger', 90, '1918-06-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/x8VfiPefRWbnjvW7DLU3NkercOV.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (281, 'The Craving', 'An Indian scholar seeks an American colleague who is working on a powerful explosive, trying to get to his formula by taking advantage of his drinking problem.', 'Francis Ford, John Ford', 50, '1918-09-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xTLyyYb9OJ6USJemUGLxSO40Cu8.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (282, 'The Tenth Symphony', 'Composer Enrid Damor knows nothing of the past life of his new wife Eve Dinant : she lived as a debauchee with an adventurer, Fred Ryce. Fred Ryce meets Damor''s daughter, Claire, and tries to marries her. He blackmails Eve. Enric learns something about her and Fred and composes a symphony to express his pain... The Tenth Symphony is considered the first major film of the Impressionist movement.', 'Abel Gance', 88, '1918-11-01', 'K', 'fr', 'https://image.tmdb.org/t/p/w500/uelnUfGfmkhdLItObINikB6ABow.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (283, 'The Dream Lady', 'Upon receiving an inheritance from her late uncle, a woman starts a fortune-telling business designed to make her dreams come true.', 'Elsie Jane Wilson', 54, '1918-07-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9mKgos85khsbZY3FOJFa7AYqyoH.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (284, 'The Eyes of Julia Deep', 'The Eyes of Julia Deep is a 1918 silent comedy-drama film starring Mary Miles Minter, directed by Lloyd Ingraham. The film is based on the short story by the same name, written by Kate L. McLaurin. It is one of the few films starring Minter which are known to have survived.', 'Lloyd Ingraham', 57, '1918-08-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/udojXs4yUpLxPpLpQhrrAlUoUeJ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (285, 'The Merry Jail', 'A neglected wife disguises herself in order to lure her wastrel husband into a compromising position.', 'Ernst Lubitsch', 48, '1917-11-30', 'P', 'de', 'https://image.tmdb.org/t/p/w500/mG1B5KKTP0rwqOqFIPYNfjDVqoY.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (286, 'The Floor Below', 'Patricia O''Rourke, a good-natured prankster who works as a copy girl for the Sentinel , angers her co-worker Stubbs and is about to lose her job when the managing editor offers her one more chance. Her assignment is to explain the clue that links the Hope Mission, a derelict home run by millionaire Hunter Mason and his secretary, Monty Latham, with a series of local robberies. When Hunter discovers Patricia in his office, he assumes that she is a crook in need of reforming and takes her into his home to be cared for by his mother.....', 'Clarence G. Badger', 80, '1918-03-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/75ss6iNN9nAlOJBR5hj6vYRfwyj.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (287, 'The Forbidden City', 'The daughter of a Chinese mandarin is sentenced to death for her secret marriage to an American. Their child, raised in the mandarin''s palace, grows up and escapes to seek her father, now a high-ranking official in the Philippines.', 'Sidney Franklin', 63, '1918-10-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sQLnopsF9XhZIB0arNCd4pVYDEs.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (288, 'The Ghost of Rosy Taylor', 'George Periolat plays a dual role in this film, initially as Joseph Sayles a sickly old man who has taken his daughter, Rhoda (played by Mary Miles Minter), overseas after a quarrel with his family. She yearns to return home, but he has disowned his past. After his death, Rhoda ventures to America on her own. She nearly becomes destitute for a lack of money but happens upon some questionable fortune as she takes on the chores of Rosy Taylor after inadvertently finding an envelope with money in it. Rosy had been hired as a housekeeper (thus the money), but has passed away before actually showing up for employment.', 'Edward Sloman, Henry King', 59, '1918-07-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jltYASOGPID40c5LKljiOxyAr9X.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (289, 'The Girl Who Stayed at Home', 'Ralph Grey visits France with his shipbuilder father, and falls in love with Blossom, granddaughter of his father''s friend, a Civil war veteran not reconciled with the Union. Blossom, however, is engaged to a French nobleman. When war breaks out, Ralph enlists, while his brother Jim, a heartbreaker, is drafted.', 'D.W. Griffith', 69, '1919-03-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hOdQbE1GuNeeYdbqSCyXdW3bQIz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (290, 'The Great Love', 'An idealistic young American during World War I, itching to fight the Germans and not wanting to wait until the U.S. joins the war, journeys to Canada, where he enlists in the British army. He is sent to train in England, and then to the front in France, where he''s wounded. Returned to England to recuperate from his wounds, he falls in love with the daughter of an Australian minister.', 'D.W. Griffith', 60, '1918-08-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/64uGJmLRRemxJLltetum5poGOjf.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (291, 'The Greatest Thing in Life', 'Leo Peret has a small quiet tobacco shop in Greenwich Village. Edward Livingston, a wealthy young clubman and man-about-town, occupies frequently ostensibly to buy cigarettes but in reality to talk to the daughter Jeannette, and he''s soon in love with the shop girl.', 'D.W. Griffith', 60, '1918-12-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/odQVMYoLgPssySkhbybNYhmT8Fx.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (292, 'He Comes Up Smiling', 'Jerry Martin quits his dull job as a bank clerk and falls in with a band of hobos. He takes on the guise of Bachelor, the "king of the market," and finds himself pursued by dangerous men who are after the real Bachelor. *Only fragments are known to exist. Preserved by the Academy Film Archive in 2010.', 'Allan Dwan', 50, '1918-09-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/klRJFZjFWymfGcOutKWyIUjAgOv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (293, 'The Heart of Humanity', 'The story centers around Nanette, an American girl living in a small Canadian village, who is in love with John Patricia, the eldest of five brothers. The war interrupts their romantic idyll, as everyone goes overseas to Belgium and France. Nanette becomes a Red Cross nurse and is terrorized by the evil Prussian Lt. von Eberhard.', 'Allen Holubar', 110, '1918-12-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qNj9Q8BoYUl1hszUa4zrcsGHegw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (294, 'Hearts of the World', 'A group of youth come of age in a peaceful French village. But war intrudes and peace is shattered. The German army invades and occupies, bringing both destruction and torture. The youngsters resist, some successfully, others tragically, until French troops retake the town.', 'D.W. Griffith', 117, '1918-03-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9M2qEZ9iOIDrViVK9bEEwQE7Jk7.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (295, 'Hell Bent', 'A cowboy must save his girlfriend from captivity and then cross the desert on foot with a single waterhole on the way.', 'John Ford', 53, '1918-06-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/52yGdedNMIsjb6C3wEM8CihHX7Q.jpg', 'https://www.youtube.com/watch?v=darotFrBNFM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (296, 'Johanna Enlists', 'A young girl, stifling on her father''s backwoods farm, is reinvigorated by the arrival of an army regiment, come to train in the area.', 'William Desmond Taylor', 64, '1918-09-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kazRRkHzX2yfSTiXs9hQOihaMP0.jpg', 'https://www.youtube.com/watch?v=yXD6MCWHVW8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (297, 'The Lady of the Dugout', 'Real life outlaw Al Jennings tells a "real" story about how he came to the aid of a woman who was abused by her alcoholic husband.', 'W.S. Van Dyke', 64, '1918-09-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sDUsRhL5OC94VKWuqh3BQPGUf0R.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (298, 'Little Orphant Annie', 'Annie, left orphaned after the death of her mother, goes to an orphanage where she tells her fellow orphans stories of ghosts and goblins. The matron of the orphanage finds Annie''s closest relative, the abusive Uncle Thomp. Big Dave, a neighbor comes to her aid, becoming her protector. Eventually Annie goes to live with Squire Goode and his large family. There, she entertains the children of the household with her stories, but sees her abusive aunt and uncle as her chief tormentors. She tells stories of how the goblins will take away the children if they are not good. War breaks out and Dave, who Annie adores, enlists. In a feverish vision triggered by her distress—revealed later as a nightmare—she imagines receiving news of Dave''s battlefield death, delivered mockingly by her uncle, leading to her heartbroken collapse and apparent deathbed vigil.', 'Colin Campbell', 57, '1918-12-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/y14VTIxwHJ1TMCcveN7PqWOitaY.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (299, 'Little Women', 'Four sisters come of age in America in the aftermath of the Civil War.', 'Harley Knoles', 56, '1918-11-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hc8HTn0Bo1gnDWuWKs4os4Rs3H.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (300, 'M''Liss', 'M''liss, a feisty young girl in a mining camp, falls for Charles Gray, the school teacher. Charles is implicated in a murder of which he is innocent, and the two must fight to save him from a lynching.', 'Marshall Neilan', 73, '1918-05-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nRSRud2qFFEVoMHIMwEyDa5UBy3.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (301, 'The Married Virgin', 'In order to save her wealthy father from disgrace and a possible prison sentence, a daughter agrees to marry the gigolo who''s been blackmailing him...', 'Joseph Maxwell', 71, '1918-12-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wb9BuxYoM5HqXf9KWK4Pwfq0ZZL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (302, 'Mickey', 'Mickey, an orphan who has been brought up in a mining settlement, is sent to New York to live with her aunt.', 'F. Richard Jones, James Young', 71, '1918-08-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yJGh9pSNGFwYKE8OfmYHU38B2ah.jpg', 'https://www.youtube.com/watch?v=PnJJHgjRWVg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (303, 'Mr. Fix-It', 'A young man impersonates his best friend, and in doing so upsets the decorum at a stuffy family gathering and falls in love. The arrival of a gang of hoodlums further disrupts the formalities, but our hero thwarts them and saves the day.', 'Allan Dwan', 54, '1918-04-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lz8uT8dxJPNHkAMb3UvWSVsOCPM.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (304, 'My Cousin', 'Sincere but struggling sculptor Tommasso (Caruso--bushy moustache, gawky) works in an ornamental plaster shop, but his masterpiece on the side is a bust of his cousin Caroli (Caruso--no moustache, polished), who is the Metropolitan Opera''s leading tenor. Tommasso hopes to marry his model Rosa, but her father, restaurant owner Pietro, wants her to find someone more settled and money-conscious, such as the greengrocer Lombardi down the street. Tommasso, he says, throws away his money, such as for a pair of tickets to take Rosa to the opera to see his famed cousin. After the opera, the cousins cross paths in the swanky Galeotto''s restaurant, but when neither recognizes the other, Tommasso is generally mocked and Rosa believes him a liar and unworthy. Tommasso must recover his reputation and make a sale, preferably the Caroli bust to his cousin, in order to win Rosa back.', 'Edward José', 50, '1918-11-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rOmq2Kf21qMPITOFvsVcPdB8WdN.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (305, 'My Four Years in Germany', 'The experiences of the American ambassador to Germany, James Gerard, are recounted in this semi-documentary.', 'William Nigh', 127, '1918-03-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jId4nxzDxyp7ZLc821AVXLzpst.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (306, 'Night Music', 'The rich Baron Von Meislingen dreams of being a poet-- Unfortunately, he has no talent what so ever. In one of his apartments lives the talented but poor poet Peter Långhår. Von Meislingen steals his latest work from him and publishes it under his own name. ''His'' poems becomes a success and Von Meislingen becomes regarded as one of the greatest living poets.', 'Georg af Klercker', 61, '1918-04-01', 'K', 'sv', 'https://image.tmdb.org/t/p/w500/9s5OsczAYvrrCceIipP16ivjfos.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (307, 'Old Wives for New', 'Charles Murdock neglects his fat and lazy wife for another woman; When his other love interest becomes involved in a murder, he leaves for Paris.', 'Cecil B. DeMille', 72, '1918-05-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wpzsAGxA77kelIODOJdTKGn57El.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (308, 'A Pair of Silk Stockings', 'Molly is a wife of wealthy Britisher Sam Thornhill. Though devoutly loyal to her husband, the capricious Molly can''t seem to avoid getting herself into compromising situations. The limit comes when a pair of Molly''s stockings find their way into the boudoir of another man.', 'Walter Edwards', 60, '1918-07-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bnv9qZ2bm4tkRntwIZu1mIrV8Cm.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (309, 'Riddle Gawne', 'When Gawne finds his brother dying and hears that the killer has run off with his brother''s wife, he swears revenge.', 'Lambert Hillyer, William S. Hart', 50, '1918-08-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bkiZMUbdgoAGIlsjEeb3V6uCHaP.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (310, 'A Romance of Happy Valley', 'John Logan leaves bucolic Happy Valley to make his fortune in the city. His parents and his sweetheart become miserable and beleaguered in his absence, but after several years he returns wealthy. However, his embittered father, not recognizing him for who he is, plans to murder the newly-arrived ''stranger'' for his money.', 'D.W. Griffith', 76, '1919-01-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5pYmIviQjmBVdSkyzXrPrwMFh3m.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (311, 'The Romance of Tarzan', 'Tarzan and Jane are to sail for England. They are attacked by natives and Tarzan is believed to have been killed. The Greystoke relatives return to England, the Porters (Jane''s family) goes to their ranch near San Francisco. Tarzan shows up in a tuxedo and rescues Jane from outlaws...', 'Wilfred Lucas', 70, '1918-10-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qoOWdnY5lULcCsJPbun8UUbsJZz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (312, 'Rose-France', 'A poem to love and patriotism soon after the end of World War I. A highly original and poetic film using many experimental camera techniques, which proved too fanciful for many but which established Marcel L''Herbier''s reputation as a talented innovator. This is the director''s debut film and it is considered the second impressionist film, the first being Abel Gance''s, 1918, La Dixième symphonie (The Tenth Symphony).', 'Marcel L''Herbier', 42, '1919-06-27', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/4AWbzUqGFjUkYlY0paRIWm1lt8k.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (313, 'Salome', 'Palestine, under the rule of Rome. Salome, daughter of Herodias and both niece and stepdaughter of King Herod, becomes infatuated with the prophet John the Baptist, who publicly denounces the depravity of the royal family and proclaims the arrival of a new messiah. (Film presumed lost.)', 'J. Gordon Edwards', 80, '1918-08-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3ydcKgcXHIu3Fv6hdLbB7rtZG0d.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (314, 'The Scarlet Drop', '"Kaintuck" Ridge (Carey), refused admission to the local militia to fight on the side of Union in the American Civil War, joins a gang of marauders and at the end of the conflict finds himself a fugitive with a price on his head.', 'John Ford', 50, '1918-04-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/euzj4DikKLM4uexAj6FSxIVpVUi.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (315, 'Shifting Sands', 'Marcia Grey is wrongly convicted on trumped-up evidence of a German. After serving her term, she rebuilds her life and marries well.', 'Albert Parker', 60, '1918-08-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ey1M7ZqGy2twUrI9ucjtlzq9Wmo.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (316, 'Stella Maris', 'Stella Maris is a beautiful, crippled girl, who is cared for by a rich family. They shield her from the harsh realities of the world, so that she has no idea of the cruel things that some people do. Unity Blake is a poor orphan all too familiar with the harsh realities of the real world. These two young women both fall in love with John, love which is complicated by the fact that he is still married to (though separated from) a bad wife.', 'Marshall Neilan', 84, '1918-01-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AraezXbzsaaZx5737xsXq17HlaA.jpg', 'https://www.youtube.com/watch?v=dY4ipTCzfcU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (317, 'Tarzan of the Apes', 'A female ape takes to mothering the orphaned boy (Tarzan) and raises him over the course of many years until a rescue mission is finally launched and the search party combs the jungle for the long-time missing Lord Greystoke. But then, one of the search members, Jane Porter, gets separated from the group and comes face to face with fearsome wild animals. Tarzan saves her from harm just in the knick of time and love begins to blossom.', 'Scott Sidney', 60, '1918-01-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jj7Jjd4Q4LaKXmhmprxumesSLbn.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (318, 'Thomas Graal''s Best Child', 'Frau Bessie, once a madcap, aristocratic and modern Swedish fraulein, has become now a whimsical and conservative Swedish burgess after her marriage to Herr Thomas Graal. The destabilization of the marriage begins right at the wedding (which contains some hilarious incidents) when Frau Bessie announces the first Graal child must be a girl, creating a terrible conflict with her husband who is hoping for a boy. It takes a scandal to finally end the war between man and wife.', 'Mauritz Stiller', 89, '1918-10-21', 'K', 'sv', 'https://image.tmdb.org/t/p/w500/oiE4v8tCNS7HhClO4XvV7kPfq0N.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (319, 'Tih Minh', 'Jacques d''Athys, a French adventurer, returns to his home in Nice after an expedition to Indochina where he has picked up a Eurasian fiancée and a book that, unbeknownst to him, contains a coded message revealing the whereabouts of both secret treasures and sensitive government intelligence. This makes him the target of foreign spies, including a Marquise of mysterious Latin origin, a Hindu hypnotist and an evil German doctor, who will stop at nothing to obtain the book.', 'Louis Feuillade', 418, '1918-11-30', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/drcLhwmeu1ndGH9uafS3QiWKBSo.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (320, 'The Unbeliever', 'A wealthy young American, bred to class distinction and racial intolerance, enters the Marines during the First World War. In the course of his training and his experiences in the trenches fighting, being wounded by, and being hospitalized with Germans, he comes to a recognition of the equality and brotherhood of men.', 'Alan Crosland', 80, '1918-02-15', 'T13', 'xx', 'https://image.tmdb.org/t/p/w500/qspL5mkq0imLEjZDH98Nu5v0XFS.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (321, 'Vendémiaire', 'If you’re already familiar with Louis Feuillade, his little-known opus Vendémiaire may come as a surprise. Unlike the bulk of his work which was characterised as ‘Fantastic Realism’, Vendémiaire is wonderfully down-to-earth realism – or down-to-French-earth realism to be specific. The film itself is divided into four chapters, the titles of which suggest that this is a movie about the cultivation and consumption of wine. But as the narrative unfolds, it becomes clear that the cultivation and consumption of wine is an allegory for French culture and French land as a whole, and the real purpose of the film is to persuade the director’s fellow citizens to defend that spirit and those lands at all costs. It’s September 1918 and the war is coming to an end, but here on the Castelviel estate in the south of France the news has not yet arrived and everyone is busy with the grape harvest....', 'Louis Feuillade', 148, '1919-01-17', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/q7g280EAr3VlPgVDJdRNB9PwWs4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (322, 'The Whispering Chorus', 'John Trimble has embezzled and obtains another identity by having a mutilated body buried in his place. He is later arrested for murdering himself. During the trial his mother, before dying from shock, asks him to keep his identity secret since his wife is now married to the Governor and expecting a child.', 'Cecil B. DeMille', 86, '1918-03-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iLmy2KqFdNthKNSGrwc30H4O2dN.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (323, 'Wild Women', 'Cheyenne Harry (Carey) and his pals, bent on helping their friend Rawhide Jack, attend a rodeo with the intent to win the prize for roping steers and to hand the winnings over to Jack.', 'John Ford', 50, '1918-02-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4IS8ihNiqQWfZqWh3iAeRrYUVoL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (324, 'A Woman''s Fool', 'Cowboy Lin McLean''s restlessness takes him to Denver, where he becomes enamored of a waitress named Katie. Intending to marry her, Lin accompanies Katie back to the ranch, but a traveling rainmaker arrives in the little town, and Katie departs with him after revealing that he is her husband. Visiting Denver for Christmas, Lin adopts Katie''s abandoned son Billy, and soon afterwards, the cowboy meets and falls in love with the new station agent, Jessamine "Jessie" Buckner. Lin and Jessie marry, and the little family is happy until Katie, determined to be rid of her neglectful husband and marry Lin instead, appears and drives Jessie away. Realizing that Lin does not love her, Katie poisons herself, and Jessie returns to Lin and Billy.', 'John Ford', 50, '1918-08-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uBRZqKlXHaRFX0GkDk6AP2VDIu3.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (325, 'The Ace of the Saddle', 'When cattle rancher Cheyenne Harry Henderson discovers that rustlers are attacking his herd, he informs Yucca County''s sheriff but learns that the lawman is in cahoots with the outlaws.', 'John Ford', 60, '1919-08-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gw9fqIg0pl40ohzOvCMPPLNTvLE.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (326, 'Different from the Others', 'Conrad Veidt plays a famous musician who is blackmailed for being gay. Eventually he stands trial and is convicted. At the end the film pleads for the abolition of §175 (the law that punishes homosexuality).', 'Richard Oswald', 51, '1919-05-28', 'P', 'de', 'https://image.tmdb.org/t/p/w500/sgORpP8DlLbkcH4eFACBcGztw6y.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (327, 'Anne of Green Gables', 'Anne Shirley, an orphan, is fostered by farmer Matthew Cuthbert and his sister Marilla, who were expecting a boy to be sent them to help with their farm work. They accept Anne, who quickly endears herself to them and to the local villagers.', 'William Desmond Taylor', 60, '1919-11-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/f9qLEKufBC1oev8CX8k57RnU8Kz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (328, 'Auction of Souls', 'A Hollywood biographical film about a survivor''s experience of the Armenian Genocide. Arshaluys (Aurora) Mardiganian plays herself in the film which is based on her published memoirs. It is thought to be the first film about made about genocide. All known complete copies of the film have been lost. A restored and edited 24-minute segment of the historic motion picture was released in 2009 by the Armenian Genocide Resource Center of Northern California. It is based on a rare surviving reel of film edited in Soviet Armenia.', 'Oscar Apfel', 90, '1919-01-19', 'T13', 'xx', 'https://image.tmdb.org/t/p/w500/mcZGz4pbMZ2DOqO4mToomrSCStB.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (329, 'The Oyster Princess', 'A pampered American oyster tycoon decides to buy a husband for his daughter, but things don’t go quite as planned. Along the way there are mishaps, misunderstandings and a foxtrot sequence that must be seen to be believed.', 'Ernst Lubitsch', 58, '1919-06-26', 'P', 'de', 'https://image.tmdb.org/t/p/w500/n4ifmOMaw415Lt4YAYfBb7Cdjh0.jpg', 'https://www.youtube.com/watch?v=lPcoIcO7z8Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (330, 'The Grey Automobile', 'A gang terrorizes Mexico City''s high society in 1915. Murder, kidnaping and robbery are their trademarks. One police inspector (Cabrera) follows the gang''s crimes and eventually sends them to jail.', 'Enrique Rosas', 223, '1919-12-11', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/5wqMI8VjqiTIFqN2zNVnLoss7D.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (331, 'Back to God''s Country', 'After her father is killed by an outlaw, Dolores marries Peter. While they''re at sea in the Arctic, Dolores meets the ship''s captain, who is the man who killed her father. The captain causes an ''accident'' to happen to Peter, so Dolores is all alone and defenceless as they drop anchor in a remote harbour.', 'David Hartford', 73, '1919-10-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6P2cgKeMBKtMdYG7wq5LAnyofm6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (332, 'Bare Fists', 'Harry''s father is killed in a gunfight, and his mother makes him swear he''ll never again use his gun, and rely only on his bare fists. But when his little brother is branded on the chest by cattle rustlers, will Harry break his promise?', 'John Ford', 61, '1919-05-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/i9rtUPyKEUeuq8oOKEAQRM0ALvb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (333, 'Barrabas', 'Rudolph Strelitz, known as ''Barrabas'', is the leader of a brutal underground gang causing chaos and destruction in the lives of civilized people. A lawyer, Claude Varèse, is strongly determined to bring Strelitz to justice for the purpose of revenge, after his father was unjustly guillotined for the murder of Laure d''Hérigny, the mistress of an American millionaire. Later, the sister of Claude Varèse, Françoise, is kidnapped by Dr Lucius, one of the henchmen of Barrabas. Serialised over 12 chapters.', 'Louis Feuillade', 489, '1919-12-05', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/fVHMCQN4Grwf2SPLwWAM3tlVchB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (334, 'Behind the Door', 'Oscar Krug is looked upon with suspicion by his neighbors because of his German name. When the US is drawn into the war with Germany, he enlists and travels the seas with his wife, Alice Morse. During a submarine attack Alice is snatched from Krug''s side by a German officer. Krug now lives to have his revenge, and when the opportunity presents itself, he will have it.', 'Irvin Willat', 73, '1919-12-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/g0pw1rY3PU43KptLCIvk0aFR2g4.jpg', 'https://www.youtube.com/watch?v=XqYkDc-vWlQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (335, 'The Belle of New York', 'An old inventor is robbed of his inventions by an unscrupulous rich man. When the inventor dies, his daughter Violet goes to New York and joins the "Follies," where she is advertised as "The Belle of New York." The rich man''s son is infatuated with Violet, and is introduced to her anonymously as Jack. When Violet learns of Jack''s identity, she casts him off. He takes to drinking and she joins the Salvation Army. Jack is attacked in an underworld saloon just as Violet enters in Salvation Army attire. She nurses him at his home. When Jack''s father discovers with whom Jack is in love, he begs forgiveness for the wrong he did Violet''s father.', 'Julius Steger', 50, '1919-03-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dEXW7kBq2OAR9SXUqedZZHkzFA4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (336, 'Blind Husbands', 'An Austrian military officer and rogue attempts to seduce the wife of a surgeon. The two men confront each other in a test of abilities that ends surprisingly.', 'Erich von Stroheim', 89, '1919-10-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/lZ2GH545hJgch1GhLoE5tXOte8c.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (337, 'Bolshevism on Trial', 'Society melodrama about a wealthy father who purchases an island to prove to his son that communism won''t work.', 'Harley Knoles', 70, '1919-04-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kcjz9WB1FrhjXmWjxbemelUZtKz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (338, 'Broken Blossoms or The Yellow Man and the Girl', 'A frail waif, abused by her brutal boxer father in London''s seedy Limehouse District, is befriended by a sensitive Chinese immigrant with tragic consequences.', 'D.W. Griffith', 88, '1919-05-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/njwFIUL76zaRmPemnrZVmmTSCjz.jpg', 'https://www.youtube.com/watch?v=kF6B9_Pwgpw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (339, 'The Broken Butterfly', 'A woman in Canada abused by her aunt falls in love with a foreign composer looking for inspiration, who comes to find it in her and the star-crossed romance that develops between them.', 'Maurice Tourneur', 58, '1919-11-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/grdND7q1Fm2t4zMG1Mqj485WwNB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (340, 'The Busher', 'A young baseball pitcher in the bush leagues is discovered by a big-league manager and given his chance in the major leagues.', 'Jerome Storm', 55, '1919-05-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2dT8vzzzEJDdjcwAhpopOAsTHQ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (341, 'Daddy-Long-Legs', 'Wealthy Jarvis Pendleton acts as benefactor for orphan Judy Abbott, anonymously sponsoring her in her boarding school. But as she grows up, he finds himself falling in love with her, and she with him, though she does not know that the man she has fallen for is her benefactor.', 'Marshall Neilan', 85, '1919-05-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/m3CF9lgC1mH1NWft43tgmyyOEdm.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (342, 'Dangerous Hours', 'Idealistic young American falls under the influence of Communist agitators.', 'Fred Niblo', 76, '1919-12-17', 'K', 'en', 'https://image.tmdb.org/t/p/w500/7ZHYetpwtsQoerBcZeYA7c8ox2o.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (343, 'The Delicious Little Devil', 'A poor hat-check girl loses her job and is forced to get a job as a dancer at a roadhouse. There she falls in love with the son of a rich businessman. The boy''s father, believing her to be after the family''s money, determines to embarrass her and show his son what she really is.', 'Robert Z. Leonard', 77, '1919-05-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8TfBEcezQtJMrAuQGlxXdgcLc7l.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (344, 'Deliverance', 'The story of Helen Keller and how she overcame her disabilities.', 'George Foster Platt', 85, '1919-08-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4KwgFrDJpHd4hIEs31X1Z1njQQg.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (345, 'Don''t Change Your Husband', 'Leila Porter comes to dislike her husband James, a glue king who is always eating onions and looking sloppy. But after she divorces him and marries two-timing playboy Schuyler Van Sutphen the now-reformed James looks pretty good.', 'Cecil B. DeMille', 80, '1919-01-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9oGjJuqrEkfRYAPm76HgHFXpqYv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (346, 'Eyes of Youth', 'A young woman, confronted by four options for proceeding in her life, is granted the ability to see what results would come from her choice of of the options. After she sees her future along three of the roads, she makes her choice.', 'Albert Parker', 64, '1919-11-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/coTPOYYnDSIqKW3BpSdzdGyLcks.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (347, 'The Fall of Babylon', 'A re-edited version of the second episode of Intolerance (1916); a mountain girl who loves Belshazzar strives to protect him against the evil High Priest of Bel and his treacherous cohorts.', 'D.W. Griffith', 63, '1919-07-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uVzglMyysX47T3LAl7ufRSp6ztI.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (348, 'The False Faces', 'During World War I, a professional thief known as The Lone Wolf is assigned to steal a cylinder with important information from behind the German lines and bring it to Allied intelligence headquarters. However, German agents set out to stop him, headed by the man who was responsible for the death of the thief''s sister.', 'Irvin Willat', 76, '1919-02-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gSx36URlNFh9xGqvVIb1BBOZepk.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (349, 'A Dangerous Courtship', 'The farmer Knut Husaby has a daughter, Aslaug, who is the most beautiful girl in the village. Many boys are after her, but Knut and his two sons drive them away, if they come too close to the farm. Aslaug is secretly in love with Tore Naesset. But he is only a smallholder''s son, and when he asks for Aslaug''s hand, her father just laughs at him. Instead her father wants Aslaug to marry Ola Thormundson, a gawky boy, who is the son of the wealthiest farmer in the village. Aslaug brings her family''s cattle to the Husaby summer farm up in the mountain. Only one road leads to the summer farm, and it passes right by the main farm. When Tore returns from a visit to Aslaug in the mountains, Knut and his sons beat him black and blue. As it''s impossible for him to use the road anymore, Tore has to figure out another way to go to Aslaug. Next Saturday he crosses the fiord in a rowing-boat. He stops at a fifty meter high wall of rock, and starts climbing it, hoping to reach Aslaug at the top.', 'Rune Carlsten', 65, '1919-12-26', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/ob6CAR4JWB32WUchR4FkE5Sbzvq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (350, 'A Fight For Love', 'The Northwest Mounties are after Cheyenne Harry for the murder of an Indian boy, and the only witness to the crime is a priest - who can''t tell what he saw because the real killer, Black Michael, has confessed to him.', 'John Ford', 60, '1919-03-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5U67kmRVZDMSBM6BIRiXJz7SUoU.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (351, 'For Better, for Worse', 'Dr. Edward Meade and friend Richard Burton both love Sylvia Norcross. Both enlist in the military, but Meade stays back to care for deformed children. Sylvia thinks him a coward and marries Burton. After Burton is presumed dead, Meade and Sylvia are to wed, but Burton returns maimed and scarred.', 'Cecil B. DeMille', 90, '1919-04-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4otIYPncNZV5NKugIIDHWPzGcmC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (352, 'Getting Mary Married', 'A young woman must resist the charms of a handsome stranger and stay single if she wants to inherit a fortune.', 'Allan Dwan', 65, '1919-04-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eFQOoEbpIBPG0nYdD6TVjhYpyjf.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (353, 'The Glorious Lady', 'During an annual celebration in which English peasants and aristocrats mingle, the Duke of Loame is thrown from his horse and saved by Ivis Benson, the daughter of a tenant farmer. Both injured, they fall in love, to the dismay of his mother and Lady Eileen, his intended bride.', 'George Irving', 56, '1919-10-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9TNWdS5RYTPlG5LZ7ShWoT3JPUK.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (354, 'Anniversary of the Revolution', 'A chronicle of the Russian Revolution of 1917, from the bourgeois democratic February Revolution to the great socialist October Revolution and the final triumph.', 'Dziga Vertov', 122, '1918-11-07', 'K', 'ru', 'https://image.tmdb.org/t/p/w500/7yE1IITKDD7c0A0PJ6LKATzq4Pf.jpg', 'https://www.youtube.com/watch?v=YL976arvZmU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (355, 'The Greatest Question', 'Young Nellie Jarvis, daughter of a wandering couple, witnesses the murder of a woman by a man and his wife. Years later, "Little Miss Yes''m", as Nellie is known, returns to the area as an orphan. Locals Mr. and Mrs. Hilton, though poverty stricken, take her into their family. Fully integrated with the loving Hiltons, she wishes to relieve them of their financial strain. Nellie travels to a nearby farmhouse to gain employment from depraved Martin Cain and his paranoid wife.', 'D.W. Griffith', 80, '1919-12-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gAcsANsJ8BWc8jQiYGDhzb0iONX.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (356, 'The Grim Game', 'Jailed unjustly for a murder he did not commit, a young man uses his amazing powers of escape to free himself and pursue the actual killers, who hold his fiancée captive.', 'Irvin Willat', 71, '1919-10-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gQ6j6u5GBq1ECVfUSGadmtDZHf8.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (357, 'A Gun Fightin'' Gentleman', 'Cheyenne Harry, owner of the biggest cattle ranch in his corner of the west, is having trouble with John Merritt, a land-grabbing Chicago meat-packer. By some artifice of shrewd legal aid, Merritt manages to seize Harry''s ranch under a bogus writ of foreclosure. Failing to get justice by his many letters to Merritt, Cheyenne Harry goes east and calls at the millionaire''s mansion. At first, Merritt refuses to see him. Then, to cause amusement for his daughter, Helen, and her guests, he invites the "uncouth" westerner into his dining hall. He is sure that he will make some grave error in table deportment and afford them all a laugh. To the amazement of Merrit and the guests Harry''s table manners are faultless. Then, to trick him into an embarrassing position, Merritt eats with his knife. Harry, realizing that it is proper for the guest to follow the example of the host, does likewise. He leaves the house chagrined but more determined than ever to get justice from Merritt.', 'John Ford', 50, '1919-11-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wGwNHZXa9m1AJK3NhhSyIuaRC4U.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (358, 'Haceldama, or The Price of Blood', 'Mr. Landry Smith, a secretive man, lives in Corrèze with his ward Minnie. Two strangers arrive to Smith''s country estate-- each of them with a possibly sinister plot in mind.', 'Julien Duvivier', 75, '1919-12-12', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/1STNtoJTvKu5p9g1i5f00fFcZoq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (359, 'Half-Blood', 'The story of a man destroyed by love.', 'Fritz Lang', 54, '1919-04-03', 'P', 'de', 'https://image.tmdb.org/t/p/w500/9HoNwy3nUdG6mOfw1TZEMFzcpwg.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (360, 'His Grace’s Will', 'A series of family entanglements develop around the changing will of Roger Bernhuses de Sars, who wants his heritage to go to his illegitimate daughter Blenda. But love and fate also plays their cards.', 'Victor Sjöström', 75, '1919-11-03', 'T13', 'sv', 'https://image.tmdb.org/t/p/w500/2BX0quSRJlmCYSSCDXiuOR1wSOk.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (361, 'Harakiri', 'The daughter of a daimyo, one forced to commit harakiri to secure her a future to choose her own destiny, falls in love with and marries a European officer. The officer returns to Europe but promises to come back for her and his new child, but when he comes back to Japan, he brings his European wife.', 'Fritz Lang', 87, '1919-12-18', 'P', 'de', 'https://image.tmdb.org/t/p/w500/bdmgM7EfKfslIVKGuBkXclwwajY.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (362, 'Hawthorne of the U.S.A.', 'American law clerks Anthony Hamilton Hawthorne and Rodney Blake are nearly broke in Monte Carlo when Hawthorne breaks the bank. While driving through the impoverished kingdom of Bovinia, Hawthorne falls in love with a woman he meets when he retrieves his blown-off cap. Deciding to stay, Hawthorne is persuaded to finance a revolution until he learns that the woman he loves is Princess Irma and that she is in danger of being assassinated.', 'James Cruze', 57, '1919-11-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ftB3jUPc21mIMj1rSmAoJTNHiU9.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (363, 'Heart o'' the Hills', 'Family tensions in the Kentucky hills are inflamed by an outsider''s dishonest scheme to exploit the area for its coal.', 'Joseph De Grasse, Sidney Franklin', 78, '1919-11-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/MtiWqffKlaqcsGyQpUz4lEvt35.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (364, 'Sir Arne''s Treasure', 'Three Scottish officers, including Sir Archi, murder Sir Arne and his household for a coffin filled with gold. The only survivor is Elsalill, who moves to relatives in Marstrand. There she meets a charming young officer- Sir Archi- and she soon understands that he was one of the murderers.', 'Mauritz Stiller', 106, '1919-09-18', 'T13', 'sv', 'https://image.tmdb.org/t/p/w500/nsLYOrcHIHxiHcxos6946kYPRBP.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (365, 'Master of Love', 'Lost film. A man''s devotion for a woman brings about his ruin.', 'Fritz Lang', 60, '1919-09-24', 'P', 'de', 'https://image.tmdb.org/t/p/w500/3wtwBPV38upEluj7umxmjeT0hFP.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (366, 'His Majesty, the American', 'A European prince is raised in America without knowing his true identity; he spends his time thrill-seeking, but his country needs him when a revolt threatens the crown.', 'Joseph Henabery', 96, '1919-09-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9KdpNn1Z1oEQZtCLNvoba3Fki6D.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (367, 'Historien om en gut', 'Esben Lykke-Seest is a school boy who gets in trouble at school when a classmate put the teachers watch in his pocket. In fear of punishment he runs away at sea and starts his adventure....', 'Peter Lykke-Seest', 80, '1919-04-29', 'T16', 'no', 'https://image.tmdb.org/t/p/w500/pvXUMHQz5ytSxWQWJbVWzjuWxpL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (368, 'The Hoodlum', 'A spoiled young rich girl is forced by misfortune to fight for survival in the slums and alleys, where she becomes involved with all manner of unpleasantness.', 'Sidney Franklin', 78, '1919-08-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2zhSxkqu0NWUrPR7b2quk7LZoAe.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (369, 'I Don''t Want to Be a Man', 'A teenage tomboy, tired of being bossed around by her strict guardian, impersonates a man so she can have more fun. She quickly discovers that being the opposite sex isn’t as easy as she had hoped for. What ensues is a gender-bending comedy decades ahead of its time.', 'Ernst Lubitsch', 45, '1918-10-01', 'P', 'de', 'https://image.tmdb.org/t/p/w500/oQrTEm3xWNpP8Jzrhz3nOE6qLcI.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (370, 'Sons of Ingmar', 'Part one of an ambitious screen adaptation of Selma Lagerlöf''s book Jerusalem.', 'Victor Sjöström', 207, '1919-01-01', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/85xSCUNt0G6uB0Efw5OQKriQtui.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (371, 'J''Accuse', 'The story of two men, one married, the other the lover of the other''s wife, who meet in the trenches of the First World War, and how their tale becomes a microcosm for the horrors of war.', 'Abel Gance', 165, '1919-04-25', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/9vZK9ZoVrAiquPCktZkqMXV3Mq5.jpg', 'https://www.youtube.com/watch?v=pv9tA7HkFwk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (372, 'Jubilo', 'Jubilo, a hobo, witnesses a robbery, finds work on Judge Hardy’s farm, and foils the vengeful machinations of a sinister villain.', 'Clarence G. Badger', 55, '1919-12-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/d41j1y1WJ2lVU5h2Vnb3Djr9jfG.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (373, 'The Cabinet of Dr. Caligari', 'Francis, a young man, recalls in his memory the horrible experiences he and his fiancée Jane recently went through. Francis and his friend Alan visit The Cabinet of Dr. Caligari, an exhibit where the mysterious doctor shows the somnambulist Cesare, and awakens him for some moments from his death-like sleep.', 'Robert Wiene', 77, '1920-02-27', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/myK9DeIsXWGKgUTZyGXg2IfFk0W.jpg', 'https://www.youtube.com/watch?v=6_uvMK0dbMY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (374, 'The Boy in Blue', 'A man searches for a cursed emerald belonging to his ancestor. Lost film, minor fragments survive', 'F. W. Murnau', 54, '1921-04-07', 'P', 'de', 'https://image.tmdb.org/t/p/w500/7IN3GiMkHnLUkVMIswDKZ3Yy52p.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (375, 'Lightning Bryce', 'Two prospectors, one the father of Sky "Lightning" Bryce and the other the father of Kate Arnold, find a large gold deposit belonging to an Indian tribe. They head for home but each sends a note to their respective off-springs advising them of their good fortune. One of the fathers conceives a plan of taking a dagger and wrapping a piece of string around the blade, after which he prints on the string with a lead pencil, the exact location of their find. If something happens to them, the string goes to the son and the knife to the daughter. That night an Indian approaches their camp and blows some mysterious wolf powder which causes a man to see wolves in place of human beings. Lightning''s father see his partner as a wolf and stabs him to death; later he is brought into town in a dying condition but before dying, hands the knife and the string over to the sheriff with instructions to deliver to Lightning and Kate.', 'Paul Hurst', 300, '1919-10-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uclMLbRvVnWyFrga1jz3AfzixXT.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (376, 'The Enchanted Circle', 'A documentary filmed aboard a German U-Boat during the First World War, featuring footage of the capture and sinking of cargo ships and a private schooner.', 'Hans Brennert', 45, '1917-08-01', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/uFy3sa6MEGnoucAKsnelEGBHdIB.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (377, 'The Lost Battalion', 'World War I, October 1918. The more than 500 men of the 77th Infantry Division of the United States Army, who have been recruited in New York City and trained in Yaphank, are sent to France, to help break down the German defenses located in the Argonne forest…', 'Burton L. King', 100, '1919-07-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1vzZgOsPP3U29yfRHPatQ2YeoFx.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (378, 'Love''s Prisoner', 'A young lady, who "hates the law" rises from the tenements to society. Financial reverses lead her to commit a series of burglaries as "The Bird". She becomes involved with the detective investigating the burglaries. After she confesses and pays for her crimes, they marry.', 'John Francis Dillon', 47, '1919-06-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3tQZyW4GWdwcHgJHNE3BCnEhVmk.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (379, 'Male and Female', 'When an aristocratic family and their servants are shipwrecked, the butler becomes their ruler.', 'Cecil B. DeMille', 116, '1919-11-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uYaztWl9nlbEaRqrehSqYqD81zV.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (380, 'Marked Men', 'Three outlaws rescue a baby in the desert and with barely any water left try to return to the town in which they just robbed a bank. Lost film. A remake of 1916''s "The Three Godfathers," which also starred Harry Carey.', 'John Ford', 50, '1919-12-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7p1ofLjFtUpLfFVYd9m5Qvvxm5O.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (381, 'The Master Mystery', 'In this action-packed serial, government agent Quentin Locke infiltrates a corrupt patents company, only to run into the gleaming terror of its robot protector, the Automaton. In order to save the beautiful Eva Brent and find a cure for the dreaded Madagascar Madness, Locke suffers an inhuman array of tortures and physical restraints. He is chained, tied with barbed wire, padlocked in a crate and thrown in the water, tied beneath a descending elevator, strapped to an electric chair, and bound in an elaborate Oriental torture chamber.', 'Burton L. King, Harry Grossman', 238, '1918-11-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zzwKT4yqafN863MLPw8049rFkU4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (382, 'Meyer from Berlin', 'Sally Meyer, a young Berliner, persuades his Doctor to convince his wife that he is ill, so that he is able to take a holiday in the Austrian Alps.', 'Ernst Lubitsch', 58, '1919-01-17', 'P', 'de', 'https://image.tmdb.org/t/p/w500/wg9X3L0idMUbvuP6yDYSMBE0I8H.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (383, 'The Miracle Man', 'A gang of crooks evade the police by moving their operations to a small town. There the gang''s leader encounters a faith healer and uses him to scam gullible public of funds for a supposed chapel. But when a real healing takes place, a change comes over the gang. Lost film, only the most famous scene has survived.', 'George Loane Tucker', 80, '1919-08-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/25eKiwXuctD5TjA5E23JvM3ovxf.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (384, 'The Mother and the Law', 'A re-edited version of the fourth episode of Intolerance (1916); two youth are made homeless by a strike, and struggle valiantly to survive their desolate situation, which worsens as reform-minded citizens remove the couple''s child from their care and the young father is falsely accused and convicted of murder.', 'D.W. Griffith', 99, '1919-08-18', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pzGIK0iJZRw9hGdbjqucAbeJzX9.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (385, 'Opium', 'In China, Professor Gesellius has completed his long research on the many uses of opium. When he is about to return home, he hears about a special variety that produces fabulous sensations because of the way it is made, but can also cause the total destruction of the mind and body of the person who consumes it.', 'Robert Reinert', 93, '1919-01-07', 'P', 'de', 'https://image.tmdb.org/t/p/w500/p3NElouXFbuO4ytboPOOenNHmUh.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (386, 'The Other Half', 'Social drama about a friendship that is pressurized by class differences.', 'King Vidor', 51, '1919-08-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7u5NQRHqKq41grKmCuHCDrPtcv6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (387, 'The Outcasts of Poker Flat', 'The owner of a gambling hall is entrusted with the care of a pretty young girl. He falls in love with her, but he must decide whether to let her go to his best friend, with whom he believes her to be in love, or to try to win her for himself.', 'John Ford', 60, '1919-06-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kHSx1Y5sUe9VSOAfCaKgHegj06W.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (388, 'The Plague in Florence', 'Suddenly appearing in Florence, an evil seductress causes Cesare, the city''s ruler, and his son to both fall madly in love with her. The son, killing his father before an order to torture the woman can be carried out, then turns the city''s churches into dens of sexual debauchery. Acts of evil and corruption continue unabated until the arrival of Death, who brings with her a horrible plague which she is about to loose upon the city.', 'Otto Rippert', 103, '1919-10-23', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/9GkxU3rJx7oLRas2lUQAAi0tJWQ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (389, 'Phil-for-Short', 'A feisty, independent young woman, Damophilia Illington ("Phil" for short, hence the title), the daughter of a progressive university professor, is devastated by the sudden death of her father. The town''s banker, an arrogant stuffed shirt, wants to marry Phil and has himself declared her guardian. Not wanting to marry him, she quickly leaves town and lands a job at a nearby university as an assistant to a professor of Greek literature (an area in which her father trained her) who is bitter and resentful after the breakup of his engagement to a woman who, it turned out, had been lying to him. "Phil", however, is determined to win him over.', 'Oscar Apfel', 82, '1919-06-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kSyt3nGO4Nrr4dJVcCxAm8RgfRp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (390, 'The President', 'A judge sees his illegitimate daughter face trial for infanticide. He''s certain that she will receive the death sentence.', 'Carl Theodor Dreyer', 85, '1919-02-01', 'K', 'da', 'https://image.tmdb.org/t/p/w500/lSb0Y8xQpVZPQ5N28UMLU1LGNYE.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (391, 'The Doll', 'The misadventures of an effete young man who must get married in order to inherit a fortune. He opts to purchase a remarkably lifelike doll and marry it instead, not realizing that the doll is actually the dollmaker’s flesh-and-blood daughter in disguise.', 'Ernst Lubitsch', 66, '1919-12-05', 'P', 'de', 'https://image.tmdb.org/t/p/w500/iJjxE2VjjSKmfvBmQFRDFkZFTRL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (392, 'The Red Lantern', 'Mahlee and Blanche Sackville are half-sisters, Blanche the daughter of an Englishman and his wife, Mahlee of the Englishman and his Chinese mistress. Mahlee rejects her people and attempts to find a life for herself among the Europeans. But she finds the color line impossible to pass and returns to lead her Chinese people in rebellion.', 'Albert Capellani', 70, '1919-05-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/s02LLntaR2PvnGI85ogBDNV5non.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (393, 'Rider of the Law', 'Jim Kyneton, once a member of an outlaw gang, joins the Texas Rangers and is forced to track down his former friends and his half brother Nick, who have been robbing a gold mine.', 'John Ford', 60, '1919-11-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/doTusHzMr0UsN2qLrhrziNqpcmB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (394, 'Riders of Vengeance', 'Harry''s bride is murdered at their wedding along with Harry''s mother and father, and the good-hearted outlaw turns grimly malevolent.', 'John Ford', 60, '1919-06-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zNDVU8DB43KxsgO8t9LCwad8kaU.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (395, 'The Roaring Road', '"Toodles" Waldron, racing enthusiast and the best salesman for J. D. Ward''s automobile company, quarrels with his boss; Ward will not let him enter the Santa Monica Grand Prize Road Race, or marry his daughter Dorothy.', 'James Cruze', 58, '1919-04-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wEaZfUU3uUsg29xLT3XkW3ikgLb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (396, 'Roped', 'Wealthy ranch owner Cheyenne Harry decides he needs a housekeeper, but his cowboys decide he needs a wife and advertise in an eastern newspaper. The ad is answered by Aileen Judson-Brown, as dictated by her fortune-hunting mother. Harry marries Aileen and a baby is born a year later. Deciding to gain more money and social standing, Mrs. Judson-Brown then tries to break up the marriage so that Aileen can marry Ferdie Van Duzen. Mrs. Judson-Brown steals the baby and tells Harry the baby has died and Aileen no longer loves him. Harry goes out West in sorrow, but when Mrs. Judson-Brown''s butler wires Harry the truth, Harry locates the baby and discovers Aileen still loves him. The reunited family goes West together, leaving Mrs. Judson-Brown behind.', 'John Ford', 60, '1919-01-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mItHcLbfN1U3gdRtSk4xrsrJeRU.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (397, 'Scarlet Days', 'In early lawless California, Rosie Nell, a woman of disreputable dance halls, is wrongly charged with the murder of one of her fellow entertainers. Because her daughter, who knows nothing of her mother''s station in life, is to return the next day from education in the east, Rosie is granted three days of grace to be spent in company with her daughter at a nearby cabin. The three days begin happily enough, thanks to the serenades of heroic bandit Alvarez and the poetry of romantic Randolph. But Bagley, the dance hall manager, has seen the daughter and has determined to make her his own.', 'D.W. Griffith', 77, '1919-11-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/liQNvx1GbIrvIgtMratWr42JEZM.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (398, 'The Sentimental Bloke', 'Bill is a Woolloomooloo larrikin who vows to abandon his life of gambling and drinking after a spell in gaol following a raid on a two-up game. He falls in love with Doreen, who works in a pickle factory, but faces competition from a more sophisticated rival.', 'Raymond Longford', 106, '1919-10-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3ptSmwCeT66uHPsnoXDE5hDrweB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (399, 'The Spiders: Part 1 - The Golden Sea', 'In San Francisco, well-known sportsman Kay Hoog announces to a club that he has found a message in a bottle with a map drawn by a Harvard professor who has gone missing. The map tells of a lost Incan civilization that possesses an immense treasure. Hoog immediately plans an expedition to find it. But Lio Sha, the head of a criminal organization known as the Spiders, is determined to get the treasure for herself and plans a rival expedition.', 'Fritz Lang', 69, '1919-10-03', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/9QNyYzPy20gNOn1k3XkIr3op7xm.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (400, 'The Fairy of Solbakken', 'Synnöve lives with her parents at the farm Solbakken on a sunny hill. Thorbjörn, who lives at Granliden in the shadow of a big mountain, often looks wistfully up to Solbakken. As teenagers they meet and fall in love. Another boy, Knud Nordhaug, is also yearning for Synnöve.', 'John W. Brunius', 111, '1919-10-20', 'T13', 'sv', 'https://image.tmdb.org/t/p/w500/oIkAXhI2yL2MekfPtWolVxtaQMz.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (401, 'Song of the Scarlet Flower', 'The son of a wealthy farmer loves a simple maid, for which he''s booted out of the house by his father.', 'Mauritz Stiller', 100, '1919-04-14', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/ugQWcz2r2gow5ywj2UGCagIOH26.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (402, 'The Devil''s Church', 'In a prologue and four acts (the prologue and the first act are lost so is necessary to describe what happens with title cards) the film depicts the terrible dream of Asmus wherein the devil joins the human world disguised as a tinker. He meets Frau Ane, Asmus'' wife; Ane yearns to have a baby but in vain so the devil takes advantage of Frau Ane''s motherly inner desire by making a deal with her but for his own purposes. As a result, the farmer''s wife comes under the devil''s spell and then seduces the local priest, giving the devil to chance to build his own church to replace the old church that has burned down.', 'Hans Mierendorff', 66, '1919-01-01', 'T18', 'de', NULL, NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (403, 'The Tong Man', 'An opium smuggler is marked for murder in this story of the Chinese Mafia.', 'William Worthington', 54, '1919-12-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bNBe7nRDHtE4KgJqvUbfxtZsWZ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (404, 'True Heart Susie', 'In a country town, Susie, innocent and big-hearted, quietly gives money to William Jenkins, a man she secretly yearns for, so he can attend college. After he graduates, he returns and becomes the town''s minister. However, he never realizes how Susie feels about him and ignores her in favor of Bettina Hopkins, a wild and unfaithful girl who steals his heart. Susie must then find a way to show William that she''s loved him all along.', 'D.W. Griffith', 87, '1919-06-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gcbYqPH849tsohFoVjG3lXgbSE8.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (405, 'Eerie Tales', 'A demon, a reaper, and the ghost of a prostitute read gothic short stories and act them out.', 'Richard Oswald', 101, '1919-11-05', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/53971ZEqRIk600jY8juaCBMaAT7.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (406, 'The Valley of the Giants', 'Rival logging companies battle for the Valley of the Giants (redwood trees) when a young engineer returns home to help his father by building a new rail line to transport the logs to the sawmill. A romance between the engineer and the rival''s niece complicates the situations.', 'James Cruze', 50, '1919-08-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cqr4HYNm2ghIYVm0NAVlCoWYk0j.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (407, 'Victory', 'Adaptation of Joseph Conrad novel about lust and violence on a South Seas Island.', 'Maurice Tourneur', 62, '1919-12-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3DcvmY561lQrPP10U5TNSMKGg0C.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (408, 'Wagon Tracks', 'Buckskin Hamilton guides a wagon train across the wasteland, caring well for the pioneers he escorts, but hoping to solve the murder of his brother by one of the travellers.', 'Lambert Hillyer', 68, '1919-07-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bCuWRfZuYxrAwCVUUrb9ylRGvei.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (409, 'A Tale of Two Worlds', 'A white child is adopted and raised by a Chinese citizen and brought to San Francisco, where no one surmises that she is actually not Chinese.', 'Frank Lloyd', 70, '1921-03-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/mbQbOEdwIAreyjLqzRNFcd8P9cL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (410, 'When the Clouds Roll By', 'Daniel Boone Brown is a pleasure-seeking playboy carousing around New York City without a care in the world -- that is, until he becomes the unwitting subject of a series of experiments at the hands of a sadistic psychiatrist.', 'Victor Fleming', 85, '1919-12-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jt16vWT6X1UAsKOklmcyxxcFUz3.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (411, 'The Wicked Darling', 'Slum girl Mary is forced to steal for a living. After she swipes a rich society''s matron''s necklace, she hides out at the home of a man who turns out to be the socialite''s former fiancé.', 'Tod Browning', 59, '1919-12-25', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/cx6tQ3gKZGkVmfgaKyOU93yaJAb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (412, 'The Witness for the Defense', 'Stella Derrick and Dick Hazelwood love each other, but their families want them to make better financial matches.', 'George Fitzmaurice', 59, '1919-09-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/tEoR2vVQ8cy1Gh47QC0CT6highd.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (413, 'Yankee Doodle in Berlin', 'Behind enemy lines, Captain Bob White disguises himself as a woman in order to fool members of the German High Command, including the Kaiser himself.', 'F. Richard Jones', 67, '1919-03-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/c6fQgpNv0cFcKGbIO5rAtSQsR5j.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (414, 'Evening – Night – Morning', 'Cheston, a millionaire, is looking after Maud, a beautiful woman from the ''demimonde''. Her brother, Brilburn, forces her to ask her rich admirer for an expensive piece of jewelry. Cheston buys a precious pearl necklace. Lost film.', 'F. W. Murnau', 50, '1920-09-24', 'K', 'de', 'https://image.tmdb.org/t/p/w500/wxeH4Jn0FdwiFoUmHShKuchcjKC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (415, 'Algol: Tragedy of Power', 'An alien from the planet Algol gives a man a device that creates enough energy to power the entire world.', 'Hans Werckmeister', 99, '1920-09-03', 'P', 'de', 'https://image.tmdb.org/t/p/w500/p6M2lSt0SMShQ9D5BZX0Qzum0nB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (416, 'Anna Boleyn', 'The story of the ill-fated second wife of the English king Henry VIII, whose marriage to the Henry led to momentous political and religious turmoil in England.', 'Ernst Lubitsch', 118, '1920-12-03', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/kuNc1A3g2KMlUzDCpvm2JRhGNNI.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (417, 'April Folly', 'April Poole (Davies), a young writer in love with publisher Kerry Sarle (Tearle), visits the office of Mr. Sarle and his partner Ronald Kenna (Frank) and reads her latest story to them. She has made Sarle the hero, Kenna the villain, and herself the heroine. In the story, April changes places with Lady Diana Mannister (Marshall), who is being sent to South Africa to separate her from her lover, a young artist. A famous diamond that Lady Diana is to deliver at the end of her journey is given to April. Thieves trail her during her journey. With efforts by Kenna to steal the diamond prevented by the intervention of Sarle, the story comes to a close.', 'Robert Z. Leonard', 50, '1920-03-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nLOgVdMwiCxfwqBCkcj2uHaFuC1.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (418, 'L''Atlantide', 'Two men, lost in the desert, meet Queen Antinea, ruler of Atlantis.', 'Jacques Feyder', 169, '1921-05-28', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/k2bdO0JIjpHzbupPlGcSO4wQEyC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (419, 'Below the Surface', 'A widely respected deep-sea diver is approached by a ring of con artists who want him to be the front man for a phony scheme to recover gold from sunken ships. When he refuses, they send a sexy young woman to seduce his son, and then blackmail the father into going along with their scheme.', 'Irvin Willat', 91, '1920-06-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s2mzu7UIXzZsDVyCc2pV2JIsNqr.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (420, 'Leaves from Satan''s Book', 'The power of Satan is highlighted in four historical tales: the betrayal and subsequent arrest of Jesus, the Spanish Inquisition, the French Revolution and the execution of Marie Antoinette, and the Finnish War of Independence in 1918.', 'Carl Theodor Dreyer', 157, '1920-11-15', 'T18', 'da', 'https://image.tmdb.org/t/p/w500/kElKCJ7pv6egE52087VWwxOj1vD.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (421, 'The Hunchback and the Dancer', 'Wilton, a hunchback, who was always scorned and ridiculed by women, returns from Java a rich man after having discovered a diamond mine. He romances Gina, who is on the rebound from a broken affair, and showers her with expensive gifts. After Gina reconciles with her boyfriend, she continues to see Wilton because of what he gives her. After he discovers her perfidy, Wilton develops a poison and mixes it into her lipstick, which will kill any man who kisses her.', 'F. W. Murnau', 50, '1920-07-08', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/hWJvGG6QU2ouIfaWtAggC0tW832.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (422, 'Conrad in Quest of His Youth', 'Conrad Warrener, a man of near middle-age, reflects nostalgically on the happy times of his youth and decides to recapture them. However, what he learns about the "second time around" is neither what he expected nor what he hoped for.', 'William C. deMille', 75, '1920-11-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7B4ikKThviyu2VfA1vVJHhRusOs.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (423, 'The County Fair', '"The County Fair" begins with a nasty rich guy threatening to turn an old lady onto the street--unless her niece (who lives with her) marries this man''s son. While she''s dead set against it, the niece is a sweet thing and would do anything to help her aunt--even marry the rich jerk. However, a possible way out is presented. When a poor young man is taken in and fed, he turns out (naturally) to be a jockey and thinks he can win the $3000 prize at the fair and save the farm.', 'Maurice Tourneur', 59, '1920-09-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yAxRPlgGAvgNFcbw6CZr4dkhLEk.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (424, 'The Cradle of Courage', 'Former crook ''Square'' Kelly serves in the First World War. When he returns from the war, one of his comrades-in-arms convinces him to join the police force. But Kelly finds himself confronting the very criminals who made up his old gang.', 'Lambert Hillyer, William S. Hart', 50, '1920-09-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iFHcSPCprwVgnnXYwlrw8i3yH2J.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (425, 'Dinty', 'Dinty is a newsboy whose fight to care for his ailing mother leads him into conflicts with the other boys on the street and then with drug smugglers in Chinatown.', 'John McDermott, Marshall Neilan', 72, '1920-11-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/maeyy982qK1Ao38eMVBJ8emjOtV.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (426, 'Down on the Farm', 'The day starts off as any normal day on Roach''s farm, where Teddy, the farmhouse dog, is doing more productive work than everyone else combined. But the day changes when Roach''s farmhand sees an opportunity to be the knight in shining armor to Louise, Roach''s daughter, who he wants to marry.', 'Erle C. Kenton, F. Richard Jones, Ray Grey', 50, '1920-04-17', 'K', 'en', 'https://image.tmdb.org/t/p/w500/qsKH19yT1lFhjcU4grHxUvOgZXf.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (427, 'Dr. Jekyll and Mr. Hyde', 'A doctor''s research into the roots of evil turns him into a hideous depraved fiend.', 'John S. Robertson', 79, '1920-03-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/u8OL0RbTNzqqB1WmkxroTBXohnv.jpg', 'https://www.youtube.com/watch?v=P0DK1dl8eRc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (428, 'Erotikon', 'Erotikon is a 1920 Swedish romantic comedy film directed by Mauritz Stiller, starring Tora Teje, Karin Molander, Anders de Wahl and Lars Hanson. It is based on the 1917 play A kék róka by Ferenc Herczeg. The story revolves around an entomology professor obsessed with the sexual life of bugs, and his easygoing wife who is courted by two suitors.', 'Mauritz Stiller', 106, '1920-11-08', 'T13', 'sv', 'https://image.tmdb.org/t/p/w500/6Jh4VB9priCQmM14pAjownxucxm.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (429, 'Excuse My Dust', 'A top race-car driver leaves the sport to get married and settle down, because his new wife doesn''t want him to race anymore. However, not long afterwards his wife takes their infant son and leaves him to go to San Francisco. The husband gets word that his son is seriously ill in San Francisco, but he has no way to get there. Just in the nick of time, however, the racer''s father-in-law just happens to have developed a new car for a cross-country race--to San Francisco!', 'Sam Wood', 48, '1920-03-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iODZQgkRZCGLXKUS74Gi2s07cKm.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (430, 'Fante-Anne', 'The story of an orphaned girl brought up by the Storlein family. Young Anne (Asta Nielsen) is brought as an infant to the Storlein farm by her mother, who has been traveling and is in need of a rest. The two are turned away at the door, and the mother takes her young daughter to the barn to sleep. The farmhand Jon discovers them in the morning but the mother has not made it through the night, so young Anne is taken in and raised by the family.', 'Rasmus Breistein', 72, '1920-09-09', 'T16', 'no', 'https://image.tmdb.org/t/p/w500/4FJnH37VYc8lCfZu7IlnrUcjEBU.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (431, 'The Flapper', 'A Southern teen at a ritzy boarding school gets into mischief while acting the sophisticated grownup to impress a suave gentleman and match wits with a pair of jewel thieves.', 'Alan Crosland', 88, '1920-05-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bAp8ph46CVJIFUeN3SnB8di5iuI.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (432, 'The Fortune Teller', 'When Renee Browning is falsely accused of having an illicit affair with circus manager Tony Salviatti, her jealous husband Horatio divorces her and takes custody of their little boy Stephen, to whom she had been devoted. Renee accepts a position as a circus fortune-teller, where she gradually deteriorates into drunken degradation.', NULL, 70, '1920-01-01', 'T13', 'en', NULL, NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (433, 'Spanish Fiesta', 'Coveted by two different men, a woman turns to a third man instead.', 'Germaine Dulac', 26, '1920-03-31', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/fclnS0UDa6mHtkZG1h8UaJRH4Nn.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (434, 'Journey into the Night', 'Dr. Egil Börne, an eminent physician, comes under the spell of an unscrupulous cabaret dancer and deserts his fiancée. The plot finds echoes throughout the Weimar period, including Sternberg’s The Blue Angel. Conrad Veidt appears in a supporting role as a sinister blind painter, whose entrance eerily presages Murnau’s Nosferatu. Der Gang in die Nacht, the earliest surviving film by F. W. Murnau, is also, paradoxically, the only Murnau film for which the original camera negative exists.', 'F. W. Murnau', 81, '1921-01-21', 'P', 'de', 'https://image.tmdb.org/t/p/w500/p8YTVpLBJsJAUro6f42gvxig8Um.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (435, 'Genuine: The Tragedy of a Vampire', 'Since completing a portrait of Genuine, a high priestess, Percy becomes irritable and withdrawn. He loses interest in painting and refuses to see his friends, preferring to spend his time alone with the portrait in his study. After turning down a wealthy patron''s offer to buy the picture, Percy falls asleep while reading stories of Genuine''s life. Genuine comes to life from the painting and escapes.', 'Robert Wiene', 88, '1920-09-02', 'T18', 'xx', 'https://image.tmdb.org/t/p/w500/pQZNf7PA0CTJXZFez7NQ3RUgJ0r.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (436, 'The Girl in Number 29', 'Laurie Devon is a New York playwright who, having had one success, refuses to work on another play.', 'John Ford', 50, '1920-05-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/JEfmiZOQMskcpoU0xxKnuPrlzp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (437, 'Go and Get It', 'Wrestling legend Bull Montana plays a murderous gorilla with a human brain transplant who is tracked by a feisty newspaper reporter.', 'Henry Roberts Symonds, Marshall Neilan', 70, '1920-07-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zEE5ywFq5mV3ZLSe7waeENtukEf.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (438, 'The Golem: How He Came into the World', 'In 16th-century Prague, a rabbi creates the Golem - a giant creature made of clay. Using sorcery, he brings the creature to life in order to protect the Jews of Prague from persecution.', 'Carl Boese, Paul Wegener', 85, '1920-10-29', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/7zdqM0MgZBfy3tuJdNO4cWAGBtj.jpg', 'https://www.youtube.com/watch?v=FSTH0lGYqJ0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (439, 'Headin'' Home', 'The "true story" of baseball great Babe Ruth; Ruth plays himself.', 'Lawrence C. Windom', 71, '1920-09-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iSanzft10nYyid7NvCHhv3AK6Xk.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (440, 'Helen of Four Gates', 'HELEN OF FOUR GATES was made in Hebden Bridge in 1920 by silent film pioneer Cecil M. Hepworth, based on a popular novel of the same name. Reportedly highly successful when it first opened, the film would later fall into obscurity, with all copies believed to be destroyed. In 2007, a print was discovered in a vault in Canada.', 'Cecil M. Hepworth', 78, '1920-09-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/biQW2EHDZMWSHcuDmwi7dgTrNdd.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (441, 'The Swallow and the Titmouse', 'Herr Pierre Van Groot owns two barges. Van Groot, his wife, and his sister-in-law navigate along the north channels between Belgium and France. Herr Pierre transports construction material in his barges but he earns extra francs trafficking in diamonds, which he hides in the boat’s rudder. Pierre engages a new first mate, Michel, who gets wise to the diamond smuggling. The film was shot in 1920, but only shown once in its 80 minute entirety at a private screening in 1924.', 'André Antoine', 78, '1924-06-05', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/xT4O36tT10bgAiQnJZeUwUw0J4h.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (442, 'Hitchin'' Posts', 'Jefferson Todd and Louis Castiga, brothers-in-law, come to blows on a Mississippi River steamer when Todd discovers Castiga''s presence there with a woman.', 'John Ford', 50, '1920-09-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/llLSUNWhYXOpfcIJDHjfwqes8ce.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (443, 'The Man of the Sea', 'Nolff, a tough Breton fisherman is happy: his wife has just given birth to a son, Michel. His only wish is to make him a fisherman like him. But when he becomes a man, Michel becomes a good-for-nothing who spends his time in taverns.', 'Marcel L''Herbier', 86, '1920-12-03', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/13c3AJysZ3sNdO0GpsA4RmNktAh.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (444, 'The Hound of the Baskervilles', 'After the death in suspicious circumstances of Charles Baskerville, the last descendant of the lineage of the Baskervilles, Henry, returned to the old family mansion. The charismatic detective Sherlock Holmes and his faithful assistant, Dr. Watson, investigating the case, and discover the existence of a supernatural hound that in addition murderer according to history, killed many years ago Hugo Baskerville, the first of the line, and it seems that the curse stalks his descendants.', 'Maurice Elvey', 100, '1921-08-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/7qAPb1Q7ZoikemUPQu8rgtsmF3r.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (445, 'Huckleberry Finn', 'Huckleberry Finn, a rambuctious boy adventurer chafing under the bonds of civilization, escapes his humdrum world and his selfish, plotting father by sailing a raft down the Mississippi River. Accompanying him is Jim, a slave running away from being sold. Together the two strike a bond of friendship that takes them through harrowing events and thrilling adventures.', 'William Desmond Taylor', 70, '1920-02-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fbsThgTWny7zCZp8iXmyljyHx5b.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (446, 'Humoresque', 'Young Leon Kanter dreams of being a great violinist. His parents scrape up the money for a violin and for lessons, and Leon rewards them by becoming a great player. But as an adult, Leon finds that people want more from him than just music.', 'Frank Borzage', 71, '1920-05-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/56JT45OHQe3TV7ZD6nK6qcdEbNf.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (447, 'The Idol Dancer', 'A religious zealot and his nephew are thrown together on a South Seas Island with an alcoholic beachcomber and a native dancer. A battle to see who will ''civilize'' whom ensues.', 'D.W. Griffith', 104, '1920-03-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8f0sBGuhjp33RVSCxTVIBqF2DQZ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (448, 'The Jack-Knife Man', 'A dying mother left his child with an old man, but the village people want to take the child away from him because he is too old.', 'King Vidor', 78, '1920-07-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vvMubNtH9aA2EtIKCenSrxYPFMC.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (449, 'The Head of Janus', 'Two opposing characters are hidden in the person of the inconspicuous London gentleman Dr. Warren and Janus. A lost film.', 'F. W. Murnau', 107, '1920-08-26', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/QomFFEz7FN5plcSmEhAGT2OdGL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (450, 'Just Pals', 'Bim seems to be his town''s biggest loser, but when he takes a needy 13-year-old boy named Bill under his wing, it seems there may be some hope for Bim. After learning about Bill, a young teacher, Mary, whom Bim secretly adores, helps get the young boy into school. And when Bim then helps Mary repay a loan, defaulted on by shifty boyfriend, it becomes evident that Bim can reform. As the plot in this captivating film twist and turns, the stakes get higher, the action gets more intense and hope for Bim bounds upward.', 'John Ford', 50, '1920-10-21', 'K', 'en', 'https://image.tmdb.org/t/p/w500/mK7YrW8eK9fBZzAix0UyBA7gHwF.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (451, 'Karin, Daughter of Ingmar', 'Karin Daughter of Ingmar is a 1920 Swedish silent drama film directed by Victor Sjöström. It is the second part in Sjöström''s large-scale adaption of Selma Lagerlöf''s novel Jerusalem, following Sons of Ingmar from the year before, and depicting chapter three and four from the novel. The critical reception was however unenthusiastic and Sjöström decided to not direct any more parts.', 'Victor Sjöström', 115, '1920-02-02', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/9s8IwaCyKgHycChI3jsCcHTd8nw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (452, 'Kismet', 'Hajj, a rascally beggar on the periphery of the court of Baghdad, schemes to marry his daughter to royalty and to win the heart of the queen of the castle himself.', 'Louis J. Gasnier', 85, '1920-11-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9E0kr4LEC9oC53e7vH9uSWGNrwY.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (453, 'Der Klosterjäger', NULL, 'Franz Osten', 70, '1920-11-26', 'P', 'de', NULL, NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (454, 'The Monastery of Sendomir', 'Two riders on their way to Warsaw stop at a monastery for the night and ask an old monk there to tell them the story of its founding.', 'Victor Sjöström', 53, '1920-01-01', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/rKP4f9gYubqhDvZApHw3chZpHRi.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (455, 'Kohlhiesel''s Daughters', 'Somewhere in Southern Bavaria Xaver wants to marry Gretel, but her father Kohlhiesel wants his elder daughter Liesel to marry first. The problem is, nobody wants to marry her, because she is too brutal. Seppel suggests, that he should marry Liesel first, get rid of her and then he can marry Gretel...', 'Ernst Lubitsch', 64, '1920-03-08', 'P', 'de', 'https://image.tmdb.org/t/p/w500/yEV6UpeA2vIW7K0yU148CPrO0mP.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (456, 'The Last of the Mohicans', 'As Alice and Cora Munro attempt to find their father, a British officer in the French and Indian War, they are set upon by French soldiers and their cohorts, Huron tribesmen led by the evil Magua. Fighting to rescue the women are Chingachgook and his son Uncas, the last of the Mohican tribe, and their white ally, the frontiersman Natty Bumppo, known as Hawkeye.', 'Maurice Tourneur', 73, '1920-11-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kNpjv5byJM8H83JJwPLMDyB095t.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (457, 'Deerslayer', 'Chingachgook, son of the chief of the Delaware Indian tribe and faithful friend of Hawkeye the Deerslayer is raised by his tribe after being orphaned.', 'Arthur Wellin', 59, '1920-09-14', 'P', 'de', 'https://image.tmdb.org/t/p/w500/aEkhZzdlFsUTTbQOh47UPnlitXB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (458, 'The Leopard Woman', 'An epic of passion, intrigue, and espionage set in the African Jungle.', 'Wesley Ruggles', 68, '1920-10-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mXJxEp32W7T2aHrby5Oc54eND4f.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (459, 'The Life of the Party', 'An attorney is thrust into wild adventures by an attractive young woman.', 'Joseph Henabery', 55, '1920-11-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/39eZ7iSfIV5XjjbdqMDY130fLWR.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (460, 'The Love Expert', 'After neglecting her studies in favor of romantic experiments, Babs Hardcastle is thrown out of boarding school. In hopes of ceasing her romance studies, Babs’s father sends her to Boston to stay with her aunt. Boston, however, proves to be the perfect place for Babs’s matchmaking. When Babs falls in love with Jim Winthrop, she learns that he must find suitable men for his two sisters, Dorcas and Matilda, and his elderly aunt Cornelia, before he can marry. Babs, determined to marry Jim, takes it upon herself to find them all husbands.', 'David Kirkland', 60, '1920-04-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fVpxcAQHr4xu36yKt5k1SMy7rDb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (461, 'The Love Flower', 'A man murders his wife''s lover and escapes with his daughter to the South Pacific. A detective is in pursuit, joined by a young man who eventually falls in love with the daughter.', 'D.W. Griffith', 104, '1920-08-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6tQwIx1uDwUrGnBb1GVcs5RPogq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (462, 'The Mark of Zorro', 'Don Diego Vega pretends to be an indolent fop as a cover for his true identity, the masked avenger Zorro. Preserved by the Academy Film Archive in 2012.', 'Fred Niblo', 107, '1920-12-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1N1gSSJs9ULgSWUM0W7zCXSR2QK.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (463, 'Growth of the Soil', 'In rural Norway in the early 20th century, the homesteader Isak makes a farm out of barren soil, together with his wife Inger and their two sons. Life is both harsh and fulfilling.', 'Gunnar Sommerfeldt', 107, '1921-12-02', 'P', 'no', 'https://image.tmdb.org/t/p/w500/nzkFnh0dffiAiysvAanHPUOGyOT.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (464, 'The Mollycoddle', 'An American who has lived much of his life outside the country returns to Arizona for the first time in years and encounters villainy.', 'Victor Fleming', 86, '1920-06-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wlosW7vbQ2Z9Ah20fX1P8ay4OXZ.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (465, 'A Lover in Pawn', 'About loaner Master Samuel, based on a writings by Hjalmar Bergman', 'Victor Sjöström', 116, '1920-10-11', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/phzXGwGQCZEfiwwXQeMmwVnROW7.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (466, 'Nomads of the North', 'A Canadian Mountie allows an innocent fugitive to escape with the women he loves.', 'David Hartford', 78, '1920-09-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/luw9FUl3J9jxyYtayh83BoQihvQ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (467, 'Nurse Marjorie', 'Lady Marjorie Donegal becomes a nurse in hospital, much to the dismay of her aristocratic family. She falls in love with one of her patients, a commoner labor leader.', 'William Desmond Taylor', 88, '1920-04-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/19y0WP7B9tlKaHxMptku7TvQwLa.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (468, 'Der Ochsenkrieg', 'Berchtesgaden in the 15th century: A power struggle between mountain peasants who have been raising milk cows on common land and a village bailiff trying to gain power driving them off the land. Both have a ducal documents that states the opposite.', 'Franz Osten', 86, '1920-10-16', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/u4IjUzrRPJBdF1zJPLzTVXwL4iE.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (469, 'The Penalty', 'Blizzard, deranged from a childhood operation in which both his legs were needlessly amputated after an accident, becomes a vicious criminal, and eventually mob leader of the San Francisco underworld.', 'Wallace Worsley', 90, '1920-08-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ct5XMbwZWv3SzZ01lYM4rQihRmA.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (470, 'Pink Tights', 'When a circus troupe comes to a small, extremely conservative New England town, the residents go to their minister to have him protest the scandalous fact that the female tightrope walker wears a pair of pink tights. When she has an accident and is forced to recuperate at the minister''s house, he has to hide her in order to avoid even more of a scandal. Mazie Darton, a high-wire performer with a traveling circus, longs for a peaceful country life. Forced to stay in a small town while laid up with an injury, Darton is spurned by the conservative townspeople. Rev. Jonathon Meek, the local parson, befriends the circus troupe, especially Darton. But he, too, opens himself to criticism from his flock, who protest his closeness with the show people. Eventually, Darton''s boyfriend arrives and the pair become closer. The parson fades from the scene as a possible mate for Darton, who ends up winning the hearts of the townspeople.', 'B. Reeves Eason', 50, '1920-09-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8IIXaaXoG0ISoO4BdEfkAV8PHJv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (471, 'Pollyanna', 'When Pollyanna is orphaned, she''s sent to live with her crotchety Aunt Polly. Pollyanna discovers that many of the people in her aunt''s New England hometown are as ill-tempered as her aunt. But Pollyanna''s incurable optimism - exemplified by her "glad game", in which she looks for the bright side of every situation - brings a change to the staid old community.', 'Paul Powell', 58, '1920-01-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sShuXyUMN1w3LNtl0HpRXingGxK.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (472, 'For Don Carlos', 'Pour Don Carlos was the biggest production by Société des Films Musidora (est. December 10, 1919). Based on a novel by Pierre Benoît, Musidora’s first creatively autonomous work is set during the conflict between Carlists and Bourbons in late 19th century Spain. Benoît insisted that Jacques Lasseyne, a Spanish grandee who put money into the production, should co-direct. The film was shot in 1920, in the Spanish Basque Country. It represents a turning point in Musidora’s career, sparking her passionate love affair with a country and a culture that welcomed her as a great star. Above all, though, she encountered Antonio Cañero, a bullfighter who acted as her technical adviser on the film. Because of him, she did all she could to ensure that her succeeding productions, until 1926, were shot in Spain. Pour Don Carlos was released in Paris and in Madrid in December 1921, in a shortened version because its original, three-hour length made it impossible to release in the market of the time.', 'Jacques Lasseyne, Musidora', 77, '1921-12-01', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/rdFKxgdYITyloOyok7ezNpaAAnW.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (473, 'The Prince of Avenue A', 'Barry O''Connor, son of Patrick O''Connor, plumber and political power, is called to the residence of William Tompkins whom he is to "put over" in the coming election.', 'John Ford', 50, '1920-02-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ylKrPJfufpvJpNROBxtkPTauBW4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (474, 'The Parson''s Widow', 'A newly elected village parson is required to marry his predecessor''s widow. However, he''s already married, and the woman is old enough to be his grandmother.', 'Carl Theodor Dreyer', 93, '1920-10-04', 'K', 'sv', 'https://image.tmdb.org/t/p/w500/xOntAvES3qCiFcX4vAq7U7Ic1kb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (475, 'The Merry-Go-Round', 'Drama about street walker Elena who marries shop keeper Albert. When her former pimp Peter shows up, her life is ruined. She shoots him and poisons herself.', 'Richard Oswald', 98, '1920-02-27', 'P', 'de', 'https://image.tmdb.org/t/p/w500/mm7S0hXi1XFA2U7kJszAu4I1YvP.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (476, 'Remodeling Her Husband', 'After she marries Jack Valentine, Janie Wakefield discovers that her husband''s reputation as a flirt is well deserved when she sees him riding in a taxi with a strange woman. Jaine sets out to remodel her husband into the man she wants.', 'D.W. Griffith, Lillian Gish', 50, '1920-06-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zBb20yWJFihHj0s3JFO2qUhuSQY.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (477, 'The Restless Sex', 'A love triangle drama, based on a novel by Robert W. Chambers, who is better-known for weird fiction (which is not noticeable in this story.)', 'Leon D''Usseau, Robert Z. Leonard', 82, '1920-11-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eZ9MQpjpzQ46WJIBEqmLCvRgrq6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (478, 'The Revenge of Tarzan', 'Tarzan and Jane are traveling to Paris to help his old friend Countess de Coude, who is being threatened by her brother, Nikolas Rokoff. Rokoff has Tarzan tossed overboard. He survives, comes ashore in North Africa, and goes to Paris to search for Jane. In Paris, Tarzan reunites with his old friend Paul D''Arnot, who informs him that Jane was taken to Africa. Tarzan returns just in time to save Jane from a lion attack, and soon defeats Rokoff and his henchmen.', 'George M. Merrick, Harry Revier', 90, '1920-05-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/271GNlF2rgAh3y3olh90M779XK2.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (479, 'Robbery Under Arms', 'It''s a bush-ranging yarn, very popular at the time, about Captain Starlight, played well by Brampton himself, and his co-horts the Marsden family. Dick Marsden is especially well played by Roland Conway, who is the quintessential Aussie bloke.', 'Kenneth Brampton', 53, '1920-09-30', 'P', 'en', NULL, NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (480, 'Romeo and Juliet in the Snow', 'The story of Romeo and Juliet, a tale as old as time-- Here, played as farcical lark: A goofy comedy of manners set in a snowy Bavarian village.', 'Ernst Lubitsch', 46, '1920-03-11', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/pdStZtVQHqdSnHByu4APT8tTFGI.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (481, 'The Round-Up', 'A lovesick sheriff protects his town, embroiled in a feud between a crafty bandit leader and the family of the prospector he stole from.', 'George Melford', 70, '1920-10-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fO64BazlAfICCJvPdaHZCOXz6GI.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (482, 'Sand', 'Railroad station agent Dan Kurrie is fired from his job by his rival in love, Joseph Garber. Believed false by the girl he loves, Margaret , Kurrie must prove himself by unmasking a gang of bandits preying on the trains.', 'Lambert Hillyer', 88, '1920-06-19', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/30biduxrjaq5UDTKH97CPYlSVnp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (483, 'The Saphead', 'Nick Van Alstyne owns the Henrietta silver mine and is very rich and his son Bertie is naive and spoiled. His daughter Rose is married to shady investor Mark. Mark wrecks Bertie''s wedding plans by making him take the blame for Mark''s illegitimate daughter, and also nearly ruins the family business by selling off some stock at too low a price.', 'Herbert Blaché, Winchell Smith', 77, '1920-09-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/n1i7g4dGkV6oKxPpFJJYk2gVhh4.jpg', 'https://www.youtube.com/watch?v=0Bcl0kRg8i4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (484, 'Satan', 'A three-part historical film: the first episode takes place in ancient Egypt, the second is based on the Hugo novel La Fin de Satan, and the third takes place during the 1917 Russian revolution. Lost film, minor fragments survive', 'F. W. Murnau', 54, '1920-01-30', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/vgaExSsDpelntdeu89zslZ693fu.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (485, 'Desire: The Tragedy of a Dancer', 'A young Russian dancer in Geneva returns to Russia, where he falls in love with a grand duchess. He is arrested but manages to escape. Lost film.', 'F. W. Murnau', 59, '1921-01-01', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/2RVBw22FqD9myoGTcGIOgJnWorq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (486, 'Sex', 'A Broadway actress uses her sex appeal to ruin a marriage only to dump her lover for a richer prospect.', 'Fred Niblo', 87, '1920-03-29', 'K', 'en', 'https://image.tmdb.org/t/p/w500/qp77TtlISuAaFF2pLa6HYI0xdRf.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (487, 'Something to Think About', 'Wealthy cripple Markley finances the education of blacksmith''s daughter Ruth. When she returns to their small town he asks to marry her, but she runs off with city worker Jim Dirk who is then killed in a subway accident. Markley offers to marry her in name only to protect her new son.', 'Cecil B. DeMille', 78, '1920-10-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/thhENCbA3EgckHRr5Oz12tNPFKE.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (488, 'The Son of Tarzan', 'Tarzan''s son Jack is kidnapped from England by his old enemy Paulovich. Jack escapes into the African jungle where he meets Meriem, a European girl held captive. Freeing her, he falls in love but she''s sought by Paulovich. Then Tarzan arrives with Jane to save the day!', 'Arthur J. Flaven, Harry Revier', 248, '1920-04-30', 'T13', 'xx', 'https://image.tmdb.org/t/p/w500/6TJ78ttG3O7pNSN8xBmYBf4nIKm.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (489, 'The Soul of Youth', 'Ed Simpson has been raised in an orphanage where he has caused much trouble. He can''t stand living there anymore and runs away. On the streets, he finds a friend in newsboy Mike. Mike teaches him how to survive, but inevitably Ed gets hauled into court. The judge sees potential in him and hands him over to be adopted by a young politician.', 'William Desmond Taylor', 80, '1920-08-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s3lHtrgRWIoBtYYgW5xzhsch4pP.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (490, 'The Spiders: Part 2 - The Diamond Ship', 'When we last saw Kay Hoog (millionaire adventurer, courageous hunk), he’d been beset with tragedy. Having escaped an ancient Incan city by the skin of his gleaming teeth, Hoog looked forward to a few years of settled life with his (amicably) captured Incan lovely, Naela. But the past struck quickly. Hoog’s arch-nemesis, the homicidal femme Lio Sha, murdered Naela on the very grounds of Hoog’s estate, prompting him to swear revenge upon her and her criminal organization, the Spiders. Now he must find them, as the Spiders continue their global quest for the Buddha-head Diamond. The head, it’s said, has the power to restore Asia to world dominance.', 'Fritz Lang', 105, '1920-02-06', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/d8ITbno8Sa6prOoHYzrOAtL9gga.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (491, 'Suds', 'Amanda Afflick is a lovesick laundress who daydreams about customer Horace Greensmith and cherishes the shirt he brought in for washing eight months and sixteen days ago. She tells her fellow workers that the garment belongs to her fiancé, a lord. Just wait, Amanda boasts, one day his lordship will return for his wash — and for her.', 'John Francis Dillon', 75, '1920-01-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vWDdPzYqjHeNheGKZju2D3JBewt.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (492, 'Sumurun', 'The favorite slave girl of a tyrannical sheik falls in love with a cloth merchant. Meanwhile, a hunchback clown suffers unrequited love for a traveling dancer who wants to join the harem.', 'Ernst Lubitsch', 115, '1920-09-01', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/4xPpsUli6UiKab3V7HZ5i5pa0xk.jpg', 'https://www.youtube.com/watch?v=SKVt2TVgq4M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (493, 'Terror Island', 'Inventor Harry Harper travels to the South Seas, where there is buried treasure belonging to a girl, Beverly West. Naturally, others are after the loot, and Beverly''s father is being held captive by cannibals until she returns to them with a pearl that belongs to one of their idols. The climax consists of Harper saving Beverly from a safe which has been lowered into the sea.', 'James Cruze', 55, '1920-04-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/cW9xKunDuZko1bXUwFka1G50L81.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (494, 'The Toll Gate', 'Outlaw Black Deering leads a band of desperadoes, but decides to give up the bandit life. Agreeing to go on one last job with his gang, he is captured when his henchman Jordan betrays the gang for the reward. Deering escapes and determines to avenge himself on Jordan.', 'Lambert Hillyer', 73, '1920-04-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/AiM9RHHR4Kdp7h6xCZDJLGYyBxB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (495, 'Treasure Island', 'Young Jim Hawkins is caught up with the pirate Long John Silver in search of the buried treasure of the buccaneer Captain Flint, in this adaptation of the classic novel by Robert Louis Stevenson.', 'Maurice Tourneur', 76, '1920-01-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9lrshRGhD6A7M2cYk4yKHWUT3GK.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (496, 'The Virgin of Stamboul', 'Turkish chieftain Achmet Bey catches one of his many wives in adultery and murders her lover. Tossing aside the cuckolding wife, he abducts his harem an innocent girl. However, a brave American who loves her comes to her rescue.', 'Tod Browning', 70, '1920-03-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kkuewUuuIvlLCUHTPs8fpgsVgUR.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (497, 'From Morning to Midnight', 'A cashier in a bank in a small German town is alerted to the power of money by the visit of a rich Italian lady. He embezzles 60,000 Marks and leaves for the capital city, where he attempts to find satisfaction in politics, sport, love and religion.', 'Karlheinz Martin', 72, '1920-01-01', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/phrxYtv83YAgN2G2QKUKHOAZ37w.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (498, 'The Wandering Image', 'When Irmgard becomes pregnant from Georg, a free-love disciple, she decides, for the sake of her child, to pretend they are married. The secret plan is to wed his twin brother, John, who will pretend to be Georg in front of the priest. Soon after that happens, Georg disappears and is declared dead. Years later, Irmgard is trying to escape John, who is obsessed with her. In the mountains, she finds a stranger willing to protect her.', 'Fritz Lang', 67, '1920-12-25', 'K', 'de', 'https://image.tmdb.org/t/p/w500/eKihlPmSmn5HgiJqjN1T4qMGnn6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (499, 'Way Down East', 'A naïve country girl is tricked into a sham marriage by a wealthy womanizer, then must rebuild her life despite the taint of having borne a child out of wedlock.', 'D.W. Griffith', 150, '1920-09-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s2sX5dcNP1pyyjrWaNnTNI4HdIq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (500, 'What Happened To Rosa', 'A fortune teller tells a store clerk with a romantic disposition that she was a Spanish noblewoman in an earlier life. The girl begins to live the part of the Spanish noblewoman and romance and comedy ensue.', 'Victor Schertzinger', 54, '1920-12-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pAjKC0kMoopHYOvadY6YLrT28Js.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (501, 'Why Change Your Wife?', 'Robert and Beth Bordon are married but share little. He runs into Sally at a cabaret and the Gordons are soon divorced. Just as he gets bored with Sally''s superficiality, Beth strives to improve her looks. The original couple falls in love again at a summer resort.', 'Cecil B. DeMille', 90, '1920-05-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/oZ7IfogJdVGspHJtiXyLR8pHrqS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (502, 'Within Our Gates', 'Abandoned by her fiancé, an educated black woman with a traumatizing past dedicates herself to helping a near bankrupt school for impoverished black children.', 'Oscar Micheaux', 74, '1920-01-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/36MR5nOWUZypLY3i32LCjdqxXOQ.jpg', 'https://www.youtube.com/watch?v=kD_FwBz3JY8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (503, 'A Woman in Grey', 'This 15 chapter serial is considered to be "the last of the adult serials". Produced in Wilkes-Barre, PA., it has crisp editing, fast action, and carefully lit and composed interiors and lush pictorial exteriors. This is a serial of great complexity with the director, the photographer and title-maker always in absolute control. The extraordinary rhythmic momentum of the film is never lost despite the films complex plot turns. This is the best of the surviving serials from the silent era.', 'James Vincent', 236, '1920-01-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sQ0LXxI9pIPjAHcujr9IyKB5PP1.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (504, 'The Woman in the Suitcase', 'Mary Moreland discovers the photograph of a woman not her mother in her father''s suitcase and sets out to find her in hopes of returning her father to his rightful place in the family.', 'Fred Niblo', 60, '1920-01-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6rLBrHqd1af42MkLBx4dUIDbdor.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (505, 'The Wonderful Chance', 'Upon leaving prison, an ex con vows to go straight, but circumstances force him to return to crime. Meanwhile, a gang of crooks kidnaps a visiting British aristocrat, but the ex-con has an incredible likeness to the Englishman, and his intended hosts take him home to their mansion.', 'George Archainbaud', 52, '1920-09-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3j2SACnjmERH27pnF0r3jBswMlI.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (506, 'The Ace of Hearts', 'A romantic rivalry among members of a secret society becomes even more tense when one of the men is assigned to carry out an assassination.', 'Wallace Worsley', 75, '1921-09-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vfiwnig4WB95Veu7zaQsYgB3SAD.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (507, 'Action', 'Three Outlaws came across a stranded baby and must decide to save the child or escape from the law.', 'John Ford', 50, '1921-09-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1f6vxdfhmj5rzsU9ySYOW7i4vfS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (508, 'The Adventures of Tarzan', 'Tarzan spurns the love of La, Queen of Opar. When he isn''t trying to keep the Bolshevik Rokoff and Clayton (pretender to the Greystoke estate) from reaching Opar, he is attacked simultaneously by two lions, dropped into a pit when a volcano splits the ground, nearly sacrificed by sun worshipers, and so on.', 'Robert F. Hill, Scott Sidney', 150, '1921-12-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jlpcD1PX3squ1ATsqPbWSxKhGaG.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (509, 'The Affairs of Anatol', 'Socialite Anatol Spencer, finding his relationship with his wife lackluster, goes in search of excitement. After bumping into old flame Emilie, he lets an apartment for her only to find that she cheats him. He is subsequently robbed, conned, and booted from pillar to post. He decides to return to his wife and discovers her carousing with his best friend Max.', 'Cecil B. DeMille', 117, '1921-09-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kBtHJOXtbSm9vfPDaH5JAovCYOb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (510, 'All Dolled Up', 'The department store clerk Mary prevents a robbery at the store where she works, involving a necklace belonging to a rich unmarried woman named Eva Bandy. Later, she manages via a misunderstanding to prevent a million-dollar robbery of the same woman. With the man of her dreams, who helped her foil the robberies, she is "adopted" by Eva.', 'Rollin S. Sturgeon', 50, '1921-03-28', 'K', 'en', 'https://image.tmdb.org/t/p/w500/fQWwugH7kBcJ4U2f7F3HFwuYf6A.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (511, 'Be My Wife', 'Max is determined to woo Mary, despite her Aunt Agatha''s disapproval. Then, Max and Mary become embroiled in the world of Madam Coralie, a prominent dressmaker-bootlegger.', 'Max Linder', 57, '1921-04-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sKWp3OoIK0y31xT6WXHBprpOmNB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (512, 'Beau Revel', 'Lawrence Revel, celebrated in society circles for his success with women, is devoted to his son Dick and objects to his marrying Nellie, a cabaret dancer. To prove her unworthiness, Beau asks his son not to see her for 2 weeks. Unwittingly, Beau falls in love with the girl, but his attentions are refused.', 'John Griffith Wray', 69, '1921-03-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/nc7WFkciV2BAFrV6tjtfBdfz1qP.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (513, 'The Wildcat', 'A charismatic lieutenant newly assigned to a remote fort is captured by a group of mountain bandits, thus setting in motion a madcap farce that is Lubitsch at his most unrestrained. A wonderfully anarchic and playfully subversive satire of military life from one of the great comedy filmmakers.', 'Ernst Lubitsch', 85, '1921-04-14', 'P', 'de', 'https://image.tmdb.org/t/p/w500/8YWjCN3B8vDKEsDyhOfUfn8XgSR.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (514, 'The Big Punch', 'Buck, who is preparing to enter a theological seminary, aids his brother and some friends who are fleeing from justice, and thus implicated he is sent to prison for 2 years. There he meets again Hope Standish, a Salvation Army girl who had interested him. Returning home, he meets the old district circuit rider and promises to continue the circuit rider''s work when he dies. The brother escapes from prison and is converted by Buck, who falls in love with Hope.', 'John Ford', 50, '1921-02-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sRPdkqVR62GgJFNUe3yBqwGQhVy.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (515, 'The Blot', 'Professor Griggs, teaching at the college, doesn''t get paid a living wage; his next door neighbor, successful shoemaker Olsen, has money and plentiful food, while the Griggses have hardly any. When the professor''s rich student Phil West falls for beautiful Griggs daughter Amelia and also befriends the poor Reverend Gates (a young man who is also in love with Amelia), he observes the difference in his life and theirs and tries to help make a difference.', 'Lois Weber', 91, '1921-09-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kMhSGNckzR79WjQptmJvkTV1g0H.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (516, 'Brewster''s Millions', 'Monte Brewster learns that he has inherited $10 million from his late grandfather, but then learns that he must spend $2 million in less than a year and remain unmarried to inherit the rest of the money.', 'Joseph Henabery', 61, '1921-01-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ing3wrCkmkCbaudaW4clrb9W8YK.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (517, 'Buried Treasure', 'Strung around the idea of reincarnation, this film goes back in time to the days of the Spanish galleons and pirates burying their treasure; treasure to be found centuries later.', 'George D. Baker', 70, '1921-04-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xQxPKGzRYsTYsdMcLDM1nawnizn.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (518, 'Burn ''Em Up Barnes', 'Car racer Burn ''em Up Barnes, son of a wealthy manufacturer, leaves home to make his own way in the world. After being robbed by hoodlums, Barnes joins a group of hobos who take him in and show him the carefree life.', 'George Beranger, Johnny Hines', 60, '1921-08-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cKzZJZZReGDSniRQlOeXpbJSYdW.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (519, 'Camille', 'Camille is a courtesan in Paris. She falls deeply in love with a young man of promise, Armand Duval. When Armand''s father begs her not to ruin his hope of a career and position by marrying Armand, she acquiesces and leaves her lover. However, when poverty and terminal illness overwhelm her, Camille discovers that Armand has not lost his love for her.', 'Ray C. Smallwood', 70, '1921-09-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/17rCD5J12IBhhymAc7AvskUNA20.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (520, 'The Conquering Power', 'Young playboy Charles Grandet is sent to live with his miserly uncle after his father loses his fortune. He and his cousin Eugenie fall in love, but his uncle sends him away and tries to arrange a marriage more to his liking (and profit!). Will true love triumph?', 'Rex Ingram', 89, '1921-07-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zTY04P11V2kWfrBqnz3EvFxHk41.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (521, 'Danton', 'At the height of Reign of Terror Maximilien Robespierre orchestrates the trial and execution of several of his fellow leading French revolutionaries including Georges Danton.', 'Dimitri Buchowetzki', 87, '1921-05-03', 'P', 'de', 'https://image.tmdb.org/t/p/w500/4kBRaJnnLZbXn53aDlZKorZ46aG.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (522, 'Desperate Trails', 'Bart Carson is in love with Lou and even goes to jail to save Walter A. Walker, a man she says is her brother but who is really a husband who has deserted his wife and two children.', 'John Ford', 50, '1921-06-11', 'K', 'en', 'https://image.tmdb.org/t/p/w500/ml9wfLeyWvRVNGk5NndeLrlCUm.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (523, 'The Devil', 'Dr. Muller, a friend to all, finds pleasure in turning the goodness in people to evil ends. He meets Marie Matin and her fiancée, Georges Roben, while viewing a new painting, "The Martyr--Truth Crucified by Evil." Marie declares that the picture was wrong--evil could never triumph over truth--and though Muller says he agrees with her, he plots to prove otherwise.', 'James Young', 58, '1921-01-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9Y93FtwGC9Zh3bsHB2BpbZQx0f3.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (524, 'Dream Street', 'In London''s Limehouse district, dancehall girl Gypsy Fair finds herself the prize in a tug of war between a pair of dueling orphaned brothers.', 'D.W. Griffith', 132, '1921-04-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fmoC8q704z8BaNLzpRfzJNRLD.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (525, 'Ducks and Drakes', 'A spoiled rich young woman overspends from her parents'' savings and ruthlessly vamps on young men that she calls up randomly on the telephone. When her fiancée and his friends get word of this, they hatch a plan to teach her a valuable lesson.', 'Maurice Campbell', 58, '1921-02-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gu2d4aSoiBGn0Vhra06PKvzVJHC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (526, 'El Dorado', 'In Granada in Spain, Sibilla works as a dancer in a squalid cabaret called El Dorado, struggling to earn enough to care for her sick child. The boy''s father Estiria, a prominent citizen, refuses them both help and recognition, fearful of jeopardising the engagement of his adult daughter Iliana to a wealthy nobleman. Iliana however slips away from her engagement party to meet her real lover Hedwick, a Swedish painter. Sibilla, in desperation after a further rejection by Estiria, sees an opportunity to blackmail him by locking the lovers overnight in their meeting-place in the Alhambra.', 'Marcel L''Herbier', 98, '1921-10-28', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/21UFgss2aXyejijtYhQQD948yF3.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (527, 'Enchantment', 'The frothy experiences of a vain little flapper. Her father induces an actor friend to become a gentlemanly cave man and the film becomes another variation of the ''Taming of the Shrew'' theme.', 'Robert G. Vignola', 90, '1921-10-29', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/dCsUx75ezJqdfuv2lMyTGNIgiZo.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (528, 'Fool''s Paradise', 'In a Mexican border town Arthur befriends cantina girl Poll. She falls for him but he still loves the dancer Rosa. When the cigar Poll gives him explodes and blinds him, Arthur is duped into thinking Poll is Rosa and marries her. When his vision is surgically restored, he leaves for Siam to find Rosa.', 'Cecil B. DeMille', 109, '1921-12-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aERr7tIe44autYq260wBhgIxEhp.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (529, 'Forbidden Fruit', 'Mary Maddock works as a seamstress to bring home money while her husband Steve, unemployed, has no real prospects of earning money. Mary''s employers, are trying to strike an oil related business deal with a rich man by the name of Nelson Rogers. The deal does not seem to be on the table, as Mr. Rogers is leaving town shortly and does not have the time to work out the details of such a deal. In an order to entice him to stay, Mrs. Mallory - wife of Mr. Mallory who is proposing the business deal - convinces Mary to be her guest at a dinner party with the intent of making Mr. Rogers fall for her and thus stay long enough for Mr. Mallory to make him agree to a business deal.', 'Cecil B. DeMille', 87, '1921-01-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/mwVNfWHi8Jw7x1n0I5sfMflHY26.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (530, 'The Four Horsemen of the Apocalypse', 'Set in the years before and during World War I, this epic tale tells the story of a rich Argentine family, one of its two descending branches being half of French heritage, the other being half German. Following the death of the family patriarch, the man''s two daughters and their families resettle to France and Germany, respectively. In time the Great War breaks out, putting members of the family on opposing sides.', 'Rex Ingram', 156, '1921-03-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/262nYFe45BxX22M9TPhB4BwEqby.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (531, 'Mrs. Dane''s Confession', 'Murder in a suburban hotel: suspect is the British upper-class-woman Dorothy who’s accused of murdering her husband – a fraud who gained wealth with shoddy tricks. Dorothy’s memories unveil piece by piece the prelude to this act of desperation.', 'Michael Curtiz', 62, '1921-10-07', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/A0BRJN3yMINsFUJuzAt8fZI7l6a.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (532, 'The Freeze-Out', 'Into the town of Broken Buckle rides a stranger who threatens to open a new gambling establishment to rival the one operated by Denver Red and Headlight Whipple. The latter''s sister, Zoe, who disapproves of her brother''s saloon and is the local schoolteacher and owner of a notions store, tries to interest The Stranger in reforming the vice-ridden community.', 'John Ford', 50, '1921-04-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3WmOgZvZdqwohSG05jOjlMQzje3.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (533, 'Hail the Woman', 'Oliver Beresford is a stern, Puritanical, and uncompromisingly rigid father. When shameful stories about his daughter Judith surface, rather than determine whether the stories are true, he bans her from his house. Her brother David, a pusillanimous reprobate, has secretly married and fathered, then abandoned, a child. Judith takes care of the child and finds a way to restore her family through the love for the babe.', 'John Griffith Wray', 80, '1921-11-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/b8q5RXF1peT8cJcg19UZ3ofa3Xj.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (534, 'Hamlet', 'A free adaptation of Shakespeare′s drama. The Danish queen masquerades her daughter as a boy, and thus, the girl lives her life as ''Prince'' Hamlet. Her father poisoned by a venomous snake placed by the treacherous Claudius, Hamlet fakes madness to investigate without suspicion.', 'Heinz Schall, Svend Gade', 112, '1921-01-27', 'K', 'de', 'https://image.tmdb.org/t/p/w500/iPX08Mtpk1mtYXNUhMUBUP9v5lh.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (535, 'Backstairs', 'In a poor neighborhood of a big city, a crippled mailman is in love with a maid who lives in his building. However, she is in love with a wealthy and handsome young man, who soon disappears. The mailman provides the maid with letters that get her hopes up... but tragedy will soon befall all three.', 'Leopold Jessner, Paul Leni', 50, '1921-12-11', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/jDvCqsc3mWnEw4Q4MpPOMugriIL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (536, 'The Hope Diamond Mystery', 'The true story of Lord Francis Hope who inherits the Hope Diamond and marries showgirl May Yohe. Lord Francis Hope gambles away the family fortune and May Yohe leaves him. Another suspected curse of owning the Hope Diamond.', 'Stuart Paton', 300, '1921-02-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zRGr52c7lux1GduKVuRjHIDl92S.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (537, 'The Indian Tomb, Part II: The Tiger of Eschnapur', 'Rowland falls sick with leprosy while Mac Allan is captured by the Maharajah, who offers Irene a deal: one night with him in exchange for letting Rowland to be cured. She accepts, but tries to commit suicide.', 'Joe May', 106, '1921-11-19', 'P', 'de', 'https://image.tmdb.org/t/p/w500/y7Dk64iKZprSDJymdfGkWHoB91x.jpg', 'https://www.youtube.com/watch?v=qVeWOvuurys', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (538, 'The Indian Tomb, Part I: The Mission of the Yoghi', 'Ayan, Maharajah of Eschnapur, believes that his wife, Princess Savitri, has been unfaithful to him with officer Mac Allan. He decides to bury her alive, so he sends the Yogi Ramigani to England to look for Herbert Rowland, an architect; but when he orders him to build a tomb, Rowland refuses.', 'Joe May', 127, '1921-10-22', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/vfregqnBEHlXGF68xD57RNJrRfL.jpg', 'https://www.youtube.com/watch?v=qVeWOvuurys', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (539, 'Johan', 'On a farm in up-country Sweden, an enigmatic stranger comes to a conservative peasant community and seduces a farmer''s wife.', 'Mauritz Stiller', 110, '1921-02-28', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/IqA5kRaZBdjjr8AVFaVN7Jqwhh.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (540, 'The Kid', 'A tramp cares for a boy after he''s abandoned as a newborn by his mother. Later the mother has a change of heart and aches to be reunited with her son.', 'Charlie Chaplin', 68, '1921-01-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/A9NWYyn7eX0H9XIjaOvfWJ9mCGA.jpg', 'https://www.youtube.com/watch?v=O5WXokyub-4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (541, 'The Phantom Carriage', 'An alcoholic, abusive ne''er-do-well is shown the error of his ways through a legend that dooms the last person to die on New Year''s Eve before the clock strikes twelve to take the reins of Death''s chariot and work tirelessly collecting fresh souls for the next year.', 'Victor Sjöström', 108, '1921-01-01', 'T16', 'sv', 'https://image.tmdb.org/t/p/w500/yGNekNFaI4SeyDO8C0BkRXM6Byu.jpg', 'https://www.youtube.com/watch?v=DUX2w7TFNHQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (542, 'Labyrinth of Horror', 'A young poor girl falls in love with a rich heir.', 'Michael Curtiz', 91, '1921-11-10', 'P', 'de', 'https://image.tmdb.org/t/p/w500/jXzzNOLEoKTrfViu22mbsHBOv3J.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (543, 'Ladies Must Live', 'Schooled by her wealthy brother-in-law William Hollins, Christine Bleeker plans to marry Ralph Lincourt when he is divorced. He, however, is equally pursued by Nancy Barron, whom Christine dislikes. Ned Klegg loves social secretary Barbara, and resents the attention paid her by Barron, Nancy''s elderly husband. Nell Martin, a servant in the Hollins home, is in love with the gardener but is persecuted by the butler. Aviator Mulvain and his mechanic Le Prim arrive, and Le Prim absconds with Nancy in an auto, pursued by Mulvain and Christine, who force him to release her. Christine announces her engagement to Mulvain, who declares he is a poor man. In the resulting commotion, it transpires that Nell, threatened with exposure, has drowned herself. The shock brings a change of emotion: Barbara rejects Barron and accepts Klegg, and Christine accepts Mulvain, content to share his poverty. Considered a lost film.', 'George Loane Tucker', 80, '1921-10-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sqACU1Eo6icKmmhFnWE2xgTqb2b.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (544, 'Leap Year', 'A young man, heir to his misogynistic and millionaire uncle, and in love with a nurse, gets in trouble when he gives advice on marriage to his girlfriends.', 'James Cruze', 56, '1924-01-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iK5Qnh2EBagSBVdSmL9vfIOuu2b.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (545, 'Little Lord Fauntleroy', 'An American boy turns out to be the long-lost heir of a British fortune. He is sent to live with the cold and unsentimental lord who oversees the trust.', 'Alfred E. Green, Jack Pickford', 112, '1921-09-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8dGPDwry1BlM7Q2tQ2MBRQhIXT0.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (546, 'The Little Minister', 'In 1840 Scotland, a young lass named Babbie revels in the country life and frolics with the locals, simple weavers whose livelihood is threatened by increasing industrialization. When Lord Rintoul attempts to rout the rebellious weavers, Babbie always manages to send word in time to prevent their being taken by surprise. Gavin, new minister to the town, falls in love with Babbie, and his relationship with the young gypsy almost costs him his position. But what Gavin and his parishioners do not know is that Babbie is actually Lady Babbie, ward of Lord Rintoul.', 'Penrhyn Stanlaws', 68, '1921-12-25', 'K', 'en', 'https://image.tmdb.org/t/p/w500/lqXDch1ldicPzHMwMRTCWwHR35O.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (547, 'Lotus Blossom', 'The film is perhaps the only remaining example of silent era cinema from a Chinese-American production company, and was co-written, co-directed (with Francis J. Grandon) and produced by James B. Leong, who changed his name from Leong But-jung after emigrating from Shanghai in 1913. Of the seven reels that originally comprised ''Lotus Blossom,'' only one (the fifth, running for 12 minutes at 20fps) is known to survive. This remaining reel of film is now available on Disc 2 of the DVD Collection "More Treasures from the American Film Archives," and was preserved by the UCLA Film and Television Archive.', 'Francis J. Grandon, James B. Leong', 70, '1921-12-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8OjB1Sa4DMKJ3k5sOioqIFCaz8p.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (548, 'The Love Light', 'Angela maintains a coastal lighthouse in Italy, where she awaits the return of her brothers from the war. She learns they are casualties and takes solace in the arms of an American sailor washed ashore. However, the sailor turns out to be a German spy, and she is torn between her love for him and her realization that he is part of the enemy force that has destroyed her family.', 'Frances Marion', 89, '1921-01-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5sP9zkGajOUZxM7teAprv9lhmIQ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (549, 'Love Never Dies', 'John and Tilly''s happy marriage is ruined when Tilly''s father finds out about the scandalous past of John''s mother. John, unaware of his father-in-law''s meddling, thinks Tilly has left him, and he leaves town. Her father leads Tilly to believe that John has died in an accident, and he pushes her to marry someone else.', 'King Vidor', 63, '1921-11-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/h0GfkfErW8k6hJ2s1Xe7QlPa8YQ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (550, 'A Fortune Hunter', 'Historical drama which features Gösta Ekman as the dashing rogue who steals the heart of the ethereal Mary Johnson.', 'John W. Brunius', 95, '1921-03-14', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/zumDF63gn4FkX8UPBVRPOHLS07K.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (551, 'The Man Tamer', 'A young woman becomes a lion tamer in a circus. The circus manager is in love with her, but she only has eyes for a millionaire''s playboy son.', 'Harry B. Harris', 50, '1921-05-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ePGPVil4kqLvwWY8had6GcGEli6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (552, 'The Man Who Had Everything', 'Harry Bullway is a careless young man, always after a good time. He nearly runs over a blind beggar with his car, but he shows no remorse. In response to his heartlessness, the beggar curses him, saying, "May you always have everything that you want."', 'Alfred E. Green', 66, '1920-10-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xRNO5r3Dl3dJLyIV27BUSIt3Ya.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (553, 'Miss Lulu Bett', 'Lulu Bett lives in the home of her sister Diana and Diana''s husband, Dwight. One day Dwight''s brother, Ninian, shows up, and he and Lulu Bett have a mock marriage. Dwight declares the marriage legal, but it turns out that Ninian already has a wife.', 'William C. deMille', 71, '1921-11-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xWUxh0FWMTClAFoGBPNe0vGL916.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (554, 'Molly O''', 'An Irish washerwoman''s daughter falls in love with one of America''s most eligible bachelors, much to the dismay of the girl''s parents -- and the young doctor''s newly acquired fiancée! Events come to a head at the charity masked ball, which the two girls happen to attend in very similar costumes, thanks to the largesse of Molly''s benevolent "fairy godfather"...', 'F. Richard Jones', 80, '1921-11-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/TRNjy1T2AmswLhkGbUbSkopUoY.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (555, 'Arsena Georgiashvili', 'Revolutionary uprising of Georgian laborers in 1905.', 'Ivane Perestiani', 49, '1921-10-01', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/cnIRATqr2NYDJApA74yzh9YoAyo.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (556, 'My Boy', 'An orphan escapes immigration officials at Ellis Island and goes to live with an old ship''s master who can''t find work and can''t pay the rent.', 'Albert Austin, Victor Heerman', 55, '1921-12-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/spCtQRCfm89bnUAm1WjJbhLB4Vs.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (557, 'Destiny', 'As a young couple stops and rests in a small village inn, the man is abducted by Death and sequestered behind a huge doorless, windowless wall. The woman poisons herself in order to join him and is met by Death, who gives her three opportunities to prove that love is stronger than death, thereby freeing her beloved from his fate.', 'Fritz Lang', 98, '1921-10-06', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/zgRB2MhCTfOMkxRO7seX6GxOaKJ.jpg', 'https://www.youtube.com/watch?v=8EVYTPoMaQI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (558, 'The Nut', 'Eccentric inventor Charlie Jackson tries to interest wealthy investors in his girlfriend''s plan to help children from poor neighbourhoods.', 'Theodore Reed', 74, '1921-03-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/puK0tVGKc0sSvDHKrzI1XP1tOMZ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (559, 'Orphans of the Storm', 'France, on the eve of the French Revolution. Henriette and Louise have been raised together as sisters. When the plague that takes their parents'' lives causes Louise''s blindness, they decide to travel to Paris in search of a cure, but they separate when a lustful aristocrat crosses their path.', 'D.W. Griffith', 150, '1921-12-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gbBzFuiVnuSPYZRXRArILc3Ywz3.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (560, 'Outside the Law', 'Silent Madden and his daughter Molly have left the criminal underworld of San Francisco thanks to the wise teachings of Chang Low, a Confucian master. But the evil Black Mike Sylva is determined to frame Madden to avenge a mistake from the past…', 'Tod Browning', 76, '1921-01-06', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/6kFx2g6eiOw3micfARbhZte69te.jpg', 'https://www.youtube.com/watch?v=SWCqCcvhfZs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (561, 'Peck''s Bad Boy', 'This portrayal of small town life before the War is based on a small boys determination to get to see the circus, over all obstacles. Escaped lions, lightheaded blackmail of his father, and playfully planting stolen papers on his sisters boyfriend are all in a days work for little Henry Peck.', 'Sam Wood', 64, '1921-04-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qqHwVTgNAXKMZEmfgr71f01ddhw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (562, 'A Perfect Crime', 'Wally Griggs is your classic meek, mild bank messenger, destined to a threadbare life of earning 63 dollars a month. At least this is what he seems to be. But when he''s not working Griggs is the dashing James Brown, an adventurer and storyteller who is familiar with bank president Halliday. A publisher, fascinated by Brown''s wild tales, offers him a deal. Griggs also uses his alter ego to help Mary Oliver, the girl her loves.', 'Allan Dwan', 50, '1921-03-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zvaXhbKEicvMIgnyxIhK35NZw8j.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (563, 'The Queen of Sheba', 'The story of the ill-fated romance between Solomon, king of Israel, and the Queen of Sheba.', 'J. Gordon Edwards', 90, '1921-04-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uyKT3mMhX3bmPWybW0dFPQZloxi.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (564, 'Rip Van Winkle', 'The story shows the development of the united state in divergent fields : Political, social and even economic field.', 'Edward Ludwig', 58, '1921-10-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5uFbEJ0Jp2w1nUQTmnZJ2eULPqd.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (565, 'A Sailor-Made Man', 'An idle, wealthy playboy foolishly joins the Navy when the father of the girl he wants to marry tells him to get a job to prove himself worthy.', 'Fred C. Newmeyer', 47, '1921-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5Qdn5nArhsVNL0awfYUhWEpQFhb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (566, 'The Haunted Castle', 'The sinister Count Oetsch scandalizes the aristocratic social gathering at Castle Vogelod as he announces his intention to "crash" the festivities. Baroness Safferstätt is expected shortly, and the guests are well-aware of the rumors that Count Oetsch murdered the baroness'' late husband. Oetsch refuses to leave, vowing that he will reveal the identity of the real killer. Before the weekend is through, the Count and Baroness will reveal secrets too shocking to be believed!', 'F. W. Murnau', 81, '1921-04-07', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/7FK7XuRQhKHmN3MKHkelQxiuQWy.jpg', 'https://www.youtube.com/watch?v=zRuWOowfupo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (567, 'The Sheik', 'Sheik Ahmed desperately desires feisty British socialite Diana, so he abducts her and carries her off to his luxurious tent-palace in the desert. The free-spirited Diana recoils from his passionate embraces and yearns to be released. Later, allowed to go into the desert, she escapes and makes her way across the sands...', 'George Melford', 86, '1921-11-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5cwKEW94PEB1IPQtlJMdP1suXnu.jpg', 'https://www.youtube.com/watch?v=5YJqG8dqlUU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (568, 'The Three Musketeers', 'In 17th century France, young D''Artagnan wants to join the King''s Musketeers, but instead befriends three legendary musketeers—Athos, Porthos, and Aramis—and together, they become embroiled in the political intrigue surrounding King Louis XIII and his adversaries, particularly the powerful Cardinal Richelieu.', 'Fred Niblo', 144, '1921-08-28', 'T13', 'xx', 'https://image.tmdb.org/t/p/w500/55FdDXbYk8EdIFP0UTxCd1I5r3t.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (569, 'Tol''able David', 'Young David Kinemon is a good-natured, easy-going lad in a mountain village. Circumstances force him to take his brother''s place as mail carrier for the community, and this brings him into deadly contact with the vicious Hatburn brothers.', 'Henry King', 94, '1921-12-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vKhaX0KRDmnQSfZB8AqS24H8a6J.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (570, 'Beyond the Rocks', 'A young woman dutifully marries an older millionaire and then falls in love with a handsome nobleman-- who''d previously saved her life-- on her unhappy honeymoon.', 'Sam Wood', 80, '1922-05-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/lWCoi2Iv9eUUesR88ctjNDLVwFB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (571, 'Blood and Sand', 'Juan is the son of a poor widow in Seville. Against his mother''s wishes he pursues a career as toreador. He rapidly gains national prominence, and takes his childhood sweetheart Carmen as his bride. He meets the Marquis'' daughter Doña Sol and finds himself in the awkward position of being in love with two women, which threatens the stability of his family and his position in society. He finds interesting parallels in the life of the infamous bandit Plumitas when they eventually meet by chance.', 'Fred Niblo', 104, '1922-08-05', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/snpOhcMkANfaj49I20K6qzrrOSC.jpg', 'https://www.youtube.com/watch?v=K6FlDCWUork', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (572, 'Dr. Jack', 'Country doctor Jack Jackson is called in to treat the Sick-Little-Well-Girl, who has been making Dr. Saulsbourg and his sanitarium very rich after years of unsuccessful treatment.', 'Fred C. Newmeyer, Sam Taylor', 60, '1922-11-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vWr8isUou7CwHwsByg3bP9LGMKS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (573, 'Dr. Mabuse, the Gambler', 'Dr. Mabuse and his organization of criminals are in the process of completing their latest scheme, a theft of information that will allow Mabuse to make huge profits on the stock exchange. Afterwards, Mabuse disguises himself and attends the Folies Bergères show, where Cara Carozza, the main attraction of the show, passes him information on Mabuse''s next intended victim, the young millionaire Edgar Hull. Mabuse then uses psychic manipulation to lure Hull into a card game where he loses heavily. When Police Commissioner von Wenk begins an investigation of this mysterious crime spree, he has little to go on, and he needs to find someone who can help him.', 'Fritz Lang', 271, '1922-04-27', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/giarOpuBw8fRlNejbBbPMlRHz1I.jpg', 'https://www.youtube.com/watch?v=MWZwOH2EKb8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (574, 'Foolish Wives', 'A con artist masquerades as Russian nobility and attempts to seduce the wife of an American diplomat.', 'Erich von Stroheim', 143, '1922-01-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/esdMep54xAUYUE4CCktAh2Rh3gk.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (575, 'Grandma''s Boy', 'A meek young man must find the courage within when a rogue tramp menaces his hometown.', 'Fred C. Newmeyer', 60, '1922-09-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9St2NINbr0zVwcMqyPvTDAKKXUc.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (576, 'Häxan', 'Grave robbing, torture, possessed nuns, and a satanic Sabbath: Benjamin Christensen''s legendary film uses a series of dramatic vignettes to explore the scientific hypothesis that the witches of the Middle Ages suffered the same hysteria as turn-of-the-century psychiatric patients. But the film itself is far from serious-- instead it''s a witches'' brew of the scary, gross, and darkly humorous.', 'Benjamin Christensen', 105, '1922-09-18', 'T18', 'sv', 'https://image.tmdb.org/t/p/w500/3LtaPLlwlA5HX2FjqAb8lsaBI8P.jpg', 'https://www.youtube.com/watch?v=ltDAAu7uEjw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (577, 'Nanook of the North', 'This pioneering documentary film depicts the lives of the indigenous Inuit people of Canada''s northern Quebec region. Although the production contains some fictional elements, it vividly shows how its resourceful subjects survive in such a harsh climate, revealing how they construct their igloo homes and find food by hunting and fishing. The film also captures the beautiful, if unforgiving, frozen landscape of the Great White North, far removed from conventional civilization.', 'Robert Flaherty', 79, '1922-06-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9WAboi1QbKu41WkyGxQVNpXwwxx.jpg', 'https://www.youtube.com/watch?v=bkilXJiCfng', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (578, 'Nosferatu', 'The mysterious Count Orlok summons a happily married real estate agent to his castle, located up in the Transylvanian mountains, to finalise a terrifying deal.', 'F. W. Murnau', 94, '1922-02-16', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/zv7J85D8CC9qYagAEhPM63CIG6j.jpg', 'https://www.youtube.com/watch?v=0LOOhc2eML4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (579, 'Phantom', 'Lorenz Lubota is a city clerk with no direction in life. One day on his way to work he is run over by a woman driving a chariot and he is immediately infatuated with her.', 'F. W. Murnau', 119, '1922-11-13', 'P', 'de', 'https://image.tmdb.org/t/p/w500/rVE0Vr6vKrZOtrTltoSfIxv7nre.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (580, 'Robin Hood', 'Amid big-budget medieval pageantry, King Richard goes on the Crusades leaving his brother Prince John as regent, who promptly emerges as a cruel, grasping, treacherous tyrant. Apprised of England''s peril by message from his lady-love Marian, the dashing Earl of Huntingdon endangers his life and honor by returning to oppose John, but finds himself and his friends outlawed, with Marian apparently dead. Enter Robin Hood, acrobatic champion of the oppressed, laboring to set things right through swashbuckling feats and cliffhanging perils!', 'Allan Dwan', 133, '1922-10-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg', 'https://www.youtube.com/watch?v=9cMq2fKqT4M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (581, 'Salomé', 'Based on Oscar Wilde''s play, the films tells the story of how Salomé agrees to dance for King Herod in return for the head of John the Baptist.', 'Charles Bryant', 74, '1923-02-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iF3A7Ob9VSKNSCNt3fC72qGWeQv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (582, 'Warning Shadows', 'During a dinner given by a wealthy baron and his wife, attended by four of her suitors in a 19th century German manor, a shadow-player rescues the marriage by giving all the guests a vision what might happen tonight if the baron stays jealous and the suitors do not reduce their advances towards his beautiful wife. Or was it a vision?', 'Arthur Robison', 90, '1923-10-16', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/vSQRXcGKVuvNmvAeJZj3Sw42FWi.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (583, 'Cœur fidèle', 'The good guys win out in this sweet tale about a young orphan who is abused for much of her life but who eventually finds happiness when she marries an honest man who extricates her from her situation.', 'Jean Epstein', 87, '1923-11-23', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/hcjZqVlQN5nYcvcbICqzYHK581G.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (584, 'The Extra Girl', 'Sue Graham is a small town girl who wants to be a motion picture star. She wins a contract when a picture of a very pretty girl is sent to a studio instead of her picture. When she arrives in Hollywood, the mistake is discovered and she starts working in the props department of the studio instead. Her parents then come out to California and invest some money with a very shifty individual.', 'F. Richard Jones', 69, '1923-10-28', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/hKOSyGduEs2jJOn5fG09swfRf16.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (585, 'The Saga of Gösta Berling', 'Gösta Berling is a young and attractive minister. Because of his alcoholism and his daring sermons, he is eventually defrocked. He becomes tutor of countess Marta''s stepdaughter and they fall in love. But the countess has a plan of her own.', 'Mauritz Stiller', 206, '1924-03-09', 'P', 'sv', 'https://image.tmdb.org/t/p/w500/9BswfOz9qdy52WKdnwM6rGQIk5b.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (586, 'The Hunchback of Notre Dame', 'In 15th century France, a gypsy girl is framed for murder by the infatuated Chief Justice, and only the deformed bellringer of Notre Dame Cathedral can save her.', 'Wallace Worsley', 113, '1923-09-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3oheTQrTuqS1jPUW6GOc65ZbM5u.jpg', 'https://www.youtube.com/watch?v=HC37IKScnfs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (587, 'Our Hospitality', 'A young man falls for a young woman on his trip home; unbeknownst to him, her family has vowed to kill every member of his family.', 'Buster Keaton, John G. Blystone', 73, '1923-11-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cAEdL6RzfDSbPO51izl01Njzikx.jpg', 'https://www.youtube.com/watch?v=1BWMJ06xDN0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (588, 'The Pilgrim', 'The Tramp is an escaped convict who is mistaken as a pastor in a small town church.', 'Charlie Chaplin', 47, '1923-02-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/52RjDFLnMybAz1VzlxMAiGodX7S.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (589, 'La Roue', 'Sisif, a railwayman, saves a young girl named Norma orphaned by a train crash and raises her as his own daughter alongside his son, Elie. As she becomes an adult, Sisif grapples with whether to tell Norma the truth about her parentage.', 'Abel Gance', 418, '1923-02-17', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/5ed3ywd7lmDPhsCXmcdSih9SxP2.jpg', 'https://www.youtube.com/watch?v=KP4AoOJ6b1o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (590, 'Safety Last!', 'When a store clerk organizes a contest to climb the outside of a tall building, circumstances force him to make the perilous climb himself.', 'Fred C. Newmeyer, Sam Taylor', 73, '1923-03-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fEt5HWJ32ek8ibef7zSZnA00Jp0.jpg', 'https://www.youtube.com/watch?v=rhNtSU8ubf0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (591, 'Souls for Sale', 'A young woman hits Hollywood, determined to become a star.', 'Rupert Hughes', 90, '1923-04-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cz3O6GkO14L64xukE4E50SvhlOk.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (592, 'The Ten Commandments', 'The first part tells the story of Moses leading the Jews from Egypt to the Promised Land, his receipt of the tablets and the worship of the golden calf. The second part shows the efficacy of the commandments in modern life through a story set in San Francisco. Two brothers, rivals for the love of Mary, also come into conflict when John discovers Dan used shoddy materials to construct a cathedral.', 'Cecil B. DeMille', 136, '1923-11-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uQNsUtxDp5G3qq1a2Wc1ycjF5AL.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (593, 'Three Ages', 'The rituals of courtship, romantic rivalry, and love play out three times as a man vies with a villain for the girl. In the Stone Age, the rivalry is set off by dinosaurs, a turtle used as a ouija board, and a round of golf with stones. In ancient Rome, the men display their brawn through a chariot race, using dogs instead of horses. In contemporary times, the man finds himself overcome by modernity, including a very fragile car.', 'Buster Keaton, Edward F. Cline', 64, '1923-09-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/khadgoKp9eLBY4t0KcST5gzddk3.jpg', 'https://www.youtube.com/watch?v=6M1w2v3ROhM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (594, 'Waxworks', 'A poet is hired by the owner of a wax museum in a circus to write tales about Harun al Raschid, Ivan the Terrible and Jack the Ripper. While writing, the poet and the daughter of the owner, Eva, fantasize the fantastic stories and fall in love for each other.', 'Leo Birinski, Paul Leni', 83, '1924-11-13', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/6n8hkbMUiY3ETNNoQspHwotvHkA.jpg', 'https://www.youtube.com/watch?v=984kcSeeNjQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (595, 'Why Worry?', 'A hypochondriac vacations in the tropics for the fresh air - and finds himself in the middle of a revolution instead.', 'Fred C. Newmeyer, Sam Taylor', 63, '1923-09-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7NrgFBBgOyL0vDAZ17jo3EIQ2uo.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (596, 'A Woman of Paris: A Drama of Fate', 'When Marie St. Clair believes she has been jilted by her artist fiance Jean, she decides to leave for Paris on her own. After spending a year in the city as a mistress of the wealthy Pierre Revel, she is reunited with Jean by chance. This leaves her with the choice between a glamorous life in Paris, and the true love she left behind.', 'Charlie Chaplin', 82, '1923-10-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/shmnpKWwfgNzntaDLPO0WYli5PX.jpg', 'https://www.youtube.com/watch?v=fKCfP1EBzY8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (597, 'Aelita: Queen of Mars', 'A young man travels to Mars in a rocket ship, where he leads a popular uprising against the ruling group with the support of Queen Aelita, who has fallen in love with him after watching him through a telescope.', 'Yakov Protazanov', 111, '1924-09-24', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/u1oLjIPDVNHr5iKDs7tx5YNgv13.jpg', 'https://www.youtube.com/watch?v=OY3PJrrK9zU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (598, 'Girl Shy', 'Harold Meadows is a shy, stuttering bachelor working in a tailor shop, who is writing a guidebook, The Secret of Making Love, for other bashful young men. Fate has him meet rich girl Mary, and they fall in love. But she is about to wed an already married man, so our hero embarks upon a hair-raising daredevil ride to prevent the wedding.', 'Fred C. Newmeyer, Sam Taylor', 80, '1924-04-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dMxXZoNWqODqkeDY9SC5O4lLrae.jpg', 'https://www.youtube.com/watch?v=SWAd7V7bWY4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (599, 'He Who Gets Slapped', 'After a baron steals his scientific discoveries, runs away with his wife, and slaps him in public, a man joins a Parisian circus sideshow as a clown whose act consists of being slapped repeatedly and becomes infatuated with a showgirl colleague whose father intends to marry her off to the baron.', 'Victor Sjöström', 72, '1924-12-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ue7ce11Y6vEjZXKZeKCBKl6O9Dp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (600, 'Hot Water', 'Lloyd''s look at married life and the issues of the in-law. Adventures include a ride on a crowded trolley with a live turkey; A wild spin in a new auto with the in-laws in tow. Finally, a sequence in which Hubby accidentally chloroforms his mother-in-law and becomes convinced that he''s killed her!', 'Fred C. Newmeyer, Sam Taylor', 59, '1924-10-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pgnb43bbR1s5H72yN45bwN0YQUn.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (601, 'The Inhuman Woman', 'A famous singer Claire Lescot, who lives on the outskirts of Paris, is courted by many men, including a maharajah, Djorah de Nopur, and a young Swedish scientist, Einar Norsen. At her lavish parties she enjoys their amorous attentions but she remains emotionally aloof and heartlessly taunts them. When she is told that Norsen has killed himself because of her, she shows no feelings. At her next concert she is booed by an audience outraged at her coldness and she decides to visit the vault in which Norsen''s body lies.', 'Marcel L''Herbier', 123, '1924-12-12', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/uOr8W7pos3WOTcHBrUKnzkGJdGp.jpg', 'https://www.youtube.com/watch?v=7SIrx8OEITI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (602, 'The Iron Horse', 'Brandon, a surveyor, dreams of building a railway to the west. He sets off with his son, Davy, to survey a route. They discover a new pass which will shave 200 miles off the expected distance, but they are set upon by a party of Cheyenne. One of them, a white renegade with only two fingers on his right hand, kills Brandon and scalps him. Davy is all alone now.', 'John Ford', 149, '1925-10-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/atYzXs2gdfKRKvVlP0Gj4hEsmuU.jpg', 'https://www.youtube.com/watch?v=wTmWsrHp2nA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (603, 'Kino-Eye', 'Promoting the joys of life in a Soviet village centering on the activities of the Young Pioneers. These children are constantly busy, pasting propaganda posters on walls, distributing hand bills, exhorting all to ''buy from the cooperative'' as opposed to the Public Sector, promoting temperance, and helping poor widows. Experimental portions, projected in reverse, feature the un-slaughtering of a bull and the un-baking of bread.', 'Dziga Vertov', 78, '1924-10-31', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/qgjeOPQJlAYS817QBt00YJBJgm5.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (604, 'The Last Laugh', 'An aging doorman, after being fired from his prestigious job at a luxurious hotel, is forced to face the scorn of his friends, neighbours and society.', 'F. W. Murnau', 90, '1924-12-23', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/7Y6Dxr3oYt1w7ew70YNdLLDYEjk.jpg', 'https://www.youtube.com/watch?v=d7rPS1TQ67I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (605, 'Manhandled', 'A comedy which concerns the struggles of an ambitious department store sales clerk who is caught up in New York high society.', 'Allan Dwan', 63, '1924-07-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yfZWy613rhGyl9je9kgJplOQVqS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (606, 'The Marriage Circle', 'An unhappily married couple moves to Vienna, where the wife’s married best friend lives, and soon, sparks fly between the wife and the best friend’s husband.', 'Ernst Lubitsch', 85, '1924-02-10', 'K', 'en', 'https://image.tmdb.org/t/p/w500/5Umgljr4iMnuAw2BrEVGiaxOH6o.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (607, 'Michael', 'A mature and visually elegant period romance that remains one of the earliest and most compassionate overtly gay-themed films in movie history. Based upon Herman Bang''s 1902 novel, Dreyer''s Michael refashions the classical Greek myth of Jupiter and Ganymede into a love triangle between an aging artist, Zoret, his protagonist Michael, and Princess Zamikoff, an aristocratic femme fatale as entranced by Michael’s youthful beauty as Zoret is.', 'Carl Theodor Dreyer', 95, '1924-09-26', 'P', 'de', 'https://image.tmdb.org/t/p/w500/uE5CcZ7wJFLxxRSo2XKuhAYHy0R.jpg', 'https://www.youtube.com/watch?v=roTvXHwWR7Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (608, 'The Navigator', 'The wealthy and impulsive Rollo Treadway decides to propose to his beautiful socialite neighbor, Betsy O''Brien. Although Betsy turns Rollo down, he still opts to go on the cruise that he intended as their honeymoon. When circumstances find both Rollo and Betsy on the wrong ship, they end up having adventures on the high seas.', 'Buster Keaton, Donald Crisp', 65, '1924-09-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eFIbnDnBnIi1qnz15UUiMFmjRmL.jpg', 'https://www.youtube.com/watch?v=rsl-1g1IpJU', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (609, 'The Extraordinary Adventures of Mr. West in the Land of the Bolsheviks', 'An ignorant and prejudiced American’s visit of Soviet Russia goes off the rails after his luggage is stolen and he is separated from his bodyguard.', 'Lev Kuleshov', 77, '1924-04-26', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/6uoYCtCPsTZfX8hfUwiuHq7VY4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (610, 'Die Nibelungen: Kriemhild''s Revenge', 'When Kriemhild, thirsty for revenge, marries to Etzel, king of the Huns, she invites King Gunther and his court to visit them, intending to finally take the life of the man responsible of her disgrace.', 'Fritz Lang', 129, '1924-04-26', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/fQ74KhKpjVrxvWJT69EnCIKFaH3.jpg', 'https://www.youtube.com/watch?v=1KJZfIWCK4Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (611, 'Die Nibelungen: Siegfried', 'Siegfried, son of King Siegmund of Xanten, travels to Worms, capital of the Burgundian kingdom, to ask King Gunther for the hand of his sister, the beautiful Kriemhild.', 'Fritz Lang', 148, '1924-02-14', 'P', 'de', 'https://image.tmdb.org/t/p/w500/rb0mUDrw87WXwH9MsfYvyBxCQ1z.jpg', 'https://www.youtube.com/watch?v=ljT4kjBkhM8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (612, 'The Hands of Orlac', 'A world-famous pianist loses both hands in an accident. When new hands are grafted on, he is horrified to learn they once belonged to a murderer.', 'Robert Wiene', 98, '1924-09-24', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/40WWy1SSx8rh1r4mn1MNpCKIteF.jpg', 'https://www.youtube.com/watch?v=6RwYXaTN_CY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (613, 'The Crazy Ray', 'A night watchman on the Eiffel Tower wakes up to find the entire population of the city frozen in place.', 'René Clair', 59, '1925-01-01', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/xEoZcxj2Zi5P7A5ayPXHy457tlB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (614, 'Peter Pan', 'Peter Pan enters the nursery of the Darling children and, with the help of fairy dust, leads them off to Never Never Land, where they meet the nefarious Captain Hook.', 'Herbert Brenon', 101, '1924-12-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9ZhpeVmPNaez39BKzH2AgLRDoAJ.jpg', 'https://www.youtube.com/watch?v=lc_NfkyrPRk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (615, 'Sherlock Jr.', 'A film projectionist longs to be a detective, and puts his meager skills to work when he is framed by a rival for stealing his girlfriend''s father''s pocketwatch.', 'Buster Keaton', 45, '1924-04-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1G9r3rqtbFAQuyWKOZm4Y5J5s7Q.jpg', 'https://www.youtube.com/watch?v=JSEK1NUPrGA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (616, 'Strike', 'Workers in a factory in pre-revolutionary Russia go on strike and are met by violent suppression.', 'Sergei Eisenstein', 89, '1925-04-28', 'T13', 'ru', 'https://image.tmdb.org/t/p/w500/mrDTaMxQKxWZ3uEs2G58vJWJDDL.jpg', 'https://www.youtube.com/watch?v=3UQMg3saU4Q', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (617, 'The Thief of Bagdad', 'A recalcitrant thief vies with a duplicitous Mongol ruler for the hand of a beautiful princess.', 'Raoul Walsh', 149, '1924-03-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8t4CJ591N2FATf2yUiQNQk9p0tB.jpg', 'https://www.youtube.com/watch?v=msVH7dZkB8o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (618, 'The Adventures of Prince Achmed', 'Taken from The Arabian Nights, a wicked sorcerer and the beautiful prince Achmed battle one against the other during a series of wondrous adventures.', 'Lotte Reiniger', 66, '1926-09-03', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/c3OKMlt9QxpPeSfpyViqYkYFvUz.jpg', 'https://www.youtube.com/watch?v=DkK6ELJeDx0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (619, 'The Big Parade', 'The story of an idle rich boy who joins the US Army''s Rainbow Division and is sent to France to fight in World War I, becomes friends with two working class men, experiences the horrors of trench warfare, and finds love with a French girl.', 'King Vidor', 151, '1925-11-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8aBXJEkAHcwG2ghNYh6GIFd9ool.jpg', 'https://www.youtube.com/watch?v=P_-BvxzdOr4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (620, 'Body and Soul', 'A convict escapes to a Southern town and passes himself off as a reverend, giving him the perfect cover to swindle the townspeople and corrupt an innocent young woman.', 'Oscar Micheaux', 94, '1925-11-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3Xl7ZaNt1ThVCvsXZDW5ISXsP7K.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (621, 'Battleship Potemkin', 'A dramatized account of a great Russian naval mutiny and a resultant public demonstration, showing support, which brought on a police massacre.', 'Sergei Eisenstein', 75, '1925-12-24', 'T16', 'ru', 'https://image.tmdb.org/t/p/w500/hZmsRLsCnE9Zshf1YJONUpCOhds.jpg', 'https://www.youtube.com/watch?v=VC66LgoOlCs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (622, 'Master of the House', 'When a man becomes tyrannical towards his family, the women of the house decide to teach him a lesson in gratitude.', 'Carl Theodor Dreyer', 107, '1925-10-05', 'P', 'da', 'https://image.tmdb.org/t/p/w500/iRxogRnql0tmHRhuH8XsV1pOSFr.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (623, 'The Eagle', 'Vladimir Dubrouvsky, a lieutenant in the Russian army, catches the eye of Czarina Catherine II. He spurns her advances and flees, and she puts out a warrant for his arrest, dead or alive. Vladimir learns that his father''s lands have been taken by the evil Kyrilla Troekouroff, and his father dies. He dons a black mask, and becomes the outlaw The Black Eagle. He enters the Troekouroff household disguised as a French instructor for Kyrilla''s daughter Mascha. He is after vengeance, but instead falls in love with Mascha.', 'Clarence Brown', 73, '1925-11-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dwF5S5Vbk2gZC3MPNxn9O5eBJSa.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (624, 'The Freshman', 'An unathletic college freshman ridiculed by his peers for his mannerisms strives to become popular by making the football team.', 'Fred C. Newmeyer, Sam Taylor', 77, '1925-09-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3531lJNSMhrpcNWXrDIYYoYH6Rp.jpg', 'https://www.youtube.com/watch?v=1ntrhlDr8MU', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (625, 'Joyless Street', 'In 1921, we follow two women - Marie and Grete - from the same poor Viennese neighborhood, as they try to better the lives of themselves and their families during the period of Austrian postwar hyperinflation.', 'G.W. Pabst', 155, '1925-03-01', 'P', 'de', 'https://image.tmdb.org/t/p/w500/qmOQssz4GfbdtOmxwMP0jBj4P4F.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (626, 'Go West', 'With little luck at keeping a job in the city a New Yorker tries work in the country and eventually finds his way leading a herd of cattle to the West Coast.', 'Buster Keaton', 83, '1925-11-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/chZ6GbfTIKgD6nYmUKZScDAnIo8.jpg', 'https://www.youtube.com/watch?v=1BWMJ06xDN0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (627, 'The Gold Rush', 'A gold prospector in Alaska struggles to survive the elements and win the heart of a dance hall girl.', 'Charlie Chaplin', 95, '1925-07-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eQRFo1qwRREYwj47Yoe1PisgOle.jpg', 'https://www.youtube.com/watch?v=DJwOpY84Oq4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (628, 'Grass: A Nation''s Battle for Life', 'A silent documentary which follows a branch of the Bakhtiari tribe of Persia as they and their herds make their epic seasonal journey to better pastures.', 'Ernest B. Schoedsack, Merian C. Cooper', 71, '1925-03-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/djZ2jwO0C0ZFq0rGSBACMjW3qF.jpg', 'https://www.youtube.com/watch?v=9HYOQjYi3m4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (629, 'Greed', 'When housewife Trina wins the lottery, her comfortable life with her dentist husband John slowly deteriorates, in part by her own increasing paranoia and partly by the machinations of villainous acquaintance Marcus.', 'Erich von Stroheim', 140, '1924-12-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/eur2vc2BGiOocBuBLVPXySO7lRh.jpg', 'https://www.youtube.com/watch?v=MGjSpPgJAoA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (630, 'Lady Windermere''s Fan', 'A society woman believes her husband is having an affair, a misconception which may have dire personal consequences for all involved.', 'Ernst Lubitsch', 89, '1925-12-26', 'K', 'en', 'https://image.tmdb.org/t/p/w500/fpDPAhrWuLiF28KMwDhYAj5ofTk.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (631, 'The Little Colonel', 'After Southern belle Elizabeth Lloyd runs off to marry Yankee Jack Sherman, her father, a former Confederate colonel during the Civil War, vows to never speak to her again. Several years pass and Elizabeth returns to her home town with her husband and young daughter. The little girl charms her crusty grandfather and tries to patch things up between him and her mother.', 'David Butler', 80, '1935-02-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/t48Hj1PtU0JhcRbiunJ1BIYxLlA.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (632, 'The Lost World', 'The first film adaptation of Sir Arthur Conan Doyle''s classic novel about a land where prehistoric creatures still roam.', 'Harry O. Hoyt', 104, '1925-02-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/411VnWtYJdEFKiaGqJOeTmBv8th.jpg', 'https://www.youtube.com/watch?v=RJL6g91AOs4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (633, 'The Merry Widow', 'Prince Danilo falls in love with dancer Sally O''Hara. However, his uncle, King Nikita I of Monteblanco, forbids the marriage due to her being a commoner. Thinking she''s been jilted by her prince, Sally marries lecherous old Baron Sadoja, whose wealth has kept the kingdom afloat. When he suddenly dies, Sally must be wooed all over again by Danilo.', 'Erich von Stroheim', 137, '1925-08-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7cicZpacvh3MINqNorntTl8xdOY.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (634, 'The Monster', 'A general store clerk and aspiring detective investigates a mysterious disappearance that took place quite close to an empty insane asylum.', 'Roland West', 86, '1925-03-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kOyxl0PCoYsZybEZnN32tOR2y0G.jpg', 'https://www.youtube.com/watch?v=L6a40e-Ya6E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (635, 'The Phantom of the Opera', 'The deformed Phantom who haunts the Paris Opera House causes murder and mayhem in an attempt to make the woman he loves a star.', 'Rupert Julian', 107, '1925-06-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mvaYpAYj957C2tlq3vVJPSzGJXK.jpg', 'https://www.youtube.com/watch?v=HYvbaILyc2s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (636, 'The Pleasure Garden', 'Two chorus girls at the Pleasure Garden Theatre follow different paths in love and fortune.', 'Alfred Hitchcock', 91, '1925-11-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/DpCDqbyxBlSChWTCx42n4WA8BX.jpg', 'https://www.youtube.com/watch?v=6kSxX3t9lys', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (637, 'Seven Chances', 'Struggling stockbroker Jimmie Shannon learns that, if he gets married by 7 p.m. on his 27th birthday -- which is today -- he''ll inherit $7 million from an eccentric relative.', 'Buster Keaton', 56, '1925-03-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fH9woIxzqVtyv6S711vSVlS12eA.jpg', 'https://www.youtube.com/watch?v=4Qlq0y36iQQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (638, 'Stage Struck', 'Daydreaming waitress Jennie Hagen fantasizes about becoming a famous actress, while in reality she and her cook boyfriend, Orme Wilson, hope to one day own their own diner. Although Orme loves Jennie, he also has a weakness for stage stars -- so when a riverboat theatrical crew comes to their town, he is smitten by lead actress Lillian Lyons. Desperate to keep Orme, Jennie insists on going onstage to best Lillian, but is soon out of her depth.', 'Allan Dwan', 84, '1925-11-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/l711nus4DPVRdk9Hdeph22iHY2K.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (639, 'The Unholy Three', 'Three sideshow performers form a conspiracy known as ''The Unholy Three'' – a ventriloquist, midget, and strongman working together to commit a series of robberies.', 'Tod Browning', 86, '1925-07-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aU3eZJEuzFzngrnTQJrqhTQ8zzO.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (640, 'Variety', 'Murderer “Boss” Huller—after having spent ten years in prison—breaks his silence to tell the warden his story.', 'E.A. Dupont', 104, '1925-11-16', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/rcpMbxYrYLngdyQrt1lK4QkpV06.jpg', 'https://www.youtube.com/watch?v=vQ46TEBYFA0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (641, 'The Wizard of Oz', 'A farm girl learns she is a princess and is swept away by a tornado to the land of Oz.', 'Larry Semon', 81, '1925-02-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/l7bVLGopGoTwmuirB0WZdUc47ns.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (642, 'Bardelys the Magnificent', 'Rafael Sabatini''s story of the swashbuckling era and of Bardeleys, the handsome courtier who could win any woman he set his mind to...and was not above boasting about it to all who would listen.', 'King Vidor', 90, '1926-09-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8Y2xo9pp5NUPxkRziFWVRw88EUv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (643, 'Battling Butler', 'A meek millionaire masquerades as a boxing star to win a girl''s heart.', 'Buster Keaton', 77, '1926-08-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7MVdo4OyzIcwycN58J9n855ggoS.jpg', 'https://www.youtube.com/watch?v=sRhQJxLgifg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (644, 'Ben-Hur: A Tale of the Christ', 'Erstwhile childhood friends, Judah Ben-Hur and Messala meet again as adults, this time with Roman officer Messala as conqueror and Judah as a wealthy, though conquered, Israelite. A slip of a brick during a Roman parade causes Judah to be sent off as a galley slave, his property confiscated and his mother and sister imprisoned. Years later, as a result of his determination to stay alive and his willingness to aid his Roman master, Judah returns to his homeland an exalted and wealthy Roman athlete. Unable to find his mother and sister, and believing them dead, he can think of nothing else than revenge against Messala.', 'Fred Niblo', 143, '1925-12-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg', 'https://www.youtube.com/watch?v=ftxWZZQs-j4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (645, 'The Black Pirate', 'A nobleman vows to avenge the death of his father by the hands of pirates. To this end, he infiltrates the pirate band; Acting in character, he single-handedly captures a merchant vessel, but things are complicated when he finds that there is a beautiful young woman of royal blood aboard.', 'Albert Parker', 94, '1926-03-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/841WLSvTRN3TQKxiUjD1TY9dc42.jpg', 'https://www.youtube.com/watch?v=lehU9FlQmSU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (646, 'La Bohème', 'A group of starving artists try to survive in 1830s Paris, including a seamstress and the would-be playwright she loves.', 'King Vidor', 93, '1926-03-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7fLAxBNFb0CUTe5Nd8qsWeMX2Fr.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (647, 'Brown of Harvard', 'Tom Brown shows up at Harvard, confident and a bit arrogant. He becomes a rival of Bob McAndrew, not only in football and rowing crew, but also for the affections of Mary Abbott, a professor''s daughter.', 'Jack Conway', 85, '1926-05-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4p55sMwwDD8LBhHilcVqJa05ZrV.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (648, 'Faust', 'God and Satan wager on the soul of a learned and prayerful alchemist as part of their eternal war over Earth.', 'F. W. Murnau', 116, '1926-10-13', 'T18', 'de', 'https://image.tmdb.org/t/p/w500/rN703hMFxmkZfyEzsXvFtuFhkXE.jpg', 'https://www.youtube.com/watch?v=Luuw4yTTtRU', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (649, 'Flesh and the Devil', 'When lifelong best friends Leo and Ulrich return home after completing their military training, Leo meets the stunning Felicitas at a railway station and is mesmerized by her beauty. A scandal follows, for which Leo is sent away. Returning home three years later, he discovers that much has changed.', 'Clarence Brown', 112, '1926-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/crbsj3275H5Q0accBiql7GyKTQW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (650, 'For Heaven''s Sake', 'An irresponsible young millionaire changes his tune when he falls for the daughter of a downtown minister.', 'Sam Taylor', 58, '1926-04-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vIaZ41s0IqU8AlMufJ7fsUKq7Vb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (651, 'A Page of Madness', 'A man takes a job at an asylum with hopes of freeing his imprisoned wife.', 'Teinosuke Kinugasa', 71, '1926-09-24', 'T18', 'ja', 'https://image.tmdb.org/t/p/w500/4omdvaOfHI438c368MRa2SPObGg.jpg', 'https://www.youtube.com/watch?v=inZy5os7Aq4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (652, 'The Lodger: A Story of the London Fog', 'London. A mysterious serial killer brutally murders young blond women by stalking them in the night fog. One foggy, sinister night, a young man who claims his name is Jonathan Drew arrives at the guest house run by the Bunting family and rents a room.', 'Alfred Hitchcock', 91, '1927-02-14', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/tD84zwFeFRf3zG98x558N3PBMV.jpg', 'https://www.youtube.com/watch?v=BJnoaTzJdLs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (653, 'Mother', 'A Soviet woman is caught between her husband and son, who find themselves on opposing sides of the Russian Revolution.', 'Vsevolod Pudovkin', 87, '1926-10-11', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/u9u71FR74RVndbAbW3rlmts0QyS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (654, 'Metropolis', 'In a futuristic city sharply divided between the rich and the poor, the son of the city''s mastermind meets a prophet who predicts the coming of a savior to mediate their differences.', 'Fritz Lang', 148, '1927-01-10', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/kr9wXRN23zLuWJIelahas1mtnYj.jpg', 'https://www.youtube.com/watch?v=ZAvzaOxDt2c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (655, 'By the Law', 'After a man kills two members of his Yukon gold prospecting team, the other two surviving members struggle to keep him subdued for the next several months until they can turn him over to the law.', 'Lev Kuleshov', 80, '1926-12-03', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/2LpGKcjV0oHN60Wpi3jWKjqXI1H.jpg', 'https://www.youtube.com/watch?v=ycElt5k821Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (656, 'The Scarlet Letter', 'In Puritan Boston, seamstress Hester Prynne and kindly Reverend Arthur Dimmesdale fall in love. After Dimmesdale must go away for a time to England, he returns to discover that Hester has given birth to their child and is the focus of local censure.', 'Victor Sjöström', 97, '1927-01-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/r17PMluxZvEFOHGILuf2iHuyQCt.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (657, 'The Son of the Sheik', 'Ahmed, son of Diana and Sheik Ahmed Ben Hassan, falls in love with Yasmin, a dancing girl who fronts her father''s gang of mountebanks. She and Ahmed meet secretly until one night when her father and the gang capture the son of the sheik, torture him, and hold him for ransom.', 'George Fitzmaurice', 69, '1926-09-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yZib8tHbOHrSTSszif728VwU2L6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (658, 'Sparrows', 'Molly, the eldest child of a group of orphans being used as slaves on a farm hidden deep in a swamp, must rescue the others when their cruel master decides that one of them will be disposed of.', 'William Beaudine', 94, '1926-09-19', 'P', 'xx', 'https://image.tmdb.org/t/p/w500/3ZPfhlwZ9HIYViUCgoZusCszohT.jpg', 'https://www.youtube.com/watch?v=dSi0X28N0mc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (659, 'Tartuffe', 'A young man shows his millionaire grandfather a film based on Molière''s play "Tartuffe" in order to expose the old man''s hypocritical governess who covets the young man''s inheritance.', 'F. W. Murnau', 70, '1926-01-25', 'P', 'de', 'https://image.tmdb.org/t/p/w500/xRin1lHzsK8s8EMfT54wgxiD61H.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (660, 'The Temptress', 'A seductive woman forsakes her husband and lover to pursue a young engineer.', 'Fred Niblo', 106, '1926-10-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uGJtzAm4j3BCRU8JRbvtwAn3xIM.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (661, '3 Bad Men', 'Three outlaws come to the aid of a young girl after her father is killed.', 'John Ford', 92, '1926-08-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4x1vv1O0QMgE2sSbtSbrV68Zscr.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (662, 'West Point', 'Arrogant and wise-cracking Brice Wayne enrolls at the United States Military Academy at West Point and adjusts to life as a plebe. He tries out for the plebe football team, where he excels and shows up the varsity team. However, his ego is unrivaled, especially in competition with upperclassman Bob Sperry. At the same time, Brice meets a local girl named Betty Channing who cheers for him at football practices.', 'Edward Sedgwick', 95, '1928-01-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5OysLUunonJyDQuW1Aj8X0bB8Si.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (663, 'Berlin: Symphony of a Great City', 'A day in the city of Berlin, which experienced an industrial boom in the 1920s, and still provides an insight into the living and working conditions at that time. Germany had just recovered a little from the worst consequences of the First World War, the great economic crisis was still a few years away and Hitler was not yet an issue at the time.', 'Walter Ruttmann', 69, '1927-09-23', 'P', 'de', 'https://image.tmdb.org/t/p/w500/1APQoI9PKgZtg6PWZjIbr0U7GvZ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (664, 'The Cat and the Canary', 'A group of potential heirs gather in a forbidding old house to learn which of them will inherit a fortune. Later, they learn that a flesh-rending maniac is loose.', 'Paul Leni', 84, '1927-08-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pblghrfHa2XvNE5lDYq2vVMyVoh.jpg', 'https://www.youtube.com/watch?v=tMtD-0NOi2A', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (665, 'Chang: A Drama of the Wilderness', 'Elephants disrupt the lives of a family deep in the jungles of Northern Siam, and an entire village.', 'Ernest B. Schoedsack, Merian C. Cooper', 69, '1927-04-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/g1y0h1diWpdxxGmMhHB9shqs2bx.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (666, 'College', 'A bookish college student dismissive of athletics is compelled to try out sports to win the affection of the girl he loves.', 'Buster Keaton, James W. Horne', 65, '1927-09-10', 'K', 'en', 'https://image.tmdb.org/t/p/w500/dUwk8qNkXb243JViqdVqOvUmiMt.jpg', 'https://www.youtube.com/watch?v=1BWMJ06xDN0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (667, 'Downhill', 'When school captain Roddy Berwick takes the blame for his friend’s scandal, he is expelled and disowned by his family. Cast out of his privileged world, Roddy drifts through a series of humiliations—from waiter to penniless actor to gigolo—descending ever further into ruin and self-disgust.', 'Alfred Hitchcock', 106, '1927-10-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s6AppTbM34sNB9FASwezhIyesn5.jpg', 'https://www.youtube.com/watch?v=4TJX1ciN4bs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (668, 'Easy Virtue', 'Unjustly accused of adultery in a scandalous divorce, Larita Filton flees to the French Riviera. She soon falls in love with a young Englishman, John Whittaker, and begins anew under an assumed name. But when John brings her home to his disapproving family, Larita’s past begins to resurface.', 'Alfred Hitchcock', 70, '1928-04-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2GVP7uJbBigNtlpnN6E6YwS75VB.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (669, 'The General', 'During America’s Civil War, Union spies steal engineer Johnny Gray''s beloved locomotive, ''The General''—with Johnnie''s lady love aboard an attached boxcar—and he single-handedly must do all in his power to both get The General back and to rescue Annabelle.', 'Buster Keaton, Clyde Bruckman', 79, '1926-12-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4NmV1Wei4LxT2lpjViCAScgCZLq.jpg', 'https://www.youtube.com/watch?v=eEVWb9NcSuY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (670, 'Happiness', 'A hapless loser (with the surname of Loser) undergoes misadventures with avaracious clergy, a tired horse, and a walking granary (among other things) on his road to collectivized happiness.', 'Aleksandr Medvedkin', 63, '1935-03-15', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/nvF0mHfmnSN9lg3yZaMSOd068pE.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (671, 'It', 'A flapper shopgirl woos her rich boss with animal magnetism -- the captivating personal quality otherwise known as "it."', 'Clarence G. Badger', 72, '1927-02-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nkkhsKik9GILqn3S5BxoZdyml21.jpg', 'https://www.youtube.com/watch?v=XXd7DGz2zHM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (672, 'The Jazz Singer', 'A young Jewish man is torn between tradition and individuality when his old-fashioned family objects to his career as a jazz singer. This is the first full length feature film to use synchronized sound, and is the original film musical.', 'Alan Crosland', 96, '1927-10-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wr8Pt1GO87cwB3210TO3JTNDsUc.jpg', 'https://www.youtube.com/watch?v=YP00IQ60ZP0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (673, 'The Kid Brother', 'The timid youngest son of the most important family in town must use his wits to win the respect of his strong father and the love of a beautiful new woman in town.', 'Harold Lloyd, Ted Wilde', 82, '1927-01-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wH5VcRHUdR0ZIb938mVEbPzF13c.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (674, 'The King of Kings', 'The King of Kings is the Greatest Story Ever Told as only Cecil B. DeMille could tell it. In 1927, working with one of the biggest budgets in Hollywood history, DeMille spun the life and Passion of Christ into a silent-era blockbuster. Featuring text drawn directly from the Bible, a cast of thousands, and the great showman’s singular cinematic bag of tricks, The King of Kings is at once spectacular and deeply reverent—part Gospel, part Technicolor epic.', 'Cecil B. DeMille', 155, '1927-04-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qJThyOfQVeEctEVVtK3LTDVL5S6.jpg', 'https://www.youtube.com/watch?v=pFhcdF_td10', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (675, 'The End of St. Petersburg', 'Shortly before the outbreak of WWI, a peasant from rural Russia arrives in St. Petersburg to find work.', 'Vsevolod Pudovkin', 74, '1927-12-13', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/wKLkiMq76do71f1TcHqXbvkiXOp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (676, 'London After Midnight', 'The abandoned Balfour House, the owner of which was found dead five years earlier, comes back to life with the arrival of two suspicious sinister-looking tenants.', 'Tod Browning', 69, '1927-12-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mDgG0R5XDai0960ICbk4GOMltlw.jpg', 'https://www.youtube.com/watch?v=JTuKq6-c5wg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (677, 'Love', 'In Imperial Russia, Anna Karenina falls in love with the dashing military officer Count Vronsky and abandons her husband and child to become his mistress.', 'Edmund Goulding', 81, '1927-11-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6Wdf0zB8DQeuquy5O3ldOK04Mfg.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (678, 'Napoleon', 'A biopic of former Emperor of France, Napoleon Bonaparte, tracing the Corsican''s career from his schooldays (where a snowball fight is staged like a military campaign) to his flight from Corsica, through the French Revolution (where a real storm is intercut with a political storm) and the Terror, culminating in his triumphant 1797 invasion of Italy.', 'Abel Gance', 425, '1927-01-10', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/kwudEzOQcihoNhCYZPhT9XqU4hG.jpg', 'https://www.youtube.com/watch?v=6504eRh5h6M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (679, 'October (Ten Days that Shook the World)', 'Sergei M. Eisenstein''s docu-drama about the 1917 October Revolution in Russia. Made ten years after the events and edited in Eisenstein''s ''Soviet Montage'' style, it re-enacts in celebratory terms several key scenes from the revolution.', 'Grigori Aleksandrov, Sergei Eisenstein', 115, '1928-05-11', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/tsfz9Ak1slSnxr6mSmRD3Wj7YZS.jpg', 'https://www.youtube.com/watch?v=tqwLwEhUtrE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (680, 'The Red Mill', 'A servant girl plays matchmaker for the local burgomaster''s daughter while setting her own sights on a visiting Irishman.', 'Roscoe Arbuckle', 74, '1927-01-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5HTn2bwnJzqwjMed599U2ghNnBz.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (681, 'The Ring', 'Both Jack Sander and Bob Corby are boxers in love with Mabel. Jack and Mabel wed, but their marriage is flat. The young wife looks to Bob for comfort.', 'Alfred Hitchcock', 116, '1927-09-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/VeNRpyspVlJzkrNAyszdGtmy9e.jpg', 'https://www.youtube.com/watch?v=3aTyC8ck348', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (682, '7th Heaven', 'In 1910s Paris, a sewer worker disillusioned with Christianity feels his prayers have been answered when he chances upon a street waif and they fall in love.', 'Frank Borzage', 119, '1927-09-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3ETXMu5PrcVMRJpfN2Z3MwcfXzy.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (683, 'The Student Prince in Old Heidelberg', 'A young prince falls in love with a beautiful barmaid while at university in old Heidelberg.', 'Ernst Lubitsch', 106, '1928-01-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3OUjEGUjo9SeO7VwMhukNZofuXF.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (684, 'Sunrise: A Song of Two Humans', 'A married farmer falls under the spell of a slatternly woman from the city, who tries to convince him to drown his wife.', 'F. W. Murnau', 94, '1927-11-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5V9jDm4u2QemGHbqjUyP5HmFmzf.jpg', 'https://www.youtube.com/watch?v=PCgbFay53BA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (685, 'Tell It to the Marines', 'U.S. Marine Sergeant O''Hara has his hands full training raw recruits, one of whom, ''Skeets'' Burns, is a particular thorn in his side. If Burns''s lackadaisical approach to the military were not bad enough, he also makes advances on nurse Nora Dale, whom Sergeant O''Hara secretly loves. Nora is oblivious to O''Hara''s feelings and is attracted to the handsome ''Skeet.'' But an indiscretion turns her against him, and it takes an expedition to China and a battle with a warlord''s bandit brigade to sort things out among the nurse and her two Marines.', 'George W. Hill', 103, '1926-12-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wX8Q8otMiIHGRDETwFLMqZaGVCL.jpg', 'https://www.youtube.com/watch?v=Em4XvsiwmeU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (686, 'Bed and Sofa', 'Life changes for a Moscow couple after they allow an old friend of the husband’s to move in.', 'Abram Room', 87, '1927-03-15', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/uEYi67LRcdPa94bpbtCm0EqwuIQ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (687, 'Two Arabian Knights', 'During World War I, two American soldiers fight to escape the Germans while squabbling over a beautiful harem girl. Preserved by the Academy Film Archive in partnership with University of Nevada, Las Vegas Foundation in 2016.', 'Lewis Milestone', 92, '1927-09-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cwura9mNFJ8XRP1KSfXbceh2Ask.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (688, 'Underworld', 'Boisterous gangster kingpin Bull Weed rehabilitates his former lawyer from his alcoholic haze, but complications arise when he falls for Weed''s girlfriend.', 'Josef von Sternberg', 87, '1927-08-20', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/6ZjgbeCwS7sipil1J221lbjaqGG.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (689, 'The Unknown', 'On the lam, criminal Alonzo hides in the circus as The Armless Wonder—a performer who uses his feet to hurl knives. Alonzo keeps the arms he really has concealed to hide his identity. Meanwhile, ringmaster''s daughter Nanon has a phobia of being touched by men, but is romantically pursued by not only Alonzo but the strongman Malabar. Alonzo''s desperation to remain with Nanon will only end in tragedy.', 'Tod Browning', 68, '1927-05-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/c9R1wE1vMJWMZNdmqXUV8oTaCPQ.jpg', 'https://www.youtube.com/watch?v=0ZPxz_gwOvk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (690, 'Wings', 'Two young men, one rich, one middle class, both in love with the same woman, become US Air Corps fighter pilots and, eventually, heroic flying aces during World War I. Devoted best friends, their mutual love of the girl eventually threatens their bond. Meanwhile, a hometown girl who''s the lovestruck lifelong next door neighbor of one of them pines away.', 'William A. Wellman', 144, '1927-08-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kEl6KCBgdmT1Nex3ka0EIWAOmtm.jpg', 'https://www.youtube.com/watch?v=08NbkvJQq-s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (691, 'Across to Singapore', 'While Joel and his older ship''s captain brother Mark are at sea, the latter is abandoned in Singapore by devious ship''s mate Finch who, upon their return, convinces the townspeople that Joel abandoned his brother. Joel, determined to not only find Mark but to see justice done, returns the ship to Singapore.', 'William Nigh', 85, '1928-04-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/paVqiDnjXYI2QUM2lxbQtLpLf4T.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (692, 'Beggars of Life', 'After killing her treacherous step-father, a girl tries to escape the country with a young vagabond. She dresses as a boy, they hop freight trains, quarrel with a group of hobos, and steal a car in their attempt to escape the police, and reach Canada.', 'William A. Wellman', 82, '1928-09-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/tUqClcPiLoMDExiC0nnQ6c0Zjku.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (693, 'Pandora''s Box', 'The rise and inevitable fall of an amoral but naive young woman whose insouciant eroticism inspires lust and violence in those around her.', 'G.W. Pabst', 141, '1929-01-30', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/3B2A5g8t3HZltKp1fplNn2xW4us.jpg', 'https://www.youtube.com/watch?v=A1kZaoHqEuU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (694, 'The Cameraman', 'A photographer takes up newsreel shooting to impress a secretary.', 'Edward Sedgwick', 74, '1928-09-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cLVJMJNW3VavnB1CZqbEC9GwSkR.jpg', 'https://www.youtube.com/watch?v=lWQTXkb5VYQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (695, 'Champagne', 'A spoiled heiress defies her millionaire father by running off to France to pursue her lover. Things don''t go entirely as planned.', 'Alfred Hitchcock', 105, '1928-08-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9xLjNbCOXuRWs7AkZ7bW4m8I0H4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (696, 'The Fall of the House of Usher', 'A man travels to the remote and decaying mansion of his old friend Roderick Usher, who lives in isolation with his mysterious and gravely ill wife, Madeleine. As the strange atmosphere surrounding the Usher family grows increasingly unsettling, the visitor finds himself drawn into their world of obsession, illness, and supernatural dread.', 'Jean Epstein', 63, '1928-10-04', 'T18', 'fr', 'https://image.tmdb.org/t/p/w500/gWpTehQgkkpMfxdCkr5CwU8vONR.jpg', 'https://www.youtube.com/watch?v=efvbSCjtACI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (697, 'The Circus', 'Charlie, a wandering tramp, becomes a circus handyman - soon the star of the show - and falls in love with the circus owner''s stepdaughter.', 'Charlie Chaplin', 72, '1928-01-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sihWAgBYa8yZFVAonGFGbLTVUj2.jpg', 'https://www.youtube.com/watch?v=FTZfMBREBtc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (698, 'The Crowd', 'John, an ambitious but undisciplined New York City office worker, meets and marries Mary. They start a family, struggle to cope with marital stress, financial setbacks, and tragedy, all while lost amid the anonymous, pitiless throngs of the big city.', 'King Vidor', 98, '1928-03-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jftzHLCZLE2DOLQWY0mENOIPjxc.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (699, 'The Docks of New York', 'A blue-collar worker on New York''s depressed waterfront finds his life changed after he saves a woman attempting suicide.', 'Josef von Sternberg', 76, '1928-09-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/rCMZpfPAHeuy02nMCttEX3OJt4B.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (700, 'The Farmer''s Wife', 'Successful middle-aged farmer Samuel Sweetland becomes widowed, then his daughter marries and leaves home. Deciding he wishes to remarry, Sweetland pursues some local women he considers prospects.', 'Alfred Hitchcock', 112, '1928-02-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xgHF8syPdDxr1WSOPpAGWoIAeN9.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (701, 'The Last Command', 'A former Imperial Russian general and cousin of the Czar ends up in Hollywood as an extra in a movie directed by a former revolutionary.', 'Josef von Sternberg', 88, '1928-01-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uKb5bFIwEzDtT3km99lqQBGNFCx.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (702, 'Laugh, Clown, Laugh', 'A despairing clown suffering a broken heart and a self-indulgent count who uncontrollably laughs learn to help each other with their problems, but both fall in love with the same young woman.', 'Herbert Brenon', 74, '1928-04-14', 'K', 'en', 'https://image.tmdb.org/t/p/w500/629NipgEKskEHAlrEeESYsI9Uoz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (703, 'Lonesome', 'Two lonely people in the big city meet and enjoy the thrills of an amusement park, only to lose each other in the crowd after spending a great day together. Will they ever see each other again?', 'Pál Fejős', 70, '1928-06-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ctxscU1tJ4nFRP4Q6n3Rngp9od1.jpg', 'https://www.youtube.com/watch?v=iuCd76BL2TY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (704, 'The Man Who Laughs', 'When a proud noble refuses to kiss the hand of the despotic King James in 1690, he is cruelly executed and his son surgically disfigured.', 'Paul Leni', 110, '1928-11-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iQXBMr4NzQst4X0rDU6MII6ZUOM.jpg', 'https://www.youtube.com/watch?v=2KhzpkSDwHA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (705, 'The Mysterious Lady', 'A beautiful Russian spy seduces an Austrian military officer in order to obtain secret plans. When she falls in love with him, both are placed in danger.', 'Fred Niblo', 89, '1928-08-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iOmtOcwSLNFwV2kqDsfnSpVphSL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (706, 'Our Dancing Daughters', 'A flapper who''s secretly a good girl and a gold-digging floozy masquerading as an ingénue both vie for the hand of a millionaire.', 'Harry Beaumont', 84, '1928-09-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ifilTkhpv4G49vZpSyWo0vYuh4z.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (707, 'The Passion of Joan of Arc', 'A classic of the silent age, this film tells the story of the doomed but ultimately canonized 15th-century teenage warrior. On trial for claiming she''d spoken to God, Jeanne d''Arc is subjected to inhumane treatment and scare tactics at the hands of church court officials. Initially bullied into changing her story, Jeanne eventually opts for what she sees as the truth. Her punishment, a famously brutal execution, earns her perpetual martyrdom.', 'Carl Theodor Dreyer', 81, '1928-04-21', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/tAgV9yxY6AC1bsPt3qJJQpD4s8.jpg', 'https://www.youtube.com/watch?v=Iz3XmfNzrNs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (708, 'The Patsy', 'An awkward teenager hopelessly in love with her older sister''s boyfriend tries to make him notice her.', 'King Vidor', 78, '1928-04-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sjlOwMr1IhzZrLocyw3hfwW50G0.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (709, 'Storm Over Asia', 'In 1918 a young and simple Mongol herdsman and trapper is cheated out of a valuable fox fur by a European capitalist fur trader. Ostracized from the trading post, he escapes to the hills after brawling with the trader who cheated him. In 1920 he becomes a Soviet partisan, and helps the partisans fight for the Soviets against the occupying British army. However he is captured by the British when they try to requisition cattle from the herdsmen at the same time as the commandant meets with a reincarnated Grand Lama. After the trapper is shot, the army discovers an amulet that suggests he is a direct descendant of Genghis Khan. They find him still alive, so the army restores his health and plans to use him as the head of a puppet regime. The trapper is thus thrust into prominence as he is placed in charge of the puppet government. By the end, however, the "puppet" turns against his masters in an outburst of fury.', 'Vsevolod Pudovkin', 127, '1928-11-10', 'T13', 'ru', 'https://image.tmdb.org/t/p/w500/myksAJCJsrwAtCs4YMYuNmSaXi7.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (710, 'The Racket', 'A renegade police captain sets out to catch a sadistic mob boss. Preserved by the Academy Film Archive in 2016.', 'Lewis Milestone', 84, '1928-11-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wHAJfHslSb6OpNQmj1hu9aE9IQR.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (711, 'Sadie Thompson', 'A young, beautiful prostitute named Sadie Thompson arrives on the South Pacific island of Pago Pago looking for honest work and falls for Timothy O''Hara, an American sailor who is unfazed by her unsavory past. However, Mr. Davidson, a missionary who arrived on the island at the same time, aims to "save" Sadie from her sinful life and petitions to have her separated from her beau and deported back to San Francisco.', 'Raoul Walsh', 97, '1928-01-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7IHxSWO4paEcPiuh515L4fzJDZx.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (712, 'Show People', 'Hollywood hopeful Peggy Pepper arrives at a major studio, from Georgia, to become a great dramatic star. Things don''t go entirely according to plan.', 'King Vidor', 79, '1928-11-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kMf0YYCNMqUbS9cTJBTCWcvsXEn.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (713, 'Speedy', 'A hapless young man living in New York City rallies to save his girlfriend''s grandfather''s horse-drawn trolley, the last in the city, from being put out of business by a railroad company.', 'Ted Wilde', 86, '1928-04-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zWhWaWCCIsnQDsFTAe98ap3R5y.jpg', 'https://www.youtube.com/watch?v=a-oh8XH5V48', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (714, 'Spies', 'The mastermind behind a ubiquitous spy operation learns of a dangerous romance between a Russian lady in his employ and a dashing agent from the government''s secret service.', 'Fritz Lang', 145, '1928-03-22', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/ri1agTtNaG8LemO9wcILukvULiR.jpg', 'https://www.youtube.com/watch?v=xbIeDOTe7zY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (715, 'Steamboat Bill, Jr.', 'The just-out-of-college, effete son of a no-nonsense steamboat captain comes to visit his father whom he''s not seen since he was a child.', 'Buster Keaton, Charles Reisner', 70, '1928-05-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zygJMsmXxeyDc1N67OCZc8xtq4I.jpg', 'https://www.youtube.com/watch?v=4a9VXNW0jjE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (716, 'Street Angel', 'A spirited young woman finds herself destitute and on the streets before joining a traveling carnival, where she meets a vagabond painter.', 'Frank Borzage', 102, '1928-04-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rGDFZRIwZPYocBvspSB7RGQMzXq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (717, 'The Wedding March', 'Against the backdrop of Vienna''s hidebound caste system, aristocrat and army officer Nicki is attracted to peasant Mitzi, although he knows it cannot last. Acquiescing to familial pressure, he ultimately gives her up to marry the more socially acceptable – albeit crippled – heiress Cecelia. Mitzi, for her part, is heartbroken and must resign herself to marrying churlish butcher Schani Eberle.', 'Erich von Stroheim', 109, '1928-10-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ej61Px6QKN1lTbkU9b1kqEHnWEW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (718, 'West of Zanzibar', 'A magician seeks vengeance upon the man who paralyzed him and the illegitimate daughter he sired with the magician''s wife.', 'Tod Browning', 70, '1928-11-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zwnhJhF73rADB9MURcpQ6AeLrPg.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (719, 'The Wind', 'When Letty Mason relocates to West Texas, she finds herself unsettled by the ever-present wind and sand. Arriving at her new home at the ranch of her cousin, Beverly, she receives a surprisingly cold welcome from his wife, Cora. Soon tensions in the family and unwanted attention from a trio of suitors leave Letty increasingly disturbed.', 'Victor Sjöström', 76, '1928-09-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/11ySoycM3ARm66RLiYE9yRcrg5b.jpg', 'https://www.youtube.com/watch?v=ViZDewxaJ8s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (720, 'A Woman of Affairs', 'Childhood friends Diana, Neville and David are caught in a love triangle as adults. Diana and Neville have long been smitten with each other, but her father disapproves of the relationship, resulting in her eventual marriage to David. It''s not long after their wedding, however, that tragedy strikes, sending Diana on a downward spiral. When Neville reappears in her life, will he be able to save her from her own misery?', 'Clarence Brown', 91, '1928-12-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4mPXzRGMBKrzN9XBrEgPoxhdbu.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (721, 'Zvenigora', 'An old man tells his grandson of a legendary treasure buried beneath the hills of Zvenigora, setting in motion a sweeping cinematic poem that intertwines Ukrainian folklore, history, and revolution.', 'Alexander Dovzhenko', 92, '1928-03-07', 'P', 'uk', 'https://image.tmdb.org/t/p/w500/iuQBwLMXwxT1N5GmF49anbdGJ0r.jpg', 'https://www.youtube.com/watch?v=9dHNh0hNrxw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (722, 'Applause', 'This early example of the "backstage" musical genre tells the story of Kitty Darling, a fading burlesque star who tries to save her convent-educated daughter April from following in mom''s footsteps.', 'Rouben Mamoulian', 80, '1929-10-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dhcVy77WKN0Mr9kCzRgwbbtkEd3.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (723, 'L''Argent', 'Adapted from the novel L''Argent by Émile Zola, the film portrays the world of banking and the stock market in Paris in the 1920s.', 'Marcel L''Herbier', 165, '1928-12-25', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/pbGXz7Yn4eWV9Edv0gT2OiZuBSB.jpg', 'https://www.youtube.com/watch?v=Z9kt8NS7s4U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (724, 'Arsenal', 'A soldier returns to Kyiv after surviving a train crash and encounters clashes between nationalists and collectivists. The story of the suppression of the Bolshevik uprising at the Arsenal factory in Kyiv by the Central Council troops.', 'Alexander Dovzhenko', 93, '1929-02-25', 'T13', 'ru', 'https://image.tmdb.org/t/p/w500/uKFpCZSNwOPyz28uOcAuHisolVA.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (725, 'Asphalt', 'Starring Betty Amann in her most famous leading role, Joe May''s Asphalt is a luxuriously produced German Expressionist classic where tragic liaisons and fatal encounters are shaped alongside the constant roar of Berlin traffic.', 'Joe May', 93, '1929-03-12', 'P', 'de', 'https://image.tmdb.org/t/p/w500/dlAQ3fEkoTOn4WNF9Zh9Rk2bMEN.jpg', 'https://www.youtube.com/watch?v=f6k8cq47N08', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (726, 'Blackmail', 'London, 1929. Frank Webber, a very busy Scotland Yard detective, seems to be more interested in his work than in Alice White, his girlfriend. Feeling herself ignored, Alice agrees to go out with an elegant and well-mannered artist who invites her to visit his fancy apartment.', 'Alfred Hitchcock', 86, '1929-07-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7ioNEKouUkkWyv5tUDwVUd7BDRR.jpg', 'https://www.youtube.com/watch?v=w1kWUWNPJa8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (727, 'The Broadway Melody', 'The vaudeville act of Harriet and Queenie Mahoney comes to Broadway, where their friend Eddie Kerns needs them for his number in one of Francis Zanfield''s shows. When Eddie meets Queenie, he soon falls in love with her—but she is already being courted by Jock Warriner, a member of New York high society. Queenie eventually recognizes that, to Jock, she is nothing more than a toy, and that Eddie is in love with her.', 'Harry Beaumont', 101, '1929-02-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/giq8GJs8YGMzHxeKxNSuwzAdd1c.jpg', 'https://www.youtube.com/watch?v=BuB2HVP-mNU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (728, 'Bulldog Drummond', 'Bulldog Drummond is a British WWI veteran who longs for some excitement after he returns to the humdrum existence of civilian life. He gets what he''s looking for when a girl requests his help in freeing her uncle from a nursing home. She believes the home is just a front and that her uncle is really being held captive while the culprits try to extort his fortune from him.', 'F. Richard Jones', 90, '1929-05-02', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/7pN3nEDQBfQRjrtgOwJ3WBBm23F.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (729, 'The Canary Murder Case', 'A beautiful showgirl, name "the Canary" is a scheming nightclub singer. Blackmailing is her game and with that she ends up dead. But who killed "the Canary". All the suspects knew and were used by her and everyone had a motive to see her dead. The only witness to the crime has also been ''rubbed out''. Only one man, the keen, fascinating, debonair detective Philo Vance, would be able to figure out who is the killer.', 'Frank Tuttle, Malcolm St. Clair', 82, '1929-02-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/x21cBrK1sM30j0xNlHKPI33toTS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (730, 'Man with a Movie Camera', 'A cameraman wanders around with a camera slung over his shoulder, documenting urban life with dazzling inventiveness.', 'Dziga Vertov', 68, '1929-05-12', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/vJgAdgJWX54v0oXfIvhwjlZnmgn.jpg', 'https://www.youtube.com/watch?v=BtTlgxtoqhg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (731, 'The Cocoanuts', 'During the Florida land boom, the Marx Brothers run a hotel, auction off some land and thwart a jewel robbery.', 'Joseph Santley, Robert Florey', 93, '1929-05-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xfiyCaWDfftKHzft2MKxAFFwHYL.jpg', 'https://www.youtube.com/watch?v=VPVNvoJcS8k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (732, 'Coquette', 'A Southern belle''s flirtation with a working man leads to tragedy.', 'Sam Taylor', 76, '1929-03-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/55WVe0RBtaLADx7VW4dpKPTeYeq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (733, 'Desert Nights', 'Jewel thieves pull a heist on a diamond mining operation in Africa and take the foreman hostage before escaping into the Kalahari Desert, but when they get lost, the foreman must take charge and save them.', 'William Nigh', 62, '1929-03-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gan6z7cRBD1GmNi6NVBOYyvhXf0.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (734, 'Disraeli', 'Prime Minister of Great Britain Benjamin Disraeli outwits the subterfuge of the Russians and chicanery at home in order to secure the purchase of the Suez Canal.', 'Alfred E. Green', 90, '1929-11-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uVTmxQJp0sqBujbieSTrB2ui9al.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (735, 'Woman in the Moon', 'A scientist discovers that there''s gold on the moon. He builds a rocket to fly there, but there''s too much rivalry among the crew to have a successful expedition.', 'Fritz Lang', 170, '1929-10-15', 'P', 'de', 'https://image.tmdb.org/t/p/w500/7s6zEsOAY3LD5qvzljmKKzjnLiT.jpg', 'https://www.youtube.com/watch?v=lDnqSc1T3k0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (736, 'Hallelujah', 'A black laborer turns preacher after accidentally killing a man.', 'King Vidor', 100, '1929-08-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eRRhrNMQkYLq90ZvwDqqMMebZWB.jpg', 'https://www.youtube.com/watch?v=eayYUrtOB60', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (737, 'The Hollywood Revue of 1929', 'An all-star revue featuring MGM contract players.', 'Charles Reisner', 118, '1929-11-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pe8dZ8LpRnfivsQ7nxLhH5AWxoW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (738, 'In Old Arizona', 'Army Sergeant Mickey Dunn sets out in pursuit of the Cisco Kid, a notorious if kind-hearted and charismatic bandit of the Old West. The Kid spends much of his loot on Tonia, the woman he loves, not realizing that she is being unfaithful to him in his absence. Soon, with her oblivious paramour off plying his trade, Tonia falls in with Dunn, drawn by the allure of a substantial reward for the Kid''s capture -- dead or alive. Together, they concoct a plan to ambush and do away with the Cisco Kid once and for all.', 'Irving Cummings, Raoul Walsh', 95, '1928-12-25', 'K', 'en', 'https://image.tmdb.org/t/p/w500/x1XSQeLUdoi72P5UOXqAyL46B9a.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (739, 'The Iron Mask', 'King Louis XIII of France is thrilled to have born to him a son - an heir to the throne. But when the queen delivers a twin, Cardinal Richelieu sees the second son as a potential for revolution, and has him sent off to Spain to be raised in secret to ensure a peaceful future for France. Alas, keeping the secret means sending Constance, lover of D''Artagnan, off to a convent. D''Artagnan hears of this and rallies the Musketeers in a bid to rescue her. Unfortunately, Richelieu out-smarts the Musketeers and banishes them forever.', 'Allan Dwan', 103, '1929-02-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/f9t60V0eJ2pLwCl0YsBnvXQmRNN.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (740, 'The Kiss', 'An unhappily married woman is caught up in scandal and murder when her affection toward a young man is misinterpreted.', 'Jacques Feyder', 62, '1929-11-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/t82WbEYJwKgnq9yKu9IQRxZk2f9.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (741, 'The Love Parade', 'The queen of mythical Sylvania marries a courtier, who finds his new life unsatisfying', 'Ernst Lubitsch', 107, '1929-11-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pWAoFnPsH4gYiFGqLwzicyMazdh.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (742, 'Lucky Star', 'Mary, a poor farm girl, meets Tim just as word comes that war has been declared. Tim enlists in the army and goes to the battlefields of Europe, where he is wounded and loses the use of his legs. Home again, Tim is visited by Mary, and they are powerfully attracted to each other; but his physical handicap prevents him from declaring his love for her. Deeper complications set in when Martin, Tim''s former sergeant and a bully, takes a shine to Mary.', 'Frank Borzage', 99, '1929-08-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/Ae5D9BmePeILMyvMIqFSNdPZr0o.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (743, 'The Manxman', 'A fisherman and a rising lawyer who grew up together as brothers fall in love with the same woman.', 'Alfred Hitchcock', 100, '1929-01-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1CoJiLwUwKipp7X89M5ZmsI016.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (744, 'Marianne', 'At the conclusion of World War I, a French girl is romanced by an American doughboy even though she is promised to a French soldier who was sent to the front.', 'Robert Z. Leonard', 111, '1929-08-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1jqPoj9MlsNb2Frzy6G9PWMyWX5.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (745, 'People on Sunday', 'A semi-documentary experimental 1930 German silent film created by amateurs with a small budget. With authentic scenes of the metropolis city of Berlin, it''s the first film from the later famous screenwriters/directors Billy Wilder and Fred Zinnemann.', 'Edgar G. Ulmer, Robert Siodmak', 74, '1930-02-04', 'P', 'de', 'https://image.tmdb.org/t/p/w500/gWIkCmYaRDlA78WMIfRUlURuLCZ.jpg', 'https://www.youtube.com/watch?v=z2O5QiCTreA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (746, 'Piccadilly', 'A young Chinese woman, working in the kitchen at a London dance club, is given the chance to become the club''s main act.', 'E.A. Dupont', 109, '1929-02-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/biZjt8E9ljayP80tZPXgWKBiiyn.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (747, 'Queen Kelly', 'A convent girl is abducted and seduced by a prince before being sent off to a brothel in East Africa.', 'Erich von Stroheim', 101, '1929-12-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/i1BN0KpSACWyDBHULPKUc24oE67.jpg', 'https://www.youtube.com/watch?v=lNlS1XFoTkQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (748, 'Spite Marriage', 'An unimpressive but well-intentioned man is given the chance to marry a popular actress, of whom he has been a hopeless fan. But what he doesn''t realize is that he is being used to make the actress'' old flame jealous.', 'Buster Keaton, Edward Sedgwick', 76, '1929-03-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eXt4ilTxsrY5a1Lagp1TE79vIvN.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (749, 'The General Line', 'Also known as The Old and the New, The General Line illustrates Lenin’s stated imperative that the nation move from agrarian to industrial culture in an epic ode to farm-collectivization progress.', 'Grigori Aleksandrov, Sergei Eisenstein', 125, '1929-09-25', 'P', 'ru', 'https://image.tmdb.org/t/p/w500/6sSikOdXU9Aiwkwfjrm9iT4fH1N.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (750, 'Diary of a Lost Girl', 'Thymian Henning, an innocent young girl, is raped by the clerk of her father''s pharmacy. She becomes pregnant, is rejected by her family, and must fend for herself in a harsh, cruel world.', 'G.W. Pabst', 113, '1929-09-27', 'K', 'de', 'https://image.tmdb.org/t/p/w500/uDR1Tt2pFR0M3gUFCJ1w2oiVYlM.jpg', 'https://www.youtube.com/watch?v=Y8CVd5pM4AA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (751, 'The Trespasser', 'A stenographer who works for a lawyer falls in love with and marries a wealthy young man. His family has the marraige annulled, after which she gives birth to a child. Her former boss helps her out to ensure the child''s welfare, which starts gossip that she is a "kept woman."', 'Edmund Goulding', 90, '1929-11-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8IIvlovQzJ4BXbdNiAvtXRbu90u.jpg', 'https://www.youtube.com/watch?v=uyfndlsXL2A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (752, 'The White Hell of Pitz Palu', 'Dr. Johannes Krafft climbs a 12,000-foot mountain over and over again to search for his wife, who was lost on their honeymoon. Another couple makes the dangerous climb with him.', 'Arnold Fanck, G.W. Pabst', 150, '1929-10-10', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/wrPcJD1wjEHamKnbccHpURJwjBc.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (753, 'Abraham Lincoln', 'An episodic dramatization of the 18th President of the United States'' life, including his early years, affair with Ann Rutledge, courtship of Mary Todd, debates with Stephen A. Douglas, the election of 1860, his presidency during the Civil War, and finally his assassination at Ford''s Theater in 1865.', 'D.W. Griffith', 83, '1930-11-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4BOmqevJBC5gBfQNXpa2epf27yO.jpg', 'https://www.youtube.com/watch?v=11rSeJ19XuI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (754, 'All Quiet on the Western Front', 'When a group of idealistic young men join the German Army during the Great War, they are assigned to the Western Front, where their patriotism is destroyed by the harsh realities of combat.', 'Lewis Milestone', 133, '1930-04-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1wZUB08igw8iLUgF1r4T6aJD65b.jpg', 'https://www.youtube.com/watch?v=Qeh3DlBEjAc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (755, 'Animal Crackers', 'The well-known explorer and hunter Captain Spaulding has just returned from Africa, and is being welcomed home with a lavish party at the estate of influential society matron Mrs. Rittenhouse when a valuable painting goes missing. The intrepid Captain Spaulding attempts to solve the crime with the help of his silly secretary Horatio Jamison, while sparring with the anarchic Signor Emanuel Ravelli and his nutty sidekick The Professor.', 'Victor Heerman', 98, '1930-08-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qj7owFXzCtIbZC51O8NwLe4Kde4.jpg', 'https://www.youtube.com/watch?v=0ykYqkECz9E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (756, 'Anna Christie', 'Old sailor Chris Christofferson eagerly awaits the arrival of his grown daughter Anna, whom he sent at five years old to live with relatives in Minnesota. He has not seen her since, but believes her to be a decent and respectably employed young woman. When Anna arrives, however, it is clear that she has lived a hard life in the dregs of society, and that much of spirit has been extinguished. She falls in love with a young sailor rescued at sea by her father, but dreads to reveal to him the truth of her past. Both father and young man are deluded about her background, yet Anna cannot quite bring herself to allow them to remain deluded.', 'Clarence Brown', 89, '1930-02-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zHsjA95g42xeBEPcWdF4s1BA53L.jpg', 'https://www.youtube.com/watch?v=46ybS7cebuU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (757, 'The Bat Whispers', 'Infamous burglar "The Bat" commits a daring jewelry theft despite heavy police presence. Soon after, a bank theft occurs, which may be the work of the criminal as well. Meanwhile, Cornelia Van Gorder has various people arrive at her old mansion, including her niece, Dale, a bank employee, and police detective Anderson. When guests start turning up dead, Cornelia begins to suspect that The Bat may be lurking around the estate.', 'Roland West', 83, '1930-11-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pkgDRRgLjvMwjJXpnKrBYriSd9X.jpg', 'https://www.youtube.com/watch?v=JeaNEWKchts', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (758, 'The Big House', 'Convicted of manslaughter for a drunken driving accident, Kent Marlowe is sent to prison, where he meets vicious incarcerated figures who are planning an escape from the brutal conditions.', 'George W. Hill', 87, '1930-06-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qVf7Dpgx0sdDkZEn4CwTYethoMp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (759, 'The Big Trail', 'Young scout Breck Coleman leads a wagon train along the dangerous trail to Oregon as he tries to get the affection of the beautiful pioneer Ruth Cameron and plans his revenge on the harsh scoundrels who murdered a friend of his in the past.', 'Raoul Walsh', 122, '1930-11-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/mmKlxMlpvTRwJWs0x2nAhdhWOIv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (760, 'The Blue Angel', 'Prim professor Immanuel Rath finds some of his students ogling racy photos of cabaret performer Lola Lola and visits a local club, The Blue Angel, in an attempt to catch them there. Seeing Lola perform, the teacher is filled with lust, eventually resigning his position at the school to marry the young woman. However, his marriage to a coquette -- whose job is to entice men -- proves to be more difficult than Rath imagined.', 'Josef von Sternberg', 108, '1930-04-01', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/khz2rKLAPDVu9auJt1sR1HO9SCG.jpg', 'https://www.youtube.com/watch?v=Lw6GJiGNO74', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (761, 'City Girl', 'A waitress from Chicago falls in love with a man from rural Minnesota and marries him, with the intent of living a better life - but life on the farm has its own challenges.', 'F. W. Murnau', 88, '1930-01-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/d0ioAdV4cg9euanBb2OdA3zpAsT.jpg', 'https://www.youtube.com/watch?v=Pop64E6uOD8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (762, 'A Cottage on Dartmoor', 'A jealous barber''s assistant becomes enraged by the attentions the manicurist he''s obsessed with and a repeat customer pay to one another.', 'Anthony Asquith', 88, '1929-10-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7pEJGYom5opZCzyoc8JXXDP8Lag.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (763, 'The Dawn Patrol', 'World War I ace Dick Courtney derides the leadership of his superior officer, but he soon is promoted to squadron commander and learns harsh lessons about sending subordinates to their deaths.', 'Howard Hawks', 108, '1930-07-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rJQIJGOx1EMkPt0vkRGpEUuXvSw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (764, 'The Divorcee', 'When a woman discovers that her husband has been unfaithful, she decides to pay him back in kind.', 'Robert Z. Leonard', 83, '1930-04-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zzu6IW9ilkUt6L4DL9SoNnwtAfy.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (765, 'The Doorway to Hell', 'A vicious crime lord decides that he has had enough and much to the shock of his colleagues decides to give the business to his second in command and retire to Florida after marrying his moll. Unfortunately, he has no idea that she and the man are lovers.', 'Archie Mayo', 78, '1930-10-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jZgIKq8CHrcy17Mdb4VMGMQNV3a.jpg', 'https://www.youtube.com/watch?v=ofEVUDv4eL4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (766, 'Feet First', 'An ambitious shoe salesman, Harold, unknowingly meets the boss'' daughter and tells her he is a leather tycoon. The rest of the film he spends hiding his true circumstances, in the store and later on a ship. Trying to deliver a letter, he later finds himself dangling high above the street on a building''s scaffolding.', 'Clyde Bruckman', 91, '1930-10-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7cD3xWlzcX7WwmQuqZ8Qi7BAz40.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (767, 'The Florodora Girl', 'A chorus girl gets bad advice from her fellow chorines in handling a rich suitor who assumes she is a gold digger.', 'Harry Beaumont', 79, '1930-05-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ylHVWhDO6Aw00gtpCQGogkn34II.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (768, 'Hell''s Angels', 'As the Great War breaks out in Europe, Oxford brothers Roy and Monte enlist in the RFC to fight for queen and country, while their college friend Karl is drafted in Germany. A love triangle involving Monte, Roy, and Roy''s girlfriend, Helen, the brothers'' disparate personalities, and Monte''s cowardice in the face of war soon threaten to compromise a top-secret bombing mission over German territory.', 'Howard Hughes', 131, '1930-11-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vt6zF55B9WLzYENs6cuXy8J5o1X.jpg', 'https://www.youtube.com/watch?v=KqD3hN9G2AM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (769, 'Juno and the Paycock', 'In the slums of Dublin during the Irish Civil War, the Boyle family’s fragile stability collapses after news of an unexpected inheritance lures them into a false sense of prosperity. Captain Boyle, a boastful idler, squanders their meager resources, while his wife Juno holds the household together. When the fortune proves illusory, the family faces ruin, betrayal, and tragedy.', 'Alfred Hitchcock', 94, '1930-06-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eKAOKqfBacUDNhPwvXFxaP59Kyp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (770, 'King of Jazz', 'A large-scale revue musical built around Paul Whiteman and his orchestra, presenting a series of musical performances, sketches, and staged tableaux in early two-color Technicolor, emblematic of Hollywood’s early sound-era “all-star” musical productions.', 'John Murray Anderson', 100, '1930-04-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2CXh34kZ4AblbpnVIqmPF1vKwti.jpg', 'https://www.youtube.com/watch?v=Mp4nfqmhxAg', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (771, 'Ladies of Leisure', 'Kay Arnold is a gold digger who wanders from party to party with the intention of catching a rich suitor. Jerry Strong is a young man from a wealthy family who strives to succeed as an artist. What begins as a relationship of mutual convenience soon turns into something else.', 'Frank Capra', 100, '1930-04-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/71LYZn15hORP7MKE1jZAEb37ZSo.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (772, 'Little Caesar', 'A small-time hood shoots his way to the top, but how long can he stay there?', 'Mervyn LeRoy', 78, '1931-01-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/1K3Q1tAHHA5Sdtja2pPALBQevA7.jpg', 'https://www.youtube.com/watch?v=pAM2UDuQIjw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (773, 'Madam Satan', 'A socialite masquerades as a notorious femme fatale to win back her straying husband during a costume party aboard a doomed dirigible.', 'Cecil B. DeMille', 116, '1930-09-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fMRAu0p3cT1p06TCbPDsjcLgs4O.jpg', 'https://www.youtube.com/watch?v=44kEVSMCzm4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (774, 'Min and Bill', 'Min, the owner of a dockside hotel, is forced to make difficult decisions about the future of Nancy, the young woman she took in as an infant.', 'George W. Hill', 66, '1930-11-29', 'K', 'en', 'https://image.tmdb.org/t/p/w500/9I8cAo1fbEeztrgvbNwk18xqTwz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (775, 'Monte Carlo', 'A countess fleeing her husband mistakes a count for her hairdresser at a Monte Carlo casino.', 'Ernst Lubitsch', 90, '1930-08-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eKw9l71pSV2lQpUsfK1pV3KJKaX.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (776, 'Morocco', 'Mogador, Morocco. Late 1920s. A complex romance develops between a womanizing Legionnaire and a disillusioned Parisian cabaret singer.', 'Josef von Sternberg', 92, '1930-11-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jDqZsxyv35iyJWW0mANk1RhxhJp.jpg', 'https://www.youtube.com/watch?v=u80OARwTRBw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (777, 'Murder!', 'When actress Diana Baring is found in a daze beside her colleague’s murdered body, all evidence points to her guilt. During the trial, juror Sir John Menier doubts the verdict, but yields to pressure. Haunted by remorse, he launches his own investigation.', 'Alfred Hitchcock', 102, '1930-07-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iu8mee9GciHFgfqG5ifdDOTLw4F.jpg', 'https://www.youtube.com/watch?v=BxMMkvTnW0A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (778, 'Not So Dumb', 'Not-so-smart chatterbox Dulcy Parker does and says all the wrong things, but they right themselves to prove she''s not so dumb after all.', 'King Vidor', 76, '1930-02-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nQzIXyGp560iqMpb8EmOVJiDl0N.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (779, 'Raffles', 'A distinguished English gentleman has a secret life--he is the notorious jewel thief the press has dubbed "The Amateur Cracksman". When he meets a woman and falls in love he decides to "retire" from that life, but an old friend comes to him with a predicament that entails him committing one last job.', 'George Fitzmaurice, Harry d''Abbadie d''Arrast', 72, '1930-07-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mOeP2d3JO1Q8bLgphb9zyEM3spG.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (780, 'The Tale of the Fox', 'In the kingdom of animals, Master Fox is used to trick and fool everyone. So the King, the Lion, receives more and more complaints about him. He orders that Master Fox is arrested and brought to him.', 'Irene Starewicz, Władysław Starewicz', 65, '1941-04-10', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/eYt1ddYGIO98MzsprcRjgZuPusW.jpg', 'https://www.youtube.com/watch?v=M6RNyaMAhrs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (781, 'The Blood of a Poet', 'In a poet’s room, an armless statue abruptly comes to life. It invites the poet to step through a mirror and to discover another world. Strange places and characters present themselves to him. The poet tears himself away from these twisted fascinations and returns, with some difficulty, to his room.', 'Jean Cocteau', 55, '1932-01-20', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/paHmfMrtQVT2cUTeteni3iDgRym.jpg', 'https://www.youtube.com/watch?v=3scPy9ohKDc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (782, 'Under the Roofs of Paris', 'In the tenement slums of Paris between the world wars, impoverished street singer Albert yearns for beautiful Romanian immigrant Pola. Pola''s boyfriend, local hoodlum Fred, grows jealous of Albert''s constant attention to his woman and frames the hapless musician for one of his own petty crimes. But while Albert is in prison for Fred''s misdeed, Pola ends up falling for Albert''s faithful best friend, Louis.', 'René Clair', 92, '1930-04-28', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/xvpsXolyLwcSIoCMdeWbRZjaBbU.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (783, 'The Unholy Three', 'A trio of former sideshow performers double as the "Unholy Three" in a scam to nab some shiny rocks.', 'Jack Conway', 72, '1930-07-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4NLoePBFJX8O0yCwBbhrqhHFXFp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (784, 'Up the River', 'Daily life at men and women''s prison units where baseball and the marching band are serious business. Two prisoners escape in order to help paroled Steve from being blackmailed by his girlfriend''s ex-partner-in-crime.', 'John Ford', 85, '1930-10-10', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pJjvzJiSAh0g0XsQvMbCFakNO0v.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (785, 'Westfront 1918', 'A group of German infantrymen of the First World War live out their lives in the trenches of France. They find brief entertainment and relief in a village behind the lines, but primarily terror fills their lives as the attacks on and from the French army ebb and flow. One of the men, Karl, goes home on leave only to discover the degradation forced on his family by wartime poverty. He returns to the lines in time to face an enormous attack by French tanks.', 'G.W. Pabst', 97, '1930-05-23', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/oaMSB0DZY0GK8VdaDuHQLLdtHkg.jpg', 'https://www.youtube.com/watch?v=0yqQLJCDDT0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (786, 'Whoopee!', 'Western sheriff Bob Wells is preparing to marry Sally Morgan; she loves part-Indian Wanenis, whose race is an obstacle. Sally flees the wedding with hypochondriac Henry Williams, who thinks he''s just giving her a ride; but she left a note saying they''ve eloped! Chasing them are jilted Bob, Henry''s nurse Mary (who''s been trying to seduce him) and others.', 'Thornton Freeland', 93, '1930-09-26', 'K', 'en', 'https://image.tmdb.org/t/p/w500/jVggH7wheJahCoQWUzt1CA2KGVN.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (787, 'Earth', 'During the agrarian collectivization process in the Soviet Union, Vasyl, a peasant member of the youth division of the Communist Party, gets a tractor with the help of a local party organization and plows private boundaries on kulak fields. However, this enthusiasm will cost him dearly.', 'Alexander Dovzhenko', 79, '1930-04-08', 'P', 'uk', 'https://image.tmdb.org/t/p/w500/zXRpYOJFZ8wWzhCYWILSiw1ouOy.jpg', 'https://www.youtube.com/watch?v=8wXzFIDMLT0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (788, 'L''Âge d''or', 'The film consists of a series of tightly interlinked vignettes, the most sustained of which details the story of a man and a woman who are passionately in love. Their attempts to consummate their passion are constantly thwarted, by their families, by the Church and bourgeois society in general.', 'Luis Buñuel', 63, '1930-11-28', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/q3OH9Yk3hOE5uYEK55ASjEtsPfE.jpg', 'https://www.youtube.com/watch?v=Q14oKtsd-Zw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (789, 'Arrowsmith', 'A medical researcher is sent to a plague outbreak, where he has to decide priorities for the use of a vaccine.', 'John Ford', 108, '1931-12-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/urUy4jYuRs53WSmE0t0BivUSQjC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (790, 'The Bachelor Father', 'Lonely in his English country estate, Sir Basil decides to gather his grown (albeit illegitimate) children around him in his declining years. He uses a ledger which keeps track of the payments he has been making to ex-lovers to locate 2 of them, and a third is found by a lawyer in New York, her mother was too proud to accept any money. Sir Basil is a curmudgeon, and his three adult children have a hard time with him at first. Toni, the American, is a free spirit who had a budding career in show business. Jeffery is English and a semi-gentleman, and Maria is Italian, with a Latin temperament. They begin to bond, especially Sir Basil and Toni, whose outgoing personality finally wins over the old man. But past lives begin to creep back into the picture and threaten the old man''s plans for a life filled with his children.', 'Robert Z. Leonard', 90, '1931-01-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5B8w50JMSSTOf0fRVSakW8ci77e.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (791, 'Bad Girl', 'A man and woman, skeptical about romance, nonetheless fall in love and are wed, but their lack of confidence in the opposite sex haunts their marriage.', 'Frank Borzage', 90, '1931-08-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kUwfDGMbTdb3Foc8p0cG7urBQBW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (792, 'The Bad Sister', 'Marianne falls in love with con man Valentine who uses their relation to get her father''s endorsement on a money-raising scheme. He runs off with the money and Marianne, later dumping her. Her sister Laura loves Dr. Lindley although she knows he loves Marianne. Marianne returns and marries a wealthy young man, and Lindley turns his love toward Laura.', 'Hobart Henley', 68, '1931-03-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/n7jx03EnD2eyob8ld07bOD5XOcl.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (793, 'The Black Camel', 'Movie star Shelah Fane is seeing wealthy Alan Jaynes while filming in Honolulu, Hawaii, but won''t marry him without consulting famed psychic Tarneverro first. Enter inspector Charlie Chan of the Honolulu Police, investigating the unsolved murder, three years earlier, of a Hollywood actor.', 'Hamilton MacFadden', 71, '1931-06-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oq1NH2ZJkkp31zzOqXiCOeGnLqj.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (794, 'Blonde Crazy', 'The adventures of a cocky con man and his beautiful accomplice.', 'Roy Del Ruth', 79, '1931-09-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dhQSdNMkXEsEXS3TllcdgbhLqMm.jpg', 'https://www.youtube.com/watch?v=5cKY_Fw1PhA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (795, 'The Champ', 'A broken-down alcoholic prizefighter struggles to keep custody of his adoring son.', 'King Vidor', 86, '1931-11-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5miye3zystUco0k4WtN5cKoKJB.jpg', 'https://www.youtube.com/watch?v=soDPKxKMESM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (796, 'La Chienne', 'Cashier Maurice Legrand is married to the wretched Adele. By chance, he meets Lucienne, ''Lulu'', and makes her his mistress. He thinks he has finally found love, but Lulu is a streetwalker, still in love with her pimp.', 'Jean Renoir', 96, '1931-11-01', 'T18', 'fr', 'https://image.tmdb.org/t/p/w500/h3b8k9sY4z8mIy0J6zu9O3ZIcLr.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (797, 'Cimarron', 'When the government opens up the Oklahoma territory for settlement, restless Yancey Cravat claims a plot of the free land for himself and moves his family there from Wichita. A newspaperman, lawyer, and just about everything else, Cravat soon becomes a leading citizen of the boom town of Osage. Once the town is established, however, he begins to feel confined once again, and heads for the Cherokee Strip, leaving his family behind. During this and other absences, his wife Sabra must learn to take care of herself and soon becomes prominent in her own right.', 'Wesley Ruggles', 123, '1931-01-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cqvfhi9s1VsTgXcV1B7vX0Cb1qA.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (798, 'City Lights', 'A tramp falls in love with a beautiful blind flower girl. His on-and-off friendship with a wealthy man allows him to be the girl''s benefactor and suitor.', 'Charlie Chaplin', 87, '1931-02-06', 'K', 'en', 'https://image.tmdb.org/t/p/w500/ugmakEL5y294I5bXgiBqApuZpwc.jpg', 'https://www.youtube.com/watch?v=7vl7F8S4cpQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (799, 'City Streets', 'A mobster''s daughter leads her boyfriend from the circus into bootlegging.', 'Rouben Mamoulian', 83, '1931-04-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1P2FKo5AgmdIA7ifosxTo8UosED.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (800, 'The Criminal Code', 'After young Robert Graham commits a murder while drunk and defending his girlfriend, he is prosecuted by ambitious Mark Brady and sentenced to 10 years. Six years later, Brady becomes the prison warden and offers the beleaguered Robert a job as his chauffeur. Robert cleans up his act, but, on the eve of his pardon, his cellmate drags him back into the world of violence, and he faces a difficult choice that could return him to prison.', 'Howard Hawks', 97, '1931-01-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/nshRsmnw7wpE2fsRkVrCED7uCcI.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (801, 'Dance, Fools, Dance', 'When misfortune hits hard on the Jordan family of Chicago''s upper class, Bonnie Jordan, a dazzling and witty girl, finds a job as an aspiring reporter; however, her naive younger brother Rodney takes a twisted path and gets involved with the wrong people.', 'Harry Beaumont', 78, '1931-02-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dwieBi0VsQpGnKLMOomldAWgipR.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (802, 'Dishonored', 'The Austrian Secret Service sends its most seductive agent to spy on the Russians.', 'Josef von Sternberg', 91, '1931-04-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/g3Q4WgQdJgLdt4EVMqLQqKsDcFv.jpg', 'https://www.youtube.com/watch?v=0Oeq47VQoQs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (803, 'Dracula', 'A British estate agent travels to Transylvania to meet with the mysterious Count Dracula, who is interested in leasing a London castle. After Dracula enslaves and drives the agent to insanity, the pair return to London together, where Dracula, a secret bloodsucker, begins preying on socialites.', 'Tod Browning', 74, '1931-02-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ueVSPt7vAba0XScHWTDWS5tNxYX.jpg', 'https://www.youtube.com/watch?v=M5zL-jCgvUA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (804, 'Drácula', 'A British estate agent travels to Transylvania to meet the mysterious Count Dracula, who is interested in leasing a London castle. After Dracula enslaves the agent and drives him to insanity, the pair return to London together, where Dracula, a secret bloodsucker, begins preying on socialites.', 'George Melford', 104, '1931-03-01', 'T18', 'es', 'https://image.tmdb.org/t/p/w500/vXpPf8MFLqp4f9KdUyjL7tSYDmd.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (805, 'The 3 Penny Opera', 'In London at the turn of the century, underworld kingpin Mack the Knife marries Polly Peachum without the knowledge of her father, the equally enterprising ''king of the beggars''.', 'G.W. Pabst', 112, '1931-02-18', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/w39cIJWmtLRxyqAE2KdhSuUa0wC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (806, 'Five Star Final', 'Searching for headlines at any cost, an unscrupulous newspaper owner forces his editor to print a serial based on a past murder, tormenting a woman involved.', 'Mervyn LeRoy', 89, '1931-09-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1DZF4buRoDNsnAtkQZd8fIYVCCV.jpg', 'https://www.youtube.com/watch?v=GUUoZLA9Iag', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (807, 'Five and Ten', 'John owns the largest chain of five and ten cent stores in the country. He moves his family to New York from Kansas City and their life, though grand, is falling apart due to his constant working. Wife and mother Jenny is lonely. Son Avery hates his job. Daughter Jennifer is snubbed by classmate Muriel and her friends. At a charity bazaar, Jennifer meets Berry and sparks are evident. However, he is engaged to Muriel and Muriel will make sure that she, and only she, marries Berry. After the marriage, Berry still thinks of Jennifer as Jennifer thinks of Berry. Avery laments about the state of his family since they were happy in Kansas City.', 'Robert Z. Leonard', 89, '1931-06-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uYnB3pqyyffBtuaJbeRfxMMhIJ5.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (808, 'Frankenstein', 'Henry Frankenstein pieces together body parts in the hope of bringing a human-like creature to life. The mad scientist’s dreams are shattered by his monstrous creation awakening with rage to a world that hates and fears him.', 'James Whale', 70, '1931-11-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mu6wHwH0IwCCaEYtpqujuPJYat1.jpg', 'https://www.youtube.com/watch?v=EEH5MZCewPQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (809, 'A Free Soul', 'An alcoholic lawyer who successfully defended a notorious gambler on a murder charge objects when his free-spirited daughter becomes romantically involved with him.', 'Clarence Brown', 93, '1931-06-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/A1mXqIz27GtoJfLCMQvkf6FBYbu.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (810, 'The Front Page', 'Hildy Johnson is an investigative reporter looking for a bigger paycheck. When an accused murderer escapes from custody, Hildy sees an opportunity for the story of a lifetime. But when he finds the criminal, he learns that the man may not be guilty. With the help of his editor, Hildy attempts to hide the convict, uncover the conspiracy and write the scoop of his career.', 'Lewis Milestone', 101, '1931-04-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1ZVA6L4a5HKIdvfpNcxDU38BHYd.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (811, 'Hyppolit, the Butler', 'Evergreen comedy about a typical parvenu, an ignorant transportation entrepreneur who has suddenly found himself very rich. Despite their humble origins, his wife strives to live a sophisticated lifestyle. When she engages a butler, Hyppolit, their whole life is turned upside down. It has remained one of the most viewed Hungarian comedies of all time: it is shown regularly and is still extremely popular', 'Steve Sekely', 72, '1931-11-27', 'P', 'hu', 'https://image.tmdb.org/t/p/w500/k3u3KwdYsQyZE6EItJZxsgp5zzw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (812, 'Illicit', 'Ann, a young woman with outrageously advanced ideas, has been living in sin with Dick, her lover, because of her conviction that marriage would destroy their love; but social pressure ends up paying off, so Ann and Dick get married.', 'Archie Mayo', 77, '1931-02-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eo6YfvqgJICwEURzIvXod9utIzJ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (813, 'Indiscreet', 'A young woman jeopardizes the relationship with the man she loves when a no-account from her past shows up.', 'Leo McCarey', 92, '1931-04-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nlRlzLXItc270RwJb5h7re0cDvg.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (814, 'Comradeship', 'At a mine on the shared edge of France and Germany, an underground explosion leads to the entrapment of a group of French miners. In an effort to save the trapped Frenchmen, German miners Wittkopp and Kasper take it upon themselves to traverse a crumbling war tunnel leading down into the mines. Yet, though the workers harbor no political biases against one another, their callous, less tolerant bosses hope to halt this cross-cultural rescue mission.', 'G.W. Pabst', 93, '1931-11-17', 'P', 'de', 'https://image.tmdb.org/t/p/w500/dSGMzPqWQz2IvjvVx0WDD3z7zBF.jpg', 'https://www.youtube.com/watch?v=0yqQLJCDDT0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (815, 'The Last Flight', 'WWI pilots Cary, Shep, Bill, and Francis, traumatized by the devastation of the war, head to Paris instead of home, where they meet the eccentric and wealthy Nikki, who is drawn to Cary. The five friends, tagged by boorish reporter Frink, drink their way from Paris to Lisbon.', 'William Dieterle', 76, '1931-08-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cUxjKqeZCEBJd0vE3CBf8bXUG15.jpg', 'https://www.youtube.com/watch?v=UNWA_pmEEaU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (816, 'The Smiling Lieutenant', 'An amorous lieutenant is forced to marry a socially awkward princess, though he tries to keep his violin-playing girlfriend on the side.', 'Ernst Lubitsch', 89, '1931-08-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6CiCOw0DYgi2Fjn3Bl8O5AAYH17.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (817, 'Limite', 'Adrift in the vast expanse of the ocean, a solitary boat carries three castaways—a man and two women. Stranded and devoid of any glimmer of rescue, they find solace in recounting the tales of their lives to one another. As they delve into their personal narratives, reminiscing about the circumstances that led them to this desolate predicament, they navigate through the depths of three distinct destinies. Bound by the confines of their shared space, every aspect of their existence becomes a boundary, underscoring their plight.', 'Mário Peixoto', 120, '1931-05-17', 'P', 'pt', 'https://image.tmdb.org/t/p/w500/lRx6OsS1PXKs9k6pfUw4DhGkjNZ.jpg', 'https://www.youtube.com/watch?v=We2Dyk9zmDU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (818, 'M', 'In this classic German thriller, Hans Beckert, a serial killer who preys on children, becomes the focus of a massive Berlin police manhunt. Beckert''s heinous crimes are so repellant and disruptive to city life that he is even targeted by others in the seedy underworld network. With both cops and criminals in pursuit, the murderer soon realizes that people are on his trail, sending him into a tense, panicked attempt to escape justice.', 'Fritz Lang', 110, '1931-05-11', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/bTdZk3q2DWpBRnLiaaItKFWOVhI.jpg', 'https://www.youtube.com/watch?v=nsVproWjN6c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (819, 'The Maltese Falcon', 'A lovely dame with dangerous lies employs the services of a private detective, who is quickly caught up in the mystery and intrigue of a statuette known as the Maltese Falcon.', 'Roy Del Ruth', 80, '1931-05-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zpE6gucVjusGXSS4lcSjqIWCeAj.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (820, 'Marius', 'César runs a bar along Marseilles'' port, assisted by his 23-year-old son, Marius. Friends since childhood, Fanny and Marius love each other, but Marius has a secret wanderlust: every ship''s whistle stirs a longing for foreign lands. When M. Panisse seeks Fanny''s hand in marriage and when a departing clipper needs a deckhand, Marius and Fanny must decide who and what they love most. César, with his generous, wise spirit, tries to guide his son.', 'Alexander Korda', 128, '1931-10-09', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/1dpo4ZJ4Sdv9XEUKNRGXvO6gp87.jpg', 'https://www.youtube.com/watch?v=VifNG9c7c04', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (821, 'Le Million', 'Debt-ridden painter Michel is overcome with joy at discovering that he has just won 1 million florins in the Dutch lottery, but almost immediately, he discovers that his softhearted girlfriend, Béatrice, has given away his jacket containing the winning ticket to an elderly petty thief. Soon Michel, Beatrice and Michel''s artistic rival, Prosper, are hurtling through the streets of Paris on the trail of the missing jacket.', 'René Clair', 83, '1931-02-04', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/tNxaR9GBrQVBsGVc5CUxXrUWWxd.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (822, 'The Miracle Woman', 'After an unappreciated minister dies, his daughter loses her faith in God, prompting her to open a phony temple with a con man. Can the love of a blind former aviator restore her faith and happiness?', 'Frank Capra', 90, '1931-07-17', 'K', 'en', 'https://image.tmdb.org/t/p/w500/vwtCXSnl2RhLu9KFtBSbQpAhoqk.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (823, 'Monkey Business', 'Four stowaways get mixed up with gangsters while running riot on an ocean liner.', 'Norman Z. McLeod', 77, '1931-09-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ArzqncdHxfoegpoglvlm9lC4czi.jpg', 'https://www.youtube.com/watch?v=jh-yzc-k54U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (824, 'Mädchen in Uniform', 'A sensitive girl is sent to an all-girls boarding school and develops a romantic attachment to one of her teachers.', 'Carl Froelich, Leontine Sagan', 88, '1931-11-27', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/xCyjsv32kZ3F1BgZqJOEIKCDFiv.jpg', 'https://www.youtube.com/watch?v=uPC7OBgY09Y', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (825, 'Night Nurse', 'Lora Hart manages to land a job in a hospital as a trainee nurse. Upon completion of her training she goes to work as a night nurse for two small children who seem to be very sick, though something much more sinister is going on.', 'William A. Wellman', 72, '1931-07-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hmY6xd0WWKOqad5cMLbzax62wDp.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (826, 'Other Men''s Women', 'The friendship of two working stiff railroad engineers is put to the test when one falls for the other’s wife.', 'William A. Wellman', 70, '1931-01-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nViV5hSzDvnGsow8MIpp5J1idjQ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (827, 'The Phantom of Paris', 'Chéri-Bibi is a world class escape artist, but he cannot escape the false murder charge that is placed on him.', 'John S. Robertson', 74, '1931-09-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mbSSvn5LDaFUHHGlbyLAxVNSwux.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (828, 'Platinum Blonde', 'Ann Schuyler is an upper-crust socialite who bullies her reporter husband into conforming to her highfalutin ways. The husband chafes at the confinement of high society, though, and yearns for a creative outlet. He decides to write a play and collaborates with a fellow reporter.', 'Frank Capra', 89, '1931-10-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/nlVEC1fvzW2bKKt6gXTON7LyNEZ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (829, 'Possessed', 'Marion is a factory worker who hopes to trade the assembly line for a beautiful penthouse apartment. Mark Whitney, a wealthy and influential lawyer, can make her dreams come true, but, there is only one problem; he will give her everything except a marriage proposal. Will this affair ever lead to marriage?', 'Clarence Brown', 76, '1931-11-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qrTMfXVNzC6oSUU46hGDLLA8I3p.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (830, 'Private Lives', 'Amanda and Elyot are one another''s former spouse. Elyot is remarried to Sibyl and Amanda married Victor. Unexpectedly, both honeymooning couples arrive at a hotel on the same day and are put in rooms with adjoining terraces. Things go well until Amanda sees Elyot on the adjacent terrace.', 'Sidney Franklin', 84, '1931-12-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3A6UrOdi8Xll5Cn0GiWwtgWgFjz.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (831, 'The Public Enemy', 'Two young Chicago hoodlums, Tom Powers and Matt Doyle, rise up from their poverty-stricken slum life to become petty thieves, bootleggers and cold-blooded killers. But with street notoriety and newfound wealth, the duo feels the heat from the cops and rival gangsters both. Despite his ruthless criminal reputation, Tom tries to remain connected to his family, however, gang warfare and the need for revenge eventually pull him away.', 'William A. Wellman', 84, '1931-04-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vVxdaRMprQO2DM4AFyJ6C4qZSFO.jpg', 'https://www.youtube.com/watch?v=ECEcNXe4x8w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (832, 'Safe in Hell', 'To avoid the rigors of the law, Gilda flees New Orleans and hides on a Caribbean island where the worst criminals can ask for asylum. Besieged by the scum of the earth, Gilda will soon find out that she has found refuge in hell.', 'William A. Wellman', 71, '1931-12-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/y2LfGVBCABX4Lx2Ufr39FtfgDfW.jpg', 'https://www.youtube.com/watch?v=SaPKnbXKQTs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (833, 'The Secret Six', 'Bootlegger/cafe owner, Johnny Franks recruits crude working man Scorpio to join his gang, masterminded by crooked criminal defense lawyer Newton. Scorpio eventually takes over Frank''s operation, beats a rival gang, becomes wealthy, and dominates the city for several years until a secret group of six masked businessmen have him prosecuted and sent to the electric chair.', 'George W. Hill', 83, '1931-04-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/67dWQ7G6uER6D5c8TT724FX7SlK.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (834, 'The Sin of Madelon Claudet', 'Out of jail for a crime she did not commit, Madelon turns to prostitution and thievery to send her illegitimate son to medical school.', 'Edgar Selwyn', 75, '1931-10-23', 'K', 'en', 'https://image.tmdb.org/t/p/w500/nr3dzgku0NqqwQntJxS5YcyUwVL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (835, 'The Skin Game', 'An old traditional family and a modern family battle over land in a small English village.', 'Alfred Hitchcock', 82, '1931-02-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/toLLyYTaAvQyLIvpAu8UeQ0sqOL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (836, 'Smart Money', 'Two brothers'' trip to the big city to do a little gambling results in a fateful turn of events.', 'Alfred E. Green', 81, '1931-06-11', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2KnQNZSnle6xxAF1K846byLZ63J.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (837, 'Street Scene', 'The setting is a city block during a sweltering summer, where the residents serve as representatives of the not-very-idealized American melting pot. There is idle chitchat, gossip, jealousy, racism, adultery, and suddenly but not unexpectedly, a murder.', 'King Vidor', 78, '1931-09-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/x80hXmYooG76fm37j0rQkw3q4Ct.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (838, 'Susan Lenox', 'A young woman runs away from an abusive home and pre-arranged marriage only to be frustrated in her attempts to find happiness with a handsome engineer.', 'Robert Z. Leonard', 76, '1931-10-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s8ZUAkn7BslZc4lYbhE2rP820Xn.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (839, 'Svengali', 'A music maestro uses hypnotism on a young model he meets in Paris to make her both his muse and wife.', 'Archie Mayo', 81, '1931-05-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jLE87vAc9bqytSZAfU76MmnQdMh.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (840, 'Tabu: A Story of the South Seas', 'On the South Pacific island of Bora Bora, a young couple''s love is threatened when the tribal chief declares the girl a sacred virgin.', 'F. W. Murnau', 86, '1931-07-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/c4zfawkB8Jsp5lhWl62QCzczR3M.jpg', 'https://www.youtube.com/watch?v=BmHQjE_YCGw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (841, 'Ten Cents a Dance', 'A taxi dancer with a jealous husband finds herself falling for a wealthy client.', 'Lionel Barrymore', 77, '1931-01-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/d1oWSFU9YpgLbXU8EjftHoEBQFF.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (842, 'Tokyo Chorus', 'During the Depression, a young man struggles to provide for his family after he is sacked for defending an older colleague.', 'Yasujirō Ozu', 91, '1931-08-15', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/koagfZhAbaphDG4nkFbzw0Axo0i.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (843, 'Tonight or Never', 'A young opera singer finds her career stalled because of her cold and passionless performances, until she finds romance with a handsome admirer.', 'Mervyn LeRoy', 80, '1931-01-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vOHkTjJWiW0kgSe2PBvvG2raC6D.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (844, 'Trader Horn', 'While on safari in an unexplored area of Africa, Trader Horn and Peru find missionary Edith Trent killed by natives. They decide to carry on her quest for her lost daughter Nina. They find her as the queen of a particularly savage tribe, and try to bring her back to civilization.', 'W.S. Van Dyke', 122, '1931-02-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rBzzjMMOXUKWglfGsSZDxIbavjk.jpg', 'https://www.youtube.com/watch?v=m6307hyF4NA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (845, 'Waterloo Bridge', 'In WWI London, out-of-work American chorus girl Myra makes ends meet by picking up men on Waterloo Bridge. During a Zeppelin air raid, she meets Roy, a naive young Yank who enlisted in the Canadian army. After they fall for each other, Roy tricks Myra into visiting his family, who live in a country estate outside London, his mother having remarried to a retired British Major. Myra is reluctant to continue the relationship with Roy, he not aware of her past.', 'James Whale', 81, '1931-09-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pHzA3gHKl63gkwOqghlcZQMwrhL.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (846, 'À Nous la Liberté', 'In this classic French satire, Louis, a convict, escapes from prison and takes on legitimate work, making his way up in the business world. Eventually becoming the head of a successful factory, Louis opts to modernize his company with mechanical innovations. But when his friend Émile finally leaves jail years later and reunites with Louis, the past catches up with them. The two, worried about being apprehended by police, long to flee the confines of industry.', 'René Clair', 95, '1931-12-18', 'K', 'fr', 'https://image.tmdb.org/t/p/w500/z6XdIxE1CRqSgfOJxX1nGik6CGm.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (847, 'American Madness', 'Socially-conscious banker Thomas Dickson faces a crisis when his protégé is wrongly accused of robbing the bank, gossip of the robbery starts a bank run, and evidence suggests Dickson''s wife had an affair... all in the same day.', 'Frank Capra', 76, '1932-08-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mKMrLe7SXLjDaFqdAmcuGXM1HHD.jpg', 'https://www.youtube.com/watch?v=0_BtIFlTtPA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (848, 'The Animal Kingdom', 'Tom Collier has had a great relationship with Daisy, but when he decides to marry, it is not Daisy whom he asks, it is Cecelia. After the marriage, Tom is bored with the social scene and the obligations of his life. He publishes books that will sell, not books that he wants to write. Even worse, he has his old friend working as a butler and Cecelia wants him fired. When Tom tries to get back together with Daisy to renew the feelings that he once felt, Daisy turns the tables on him and leaves to protect both of them.', 'Edward H. Griffith', 85, '1932-12-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/nONPUIWAj2UtuZOmBvPtOEfVozk.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (849, 'Arsène Lupin', 'A charming and very daring thief known as Arsene Lupin is terrorizing the wealthy of Paris. He even goes so far as to threaten the Mona Lisa. But the police, led by the great Guerchard, think they know Arsene Lupin''s identity, and they have a secret weapon to catch him.', 'Jack Conway', 84, '1932-02-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zmN5X4wM9DcMoiIMMfDxX8eoqbP.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (850, 'Back Street', 'A woman''s love for and devotion to a married man results in her being relegated to the "back streets" of his life.', 'John M. Stahl', 93, '1932-08-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kj74LmtNkIBpoLDHOq5Crmvc2eq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (851, 'The Beast of the City', 'Police Chief Jim Fitzpatrick is after gangster Sam Belmonte. He uses his police detective brother Ed to watch over Daisy who is associated with Belmonte but things don''t go as planned.', 'Charles Brabin', 86, '1932-02-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/j7yvH2ngnLrM0yjRMJ3Yh8mk8VS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (852, 'A Bill of Divorcement', 'A World War I veteran returns home after fifteen years in an asylum and finds that everything has changed — his daughter is grown and about to marry.', 'George Cukor', 70, '1932-09-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fHop0zEy6bdhmar8xckZWxWLXlc.jpg', 'https://www.youtube.com/watch?v=dUWvmCD7Pso', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (853, 'Bird of Paradise', 'When a young South Seas sailor falls overboard, the beautiful daughter of a Polynesian king dives in and saves his life. Thus begins the romance of Johnny and Luana. Though Luana is promised to another man, Johnny whisks her away, and for a brief time the lovers live very happily together. But, when a local volcano threatens their lives, Luana knows that she must sacrifice herself to the volcanic gods in order to save her island.', 'King Vidor', 80, '1932-08-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/n2vjVQ1Y3m0LBTm59bYm1NfclqW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (854, 'The Blue Light', 'Junta is hated by the people in the village where she lives, especially by the women, who suspect her of being a witch. Only she can climb the nearby mountains to a cave high up, whence a mysterious blue light glows when the moon is full. Many young men of the village have died trying to follow her. She is driven out of town, and takes to living in the mountains. Eventually she shares the secret of the blue light with one man, and he betrays it.', 'Leni Riefenstahl', 83, '1932-03-24', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/n3rEqnaZxL7gR44g5N9khdcgzCJ.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (855, 'Blonde Venus', 'In an effort to be able to afford expensive treatment for her gravely ill American husband, a retired German entertainer returns to the cabaret as Blonde Venus and catches the eye of a wealthy politician.', 'Josef von Sternberg', 93, '1932-09-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fC2KsO3vVCSgBR5f29resfAmgVF.jpg', 'https://www.youtube.com/watch?v=VKas4aaFgJk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (856, 'Blondie of the Follies', 'New York City tenement dwelling neighbors Blondie and Lottie are longtime best friends. When Lottie makes the cast of the Follies and moves up in the world, she arranges for Blondie, as well, to join the cast and gain the advantages. But the friendship goes awry when Lottie''s sweetheart, wealthy Larry Belmont, falls for Blondie and she for him.', 'Edmund Goulding', 91, '1932-09-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6eT7ELpyc05KJwS3a2kmmTwAlMh.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (857, 'Boudu Saved from Drowning', 'Michel Simon gives one of the most memorable performances in screen history as Boudu, a Parisian tramp who takes a suicidal plunge into the Seine and is rescued by a well-to-do bookseller, Edouard Lestingois. The Lestingois family decides to take in the irrepressible bum, and he shows his gratitude by shaking the household to its foundations. With Boudu Saved from Drowning, legendary director Jean Renoir takes advantage of a host of Parisian locations and the anarchic charms of his lead actor to create an effervescent satire of the bourgeoisie.', 'Jean Renoir', 84, '1932-11-11', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/hCRUtli9TCrekxSysHJ15QhMk44.jpg', 'https://www.youtube.com/watch?v=etAwZ9ZILAQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (858, 'Broken Lullaby', 'A young French soldier in World War I is overcome with guilt when he kills a German soldier who, like himself, is a musically gifted conscript, each having attended the same musical conservatory in France. The fact that the incident occurred in war does not assuage his guilt. He travels to Germany to meet the man''s family.', 'Ernst Lubitsch', 76, '1932-01-24', 'K', 'en', 'https://image.tmdb.org/t/p/w500/zYZjUEPC0j96rNfGj0dHajLMw5t.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (859, 'The Cabin in the Cotton', 'Sharecropper''s son Marvin tries to help his community overcome poverty and ignorance.', 'Michael Curtiz', 78, '1932-09-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hfjPvRk899cGswfTXPpW7dWVolW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (860, 'Call Her Savage', 'A high-spirited and short-tempered Texan woman storms her way through life until her luck runs out, forcing her to learn the error of her ways.', 'John Francis Dillon', 88, '1932-11-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/817TDYCmdxN0TVuiGoXHiHwnRLr.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (861, 'Chandu the Magician', 'When delusional madman Roxor kidnaps a scientist in hopes of using his death ray to achieve world dominance, he is opposed by Chandu, a powerful hypnotist and yogi.', 'Marcel Varnel, William Cameron Menzies', 71, '1932-08-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3pYOJPXdRLVjEh60OzhuBJqMutb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (862, 'Frisco Jenny', 'Jenny is carrying the child of a young man who dies in the San Francisco earthquake (1906). After giving birth, she decides to place her child in the custody of a wealthy married couple. Years later, thanks to the protection of a corrupt politician, she becomes the main "madame" of San Francisco, in addition to participating in various illegal activities.', 'William A. Wellman', 71, '1933-01-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/akye9O1aMeMlh9DS9c2ZUACPeaW.jpg', 'https://www.youtube.com/watch?v=DY2OgiPyt10', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (863, 'Wooden Crosses', 'The young and patriotic student Demachy joins the French army in 1914 to defend his country. But he and his comrades soon experience the terrifying, endless trench war in Champagne, where more and more wooden crosses have to be erected for this cannon fodder.', 'Raymond Bernard', 110, '1932-03-17', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/lcIwbiZn57HR9xpQD1U8pUC0PBJ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (864, 'The Crowd Roars', 'Famous auto racing champion Joe Greer returns to his hometown to compete in a local race, discovering that his younger brother has aspirations to become a racing champion.', 'Howard Hawks', 85, '1932-04-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/o8uxqjQuAIZ4PbBkdqtEmC7pGBf.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (865, 'The Dark Horse', 'The Progressive Party convention is deadlocked for governor, so both sides nominate the dark horse Zachary Hicks. Kay Russell suggests they hire Hal Blake as campaign manager; but first they have to get him out of jail for not paying alimony. Blake organizes the office and coaches Hicks to answer every question by pausing and then saying, "Well yes, but then again no." Blake will sell Hicks as dumb but honest. Russell refuses to marry Blake, while Joe keeps people away from Blake''s office. Blake teaches Hicks a speech by Lincoln. At the debate when the conservative candidate Underwood recites the same speech, Blake exposes him as a plagiarist. Hicks is presented for photo opportunities and gives his yes-and-no answer to any question, including whether he expects to win.', 'Alfred E. Green', 75, '1932-06-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/k9Kny1v2btbtBj8QAGZHOZC4dy4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (866, 'Doctor X', 'A wisecracking New York reporter intrudes on a research scientist''s quest to unmask The Moon Killer.', 'Michael Curtiz', 76, '1932-08-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/z8hlncTkxO58t5KAvNRTXnm29Ii.jpg', 'https://www.youtube.com/watch?v=gu2KEKMP58c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (867, 'Downstairs', 'In the Austrian manor of Baron and Baroness von Burgen, the relationship between the upstairs aristocracy and the downstairs staff is quite positive. The servants seem to enjoy their time together, and some even fall in love, as head butler Albert and maid Anna have done. But when lecherous new chauffeur Karl Schneider enters the house, affairs and blackmail follow, and the harmony of the home is slowly destroyed.', 'Monta Bell', 77, '1932-08-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1irNBBQiipoMwvDYhj5uhWMQApF.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (868, 'Dr. Jekyll and Mr. Hyde', 'Dr. Henry Jekyll believes that there are two distinct sides to men: one that is good and one that is evil. He believes that by separating the two, man can become liberated. He succeeds in his experiments with chemicals to accomplish this and transforms into Hyde to commit horrendous crimes. When he discontinues use of the drug, it is already too late.', 'Rouben Mamoulian', 96, '1931-12-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mZtQORzQWkCSqeeHApH6vJDA1D2.jpg', 'https://www.youtube.com/watch?v=CReiffsq5Bk', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (869, 'Emma', 'After decades of raising the motherless Smith children, housekeeper Emma Thatcher is faced with resentment when she marries their father.', 'Clarence Brown', 72, '1932-01-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kwOOi0dMKsbPqjMwyBoT76FclCi.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (870, 'Ecstasy', 'Eva has just gotten married to an older gentleman, but discovers that he is obsessed with order in his life and doesn''t have much room for passion. She becomes despondent and leaves him, returning to her father''s house. One day while bathing in the lake, she meets a young man and they fall in love. The husband has become grief stricken at the loss of his young bride, and fate brings him together with the young lover that has taken Eva from him.', 'Gustav Machatý', 89, '1933-01-20', 'K', 'cs', 'https://image.tmdb.org/t/p/w500/nwCNnXnw0iYsMdWqp4qyGrzHTh0.jpg', 'https://www.youtube.com/watch?v=-0JsWm_AC1E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (871, 'Fanny', 'Soon after Marius''s departure, Fanny learns that she is pregnant with his child, to the disappointment of her mother and of Marius''s father, César. To secure a better life for her unborn child, she accepts a marriage proposal from the aging widower Honoré Panisse.', 'Marc Allégret', 127, '1932-10-27', 'P', 'fr', 'https://image.tmdb.org/t/p/w500/8hY9A0mWwVXhgdV1S2YKxSp1ruS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (872, 'A Farewell to Arms', 'A tale of the World War I love affair, begun in Italy, between American ambulance driver Lt. Frederic Henry and British nurse Catherine Barkley. Eventually separated by Frederic''s transfer, tremendous challenges and difficult decisions face each as the war rages on.', 'Frank Borzage', 89, '1932-12-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eNmPByGZJqlp60nCZRhsAlVAb3F.jpg', 'https://www.youtube.com/watch?v=KT1RIeg5WL0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (873, 'Forbidden', 'On a cruise to Cuba, Lulu Smith falls in love with Bob Grover. Back home, she breaks off the romance when he tells her he is married. Lulu has a baby but doesn''t tell Bob, who turns out to be a rising politician. She passes herself off as the baby''s nanny. When Bob learns what is going on, he adopts the little girl, not telling his wife or anyone else where she came from. Lulu gets a job at a newspaper. Things get complicated when the editor gets the dirt on Bob, but also wants to marry Lulu.', 'Frank Capra', 85, '1932-01-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nBUDSm2r6UvFXGjMiGSMnPmTEFw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (874, 'Freaks', 'A circus'' beautiful trapeze artist agrees to marry the leader of side-show performers, but his deformed friends discover she is only marrying him for his inheritance.', 'Tod Browning', 64, '1932-01-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fX2Wxd0W9E7eVClUd8kJTfennoV.jpg', 'https://www.youtube.com/watch?v=681Ii7g9Ln4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (875, 'Grand Hotel', 'Guests at a posh Berlin hotel struggle through worry, scandal, and heartache.', 'Edmund Goulding', 112, '1932-09-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/g8xrpXJWzz91R4jL8ybMKMValB2.jpg', 'https://www.youtube.com/watch?v=QFBKK8uaPww', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (876, 'Hell''s House', 'A teenager lands in a brutal reform school for refusing to squeal on his bootlegger boss.', 'Howard Higgin', 72, '1932-01-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xQLiQVUV4SKmKZHS9C0kXYgJz6J.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (877, 'Horse Feathers', 'Quincy Adams Wagstaff, the new president of Huxley U, hires bumblers Baravelli and Pinky to help his school win the big football game against rival Darwin U.', 'Norman Z. McLeod', 68, '1932-08-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sndzhGYShAcSf3AaYGfiwl4YbgS.jpg', 'https://www.youtube.com/watch?v=1RZ6csU7DYY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (878, 'Hot Saturday', 'A pretty but virtuous small-town bank clerk is the victim of a vicious rumor from an unsuccessful suitor that she spent the night with a notorious womanizer.', 'William A. Seiter', 73, '1932-10-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ItvxwGzzA3WZgb3MBRzO8zNRRJ.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (879, 'I Am a Fugitive from a Chain Gang', 'A World War I veteran’s dreams of becoming a master architect evaporate in the cold light of economic realities. Things get even worse when he’s falsely convicted of a crime and sent to work on a chain gang.', 'Mervyn LeRoy', 92, '1932-11-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jer6lim61i8V6a5HOZq2i07UQQf.jpg', 'https://www.youtube.com/watch?v=24R9vDcviKQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (880, 'If I Had a Million', 'An elderly business tycoon, believed to be dying, decides to give a million dollars each to eight strangers chosen at random from the phone directory.', 'Ernst Lubitsch, H. Bruce Humberstone, James Cruze, Norman Taurog, Norman Z. McLeod, Stephen Roberts, William A. Seiter', 88, '1932-11-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qHFusV8b94ayRPrEEfWKuo3jNCE.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (881, 'Jewel Robbery', 'Baroness Teri von Horhenfels deals with the tedium of her aristocratic Vienna life with a long line of lovers. Her rich husband, Franz, seems oblivious. As she''s just about to end her latest affair, the baroness gets a much-needed dose of adrenaline when she becomes the target of a charismatic thief. After staging a daring robbery, he makes off with not only the baroness''s ring but also her heart.', 'William Dieterle', 68, '1932-07-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wVMMFJ6Z2TXmWvQGxjNXRMl3p3H.jpg', 'https://www.youtube.com/watch?v=oicmvvec4q8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (882, 'Kongo', 'The ruthless Flint, a disabled man, rules an isolated region of Kongo like an omnipotent god, through superstition and sadism, living only for the day when he can get revenge on the man who ruined his life.', 'William J. Cowen', 87, '1932-10-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4mDntFmBDmQGLjKW21oIfrxFOst.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (883, 'Lawyer Man', 'Idealistic attorney Anton Adam makes headlines when he successfully prosecutes prominent New York City political party boss John Gilmurry. Adam''s sudden renown attracts the attention of high-profile legal eagle Granville Bentley, who asks Adam to become a partner in his firm. But Adam''s rising career nosedives when he''s framed by corrupt Dr. Gresham and a sexy actress in a trumped-up breach of promise suit. The only constant in Adam''s life is the loyalty and unrequited love of his secretary, Olga.', 'William Dieterle', 68, '1932-12-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/czEj1dT5yWtlJp09pfbE8RMMmrS.jpg', 'https://www.youtube.com/watch?v=hGNL12M04KI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (884, 'Love Me Tonight', 'A Parisian tailor goes to a château to collect a bill, only to fall for an aloof young princess living there.', 'Rouben Mamoulian', 89, '1932-08-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3wjHj3LmmezUsBHxFL8xpRdMxVX.jpg', 'https://www.youtube.com/watch?v=go_hj2t_zAY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (885, 'The Man Who Played God', 'While giving a private performance for a visiting monarch, concert pianist Montgomery Royle is deafened when a bomb is detonated in an attempt to assassinate the foreign ruler. With his career over as a result of his injury, Royle returns to New York City with his sister Florence, close friend Mildred Miller, and considerably younger fiancée Grace Blair. After abandoning thoughts of suicide, Montgomery discovers he can lip read, and he spends his days observing people in Central Park from his apartment window. As he learns of people''s problems, he tries to help them anonymously and becomes absorbed in his game of "playing God".', 'John G. Adolfi', 80, '1932-02-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wmhTcgjpsRvl5ft4ryMSGuoCHTu.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (886, 'The Mask of Fu Manchu', 'The villainous Dr. Fu Manchu races against a team of Englishmen to find the tomb of Ghengis Khan, because he wants to use the relics to cause an uprising in the East to wipe out the white race.', 'Charles Brabin', 68, '1932-11-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4iMjZwxFGxlF0RkfSAzgn6iTUb3.jpg', 'https://www.youtube.com/watch?v=d0ING5qhUnE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (887, 'Mata Hari', 'A semi-fictionalized account of the life of Mata Hari, an exotic dancer who was accused of spying for Germany during World War I.', 'George Fitzmaurice', 89, '1931-12-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3HvUY98WbP1HuIFk8W3f1gDLKZX.jpg', 'https://www.youtube.com/watch?v=THUQX8QvocQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (888, 'Me and My Gal', 'Jaunty young policeman Danny Dolan falls in love with waterfront cafe waitress Helen Riley.', 'Raoul Walsh', 79, '1932-12-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pAPxl1vECf3hmyX1W4juWd2Fzil.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (889, 'Merrily We Go to Hell', 'A drunken newspaperman, Jerry Corbett, is rescued from his alcoholic haze by an heiress, Joan Prentice, whose love sobers him up and encourages him to write a play, but he lapses back into dipsomania.', 'Dorothy Arzner', 83, '1932-06-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kSwYDEtFhPXYuyIO3WxpzfusTIA.jpg', 'https://www.youtube.com/watch?v=ulcSW8VAVPc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (890, 'Million Dollar Legs', 'A small country on the verge of bankruptcy is persuaded to enter the 1932 Los Angeles Olympics as a means of raising money.', 'Edward F. Cline', 64, '1932-07-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/atqRmaEd22UZe78RWh0Sd00XoSX.jpg', 'https://www.youtube.com/watch?v=7Ni39WXW6uI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (891, 'The Monster Walks', 'Ruth Earlton has come home to her ancestral mansion to claim her inheritance. Accompanied by her boyfriend, she discovers that her father died suddenly under suspicious circumstances. Now it''s her turn, as her deranged and relentless uncle targets her for death with the help of his wife and son, plus a very unhappy ape.', 'Frank R. Strayer', 60, '1932-02-07', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/c2MEDsZHT2zYCTXnYbsL2JyfWKO.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (892, 'The Most Dangerous Game', 'When legendary hunter Bob Rainsford is shipwrecked on the perilous reefs surrounding a mysterious island, he finds himself the guest of the reclusive and eccentric Count Zaroff. While he is very gracious at first, Zaroff eventually forces Rainsford and two other shipwreck survivors, brother and sister Eve and Martin Towbridge, to participate in a sadistic game of cat and mouse in which they are the prey and he is the hunter.', 'Ernest B. Schoedsack, Irving Pichel', 63, '1932-09-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3aNlOIFlGOnIzxqvAWpgm5Sly1H.jpg', 'https://www.youtube.com/watch?v=DoHUfQKA_sc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (893, 'Movie Crazy', 'After a mix-up with his application photograph, an aspiring actor is invited to a screen test and goes off to Hollywood.', 'Clyde Bruckman', 96, '1932-09-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9iqQodSzndRx2MAnJ3xe6N1fjsh.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (894, 'The Mummy', 'An ancient Egyptian priest named Imhotep is revived when a British archaeological expedition finds his mummy and one of the researchers accidentally reads an ancient life-giving spell. Imhotep escapes from the field site and searches for the reincarnation of the soul of his lover.', 'Karl Freund', 73, '1932-12-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/vSKpbZVvzqQcw6htiyEinbCY9vq.jpg', 'https://www.youtube.com/watch?v=5eLN8ve_Eoc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (895, 'Murders in the Rue Morgue', 'In 19th century Paris, a maniac abducts young women and injects them with ape blood in an attempt to prove ape-human kinship but constantly meets failure as the abducted women die.', 'Robert Florey', 61, '1932-01-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vd7APCDkYTL0ZpNc88XB1uEYCQx.jpg', 'https://www.youtube.com/watch?v=W3ONG8qFw_4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (896, 'Night After Night', 'A successful ex-boxer opens a high-class speakeasy in what once was the childhood home of a formerly rich society girl.', 'Archie Mayo', 73, '1932-10-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zXp66XqUpqDWBcdBesQ6CVZOpyc.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (897, 'No Man of Her Own', 'An on-the-lam New York card shark marries a small-town librarian who thinks he''s a businessman.', 'Wesley Ruggles', 85, '1932-12-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zLaI6pxeXBQAI2JroGC2faPuD4T.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (898, 'Number Seventeen', 'A gang of jewel thieves hides out in an abandoned London house after a robbery, unaware that a detective is among them in disguise.', 'Alfred Hitchcock', 63, '1932-07-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rie7xUzlxMHNDmaQSLatkoZn3jf.jpg', 'https://www.youtube.com/watch?v=_1In3eSTomc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (899, 'The Old Dark House', 'In a remote region of Wales, five travelers beset by a relentless storm find shelter in an old mansion.', 'James Whale', 70, '1932-10-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/t4058MoAiVg8R1aqHNL3nAP48km.jpg', 'https://www.youtube.com/watch?v=06RuAO980U4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (900, 'One Hour with You', 'Andre and Colette Bertier are happily married. When Colette introduces her husband to her flirtatious best friend, Mitzi, he does his best to resist her advances. But she is persistent, and very cute, and he succumbs. Mitzi''s husband wants to divorce her, and has been having her tailed. Andre gets caught, and must confess to his wife. But Colette has had problems resisting the attentions of another man herself, and they forgive each other.', 'Ernst Lubitsch', 80, '1932-03-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oVDJZXwHKD0NgHaHZrkHuqHsJyF.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (901, 'One Way Passage', 'A terminally ill woman and a debonair murderer facing execution meet and fall in love on a trans-Pacific crossing, each without knowing the other''s secret.', 'Tay Garnett', 68, '1932-10-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/c3FRmz3VTtvlmmNBJ7l8ILO0zzD.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (902, 'Pack Up Your Troubles', 'The story begins in 1917 with Stan and Ollie being drafted into the U.S. Army to fight in World War I. While in the Army, the pair befriend a man named Eddie Smith, who is killed by the enemy during a battle. After the war is over, Stan and Ollie venture to New York City, where they begin a quest to reunite Eddie''s little daughter with her rightful family. The task proves both monumental and problematic as the boys discover just how many people in New York have the last name Smith.', 'George Marshall, Ray McCarey', 68, '1932-09-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1nfi4YmKSHn974CDd5VxOtPYOLU.jpg', 'https://www.youtube.com/watch?v=_VkXBsYDfFk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (903, 'The Penguin Pool Murder', 'New York schoolmarm Hildegarde Withers assists a detective when a body of unscrupulous stockbroker Gerald Parker suddenly appears in the penguin tank at the aquarium.', 'George Archainbaud', 70, '1932-12-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5JsNPCnbNjxYDLh9t1eXgZGnHB4.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (904, 'Polly of the Circus', 'When Polly Fisher, a circus aerialist, is hurt while performing, she is taken to the house of a nearby minister, John Hartley. As she recuperates, they fall in love with each other and secretly marry. But when the truth leaks out , John''s congregation rebels at having a circus woman as their minister''s wife, and he is fired. Polly decides to leave John in hopes of giving back to him the calling that means so much to him. But fate steps in and rearranges all plans.', 'Alfred Santell', 69, '1932-02-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uQhm7knOh0XF9IkO95ZGHsE1Ged.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (905, 'The Purchase Price', 'Nightclub singer Joan Gordon runs away from her gangster boyfriend to become a mail-order bride to a struggling North Dakota farmer. Their relationship has a rocky start, but just as Joan realizes she''s developing feelings for her husband, her old boyfriend arrives to win her back.', 'William A. Wellman', 68, '1932-07-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/oWQ59z6PoTyzFVX6GfQLvH42Iq.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (906, 'Rain', 'Due to a possible cholera epidemic onboard, passengers on a ship are forced to disembark at Pago Pago, a small village on a Pacific island where it incessantly rains. Among the stranded passengers are Sadie Thompson, a prostitute, and Alfred Davidson, a fanatic missionary who will try to redeem her.', 'Lewis Milestone', 94, '1932-10-12', 'K', 'en', 'https://image.tmdb.org/t/p/w500/loiZCnkxAiSDyFmCAsUoTm62CAb.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (907, 'Rasputin and the Empress', 'The story of corrupt, power-hungry, manipulative Grigori Rasputin''s influence on members of the Russian Imperial family and others, and what resulted.', 'Richard Boleslawski', 121, '1932-12-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/txLqNjctfiVbCyxIKa261W5tz70.jpg', 'https://www.youtube.com/watch?v=8ka57eClzIY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (908, 'Red Dust', 'Dennis, owner of a rubber plantation in Cochinchina, is involved with Vantine, who left Saigon to evade the police. When his new surveyor arrives along with his refined wife Dennis is quickly infatuated by her.', 'Victor Fleming', 83, '1932-10-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/laHlMLtR1SyKoOhWmQG5aLHflJa.jpg', 'https://www.youtube.com/watch?v=gpEj0mOHSLQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (909, 'Red-Headed Woman', 'Lil works for the Legendre Company and causes Bill to divorce Irene and marry her. She has an affair with businessman Gaerste and uses him to force society to pay attention to her.', 'Jack Conway', 79, '1932-06-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3Iv5sY7qWljRFEHQ3qsgRetIboC.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (910, 'The Rich Are Always with Us', 'A wealthy couple''s marriage is falling apart due to the man''s infidelity. The wife''s male friend has long loved her and sees his big opportunity.', 'Alfred E. Green', 71, '1932-05-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/n7Mgtli5R9OQku7NZf1judTmDCE.jpg', 'https://www.youtube.com/watch?v=BHxPypMBpy4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (911, 'Rich and Strange', 'After receiving an advance inheritance, a bored London couple set off on a world cruise hoping to rejuvenate their marriage and escape their dull routine. But newfound wealth and freedom only expose deeper cracks in their relationship, as each becomes infatuated with someone else. Their journey through exotic ports and mounting disillusionment ultimately brings them face to face with the fragility—and resilience—of love.', 'Alfred Hitchcock', 83, '1931-12-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8uELURwfZlQBsy26VUk7ap0v3ZS.jpg', 'https://www.youtube.com/watch?v=0SoJL6G8Ai8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (912, 'Scarface', 'In 1920s Chicago, Italian immigrant and notorious thug, Antonio ''Tony'' Camonte, aka Scarface, shoots his way to the top of the mobs while trying to protect his sister from the criminal life.', 'Howard Hawks', 93, '1932-04-09', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/y4E5oRiHMTFkEB12IIcpbKbKzDW.jpg', 'https://www.youtube.com/watch?v=XRmWftEjit0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (913, 'Shanghai Express', 'A beautiful temptress re-kindles an old romance while trying to escape her past during a tension-packed train journey.', 'Josef von Sternberg', 82, '1932-02-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/z0ea6xM3HhIZi7zApDVsxewv9R8.jpg', 'https://www.youtube.com/watch?v=i86Hc6AAVt4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (914, 'Shopworn', 'A waitress falls for a wealthy young man but has to fight his mother to find happiness.', 'Nick Grindé', 66, '1932-03-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/p0dOmUGunUBbOtobAkwHZTNm87J.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (915, 'The Sign of the Cross', 'A Roman soldier becomes torn between his love for a Christian woman and his loyalty to Emperor Nero.', 'Cecil B. DeMille', 126, '1932-12-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qJdANRQy3BkTJGxXXHKMVoUigSD.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (916, 'Smilin'' Through', 'On the day of his wedding, Sir John Carteret''s fiancée, Moonyeen, is killed by a jealous rival named Jeremy, leaving him emotionally devastated. Carteret spends three decades in seclusion, mostly communing with the spirit of Moonyeen, until he learns that her niece, Kathleen, has become an orphan. He adopts and raises the child as his own but is alarmed when, as a young woman, she falls in love with the son of Moonyeen''s murderer.', 'Sidney Franklin', 98, '1932-09-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aq0rbICU0lGFQlCYMLJwV0iolPv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (917, 'So Big!', 'A farmer''s widow takes on the land and her late husband''s tempestuous son.', 'William A. Wellman', 81, '1932-04-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/41SiOxy1lIRGVOQgL2tzsno0dhA.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (918, 'Speak Easily', 'A professor gets mixed up with chorus girls in a Broadway musical.', 'Edward Sedgwick', 81, '1932-08-13', 'K', 'en', 'https://image.tmdb.org/t/p/w500/pWVjJr90gKkt50omskSlT3t0Emy.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (919, 'Tarzan the Ape Man', 'James Parker and Harry Holt are on an expedition in Africa in search of the elephant burial grounds that will provide enough ivory to make them rich. Parker''s beautiful daughter Jane arrives unexpectedly to join them. Jane is terrified when Tarzan and his ape friends abduct her, but when she returns to her father''s expedition she has second thoughts about leaving Tarzan.', 'W.S. Van Dyke', 100, '1932-03-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4n6VfSDMN9ylv5JNAb19qVGN1Hf.jpg', 'https://www.youtube.com/watch?v=lIoPPD0NKhA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (920, 'Taxi!', 'Amidst a backdrop of growing violence and intimidation, independent cab drivers struggling against a consolidated juggernaut rally around hot-tempered Matt Nolan. Nolan is determined to keep competition alive on the streets, even if it means losing the woman he loves.', 'Roy Del Ruth', 69, '1932-01-23', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4S2teUultfRWlJxpa0fRXsW7mPF.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (921, 'The Testament of Dr. Mabuse', 'After a detective is assaulted by thugs and placed in an asylum run by Professor Baum, he observes the professor''s preoccupation with another patient, the criminal genius Dr. Mabuse the hypnotist. When Mabuse''s notes are found to be connected with a rash of recent crimes, Commissioner Lohmann must determine how Mabuse is communicating with the criminals, despite conflicting reports on the doctor''s whereabouts, and capture him for good.', 'Fritz Lang', 122, '1933-04-21', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/tc2ET7j6X066VCjdHblSwLr8sEz.jpg', 'https://www.youtube.com/watch?v=IEEjeviFMeY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (922, 'Thirteen Women', 'Thirteen women who were schoolmates ask a swami to cast their horoscopes. The news they receive is not good for any of them.', 'George Archainbaud', 59, '1932-09-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jLNBQpb3X3UtWWr6qw7q3WD4X2d.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (923, 'Three on a Match', 'Although Vivian Revere is seemingly the most successful of a trio of reunited schoolmates, she throws it away by descending into a life of debauchery and drugs.', 'Mervyn LeRoy', 63, '1932-10-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rgx6zwUzi4jZyXaB0Hg8dKx47Qp.jpg', 'https://www.youtube.com/watch?v=yQUvX0FrFhA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (924, 'Tiger Shark', 'A Portuguese tuna fisherman catches his bride with his first mate.', 'Howard Hawks', 77, '1932-09-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hBnxEG4HCVqtScs6Ew8UrHMMzlj.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (925, 'Trouble in Paradise', 'Thief Gaston Monescu and pickpocket Lily are partners in crime and love. Working for perfume company executive Mariette Colet, the two crooks decide to combine their criminal talents to rob their employer. Under the alias of Monsieur Laval, Gaston uses his position as Mariette''s personal secretary to become closer to her. However, he takes things too far when he actually falls in love with Mariette, and has to choose between her and Lily.', 'Ernst Lubitsch', 83, '1932-10-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/FBxuoLRD3Biyul14unT5m3PYNS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (926, 'Two Seconds', 'A condemned murderer, in the process of being executed, relives the events that led to his being sentenced to die in the electric chair. Told in flashback, we witness a sleazy dancehall girl dupe a high rise riveter into marriage so she can live off of him. But when he loses his job and his marbles, she ends up supporting him with money from her side man--and misses no opportunity to rub it in his face that she''s now supporting him in his emasculated state. As the animosity grows and things get more and more unbearable, he is eventually driven to desperate measures.', 'Mervyn LeRoy', 67, '1932-05-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mSsJxhXgkoqijFV5gRe2BvahJP1.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (927, 'I Was Born, But...', 'Brothers Keiji and Ryoichi move to a new neighborhood in the Tokyo suburbs after their father, an office clerk, is promoted. The boys join the local gang as lowly new kids and emerge as natural leaders after defeating a bully. While visiting the home of their father''s boss, the brothers witness the ridicule their father endures to please his superior. Angry and embarrassed, the boys find their naive ideas about power being challenged.', 'Yasujirō Ozu', 91, '1932-06-03', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/dD3Do5OQj23RJd4thYyUW2AqsCc.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (928, 'Union Depot', 'Among the travelers of varied backgrounds that meet and interact on one night at Union Depot, a metropolitan train station, are Chick and his friend Scrap Iron, both newly released from prison after serving time for vagrancy. Hungry and desperate for a break, Chick fortuitously comes across across a valise abandoned by a drunken traveler. In it he finds a shaving kit and a suit of clothes with a bankroll, which help transform the affable tramp into a dashing gent. After buying himself a meal, Chick seeks some female companionship among the many hustlers who walk the station. He propositions Ruth Collins, a stranded, out-of-work showgirl and takes her to the station''s hotel.', 'Alfred E. Green', 67, '1932-01-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/r9ujw92xMRPQ7dFH6rzKzbenuhs.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (929, 'Vampyr', 'Allan Gray, a young man fascinated by the supernatural, goes to a small village where he feels a sinister force descending upon him. There, Allan meets an old man who asks him to protect his two daughters, for one of them has been bitten by a vampire.', 'Carl Theodor Dreyer', 74, '1932-05-06', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/yt3JS5JSoZseSohYkhs6FLU9B0O.jpg', 'https://www.youtube.com/watch?v=acZJwgwmk4w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (930, 'Virtue', 'A relationship gradually develops between a savvy New York City street girl and a good-hearted cab driver, but other matters keep getting in their way, including financial problems and a murder.', 'Edward Buzzell', 68, '1932-10-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mxBzbdpLYQ6XK9AFc5xRIZSgxpn.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (931, 'What Price Hollywood?', 'Sassy and ambitious waitress Mary Evans amuses and befriends amiable seldom-sober Hollywood film director Max Carey when he stumbles into her restaurant. Max invites Mary to his film premiere and, after a night of drinking and carousing, Mary is granted a screen test. A studio contract follows. Just as Mary finds her dreams coming true, Carey’s life and career begins its descent.', 'George Cukor', 88, '1932-06-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1sgN5YoUMKnPQhOzqwXRjC3oCxo.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (932, 'White Zombie', 'A wealthy landowner living in Haiti convinces a sorcerer to lure the woman he has fallen for away from her fiancé. The madman later betrays their agreement by keeping the woman for himself…as a zombie.', 'Victor Halperin', 67, '1932-07-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/s5DnfWHGeCExlweIFF4JOHKyx3H.jpg', 'https://www.youtube.com/watch?v=Qzum68zgBl4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (933, '20,000 Years in Sing Sing', 'Brash hoodlum Tom Connors enters Sing Sing cocksure of himself and disrespectful toward authority, but his tough but compassionate warden changes him.', 'Michael Curtiz', 78, '1932-12-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pz6IM5TC5uLi3AQeXVMvPSgwngw.jpg', 'https://www.youtube.com/watch?v=x2f9JNfq1V4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (934, 'Alice in Wonderland', 'In Victorian England, a bored young girl dreams that she has entered a fantasy world called Wonderland, populated by even more fantastic characters.', 'Norman Z. McLeod', 76, '1933-12-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/k4hlsqfhEtTrEtiDE647qxTR6PI.jpg', 'https://www.youtube.com/watch?v=-iaZZx-ldvU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (935, 'Baby Face', 'A young woman uses her body and her sexuality to help her climb the social ladder, but soon begins to wonder if her new status will ever bring her happiness.', 'Alfred E. Green', 76, '1933-07-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ul4BLZAXepOQRwUtORmvEpZ4KW4.jpg', 'https://www.youtube.com/watch?v=8uI4eij-K0Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (936, 'The Bitter Tea of General Yen', 'Shanghai, China, the 1920s. In the midst of a bloody civil war, General Yen, a ruthless warlord, rescues Megan Davis —who was about to marry a missionary— from certain death amid the chaos.', 'Frank Capra', 88, '1933-01-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/63lQVmPRDuc4fUDfgbKYnvuSYYr.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (937, 'Bombshell', 'A glamorous film star rebels against the studio, her pushy press agent and a family of hangers-on.', 'Victor Fleming', 96, '1933-10-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dFWEo4b1kxu997TFetFDjk1RwJm.jpg', 'https://www.youtube.com/watch?v=8n-WQ6tqH3c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (938, 'Bureau of Missing Persons', 'A young woman goes to the police looking for her missing husband. When it turns out her husband is both a murder victim and a bachelor - and that she is the primary suspect - tough cop Butch Saunders comes up with a scheme to crack the case.', 'Roy Del Ruth', 73, '1933-09-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/grDoaGUj3Ue9N3NdwHnpHJLfm9K.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (939, 'A Song of Lisbon', 'Vasco is a medical student in Lisbon, supported by his rich aunts, whom he had falsely told he had already graduated. In fact, he devotes himself to a bohemian life, preferring the popular fairs and pretty women, especially Alice, a seamstress from the Castelinhos quarter, which rather upsets her ambitious father, tailor Caetano, who is familiar with Vasco''s debts. After failing yet another final exam, he is surprised by his aunts'' announcement that they will visit him in Lisbon to see his practice.', 'José Cottinelli Telmo', 85, '1933-11-07', 'P', 'pt', 'https://image.tmdb.org/t/p/w500/t7zpnBcbbbKMWuZwk05r9PNongi.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (940, 'Cavalcade', 'A cavalcade of English life from New Year''s Eve 1899 until 1933 is seen through the eyes of well-to-do Londoners Jane and Robert Marryot. Amongst events touching their family are the Boer War, the death of Queen Victoria, the sinking of the Titanic, and the Great War.', 'Frank Lloyd', 112, '1933-02-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/a6yld4HmB49b9CP9wmv3wcwk65K.jpg', 'https://www.youtube.com/watch?v=d2sd4bObXD0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (941, 'Christopher Strong', 'A romance develops between a happily married middle-aged British politician and an adventurous young aviatrix.', 'Dorothy Arzner', 78, '1933-03-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jhPBTEHlgw4xONmNxdJzWRuugMm.jpg', 'https://www.youtube.com/watch?v=OFOs8QWtMDU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (942, 'Counsellor at Law', 'A successful lawyer struggles to deal with his wife''s unfaithfulness and his own hidden past.', 'William Wyler', 82, '1933-12-25', 'K', 'en', 'https://image.tmdb.org/t/p/w500/6mQ9jFo5qpNGptSe5AJMYAcrnSs.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (943, 'Dancing Lady', 'Janie lives to dance and will dance anywhere, even stripping in a burlesque house. Tod Newton, the rich playboy, discovers her there and helps her get a job in a real Broadway musical being directed by Patch. Tod thinks he can get what he wants from Janie, Patch thinks Janie is using her charms rather than talent to get to the top, and Janie thinks Patch is the greatest. Steve, the stage manager, has the Three Stooges helping him manage all the show girls. Fred Astaire and Nelson Eddy make appearances as famous Broadway personalities.', 'Robert Z. Leonard', 92, '1933-11-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bJc8DTD34kbpccaMDROojHXJ0RS.jpg', 'https://www.youtube.com/watch?v=ehdyRdR8GaM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (944, 'The Death Kiss', 'When a movie actor is shot and killed during production, the true feelings about the actor begin to surface. As the studio heads worry about negative publicity, one of the writers tags along as the killing is investigated and clues begin to surface.', 'Edwin L. Marin', 75, '1932-12-05', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/jr9NNKQqSDGDR1wiinfrUFhHvpG.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (945, 'Passing Fancy', 'In Depression-era Tokyo, a struggling middle-aged single father with a young son comes across a homeless young lady and convinces a bar owner to take her in.', 'Yasujirō Ozu', 101, '1933-09-07', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/aoxgzp1QLDHnR2GgXB56F6HkX19.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (946, 'Design for Living', 'Independent Gilda is resigned fo a life of married tedium when Tom and George, having gotten past their jealousy, come to America and whisk Gilda away to live an exciting polyamorous life in Paris.', 'Ernst Lubitsch', 91, '1933-12-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/h0T4FHsY51IccSGqGfaoYsd7hyx.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (947, 'The Devil''s Brother', 'Two wannabe bandits join the service of a dashing nobleman, who secretly masquerades as Fra Diavolo, a notorious outlaw.', 'Hal Roach', 90, '1933-05-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gblt0cSVu82R921SmgNFX0Nq9bv.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (948, 'Dinner at Eight', 'An ambitious New York socialite plans an extravagant dinner party as her businessman husband, Oliver, contends with financial woes, causing a lot of tension between the couple. Meanwhile, their high-society friends and associates, including the gruff Dan Packard and his sultry spouse, Kitty, contend with their own entanglements, leading to revelations at the much-anticipated dinner.', 'George Cukor', 111, '1933-12-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/p9V2dIMqC1g1S9bDgvxqUOJDfp6.jpg', 'https://www.youtube.com/watch?v=vDP8jh1JRhw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (949, 'Double Harness', 'After tricking him into marriage, a woman tries to win the love of her philandering husband.', 'John Cromwell', 69, '1933-07-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/WYjDNBuzzL1B8H0216VGBJ0U9v.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (950, 'Duck Soup', 'Rufus T. Firefly is named president/dictator of bankrupt Freedonia and declares war on neighboring Sylvania over the love of wealthy Mrs. Teasdale.', 'Leo McCarey', 68, '1933-11-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/31t63plEGKHhYuuCpC9bFWO9SBS.jpg', 'https://www.youtube.com/watch?v=MSMTkUYyKYU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (951, 'The Eagle and the Hawk', 'The pilots of a Royal Air Force squadron in World War I face not only physical but mental dangers in their struggle to survive while fighting the enemy.', 'Stuart Walker', 73, '1933-05-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qkg6lo4OvOTOqCQ2dkMJKuQ93BU.jpg', 'https://www.youtube.com/watch?v=8jqgTwtTbJE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (952, 'Emperor Jones', 'Unscrupulously ambitious, Brutus Jones escapes from jail after killing a guard and, through bluff and bravado, finds himself the emperor of a Caribbean island.', 'Dudley Murphy', 73, '1933-09-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/676jzPaamXDHe0pJdiiHkt9ZTFd.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (953, 'Employees'' Entrance', 'Kurt Anderson is the tyrannical manager of a New York department store in financial straits. He thinks nothing of firing an employee of more than 20 years or of toying with the affections of every woman he meets. One such victim is Madeline, a beautiful young woman in need of a job. Anderson hires her as a salesgirl, but not before the two spend the night together. Madeline is ashamed, especially after she falls for Martin West, a rising young star at the store. Her biggest fear is that Martin finds out the truth about her "career move."', 'Roy Del Ruth', 75, '1933-02-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/oRBztofgI6c4v2ahiMNm0unGzls.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (954, 'Ex-Lady', 'Although free spirit Helen Bauer does not believe in marriage, she consents to marry Don, but his infidelities cause her to also take on a lover.', 'Robert Florey', 67, '1933-05-15', 'K', 'en', 'https://image.tmdb.org/t/p/w500/bYKtoVtx0yRHzgaGOhh88Dt9JYc.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (955, 'Female', 'Alison Drake, the tough-minded executive of an automobile factory, succeeds in the man''s world of business until she meets an independent design engineer.', 'Michael Curtiz', 60, '1933-11-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zHgACPj8LHUai00XjDZYPNQ2xeg.jpg', 'https://www.youtube.com/watch?v=eDfRzke3R9E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (956, 'Flying Down to Rio', 'An American bandleader woos a Brazilian beauty who is already engaged to his employer. His friends try to help him, while learning the local dance, The Carioca. The first pairing of Fred Astaire & Ginger Rogers, and their only pre-Code film.', 'Thornton Freeland', 89, '1933-12-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zKBXy84eN6tgwXaYsiFSCgq0GBc.jpg', 'https://www.youtube.com/watch?v=lJI1CRzGTIs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (957, 'Footlight Parade', 'A fledgling producer finds himself at odds with his workers, financiers and his greedy ex-wife when he tries to produce live musicals for movie-going audiences.', 'Lloyd Bacon', 104, '1933-10-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3i03jv70icLoxJiwkqcFsLmmmrA.jpg', 'https://www.youtube.com/watch?v=EIv4A53jH6s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (958, '42nd Street', 'Broadway director Julian Marsh needs just one more hit show so he can retire and recover his health. It looks like he just may pull it off until temperamental star Dorthy Brock breaks her ankle on the eve of the show''s premiere and has to be replaced by her understudy Peggy.', 'Lloyd Bacon', 89, '1933-03-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/q4UEd8BL74zVsOOaJkKVMLMmdTg.jpg', 'https://www.youtube.com/watch?v=f2OaJv0NBB8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (959, 'Gabriel Over the White House', 'A political hack becomes President during the height of the Depression and undergoes a metamorphosis into an incorruptible statesman after a near-fatal accident.', 'Gregory La Cava', 86, '1933-03-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fZt8iHZerWqN54JuOWvX7pc8T3G.jpg', 'https://www.youtube.com/watch?v=S6cCsd-OhU4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (960, 'The Ghoul', 'British Egyptologist Professor Morlant seeks immortality through a jewel buried in the tomb of an Oriental idol. Upon his death, Morlant returns to Earth to seek vengeance upon those who removed the jewel from his grave.', 'T. Hayes Hunter', 77, '1933-08-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/dmMBlNiGLQJRVNGgy8SRnscidUn.jpg', 'https://www.youtube.com/watch?v=_SZtP0V0L2M', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (961, 'Going Hollywood', 'Sylvia is a French teacher at an all-girls school who wants to find love. When she hears Bill Williams on the radio, she decides to go visit and thank him. However, difficult problems lie ahead when Lili gets in the way.', 'Raoul Walsh', 78, '1933-12-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uS8537GrF5d53SDTFMMEW2fRhE1.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (962, 'Gold Diggers of 1933', 'When all Broadway shows are shut down during the Depression, a trio of desperate showgirls scheme to bilk a repugnant high society man of his money to keep their show going.', 'Mervyn LeRoy', 97, '1933-05-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sXsUJsW9fcVT15hfBu9LyU22qmG.jpg', 'https://www.youtube.com/watch?v=n7LcBOOqgZo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (963, 'Hans Westmar', 'Nazi film about the story of a Nazi Storm Trooper named Horst Wessel--here called "Hans Westmar"--who took part in street brawls and assassinations in Berlin in the 1920s and 1930s against Communists and other opponents of the Nazis, and was killed by Communists not long before this film came out.', 'Franz Wenzler', 95, '1933-12-13', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/6P8LclqXP8j482OCJ2PQaiR5jpW.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (964, 'Heroes for Sale', 'World War I veteran Tom Holmes is marked by the unbearable suffering caused by his battle wounds. Over the years, he comes to experience both the pain of misfortune and a love for other human beings.', 'William A. Wellman', 72, '1933-06-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/36ENJ2HpKkQLRycFwwgHxKQw71T.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (965, 'Dragnet Girl', 'A gangster tries to find redemption with the inadvertent help of an innocent shop girl and his jealous girlfriend will do anything to keep him.', 'Yasujirō Ozu', 100, '1933-04-27', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/uHkdSXumZHqUILAy8zsiYLlfGmH.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (966, 'Hitler Youth Quex', 'Nazi propaganda film based on the life and death of Hitler Youth Herbert "Quex" Norkus – in the film, renamed Heini Völker – who was killed while distributing flyers in a Communist neighborhood.', 'Hans Steinhoff', 91, '1933-09-10', 'K', 'de', 'https://image.tmdb.org/t/p/w500/ndIG50vNtPYKGimY1hgOBxCjyS0.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (967, 'Hold Your Man', 'Ruby falls in love with small-time con man Eddie. During a botched blackmail scheme, Eddie accidentally kills the man they were setting up. Eddie takes off and Ruby is sent to a reformatory for two years.', 'Sam Wood', 87, '1933-06-30', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xQYkhqL9yQ1aaPp2WXGG7WWRofw.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (968, 'I''m No Angel', 'Bold performer Tira works as dancing beauty and lion tamer at a fair. Out of an urgent financial need, she agrees to a risky new number: she''ll put her head into the lion''s mouth! With this attraction, the circus makes it to New York and Tira can pursue her dearest occupation — flirting with rich men and accepting expensive presents.', 'Wesley Ruggles', 87, '1933-10-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ttACv1NRimYH9JiyVwy5Kwq2nL0.jpg', 'https://www.youtube.com/watch?v=WljI-X_Zkf8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (969, 'International House', 'Foreign investors converge on a luxury hotel in China to bid on a new kind of radioscope. But, this is a hotel where Burns and Allen are the in-house medical staff, a measles risk sends the whole building into quarantine, and a madcap millionaire crashes dinner in his autogyro. Hotel and radioscope become a stage for an all-star cast of comedians and musicians, from vaudeville to the new generation.', 'A. Edward Sutherland', 68, '1933-05-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fCZ2Q7vOoxitgaVv1exWSkHIPmR.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (970, 'The Invisible Man', 'After experimenting on himself and becoming invisible, scientist Jack Griffin, now aggressive due to the drug''s effects, seeks a way to reverse the experiment at any cost.', 'James Whale', 71, '1933-10-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ejoVwGmEbTBrf78tqnTSO5g8iVz.jpg', 'https://www.youtube.com/watch?v=C4rEv7ArYwg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (971, 'Island of Lost Souls', 'An obsessed scientist conducts profane experiments in evolution, eventually establishing himself as the self-styled demigod to a race of mutated, half-human abominations.', 'Erle C. Kenton', 71, '1932-12-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/g7K7r1FojQC52YHxfmuXgwYBq5Q.jpg', 'https://www.youtube.com/watch?v=D6wWPwz4BAM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (972, 'The Kennel Murder Case', 'Philo Vance, accompanied by his prize-losing Scottish terrier, investigates the locked-room murder of a prominent and much-hated collector whose broken Chinese vase provides an important clue.', 'Michael Curtiz', 73, '1933-10-28', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/sLVl74dMT8JF7HiBqwqqASnEeHx.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (973, 'King Kong', 'Adventurous filmmaker Carl Denham sets out to produce a motion picture unlike anything the world has seen before. Alongside his leading lady Ann Darrow and his first mate Jack Driscoll, they arrive on an island and discover a legendary creature said to be neither beast nor man. Denham captures the monster to be displayed on Broadway as King Kong, the eighth wonder of the world.', 'Ernest B. Schoedsack, Merian C. Cooper', 100, '1933-04-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lHlnxKL5GbgRibyRFI7n1Ey850i.jpg', 'https://www.youtube.com/watch?v=I8P7RzqOU_M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (974, 'Ladies They Talk About', 'A moll, imprisoned after participating in a bank robbery, helps with a breakout plot.', 'Howard Bretherton, William Keighley', 69, '1933-02-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1oEJ9Y2aO9qMvgiYqhmoca5kXys.jpg', 'https://www.youtube.com/watch?v=4tW4c6H6j1A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (975, 'Lady Killer', 'An ex-gang member tries to resist his old cohorts'' criminal influence after he suddenly becomes a Hollywood movie star.', 'Roy Del Ruth', 76, '1933-12-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jDFue65MCa3fnehTVA9KCunQD0M.jpg', 'https://www.youtube.com/watch?v=a1wROiL2ZL8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (976, 'Lady for a Day', 'Apple Annie is an aging New York City fruit seller whose daughter Louise has been raised in a Spanish convent since she was an infant. As she grows up, Louise is led to believe that her mother is a society matron called Mrs. E. Worthington Manville. Annie worries that her lie is in danger of being uncovered when she learns that Louise is sailing to New York with her new fiancé and his nobleman father.', 'Frank Capra', 96, '1933-09-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3qOtbnBKhcM66wtYgUViasKdj6s.jpg', 'https://www.youtube.com/watch?v=okXAbM8aVfE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (977, 'Liebelei', 'Vienna in the beginning of the twentieth century. Cavalry Lieutenant Fritz Lobheimer is about to end his affair with Baroness Eggerdorff when he meets the young Christine, the daughter of an opera violinist. Baron Eggerdorff however soon hears of his past misfortune...', 'Max Ophüls', 88, '1933-03-10', 'P', 'de', 'https://image.tmdb.org/t/p/w500/yQyvKKKotBSnKk3ZFyhCzDzhnsy.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (978, 'The Little Giant', 'Prohibition is ending so bootlegger Bugs Ahearn decides to crack California society. He leases a house from down-on-her-luck Ruth and hires her as social secretary. He rescues Polly Cass from a horsefall and goes home to meet her dad who sells him some phony stock certificates. When he learns about this he sends to Chicago for mob help.', 'Roy Del Ruth', 76, '1933-05-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/n7YHYu2JO0zBCEsBW8lKRBvpTgr.jpg', 'https://www.youtube.com/watch?v=QcRJ2vZoSD0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (979, 'Little Women', 'Four sisters come of age in America in the aftermath of the Civil War.', 'George Cukor', 115, '1933-11-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6jbBsk4uDuSkO2Uxv5YxoPNmVVj.jpg', 'https://www.youtube.com/watch?v=LQLLijJevd8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (980, 'Man''s Castle', 'Bill takes Trina into his depression camp cabin. Later, just as he finds showgirl LaRue who will support him, Trina becomes pregnant.', 'Frank Borzage', 75, '1933-11-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v1FnexSyXDvR7V5ugPXGXve7B8c.jpg', NULL, 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (981, 'The Mayor of Hell', 'Members of a teenage gang are sent to the State Reformatory, presided over by the callous Thompson. Soon Patsy Gargan, a former gangster appointed Deputy Commissioner, arrives and takes over the administration to run the place on radical principles. Thompson needs a quick way to discredit him.', 'Archie Mayo', 90, '1933-06-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lqYNH0qqCDrWQ19WHmyLP6q2PjA.jpg', 'https://www.youtube.com/watch?v=ZxFZDz5O68A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (982, 'Midnight Mary', 'While on trial for her life, a young woman recalls her tough upbringing and her involvement with the men who brought her to this current state of affairs.', 'William A. Wellman', 74, '1933-06-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gd3TAaPUKfnGEYXveQnmU6rAe8B.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (983, 'Morning Glory', 'Wildly optimistic chatterbox Eva Lovelace is a would-be actress trying to crash the New York stage. She attracts the interest of a paternal actor, a philandering producer, and an earnest playwright. Is she destined for stardom, or will she fade like a morning glory after its brief blooming?', 'Lowell Sherman', 74, '1933-08-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jp92gr0EWgYQxoGcY5GQaV3kmax.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (984, 'Murders in the Zoo', 'Dr. Gorman is a millionaire adventurer, traveling the world in search of dangerous game. His bored, beautiful, much younger wife entertains herself in the arms of other men. In turn, Gorman uses his animals to kill these men. When a New York City zoo suggests a fundraising gala, Gorman sees a prime opportunity to dispatch the dashing Roger and anyone else who might cross him.', 'A. Edward Sutherland', 62, '1933-03-31', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/8GL0POYXHakLfgWSi0iwehLdhcY.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (985, 'Mystery of the Wax Museum', 'A wax sculptor opens a new museum years after he is severely injured during a fire that destroyed his original collection. The disappearance of both people and corpses coincides with this grand reopening and leads a reporter to start investigating.', 'Michael Curtiz', 78, '1933-02-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rs4FJ6F5gY0wDqNGzGqV5OU7VzS.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (986, 'Outskirts', 'In a remote Russian village during World War I, colourful and nuanced characters experience divided loyalties: family loyalty vs. personal desire, nationalism vs. transcendent humanism.', 'Boris Barnet', 91, '1933-03-25', 'T13', 'ru', 'https://image.tmdb.org/t/p/w500/Aezrd4wZ2LauHhExEwKMTBIy1Fe.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (987, 'Parachute Jumper', 'An Air Force washout and his buddy room with a pretty young lady. Desperate for jobs during the Depression, they finally land employment with the mob.', 'Alfred E. Green', 72, '1933-01-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lH3kQo4Q6O6OoIVVcPkmxgOMkpd.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (988, 'Peg o'' My Heart', 'Peg and her father live a simple life in an Irish fishing village. One day Sir Gerald arrives at the village to tell Pat that Peg is heir to estate of her grandfather, who hated Pat. The upshot of the will is that she must go to England for 3 years to learn to be a lady and that Pat can never see her again.', 'Robert Z. Leonard', 87, '1933-05-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/alvPkrbQ7LX2jrapEwpY76LTUS6.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (989, 'Penthouse', 'Gertie Waxted knows how notorious gangster Jim Crelliman runs his rackets, because she''s long been under the hoodlum''s thumb. She''s secretly helping lawyer Jackson Durant in a snoop job aimed at pinning a murder on the thug. Her life will be in peril when that secret gets out.', 'W.S. Van Dyke', 88, '1933-09-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mUJCt9wBvsspffPacWFo66F8VoM.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (990, 'Picture Snatcher', 'An ex-con uses his street smarts to become a successful photojournalist.', 'Lloyd Bacon', 77, '1933-05-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2V2AwXXjc44S56dVmN272hgnEkt.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (991, 'Private Detective 62', 'A former government agent in France, who has failed at an assignment and been disavowed, is deported back to the USA, where he can only find work at a low-rent detective agency. He soon gets involved with a woman with ties to a crooked gambling club owner, who is a client of his agency.', 'Michael Curtiz', 66, '1933-06-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7nTQPjyY6xsAQcbsSjS13ncBAmD.jpg', 'https://www.youtube.com/watch?v=i4f7G4bx1p4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (992, 'The Private Life of Henry VIII', 'Renowned for his excess, King Henry VIII goes through a series of wives during his rule. With Anne Boleyn, his second betrothed, executed on charges of treason, Henry weds maid Jane Seymour, but that wedded bliss also ends in tragedy. Not one to be single for long, the tyrannical king chooses German-born Anne of Cleves, but their union lasts only months before an annulment is granted, and so Henry''s reign of spousal terror continues.', 'Alexander Korda', 97, '1933-08-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ncQC8U3gGFhCTWlxxn32nkFr2d4.jpg', NULL, 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (993, 'Queen Christina', 'Popular monarch Queen Christina of Sweden must choose between love and loyalty to her nation when she unexpectedly falls for a Spanish envoy.', 'Rouben Mamoulian', 99, '1934-02-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lGGYwoBp21CzF7cMzNPcOr6i6iw.jpg', 'https://www.youtube.com/watch?v=icS3e2IFxBk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (994, 'Riders of Destiny', 'James Kincaid controls the local water supply and plans to do away with the other ranchers. Government agent Sandy Saunders arrives undercover to investigate Kincaid''s land swindle scheme, and win the heart of one of his victims, Fay Denton.', 'Robert N. Bradbury', 55, '1933-10-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aZCgQuRhDpWjjJgVYTDxWwcJ08i.jpg', 'https://www.youtube.com/watch?v=_1Hj6p-Dfi8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (995, 'Sagebrush Trail', 'Imprisoned for a murder he did not commit, John Brant escapes and ends up out west where, after giving the local lawmen the slip, he joins up with an outlaw gang. Brant finds out that ''Jones'', one of the outlaws he has become friends with, committed the murder that Brant was sent up for, but has no knowledge that anyone was ever put in jail for his crime. Willing to forgive and forget, Brant doesn''t realize that ''Jones'' has not only fallen for the same pretty shopgirl Brant has, but begins to suspect that Brant is not truly an outlaw.', 'Armand Schaefer', 54, '1933-12-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pCJlvS7o6wJ6Xn8qZ5GkVJWpRMc.jpg', 'https://www.youtube.com/watch?v=ZzY7Lg3yrJ8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (996, 'Secret of the Blue Room', 'According to a legend, the mansion''s "blue room" is cursed -- everyone who has ever spent the night in that room has met with an untimely end. The three suitors of the heroine wager that each can survive a night in the forbidding blue room.', 'Kurt Neumann', 66, '1933-07-20', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/y2DEVVE9ZHn9kvaWlgngiLx98Wa.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (997, 'She Done Him Wrong', 'New York singer and nightclub owner Lady Lou has more male friends than can be imagined. One is a vicious escaped criminal on the way to see ''his'' girl, unaware she hasn''t exactly been faithful in his absence. Help is at hand in the form of young Captain Cummings, a local temperance league leader.', 'Lowell Sherman', 65, '1933-02-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kwxAUj8tf9kO2ESAriD8foYN28q.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (998, 'A Shriek in the Night', 'Rival newspaper reporters Pat Morgan and Ted Rand find themselves unraveling the mystery behind the death of a millionaire philanthropist who fell from his penthouse balcony. When it is discovered that the plunge was not an accident, the building''s residents come under suspicion. Soon, the body count begins to mount as three more murders occur by strangulation.', 'Albert Ray', 66, '1933-07-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mQzNjqtHJHVoG1M9UcINVKenC0Y.jpg', NULL, 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (999, 'The Son of Kong', 'Beleaguered adventurer Carl Denham returns to the island where he found King Kong.', 'Ernest B. Schoedsack', 70, '1933-12-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/eJ2Qe3tesoKUtWNJRDpHKz1xCJc.jpg', 'https://www.youtube.com/watch?v=ZORAQa93iyQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (1000, 'Sons of the Desert', 'Ollie and Stan deceive their wives into thinking they are taking a medically necessary cruise when they are really going to a lodge convention.', 'William A. Seiter', 65, '1933-12-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4ojrxP6qiyDOQ5jHQlh7Yn59wJt.jpg', 'https://www.youtube.com/watch?v=jXf_GgrLGAM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);

